def _xiaoxia_calendar_config_status():
    missing = []
    if not XIAOXIA_GOOGLE_CLIENT_ID:
        missing.append("XIAOXIA_GOOGLE_CLIENT_ID")
    if not XIAOXIA_GOOGLE_CLIENT_SECRET:
        missing.append("XIAOXIA_GOOGLE_CLIENT_SECRET")
    if not XIAOXIA_GOOGLE_REFRESH_TOKEN:
        missing.append("XIAOXIA_GOOGLE_REFRESH_TOKEN")
    return {
        "configured": not missing,
        "missing": missing,
        "calendar_id": XIAOXIA_GOOGLE_CALENDAR_ID,
        "scope": XIAOXIA_GOOGLE_CALENDAR_SCOPE,
    }


async def _xiaoxia_calendar_access_token(force_refresh=False):
    """以 refresh token 換短效 access token；只存在記憶體，不把 token 寫進 repo / volume。"""
    import time as _time
    now_ts = _time.time()
    cached = str(_XIAOXIA_CALENDAR_TOKEN_CACHE.get("access_token") or "").strip()
    expires_at = float(_XIAOXIA_CALENDAR_TOKEN_CACHE.get("expires_at") or 0.0)

    if cached and not force_refresh and now_ts < (expires_at - 60):
        return cached

    status = _xiaoxia_calendar_config_status()
    if not status["configured"]:
        raise RuntimeError("XIAOXIA_CALENDAR_ENV_MISSING: " + ", ".join(status["missing"]))

    payload = {
        "client_id": XIAOXIA_GOOGLE_CLIENT_ID,
        "client_secret": XIAOXIA_GOOGLE_CLIENT_SECRET,
        "refresh_token": XIAOXIA_GOOGLE_REFRESH_TOKEN,
        "grant_type": "refresh_token",
    }
    timeout = aiohttp.ClientTimeout(total=30)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.post("https://oauth2.googleapis.com/token", data=payload) as resp:
            body = await resp.text()
            if resp.status >= 400:
                raise RuntimeError(f"GOOGLE_TOKEN_HTTP_{resp.status}: {body[:800]}")
            try:
                data = json.loads(body)
            except Exception:
                raise RuntimeError(f"GOOGLE_TOKEN_BAD_JSON: {body[:800]}")

    token = str(data.get("access_token") or "").strip()
    if not token:
        raise RuntimeError(f"GOOGLE_TOKEN_MISSING_ACCESS_TOKEN: {str(data)[:800]}")
    expires_in = int(data.get("expires_in") or 3600)
    _XIAOXIA_CALENDAR_TOKEN_CACHE["access_token"] = token
    _XIAOXIA_CALENDAR_TOKEN_CACHE["expires_at"] = now_ts + max(60, expires_in)
    return token


def _xiaoxia_calendar_event_url(event_id=None):
    base = (
        "https://www.googleapis.com/calendar/v3/calendars/"
        + quote(XIAOXIA_GOOGLE_CALENDAR_ID, safe="")
        + "/events"
    )
    if event_id:
        return base + "/" + quote(str(event_id), safe="")
    return base


async def _xiaoxia_calendar_request(method, url, *, params=None, json_body=None, retry_auth=True):
    token = await _xiaoxia_calendar_access_token()
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json",
    }
    if json_body is not None:
        headers["Content-Type"] = "application/json"

    timeout = aiohttp.ClientTimeout(total=30)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.request(
            method.upper(),
            url,
            headers=headers,
            params=params,
            json=json_body,
        ) as resp:
            body = await resp.text()

    if resp.status == 401 and retry_auth:
        await _xiaoxia_calendar_access_token(force_refresh=True)
        return await _xiaoxia_calendar_request(
            method,
            url,
            params=params,
            json_body=json_body,
            retry_auth=False,
        )

    if resp.status >= 400:
        raise RuntimeError(f"GOOGLE_CALENDAR_HTTP_{resp.status}: {body[:1200]}")

    if resp.status == 204 or not body.strip():
        return {}
    try:
        return json.loads(body)
    except Exception:
        raise RuntimeError(f"GOOGLE_CALENDAR_BAD_JSON: {body[:1200]}")


async def _xiaoxia_calendar_list_events(start_dt=None, end_dt=None, max_results=50):
    start_dt = start_dt or datetime.now(TZ_TPE)
    end_dt = end_dt or (start_dt + timedelta(days=14))
    params = {
        "timeMin": start_dt.isoformat(),
        "timeMax": end_dt.isoformat(),
        "singleEvents": "true",
        "orderBy": "startTime",
        "maxResults": str(max(1, min(int(max_results or 50), 2500))),
    }
    data = await _xiaoxia_calendar_request("GET", _xiaoxia_calendar_event_url(), params=params)
    return list(data.get("items") or [])


async def _xiaoxia_calendar_create_event(
    summary,
    start_dt,
    end_dt,
    *,
    description="",
    location="",
):
    body = {
        "summary": str(summary or "").strip() or "小俠行程",
        "description": str(description or "").strip(),
        "start": {
            "dateTime": start_dt.isoformat(),
            "timeZone": "Asia/Taipei",
        },
        "end": {
            "dateTime": end_dt.isoformat(),
            "timeZone": "Asia/Taipei",
        },
    }
    if location:
        body["location"] = str(location).strip()
    return await _xiaoxia_calendar_request("POST", _xiaoxia_calendar_event_url(), json_body=body)


async def _xiaoxia_calendar_update_event(event_id, patch):
    if not event_id:
        raise ValueError("event_id is required")
    return await _xiaoxia_calendar_request(
        "PATCH",
        _xiaoxia_calendar_event_url(event_id),
        json_body=dict(patch or {}),
    )


async def _xiaoxia_calendar_delete_event(event_id):
    if not event_id:
        raise ValueError("event_id is required")
    return await _xiaoxia_calendar_request("DELETE", _xiaoxia_calendar_event_url(event_id))


def _xiaoxia_calendar_event_start_text(event):
    start = (event or {}).get("start") or {}
    raw = str(start.get("dateTime") or start.get("date") or "").strip()
    if not raw:
        return "時間未定"
    if "T" not in raw:
        return raw + "（全天）"
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00")).astimezone(TZ_TPE)
        return dt.strftime("%m/%d（%a） %H:%M").replace(
            "Mon", "一").replace("Tue", "二").replace("Wed", "三").replace(
            "Thu", "四").replace("Fri", "五").replace("Sat", "六").replace("Sun", "日")
    except Exception:
        return raw[:16]


async def _xiaoxia_calendar_connection_test():
    """
    Zeabur 端完整 CRUD smoke test：
    list -> create -> patch -> delete。
    測試 event 約 15 分鐘後開始，完成後自動刪除。
    """
    now_dt = datetime.now(TZ_TPE)
    result = {
        "list_ok": False,
        "create_ok": False,
        "update_ok": False,
        "delete_ok": False,
        "event_id": "",
    }

    existing = await _xiaoxia_calendar_list_events(now_dt, now_dt + timedelta(days=14), max_results=5)
    result["list_ok"] = True
    result["existing_count"] = len(existing)

    start_dt = now_dt + timedelta(minutes=15)
    end_dt = start_dt + timedelta(minutes=30)
    created = None
    try:
        created = await _xiaoxia_calendar_create_event(
            "🧪 Xiaoxia Zeabur Calendar Test",
            start_dt,
            end_dt,
            description=(
                "v1.10.32 Zeabur 端 Calendar API 測試。\n"
                "程式會自動修改後刪除此活動。"
            ),
        )
        event_id = str(created.get("id") or "")
        result["event_id"] = event_id
        result["create_ok"] = bool(event_id)
        if not event_id:
            raise RuntimeError("CREATE_RETURNED_NO_EVENT_ID")

        updated = await _xiaoxia_calendar_update_event(
            event_id,
            {
                "summary": "🧪 Xiaoxia Zeabur Calendar Test｜修改成功",
                "description": (
                    "v1.10.32 Zeabur 端 Calendar API 測試。\n"
                    "修改測試：成功。\n"
                    "程式稍後會自動刪除此活動。"
                ),
            },
        )
        result["update_ok"] = bool(updated.get("id") == event_id)

        await _xiaoxia_calendar_delete_event(event_id)
        result["delete_ok"] = True
        return result
    except Exception:
        # create 成功但 update 失敗時，best effort 清掉測試垃圾。
        if created and result.get("event_id") and not result.get("delete_ok"):
            try:
                await _xiaoxia_calendar_delete_event(result["event_id"])
                result["cleanup_delete_ok"] = True
            except Exception as cleanup_exc:
                result["cleanup_delete_error"] = f"{type(cleanup_exc).__name__}: {cleanup_exc}"
        raise



def _xiaoxia_calendar_normalize_event(event):
    event = event if isinstance(event, dict) else {}
    start = event.get("start") or {}
    end = event.get("end") or {}
    return {
        "id": str(event.get("id") or ""),
        "summary": _clean_text_compact(event.get("summary") or "未命名行程"),
        "description": str(event.get("description") or "").strip(),
        "location": str(event.get("location") or "").strip(),
        "start": start.get("dateTime") or start.get("date") or "",
        "end": end.get("dateTime") or end.get("date") or "",
        "updated": str(event.get("updated") or ""),
    }

def _xiaoxia_calendar_parse_event_dt(raw):
    raw = str(raw or "").strip()
    if not raw:
        return None
    try:
        if "T" in raw:
            return datetime.fromisoformat(raw.replace("Z", "+00:00")).astimezone(TZ_TPE)
        d = datetime.strptime(raw[:10], "%Y-%m-%d").date()
        return datetime.combine(d, time.min, tzinfo=TZ_TPE)
    except Exception:
        return None

def _xiaoxia_calendar_event_date(event):
    dt = _xiaoxia_calendar_parse_event_dt((event or {}).get("start"))
    return dt.date() if dt else None

def _xiaoxia_calendar_event_time_text(event):
    raw = str((event or {}).get("start") or "")
    if "T" not in raw:
        return "全天"
    dt = _xiaoxia_calendar_parse_event_dt(raw)
    return dt.strftime("%H:%M") if dt else raw[11:16]

def _xiaoxia_calendar_parse_description_metadata(description):
    meta, body = {}, []
    for raw in str(description or "").splitlines():
        m = re.match(r"^(同行|來源|鎖定|類型)\s*[：:]\s*(.+)$", raw.strip())
        if m:
            meta[m.group(1)] = m.group(2).strip()
        else:
            body.append(raw)
    meta["body"] = "\n".join(body).strip()
    return meta

def _xiaoxia_calendar_load(path):
    data = _load_json_file_or_default(path, {})
    return data if isinstance(data, dict) else {}

def _xiaoxia_calendar_save(path, payload):
    tmp = str(path) + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)

def _xiaoxia_calendar_three_day_context(events, now_dt):
    out = {"updated_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"), "today": [], "tomorrow": [], "day_after_tomorrow": []}
    date_map = {
        now_dt.date(): "today",
        (now_dt + timedelta(days=1)).date(): "tomorrow",
        (now_dt + timedelta(days=2)).date(): "day_after_tomorrow",
    }
    for ev in events:
        key = date_map.get(_xiaoxia_calendar_event_date(ev))
        if not key:
            continue
        meta = _xiaoxia_calendar_parse_description_metadata(ev.get("description") or "")
        out[key].append({
            "id": ev.get("id"),
            "time": _xiaoxia_calendar_event_time_text(ev),
            "title": ev.get("summary") or "未命名行程",
            "location": ev.get("location") or "",
            "companions": meta.get("同行") or "",
            "source": meta.get("來源") or "",
            "type": meta.get("類型") or "",
            "locked": meta.get("鎖定") or "",
        })
    for key in ("today", "tomorrow", "day_after_tomorrow"):
        out[key].sort(key=lambda x: (x.get("time") or "", x.get("title") or ""))
    return out

def _xiaoxia_calendar_recent_context_text():
    ctx = _xiaoxia_calendar_load(XIAOXIA_CALENDAR_CONTEXT_PATH)
    if not ctx:
        return ""
    lines = ["【小俠近日行程｜Calendar】"]
    for key, label in (("today", "今天"), ("tomorrow", "明天"), ("day_after_tomorrow", "後天")):
        rows = ctx.get(key) or []
        if not rows:
            lines.append(f"{label}：目前沒有已排定行程。")
            continue
        items = []
        for row in rows[:8]:
            who = f"（同行：{row.get('companions')}）" if row.get("companions") else ""
            loc = f" @ {row.get('location')}" if row.get("location") else ""
            items.append(f"{row.get('time')} {row.get('title')}{who}{loc}")
        lines.append(f"{label}：" + "；".join(items))
    lines.append("以上是已知行程；未發生的行程不得當成已發生。")
    return "\n".join(lines)

def _xiaoxia_daily_mainline_for_chat_text():
    data = _xiaoxia_calendar_load(XIAOXIA_DAILY_MAINLINE_PATH)
    if str(data.get("date") or "") != datetime.now(TZ_TPE).strftime("%Y-%m-%d"):
        return ""
    rows = data.get("activities") or []
    if not rows:
        return ""
    lines = ["【小俠今日活動主線｜只知道主線，不知道未來劇情】"]
    for row in rows[:8]:
        lines.append(f"- {row.get('time')}｜{row.get('title')}：{row.get('mainline')}")
    lines.append("不可提前預告未發生的細節。")
    return "\n".join(lines)

def _xiaoxia_calendar_find_activity_seed(title):
    catalog = load_xiaoxia_activity_catalog()
    items = catalog.get("activities") if isinstance(catalog, dict) else catalog
    if not isinstance(items, list):
        return None
    title = _clean_text_compact(title or "")
    exact, partial = [], []
    for item in items:
        if not isinstance(item, dict):
            continue
        it = _clean_text_compact(item.get("title") or "")
        if it == title:
            exact.append(item)
        elif it and (it in title or title in it):
            partial.append(item)
    return (exact or partial or [None])[0]

def _xiaoxia_calendar_recent_episode_for_event(title):
    rows = _load_json_file_or_default(XIAOXIA_AUTONOMY_EPISODE_LOG_PATH, [])
    if not isinstance(rows, list):
        return None
    title = _clean_text_compact(title or "")
    for row in reversed(rows[-100:]):
        if not isinstance(row, dict):
            continue
        rt = _clean_text_compact(row.get("activity_title") or row.get("title") or "")
        if rt and (rt == title or rt in title or title in rt):
            return row
    return None

async def _xiaoxia_generate_today_mainline(today_events, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    activities = []
    for ev in today_events:
        title = _clean_text_compact(ev.get("summary") or "未命名行程")
        meta = _xiaoxia_calendar_parse_description_metadata(ev.get("description") or "")
        seed = _xiaoxia_calendar_find_activity_seed(title)
        episode = _xiaoxia_calendar_recent_episode_for_event(title)

        if isinstance(episode, dict):
            base = _clean_text_compact(
                episode.get("episode_summary") or episode.get("summary") or episode.get("what_happened")
                or episode.get("progress_focus") or episode.get("episode_angle") or ""
            )
            source = "既有 episode"
        elif isinstance(seed, dict):
            base = _clean_text_compact(
                seed.get("seed_prompt") or seed.get("description") or seed.get("scene") or seed.get("title") or ""
            )
            source = "活動種子"
        elif meta.get("body"):
            base, source = _clean_text_compact(meta.get("body") or ""), "Calendar 說明"
        else:
            base, source = title, "Calendar 行程"

        prompt = f"""你是女友小俠生活線的今日主線編劇助手。
只替今天這一筆已排定活動寫一個非常簡短的「主線」，讓小俠知道今天這件事目前大概要做什麼、走到哪裡。
不要預言今天會發生什麼，不要寫可能事件，不要寫 future hook，不要安排結果、巧遇或驚喜。
若有既有 episode，只延續目前階段，不要跨很多階段。
活動：{title}
時間：{_xiaoxia_calendar_event_time_text(ev)}
來源：{source}
可用背景：{base[:1200]}
只回傳一行繁體中文，40~90字，不要標題、不用 JSON。"""
        try:
            r = await gemini_client.aio.models.generate_content(
                model="gemini-2.5-flash",
                contents=prompt,
                config=types.GenerateContentConfig(temperature=0.35),
            )
            mainline = _clean_text_compact(getattr(r, "text", "") or "")
        except Exception as exc:
            print(f"⚠️ [XIAOXIA_DAILY_MAINLINE_GEMINI_FAILED] title={title} {type(exc).__name__}: {exc}")
            mainline = ""

        if not mainline:
            mainline = f"依今天已排定的「{title}」自然進行，不預設結果。"

        activities.append({
            "event_id": ev.get("id"),
            "time": _xiaoxia_calendar_event_time_text(ev),
            "title": title,
            "mainline": mainline,
            "source": source,
        })

    payload = {
        "date": now_dt.strftime("%Y-%m-%d"),
        "generated_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        "activities": activities,
        "rule": "only_mainline_no_future_plot",
    }
    _xiaoxia_calendar_save(XIAOXIA_DAILY_MAINLINE_PATH, payload)
    return payload

async def _xiaoxia_calendar_refresh_cache(*, reason="manual", regenerate_today=True):
    now_dt = datetime.now(TZ_TPE)
    raw = await _xiaoxia_calendar_list_events(
        now_dt.replace(hour=0, minute=0, second=0, microsecond=0),
        now_dt + timedelta(days=14),
        max_results=250,
    )
    events = [_xiaoxia_calendar_normalize_event(x) for x in raw if isinstance(x, dict)]
    cache = {
        "updated_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        "reason": reason,
        "window_start": now_dt.strftime("%Y-%m-%d"),
        "window_end": (now_dt + timedelta(days=14)).strftime("%Y-%m-%d"),
        "event_count": len(events),
        "events": events,
    }
    _xiaoxia_calendar_save(XIAOXIA_CALENDAR_CACHE_PATH, cache)
    ctx = _xiaoxia_calendar_three_day_context(events, now_dt)
    _xiaoxia_calendar_save(XIAOXIA_CALENDAR_CONTEXT_PATH, ctx)
    if regenerate_today:
        today_events = [x for x in events if _xiaoxia_calendar_event_date(x) == now_dt.date()]
        await _xiaoxia_generate_today_mainline(today_events, now_dt)
    print(f"📅 [XIAOXIA_CALENDAR_CACHE_REFRESHED] reason={reason} events={len(events)}")
    return {"cache": cache, "context": ctx, "daily_mainline": _xiaoxia_calendar_load(XIAOXIA_DAILY_MAINLINE_PATH)}

def _xiaoxia_calendar_mentions_non_near_term(user_text):
    t = str(user_text or "")
    return any(k in t for k in ("下週","下下週","下個星期","月底","這個月","下個月","幾號","哪一天","什麼時候","行程","月曆","日曆")) or bool(re.search(r"\b\d{1,2}[/-]\d{1,2}\b", t))

def _xiaoxia_calendar_relevant_cache_text(user_text):
    if not _xiaoxia_calendar_mentions_non_near_term(user_text):
        return ""
    cache = _xiaoxia_calendar_load(XIAOXIA_CALENDAR_CACHE_PATH)
    events = cache.get("events") or []
    if not events:
        return ""
    lines = ["【小俠未來14天行程快取】"]
    for ev in events[:12]:
        dt = _xiaoxia_calendar_parse_event_dt(ev.get("start"))
        when = dt.strftime("%m/%d %H:%M") if dt else str(ev.get("start") or "")
        lines.append(f"- {when}｜{ev.get('summary')}")
    lines.append("若大俠剛手動改 Google Calendar，先用 /小俠月曆 更新。")
    return "\n".join(lines)

def _daxia_reality_context_text(now_dt=None, user_text=""):
    now_dt = now_dt or datetime.now(TZ_TPE)
    wd = now_dt.weekday()
    t = str(user_text or "")
    explicit_home = bool(re.search(r"(今天|我).{0,6}(休假|請假|放假|在家工作|居家辦公|WFH)", t, re.I))
    explicit_out = bool(re.search(r"(今天|我).{0,6}(出差|外出|不在公司)", t, re.I))
    if explicit_home:
        state = "大俠今天已明確表示休假／請假／在家工作；不要假設他人在公司。"
    elif explicit_out:
        state = "大俠今天已明確表示出差或不在公司；不要套用一般公司位置。"
    elif wd >= 5:
        state = "今天是週末，預設休假；除非大俠另說要上班。"
    elif 7 <= now_dt.hour < 18:
        state = "今天是一般週間；正常工時08:00–17:00。07:00–18:00若無例外說明，預設大俠人在公司、通勤或準備上下班，不要描述他正和小俠在家中同一空間。"
    else:
        state = "今天是一般週間，但目前不在07:00–18:00公司預設時段。"
    return (
        "【大俠當下生活狀態】\n"
        f"時間：{now_dt.strftime('%Y-%m-%d %H:%M')}\n"
        "正常工時：08:00–17:00\n"
        "公司/通勤預設時段：07:00–18:00\n"
        f"判定：{state}\n"
        "國定假日：v1.10.33 暫不判定。"
    )

def _xiaoxia_calendar_chat_context(user_text):
    """Calendar/reality context is enrichment only; any failure must never break ordinary chat."""
    try:
        return "\n\n".join(x for x in (
            _daxia_reality_context_text(user_text=user_text),
            _xiaoxia_calendar_recent_context_text(),
            _xiaoxia_daily_mainline_for_chat_text(),
            _xiaoxia_calendar_relevant_cache_text(user_text),
        ) if x).strip()
    except Exception as exc:
        print(f"⚠️ [XIAOXIA_CALENDAR_CHAT_CONTEXT_FAILED_OPEN] {type(exc).__name__}: {exc}")
        return ""


def _xiaoxia_calendar_planner_state_load():
    d = _load_json_file_or_default(XIAOXIA_CALENDAR_PLANNER_STATE_PATH, {})
    return d if isinstance(d, dict) else {}

def _xiaoxia_calendar_planner_state_save(data):
    _xiaoxia_calendar_save(XIAOXIA_CALENDAR_PLANNER_STATE_PATH, data if isinstance(data, dict) else {})

def _xiaoxia_calendar_extract_activity_catalog():
    catalog = load_xiaoxia_activity_catalog()
    raw = catalog.get("activities") if isinstance(catalog, dict) else catalog
    if not isinstance(raw, list):
        return []
    out = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        title = _clean_text_compact(item.get("title") or "")
        if not title:
            continue
        out.append({
            "id": str(item.get("id") or item.get("activity_id") or title),
            "title": title,
            "category": _clean_text_compact(item.get("category") or item.get("theme") or item.get("type") or "日常"),
            "description": _clean_text_compact(item.get("description") or item.get("seed_prompt") or item.get("scene") or item.get("summary") or ""),
        })
    return out

def _xiaoxia_calendar_is_recurring_like(title, description=""):
    t = f"{title} {description}"
    return any(k in t for k in ("固定","每週","課程","訓練","上課","教課","授課","值班","練習","復健","回診","社團","工作坊","排練"))

def _xiaoxia_calendar_time_policy_for_activity(item, date_obj):
    title = _clean_text_compact(item.get("title") or "")
    desc = _clean_text_compact(item.get("description") or "")
    t = f"{title} {desc}"
    weekday = date_obj.weekday() < 5
    if any(k in t for k in ("夜市","夜景","星空","看夜景","晚餐","酒吧")):
        hour = random.choice([18,19,20]); minute = random.choice([0,30])
    elif any(k in t for k in ("淨灘","海邊","登山","健行","步道","晨跑")):
        hour = random.choice([7,8,9,16,17]); minute = random.choice([0,30])
    elif "早餐" in t or "早午餐" in t:
        hour = random.choice([8,9,10]); minute = random.choice([0,30])
    elif "午餐" in t:
        hour = random.choice([11,12]); minute = random.choice([0,30])
    else:
        hour = random.choice([9,10,14,15,16]) if weekday else random.choice([10,14,15,16])
        minute = random.choice([0,30])
    duration = 120 if any(k in t for k in ("旅行","登山","健行","淨灘","看展","展覽","市集")) else 90
    start = datetime.combine(date_obj, time(hour, minute), tzinfo=TZ_TPE)
    return start, start + timedelta(minutes=duration)

def _xiaoxia_calendar_overlap(start_dt, end_dt, events):
    for ev in events or []:
        s = _xiaoxia_calendar_parse_event_dt(ev.get("start"))
        e = _xiaoxia_calendar_parse_event_dt(ev.get("end"))
        if not s:
            continue
        e = e or (s + timedelta(hours=1))
        if start_dt < e and end_dt > s:
            return True
    return False

def _xiaoxia_calendar_build_event_description(item):
    body = _clean_text_compact(item.get("description") or "")
    lines = ["來源：小俠自主", "鎖定：否", f"類型：{item.get('category') or '日常'}"]
    if body:
        lines += ["", body]
    return "\n".join(lines)

async def _xiaoxia_calendar_plan_14_days(start_date=None):
    await _xiaoxia_calendar_refresh_cache(reason="planner_preflight", regenerate_today=False)
    cache = _xiaoxia_calendar_load(XIAOXIA_CALENDAR_CACHE_PATH)
    existing_by_date = {}
    for ev in cache.get("events") or []:
        d = _xiaoxia_calendar_event_date(ev)
        if d:
            existing_by_date.setdefault(d.isoformat(), []).append(ev)

    catalog = _xiaoxia_calendar_extract_activity_catalog()
    if not catalog:
        raise RuntimeError("XIAOXIA_ACTIVITY_CATALOG_EMPTY")

    now_date = datetime.now(TZ_TPE).date()
    start_date = start_date or now_date
    created = []
    used_by_week = {}
    recent_titles = set()

    episodes = _load_json_file_or_default(XIAOXIA_AUTONOMY_EPISODE_LOG_PATH, [])
    if isinstance(episodes, list):
        for row in episodes[-30:]:
            if isinstance(row, dict):
                t = _clean_text_compact(row.get("activity_title") or row.get("title") or "")
                if t:
                    recent_titles.add(t)

    for i in range(14):
        d = start_date + timedelta(days=i)
        key = d.isoformat()
        existing = existing_by_date.setdefault(key, [])
        week_key = f"{d.isocalendar().year}-W{d.isocalendar().week:02d}"
        used = used_by_week.setdefault(week_key, set())
        target = 2 if d.weekday() < 5 else random.choice([0,1])

        existing_auto = 0
        for ev in existing:
            meta = _xiaoxia_calendar_parse_description_metadata(ev.get("description") or "")
            if meta.get("來源") == "小俠自主":
                existing_auto += 1
                used.add(_clean_text_compact(ev.get("summary") or ""))

        needed = max(0, target - existing_auto)
        attempts = 0
        while needed and attempts < 40:
            attempts += 1
            pool = []
            for item in catalog:
                title = item["title"]
                recurring = _xiaoxia_calendar_is_recurring_like(title, item.get("description") or "")
                if not recurring and (title in used or title in recent_titles):
                    continue
                pool.append(item)
            if not pool:
                pool = catalog[:]
            item = random.choice(pool)
            start_dt, end_dt = _xiaoxia_calendar_time_policy_for_activity(item, d)
            for _ in range(4):
                if not _xiaoxia_calendar_overlap(start_dt, end_dt, existing):
                    break
                start_dt += timedelta(hours=1); end_dt += timedelta(hours=1)
            if _xiaoxia_calendar_overlap(start_dt, end_dt, existing):
                continue

            ev = await _xiaoxia_calendar_create_event(
                item["title"], start_dt, end_dt,
                description=_xiaoxia_calendar_build_event_description(item)
            )
            nev = _xiaoxia_calendar_normalize_event(ev)
            existing.append(nev)
            created.append({
                "date": key, "event_id": nev.get("id"), "title": item["title"],
                "start": nev.get("start"), "end": nev.get("end"),
                "activity_id": item["id"], "category": item["category"],
            })
            used.add(item["title"])
            recent_titles.add(item["title"])
            needed -= 1

    refreshed = await _xiaoxia_calendar_refresh_cache(reason="planner_14d_completed", regenerate_today=True)
    st = _xiaoxia_calendar_planner_state_load()
    st.update({
        "last_plan_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "window_start": start_date.isoformat(),
        "window_end": (start_date + timedelta(days=13)).isoformat(),
        "created_count": len(created),
        "created": created[-100:],
    })
    _xiaoxia_calendar_planner_state_save(st)
    return {"created": created, "refreshed": refreshed}

async def _xiaoxia_calendar_review_next_week():
    await _xiaoxia_calendar_refresh_cache(reason="weekly_review_preflight", regenerate_today=False)
    cache = _xiaoxia_calendar_load(XIAOXIA_CALENDAR_CACHE_PATH)
    now_date = datetime.now(TZ_TPE).date()
    days = (7 - now_date.weekday()) % 7 or 7
    mon = now_date + timedelta(days=days)
    sun = mon + timedelta(days=6)
    reviewed, locked = [], []
    for ev in cache.get("events") or []:
        d = _xiaoxia_calendar_event_date(ev)
        if d and mon <= d <= sun:
            meta = _xiaoxia_calendar_parse_description_metadata(ev.get("description") or "")
            row = {"date": d.isoformat(), "title": ev.get("summary"), "locked": meta.get("鎖定") == "是", "source": meta.get("來源") or ""}
            reviewed.append(row)
            if row["locked"]:
                locked.append(row)

    plan = await _xiaoxia_calendar_plan_14_days(start_date=now_date)
    st = _xiaoxia_calendar_planner_state_load()
    st.update({
        "last_review_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "reviewed_next_week": reviewed,
        "locked_next_week_count": len(locked),
    })
    _xiaoxia_calendar_planner_state_save(st)
    return {"reviewed": reviewed, "locked": locked, "planner_created": plan.get("created") or []}

async def _xiaoxia_calendar_weekly_planner_scheduler():
    print("📅 [XIAOXIA_CALENDAR_WEEKLY_PLANNER] background loop started")
    while True:
        try:
            now_dt = datetime.now(TZ_TPE)
            days_ahead = (7 - now_dt.weekday()) % 7
            target_date = now_dt.date() + timedelta(days=days_ahead)
            target = datetime.combine(target_date, time(1,15), tzinfo=TZ_TPE)
            if target <= now_dt:
                target += timedelta(days=7)
            await asyncio.sleep(max(1.0, (target - now_dt).total_seconds()))
            if _xiaoxia_calendar_config_status().get("configured"):
                await _xiaoxia_calendar_review_next_week()
                print("📅 [XIAOXIA_CALENDAR_WEEKLY_PLANNER] review completed")
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            print(f"⚠️ [XIAOXIA_CALENDAR_WEEKLY_PLANNER_FAILED] {type(exc).__name__}: {exc}")
            await asyncio.sleep(60)

async def _handle_xiaoxia_calendar_message_direct(message):
    """
    v1.10.32 MVP commands:
      /小俠月曆
      /小俠月曆 狀態
      /小俠月曆 測試
      /小俠月曆 未來14天
      /小俠月曆 本週
      /小俠月曆 下週

    此版只驗證 Zeabur 與女友小俠 Calendar 的獨立 OAuth CRUD，
    尚不接 weekly planner / autonomy 排程，避免一次改太多。
    """
    content = str(getattr(message, "content", "") or "").strip()
    if not re.match(r"^/小俠月曆(?:\s+|$)", content, flags=re.IGNORECASE):
        return False

    if not _is_girlfriend_xiaoxia_channel(message.channel):
        await message.channel.send("大俠，`/小俠月曆` 目前只在女友小俠頻道使用。")
        return True

    raw = re.sub(r"^/小俠月曆(?:\s+|$)", "", content, flags=re.IGNORECASE).strip()
    status = _xiaoxia_calendar_config_status()

    if raw in {"", "help", "幫助", "說明"}:
        configured_text = "✅ 已設定" if status["configured"] else "❌ 尚缺：" + ", ".join(status["missing"])
        await message.channel.send(
            "📅 **小俠月曆 v1.10.32 MVP**\n"
            f"OAuth 環境變數：{configured_text}\n"
            f"Calendar ID：`{status['calendar_id']}`\n\n"
            "可用：\n"
            "• `/小俠月曆 狀態`\n"
            "• `/小俠月曆 測試` → Zeabur 端執行讀取/新增/修改/刪除並自動清理\n"
            "• `/小俠月曆 更新` → 同步14天快取＋近3天摘要＋今日主線\n"
            "• `/小俠月曆 規劃14天` → 以現有生活活動庫排未來兩週\n"
            "• `/小俠月曆 review` → Review 下一週並補齊兩週滾動視窗\n"
            "• `/小俠月曆 未來14天`\n"
            "• `/小俠月曆 本週`\n"
            "• `/小俠月曆 下週`\n\n"
            "v1.10.33：聊天會讀近3天行程與今日活動主線。"
        )
        return True

    if raw in {"狀態", "status"}:
        if not status["configured"]:
            await message.channel.send(
                "📅 **小俠月曆連線狀態：未完成**\n"
                "缺少：" + ", ".join(f"`{x}`" for x in status["missing"])
            )
            return True
        try:
            events = await _xiaoxia_calendar_list_events(
                datetime.now(TZ_TPE),
                datetime.now(TZ_TPE) + timedelta(days=1),
                max_results=3,
            )
            cache = _xiaoxia_calendar_load(XIAOXIA_CALENDAR_CACHE_PATH)
            context = _xiaoxia_calendar_load(XIAOXIA_CALENDAR_CONTEXT_PATH)
            mainline = _xiaoxia_calendar_load(XIAOXIA_DAILY_MAINLINE_PATH)
            await message.channel.send(
                "📅 **小俠月曆連線狀態：✅ 正常**\n"
                f"Calendar ID：`{status['calendar_id']}`\n"
                f"Scope：`{status['scope']}`\n"
                f"未來 24 小時可讀事件：{len(events)} 筆\n"
                f"14天快取最後更新：`{cache.get('updated_at') or '尚未建立'}`\n"
                f"14天快取事件：{cache.get('event_count', 0)} 筆\n"
                f"近3天摘要：{'✅' if context else '尚未建立'}\n"
                f"今日主線：{'✅' if mainline and mainline.get('date') == datetime.now(TZ_TPE).strftime('%Y-%m-%d') else '尚未建立'}"
            )
        except Exception as exc:
            await message.channel.send(
                "📅 **小俠月曆連線狀態：❌ 失敗**\n"
                f"`{type(exc).__name__}: {str(exc)[:1300]}`"
            )
        return True

    if raw in {"規劃14天", "規劃兩週", "planner", "plan14"}:
        msg = await message.channel.send("📅 小俠正在把未來兩週生活排進 Google Calendar；既有行程不會被覆蓋……")
        try:
            result = await _xiaoxia_calendar_plan_14_days()
            created = result.get("created") or []
            preview = "\n".join(f"• {r.get('date')} {str(r.get('start') or '')[11:16]}｜{r.get('title')}" for r in created[:12])
            more = f"\n…另有 {len(created)-12} 筆" if len(created) > 12 else ""
            await msg.edit(content="✅ **小俠兩週 Planner 完成**\n" + f"新增活動：{len(created)} 筆\n" + (preview or "沒有需要新增的活動。") + more + "\n\n既有 Calendar 行程保留不動；週末只排 0～1 個自主活動。")
        except Exception as exc:
            await msg.edit(content=f"❌ 兩週 Planner 失敗：`{type(exc).__name__}: {str(exc)[:1500]}`")
        return True

    if raw in {"review", "檢查", "週檢查", "review下週"}:
        msg = await message.channel.send("📅 小俠正在 review 下一週 Calendar，並補齊兩週滾動生活視窗……")
        try:
            result = await _xiaoxia_calendar_review_next_week()
            await msg.edit(content=(
                "✅ **小俠 Calendar Review 完成**\n"
                f"下一週既有事件：{len(result.get('reviewed') or [])} 筆\n"
                f"鎖定事件：{len(result.get('locked') or [])} 筆\n"
                f"本次補入活動：{len(result.get('planner_created') or [])} 筆\n"
                "目前採保守模式：Calendar 現況就是權威，不自動移動或刪除大俠已調整事件。"
            ))
        except Exception as exc:
            await msg.edit(content=f"❌ Calendar Review 失敗：`{type(exc).__name__}: {str(exc)[:1500]}`")
        return True

    if raw in {"更新", "refresh", "同步"}:
        wait_msg = await message.channel.send("📅 小俠正在同步 Google Calendar：未來14天快取 → 近3天摘要 → 今日活動主線……")
        try:
            result = await _xiaoxia_calendar_refresh_cache(reason="discord_manual_refresh", regenerate_today=True)
            cache = result.get("cache") or {}
            daily = result.get("daily_mainline") or {}
            await wait_msg.edit(content=(
                "✅ **小俠月曆已更新**\n"
                f"未來14天事件：{cache.get('event_count', 0)} 筆\n"
                f"快取時間：`{cache.get('updated_at')}`\n"
                f"今日主線活動：{len(daily.get('activities') or [])} 筆"
            ))
        except Exception as exc:
            await wait_msg.edit(content=f"❌ 小俠月曆更新失敗：`{type(exc).__name__}: {str(exc)[:1500]}`")
        return True

    if raw in {"測試", "test"}:
        if not status["configured"]:
            await message.channel.send(
                "❌ 小俠月曆環境變數尚未完整："
                + ", ".join(f"`{x}`" for x in status["missing"])
            )
            return True
        wait_msg = await message.channel.send(
            "🧪 小俠正在從 **Zeabur** 測試自己的 Google Calendar：讀取 → 新增 → 修改 → 刪除……"
        )
        try:
            result = await _xiaoxia_calendar_connection_test()
            await wait_msg.edit(
                content=(
                    "✅ **小俠 Google Calendar｜Zeabur 端完整測試通過**\n"
                    f"讀取：{'✅' if result.get('list_ok') else '❌'} "
                    f"（原有近期事件 {result.get('existing_count', 0)} 筆）\n"
                    f"新增：{'✅' if result.get('create_ok') else '❌'}\n"
                    f"修改：{'✅' if result.get('update_ok') else '❌'}\n"
                    f"刪除：{'✅' if result.get('delete_ok') else '❌'}\n\n"
                    "測試活動已自動刪除；沒有在小俠月曆留下垃圾。"
                )
            )
        except Exception as exc:
            await wait_msg.edit(
                content=(
                    "❌ **小俠 Google Calendar｜Zeabur 端測試失敗**\n"
                    f"`{type(exc).__name__}: {str(exc)[:1500]}`"
                )
            )
        return True

    now_dt = datetime.now(TZ_TPE)
    if raw in {"未來14天", "14天", "未來兩週"}:
        start_dt = now_dt
        end_dt = now_dt + timedelta(days=14)
        label = "未來 14 天"
    elif raw in {"本週", "這週"}:
        start_date = now_dt.date() - timedelta(days=now_dt.weekday())
        start_dt = datetime.combine(start_date, time.min, tzinfo=TZ_TPE)
        end_dt = start_dt + timedelta(days=7)
        label = "本週"
    elif raw in {"下週"}:
        start_date = now_dt.date() - timedelta(days=now_dt.weekday()) + timedelta(days=7)
        start_dt = datetime.combine(start_date, time.min, tzinfo=TZ_TPE)
        end_dt = start_dt + timedelta(days=7)
        label = "下週"
    else:
        await message.channel.send(
            "我現在先支援：`/小俠月曆 狀態`、`測試`、`未來14天`、`本週`、`下週`。"
        )
        return True

    try:
        events = await _xiaoxia_calendar_list_events(start_dt, end_dt, max_results=80)
    except Exception as exc:
        await message.channel.send(
            f"❌ 讀取小俠月曆失敗：`{type(exc).__name__}: {str(exc)[:1300]}`"
        )
        return True

    if not events:
        await message.channel.send(f"📅 **小俠月曆｜{label}**\n目前沒有任何已排定行程。")
        return True

    rows = []
    for event in events[:30]:
        title = _clean_text_compact(event.get("summary") or "未命名行程")
        start_text = _xiaoxia_calendar_event_start_text(event)
        rows.append(f"• **{start_text}**｜{title}")

    more = ""
    if len(events) > 30:
        more = f"\n…另有 {len(events) - 30} 筆未顯示。"
    await message.channel.send(
        f"📅 **小俠月曆｜{label}**\n" + "\n".join(rows) + more
    )
    return True


# ==========================================
# 🧭 v1.4.82：Generation Trace Framework
# ==========================================
def _new_generation_trace_id(kind="gen"):
    safe_kind = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(kind or "gen")).strip("_") or "gen"
    return f"{safe_kind}_{datetime.now(TZ_TPE).strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:8]}"


def _trace_preview(value, limit=1200):
    text = str(value or "")
    text = re.sub(r"\s+", " ", text).strip()
    if len(text) > limit:
        return text[:limit] + "…"
    return text


def _trace_sanitize(value, *, depth=0, max_str=5000):
    """避免 trace 把超長 prompt / 大型 dict 撐爆；完整 final prompt 仍會保留到 5000 字。"""
    if depth > 5:
        return _trace_preview(value, 800)
    if isinstance(value, str):
        return value if len(value) <= max_str else value[:max_str] + "…[TRUNCATED]"
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    if isinstance(value, dict):
        cleaned = {}
        for k, v in list(value.items())[:80]:
            key = str(k)
            if key in {"__trace_context"}:
                continue
            cleaned[key] = _trace_sanitize(v, depth=depth + 1, max_str=max_str)
        return cleaned
    if isinstance(value, (list, tuple)):
        return [_trace_sanitize(v, depth=depth + 1, max_str=max_str) for v in list(value)[:80]]
    return _trace_preview(value, 1000)


def _trace_stage(trace_context, stage, data=None, prompt=None, note=""):
    if not isinstance(trace_context, dict):
        return None
    trace_context.setdefault("trace_id", _new_generation_trace_id(trace_context.get("kind") or "gen"))
    trace_context.setdefault("created_at", datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"))
    trace_context["updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
    history = trace_context.setdefault("prompt_history", [])
    entry = {
        "time": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "stage": str(stage or "stage"),
    }
    if note:
        entry["note"] = str(note)
    if prompt is not None:
        entry["prompt"] = _trace_sanitize(str(prompt), max_str=8000)
        entry["prompt_preview"] = _trace_preview(prompt, 500)
    if data is not None:
        entry["data"] = _trace_sanitize(data)
    history.append(entry)
    # 保留最後 40 個階段，避免 More / 重試反覆後過長。
    if len(history) > 40:
        del history[:-40]
    return entry


def _write_generation_trace(kind, trace_context, extra=None):
    if not isinstance(trace_context, dict):
        return None
    try:
        os.makedirs(GENERATION_TRACE_DIR, exist_ok=True)
        kind = str(kind or trace_context.get("kind") or "generation").strip().lower()
        trace_context["kind"] = kind
        trace_context["updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        payload = _trace_sanitize(trace_context)
        if isinstance(extra, dict):
            payload.update(_trace_sanitize(extra))
        line = json.dumps(payload, ensure_ascii=False)
        for path in (GENERATION_TRACE_ALL_PATH, GENERATION_TRACE_KIND_PATHS.get(kind)):
            if path:
                with open(path, "a", encoding="utf-8") as f:
                    f.write(line + "\n")
        latest = _load_json_file_or_default(GENERATION_TRACE_LATEST_PATH, {}) if os.path.exists(GENERATION_TRACE_LATEST_PATH) else {}
        if not isinstance(latest, dict):
            latest = {}
        latest[kind] = payload
        latest["last"] = payload
        with open(GENERATION_TRACE_LATEST_PATH, "w", encoding="utf-8") as f:
            json.dump(latest, f, ensure_ascii=False, indent=2)
        print(f"🧭 [GENERATION_TRACE_WRITTEN] kind={kind} trace_id={payload.get('trace_id')} path={GENERATION_TRACE_KIND_PATHS.get(kind)}")
        return payload
    except Exception as exc:
        print(f"⚠️ [GENERATION_TRACE_WRITE_FAILED] {type(exc).__name__}: {exc}")
        return None


def _load_recent_generation_traces(kind=None, limit=3):
    kind = str(kind or "all").strip().lower()
    path = GENERATION_TRACE_ALL_PATH if kind in {"", "all", "最近", "latest"} else GENERATION_TRACE_KIND_PATHS.get(kind, GENERATION_TRACE_ALL_PATH)
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.readlines()[-max(1, int(limit or 3)):]
        rows = []
        for line in lines:
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except Exception:
                pass
        return rows
    except Exception as exc:
        print(f"⚠️ [GENERATION_TRACE_READ_FAILED] {type(exc).__name__}: {exc}")
        return []


def _format_trace_for_discord(trace):
    if not isinstance(trace, dict):
        return "（trace 格式錯誤）"
    lines = []
    lines.append(f"kind={trace.get('kind')} trace_id={trace.get('trace_id')}")
    lines.append(f"time={trace.get('created_at')} → {trace.get('updated_at')}")
    for key in ["action", "source_mode", "photo_mode_override", "pose_critical", "raw_seedream_mode", "allow_background_bystanders", "diary_allow_background_bystanders", "user_input", "scene_seed_text", "scene_summary", "action_summary", "wardrobe_id", "wardrobe_mode", "used_pending_wardrobe", "current_outfit_for_seedream", "result_url", "seedream_model_label", "seedream_model_id", "final_level", "people_policy", "strict_solo_required", "specified_character_interaction", "error"]:
        val = trace.get(key)
        if val not in (None, "", [], {}):
            lines.append(f"{key}: {_trace_preview(val, 180)}")
    for gate_key in ["solo_gate_result", "adherence_gate_result", "adherence_gate_violation"]:
        val = trace.get(gate_key)
        if val not in (None, "", [], {}):
            lines.append(f"{gate_key}: {_trace_preview(val, 320)}")
    imgs = trace.get("seedream_input_images")
    if imgs:
        lines.append(f"seedream_input_images: count={len(imgs)} last={_trace_preview(imgs[-1], 120)}")
    stages = trace.get("prompt_history") or []
    if stages:
        lines.append("stages:")
        for st in stages[-10:]:
            stage = st.get("stage")
            preview = st.get("prompt_preview") or _trace_preview(st.get("prompt") or st.get("data"), 220)
            lines.append(f"- {stage}: {preview}")
    text = "\n".join(lines)
    return text[:1800]


def _wardrobe_visual_summary_only(item_or_text):
    """衣櫃文字進入穿搭連續狀態時，只保留視覺資訊，移除『適合夜景/居家』等場景建議。"""
    if isinstance(item_or_text, dict):
        text = str(item_or_text.get("style_summary") or item_or_text.get("name") or "")
    else:
        text = str(item_or_text or "")
    text = _clean_text_compact(text)
    if not text:
        return ""
    # 移除常見「適合...場景」句段；避免 W096 這類衣櫃摘要在第二次 /photo 把場景拉回夜景。
    text = re.sub(r"(?:，|。|；|;)?\s*整體風格[^。；;]*適合[^。；;]*[。；;]?", "", text)
    text = re.sub(r"(?:，|。|；|;)?\s*適合[^。；;]*[。；;]?", "", text)
    text = re.sub(r"\s+", " ", text).strip(" ，。；;")
    return text


