def _get_autonomy_today_diary_candidate(entry_date):
    """若今天已有 /小俠自主 新生圖，可作為交換日記的自動候選圖。"""
    try:
        state = load_xiaoxia_autonomy_state()
    except Exception:
        return None
    today = state.get("today") if isinstance(state, dict) else None
    if not isinstance(today, dict):
        return None
    if str(today.get("date") or "") != str(entry_date or ""):
        return None
    photo_url = str(today.get("photo_url") or "").strip()
    if not photo_url or not today.get("photo_sent"):
        return None
    activity_title = str(today.get("activity_title") or "小俠自主生活").strip() or "小俠自主生活"
    composition = str(today.get("scene") or today.get("activity_title") or "").strip()
    if not composition:
        composition = f"小俠今天的自主活動：{activity_title}"
    return {
        "image_url": photo_url,
        "composition": composition,
        "source": "xiaoxia_autonomy_auto",
        "source_module": "autonomy",
        "image_role": "autonomy_today_image",
        "message": str(today.get("share_text") or "").strip(),
        "activity_id": str(today.get("activity_id") or "").strip(),
        "activity_title": activity_title,
        "episode_id": str(today.get("episode_id") or "").strip(),
        "uploaded_at": str(today.get("sent_at") or "").strip(),
    }


def _load_json_file_or_default(path, default):
    try:
        if not os.path.exists(path):
            return default
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return default


def load_diary_wardrobe_prefs():
    data = _load_json_file_or_default(DIARY_WARDROBE_PREFS_PATH, {})
    return data if isinstance(data, dict) else {}


def save_diary_wardrobe_prefs(data):
    with open(DIARY_WARDROBE_PREFS_PATH, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def _prune_diary_wardrobe_prefs(data, keep_days=7):
    if not isinstance(data, dict):
        return {}
    today = datetime.now(TZ_TPE).date()
    cleaned = {}
    for key, value in data.items():
        try:
            dt = datetime.strptime(str(key), "%Y-%m-%d").date()
        except Exception:
            continue
        if abs((today - dt).days) <= keep_days:
            cleaned[str(key)] = value
    return cleaned


def set_diary_wardrobe_pref(mode, wardrobe_id=None, target_date=None, scene_request=None):
    date_key = target_date or datetime.now(TZ_TPE).strftime("%Y-%m-%d")
    data = _prune_diary_wardrobe_prefs(load_diary_wardrobe_prefs())
    payload = {
        "mode": str(mode or "").strip(),
        "wardrobe_id": str(wardrobe_id or "").strip().upper(),
        "scene_request": _clean_text_compact(scene_request or ""),
        "updated_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
    }
    data[date_key] = payload
    save_diary_wardrobe_prefs(data)
    return payload


def get_diary_wardrobe_pref(target_date=None):
    date_key = target_date or datetime.now(TZ_TPE).strftime("%Y-%m-%d")
    data = _prune_diary_wardrobe_prefs(load_diary_wardrobe_prefs())
    if data != load_diary_wardrobe_prefs():
        save_diary_wardrobe_prefs(data)
    pref = data.get(date_key)
    return pref if isinstance(pref, dict) else None


def get_latest_diary_scene_pref(max_age_hours=36):
    """
    v1479 safety net:
    If the diary entry date and the command date do not match exactly because of timing,
    still use the latest explicit /交換日記 scene request within a short window.
    """
    data = _prune_diary_wardrobe_prefs(load_diary_wardrobe_prefs())
    latest = None
    latest_dt = None
    now = datetime.now(TZ_TPE)
    for date_key, pref in data.items():
        if not isinstance(pref, dict):
            continue
        scene = str(pref.get("scene_request") or "").strip()
        if not scene:
            continue
        updated_raw = str(pref.get("updated_at") or "").strip()
        try:
            dt = datetime.strptime(updated_raw, "%Y-%m-%d %H:%M:%S").replace(tzinfo=TZ_TPE)
        except Exception:
            try:
                dt = datetime.strptime(str(date_key), "%Y-%m-%d").replace(tzinfo=TZ_TPE)
            except Exception:
                continue
        if latest_dt is None or dt > latest_dt:
            latest = pref
            latest_dt = dt
    if not latest or not latest_dt:
        return None
    if (now - latest_dt).total_seconds() > max_age_hours * 3600:
        return None
    return latest


WARDROBE_FORMALITY_TAGS = ("居家", "休閒", "Smart Casual", "輕正式", "正式", "禮服")
WARDROBE_SEASON_TAGS = ("春夏", "秋冬", "四季")
WARDROBE_OCCASION_TAGS = ("社交", "休閒", "居家", "商務", "正式", "晚宴", "旅遊", "運動", "泳裝", "睡眠", "內著", "Cosplay")


def _wardrobe_semantic_profile(item):
    """由既有欄位推導選衣語意；不回寫 xiaoxia_wardrobe.json。"""
    if not isinstance(item, dict):
        return {"formality": [], "season": [], "occasion": [], "style": []}
    text = " ".join([
        str(item.get("name") or ""), str(item.get("main_category") or ""),
        str(item.get("sub_category") or ""), " ".join(str(x) for x in (item.get("tags") or [])),
        str(item.get("style_summary") or ""),
    ]).lower()
    main = str(item.get("main_category") or "")
    formality=[]; season=[]; occasion=[]; style=[]
    def add(bucket, value):
        if value and value not in bucket: bucket.append(value)
    if any(k in text for k in ["禮服", "晚宴", "宴會", "華麗"]): add(formality,"禮服"); add(occasion,"晚宴")
    elif any(k in text for k in ["西裝", "正式", "商務", "套裝", "襯衫"]): add(formality,"正式" if "正式" in text or "商務" in text else "輕正式")
    elif any(k in text for k in ["優雅", "知性", "精緻", "高跟鞋", "洋裝", "裙裝套裝"]): add(formality,"輕正式")
    elif main in {"睡衣／居家服", "內衣"}: add(formality,"居家")
    else: add(formality,"休閒")
    if any(k in text for k in ["毛呢", "針織", "長袖", "厚實", "羊毛", "冬", "保暖"]): add(season,"秋冬")
    elif any(k in text for k in ["雪紡", "薄紗", "無袖", "短袖", "細肩帶", "春夏", "清涼"]): add(season,"春夏")
    else: add(season,"四季")
    if main == "內衣": add(occasion,"內著")
    elif main == "泳裝": add(occasion,"泳裝")
    elif main == "睡衣／居家服": add(occasion,"睡眠" if any(k in text for k in ["睡衣","睡裙","睡袍"]) else "居家")
    elif any(k in text for k in ["運動", "瑜伽", "瑜珈", "健身", "網球", "泳"]): add(occasion,"運動")
    elif any(k in text for k in ["商務", "辦公", "職場", "西裝"]): add(occasion,"商務")
    elif any(k in text for k in ["晚宴", "禮服", "宴會"]): add(occasion,"晚宴")
    elif any(k in text for k in ["旅行", "度假", "旅遊", "戶外"]): add(occasion,"旅遊")
    elif main in {"洋裝","套裝","上衣","下身","外套","鞋子","包包","配件"}: add(occasion,"社交" if any(k in text for k in ["優雅","知性","精緻","高跟鞋","鍊條包","洋裝"]) else "休閒")
    for label, kws in {
        "優雅":["優雅","柔美","雪紡","百褶"], "甜美":["甜美","蝴蝶結","荷葉","粉色"],
        "知性":["知性","襯衫","學院"], "性感":["性感","蕾絲","鏤空","透膚","低胸"],
        "休閒":["休閒","牛仔","t恤","棉質"], "俐落":["俐落","西裝","剪裁"],
    }.items():
        if any(k in text for k in kws): add(style,label)
    return {"formality":formality[:2], "season":season[:1], "occasion":occasion[:2], "style":style[:4]}


def _wardrobe_semantic_fingerprint(item):
    raw = json.dumps({k:item.get(k) for k in ("id","name","main_category","sub_category","tags","style_summary")}, ensure_ascii=False, sort_keys=True)
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()


def _load_or_refresh_wardrobe_semantic_cache(items=None):
    items = items if isinstance(items, list) else load_wardrobe()
    cache = _load_json_file_or_default(WARDROBE_SEMANTIC_CACHE_PATH, {})
    if not isinstance(cache, dict): cache = {}
    changed=False; valid_ids=set()
    for item in items:
        if not isinstance(item, dict): continue
        wid=str(item.get("id") or "").strip().upper()
        if not wid: continue
        valid_ids.add(wid); fp=_wardrobe_semantic_fingerprint(item)
        row=cache.get(wid) if isinstance(cache.get(wid),dict) else {}
        if row.get("fingerprint") != fp:
            cache[wid]={"fingerprint":fp, "semantic":_wardrobe_semantic_profile(item), "updated_at":datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")}
            changed=True
    for wid in list(cache):
        if wid not in valid_ids: del cache[wid]; changed=True
    if changed:
        try:
            with open(WARDROBE_SEMANTIC_CACHE_PATH,"w",encoding="utf-8") as f: json.dump(cache,f,ensure_ascii=False,indent=2)
        except Exception as exc: print(f"⚠️ [WARDROBE_SEMANTIC_CACHE_WRITE_FAILED] {type(exc).__name__}: {exc}")
    return cache


def _compact_wardrobe_brief(item, semantic_cache=None):
    if not isinstance(item, dict):
        return {}
    wid=str(item.get("id") or "").strip().upper()
    semantic_cache = semantic_cache if isinstance(semantic_cache,dict) else _load_or_refresh_wardrobe_semantic_cache([item])
    semantic=((semantic_cache.get(wid) or {}).get("semantic") if isinstance(semantic_cache.get(wid),dict) else None) or _wardrobe_semantic_profile(item)
    return {
        "id": wid,
        "name": str(item.get("name") or "").strip(),
        "main_category": str(item.get("main_category") or "").strip(),
        "sub_category": str(item.get("sub_category") or "").strip(),
        "tags": [str(x).strip() for x in (item.get("tags") or []) if str(x).strip()][:14],
        "style_summary": str(item.get("style_summary") or "").strip(),
        "semantic": semantic,
    }


def _recent_wardrobe_usage(limit=50):
    entries = load_wardrobe_usage_log()
    if not isinstance(entries, list):
        return []
    valid = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        if not wid:
            continue
        valid.append(entry)
    return valid[-limit:]


def _wardrobe_rotation_noise_purpose(purpose):
    purpose = str(purpose or "").strip().lower()
    return purpose in {"photo_more", "photo_reroll", "photobook_more_camera"}


def _filtered_recent_wardrobe_usage_for_rotation(recent_entries=None):
    recent_entries = recent_entries or _recent_wardrobe_usage(50)
    filtered = []
    for entry in recent_entries:
        if not isinstance(entry, dict):
            continue
        if _wardrobe_rotation_noise_purpose(entry.get("purpose") or ""):
            continue
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        if not wid:
            continue
        filtered.append(entry)
    return filtered


def _wardrobe_recent_usage_sets(recent_entries=None):
    recent_entries = _filtered_recent_wardrobe_usage_for_rotation(recent_entries)
    last_10_ids = []
    today = datetime.now(TZ_TPE).date()
    recent_3day_ids = set()
    for entry in reversed(recent_entries[-10:]):
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        if wid and wid not in last_10_ids:
            last_10_ids.append(wid)
    for entry in recent_entries:
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        ds = str(entry.get("date") or "").strip()
        if not wid or not ds:
            continue
        try:
            used_date = datetime.strptime(ds, "%Y-%m-%d").date()
        except Exception:
            continue
        delta = (today - used_date).days
        if 0 <= delta <= 2:
            recent_3day_ids.add(wid)
    return recent_3day_ids, set(last_10_ids), last_10_ids


def _autonomy_wardrobe_rotation_state(recent_entries=None):
    recent_entries = _filtered_recent_wardrobe_usage_for_rotation(recent_entries or _recent_wardrobe_usage(80))
    today = datetime.now(TZ_TPE).date()
    today_ids = set()
    recent_3day_ids = set()
    recent_7day_ids = set()
    recent_7day_autonomy_ids = set()
    last_10_ids = []
    for entry in reversed(recent_entries[-14:]):
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        if wid and wid not in last_10_ids:
            last_10_ids.append(wid)
    for entry in recent_entries:
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        ds = str(entry.get("date") or "").strip()
        purpose = str(entry.get("purpose") or "").strip().lower()
        if not wid or not ds:
            continue
        try:
            used_date = datetime.strptime(ds, "%Y-%m-%d").date()
        except Exception:
            continue
        delta = (today - used_date).days
        if delta < 0:
            continue
        if delta == 0:
            today_ids.add(wid)
        if delta <= 2:
            recent_3day_ids.add(wid)
        if delta <= 6:
            recent_7day_ids.add(wid)
            if purpose.startswith("autonomy_"):
                recent_7day_autonomy_ids.add(wid)
    return {
        "recent_entries": recent_entries,
        "today_ids": today_ids,
        "recent_3day_ids": recent_3day_ids,
        "recent_7day_ids": recent_7day_ids,
        "recent_7day_autonomy_ids": recent_7day_autonomy_ids,
        "last_10_ids": last_10_ids,
        "last_10_ids_set": set(last_10_ids),
    }


def _summarize_recent_wardrobe_usage(recent_entries=None, limit=8):
    recent_entries = _filtered_recent_wardrobe_usage_for_rotation(recent_entries or _recent_wardrobe_usage(50))
    lines = []
    seen = set()
    for entry in reversed(recent_entries):
        wid = str(entry.get("wardrobe_id") or "").strip().upper()
        if not wid or wid in seen:
            continue
        seen.add(wid)
        name = str(entry.get("name") or "").strip()
        purpose = str(entry.get("purpose") or "").strip()
        scene = _clean_text_compact(entry.get("scene") or "")
        date = str(entry.get("date") or "").strip()
        lines.append(f"- {wid} {name}｜{date}｜{purpose}｜{scene[:40]}")
        if len(lines) >= limit:
            break
    return "\n".join(lines) if lines else "- 無"


def _log_wardrobe_usage(item, purpose="photo", scene_text="", extra=None, usage_date=None, usage_timestamp=None):
    if not isinstance(item, dict):
        return
    wid = str(item.get("id") or "").strip().upper()
    if not wid:
        return
    entries = load_wardrobe_usage_log()
    resolved_date = str(usage_date or "").strip()[:10] or _today_str_tpe()
    resolved_timestamp = str(usage_timestamp or "").strip()
    if not resolved_timestamp:
        now_text = datetime.now(TZ_TPE).strftime("%H:%M:%S")
        resolved_timestamp = f"{resolved_date} {now_text}"
    payload = {
        "timestamp": resolved_timestamp,
        "date": resolved_date,
        "wardrobe_id": wid,
        "name": str(item.get("name") or "").strip(),
        "main_category": str(item.get("main_category") or "").strip(),
        "sub_category": str(item.get("sub_category") or "").strip(),
        "purpose": str(purpose or "photo"),
        "scene": _clean_text_compact(scene_text or ""),
    }
    if isinstance(extra, dict):
        for k, v in extra.items():
            if v is None:
                continue
            payload[str(k)] = v
    entries.append(payload)
    save_wardrobe_usage_log(entries)


def _fallback_free_wardrobe_pick(scene_text, items, hard_exclude_ids=None, soft_avoid_ids=None):
    usable = []
    hard_exclude_ids = set(hard_exclude_ids or [])
    soft_avoid_ids = set(soft_avoid_ids or [])
    for item in items or []:
        ref_path, _ref_url = _wardrobe_reference_for_generation(item)
        if ref_path:
            usable.append(item)
    if not usable:
        return None

    hay = str(scene_text or "")
    preferred = []
    if any(k in hay for k in ["泳", "海邊", "泳池", "溫泉", "比基尼"]):
        preferred = ["泳裝"]
    elif any(k in hay for k in ["床", "臥室", "睡", "燭光", "居家", "沙發", "夜裡"]):
        preferred = ["睡衣／居家服", "內衣"]
    elif any(k in hay for k in ["夜景", "餐廳", "約會", "晚餐", "外出", "街", "咖啡"]):
        preferred = ["洋裝", "套裝", "上衣"]
    elif any(k in hay for k in ["運動", "健身", "瑜伽", "跑步"]):
        preferred = ["套裝", "上衣", "下身"]

    pool = usable
    if preferred:
        filtered = [it for it in usable if str(it.get("main_category") or "") in preferred]
        if filtered:
            pool = filtered

    pool_hard = [it for it in pool if str(it.get("id") or "").strip().upper() not in hard_exclude_ids] or pool
    pool_soft = [it for it in pool_hard if str(it.get("id") or "").strip().upper() not in soft_avoid_ids] or pool_hard
    return random.choice(pool_soft)


async def _choose_wardrobe_item_for_free_mode(scene_text, purpose="photo"):
    items = load_wardrobe()
    usable = []
    for item in items:
        ref_path, _ref_url = _wardrobe_reference_for_generation(item)
        if ref_path:
            usable.append(item)
    if not usable:
        return None

    recent_entries = _filtered_recent_wardrobe_usage_for_rotation(_recent_wardrobe_usage(50))
    recent_3day_ids, last_10_ids_set, last_10_ids_ordered = _wardrobe_recent_usage_sets(recent_entries)
    candidate_items = [it for it in usable if str(it.get("id") or "").strip().upper() not in recent_3day_ids] or usable

    semantic_cache = _load_or_refresh_wardrobe_semantic_cache(usable)
    catalog = [_compact_wardrobe_brief(item, semantic_cache) for item in candidate_items]
    recent_summary = _summarize_recent_wardrobe_usage(recent_entries, limit=8)
    prompt = f"""
你是小俠的穿搭挑選助理。請根據需求，從衣櫃中挑出最適合的一件。

模式：{purpose}
需求描述：{str(scene_text or '').strip() or '小俠依今天心情自由發揮'}

最近穿搭紀錄（避免一直重複）：
{recent_summary}

規則：
1. 只能從提供的衣櫃清單中挑一個 existing wardrobe_id。
2. 不可自創不存在的 W 編號。
3. 最近 3 天穿過的同一件，原則上不要再選，除非候選非常少。
4. 最近 10 次內出現過的衣服，請降低優先權，讓整體更有輪替感。
5. 先從需求推論「場合屬性」，再判斷「正式程度」，接著判斷「季節與功能」，最後才考慮風格與顏色；不要只比對相同關鍵字。
6. 居家私密情境才可考慮睡衣／居家服或內衣；公開社交情境優先社交、休閒、Smart Casual 或輕正式服裝。
7. 候選中的 semantic.formality／season／occasion／style 是程式從既有 JSON 推導的穿搭語意，可直接用於判斷，但不得讓衣服反過來改變本次場景。
8. 回答必須是 JSON：{{"wardrobe_id":"Wxxx","reason":"一句中文理由"}}

本次可選衣櫃清單：
{json.dumps(catalog, ensure_ascii=False)}
"""
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.45),
        )
        data = _extract_json_object(getattr(resp, 'text', '') or '')
        wid = str((data or {}).get("wardrobe_id") or "").strip().upper()
        if wid:
            picked = _find_wardrobe_item(wid)
            if picked and _wardrobe_reference_for_generation(picked)[0]:
                if wid not in recent_3day_ids:
                    return picked
                # 若模型仍選了近 3 日重複項，就先嘗試改用其他候選。
                alternates = [it for it in candidate_items if str(it.get("id") or "").strip().upper() != wid]
                if alternates:
                    softened = [it for it in alternates if str(it.get("id") or "").strip().upper() not in last_10_ids_set] or alternates
                    return random.choice(softened)
                return picked
    except Exception as exc:
        print(f"⚠️ [FREE_WARDROBE_PICK_FAILED] {type(exc).__name__}: {exc}")
    return _fallback_free_wardrobe_pick(scene_text, candidate_items, hard_exclude_ids=recent_3day_ids, soft_avoid_ids=last_10_ids_set)




