def _default_xiaoxia_autonomy_state():
    return {
        "version": 1,
        "enabled": False,
        "allow_work_hours": True,
        "max_photo_per_day": 1,
        "photo_probability_per_day": 0.75,
        "reward_photo_target_gap_days": 5,
        "last_reward_photo_date": "",
        "today": {},
        "history": [],
    }


def load_xiaoxia_activity_catalog():
    data = _load_json_file_or_default(XIAOXIA_ACTIVITY_CATALOG_PATH, None)
    default = [_autonomy_enrich_activity(x) for x in _default_xiaoxia_activity_catalog()]
    if isinstance(data, list) and data:
        # R4A：既有 Zeabur 檔案若只有舊活動庫，不覆蓋使用者手動修改，但自動補入新版內建活動。
        existing = [_autonomy_enrich_activity(x) for x in data if isinstance(x, dict)]
        seen = {str(x.get("id") or "") for x in existing}
        added = []
        for item in default:
            aid = str(item.get("id") or "")
            if aid and aid not in seen:
                existing.append(item)
                added.append(aid)
        if added:
            try:
                with open(XIAOXIA_ACTIVITY_CATALOG_PATH, "w", encoding="utf-8") as f:
                    json.dump(existing, f, ensure_ascii=False, indent=2)
                print(f"🌱 [AUTONOMY_CATALOG_MIGRATED] added={len(added)} ids={added[:12]}")
            except Exception as exc:
                print(f"⚠️ [AUTONOMY_CATALOG_MIGRATE_FAILED] {type(exc).__name__}: {exc}")
        return existing
    try:
        with open(XIAOXIA_ACTIVITY_CATALOG_PATH, "w", encoding="utf-8") as f:
            json.dump(default, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"⚠️ [AUTONOMY_CATALOG_INIT_FAILED] {type(exc).__name__}: {exc}")
    return default


def load_xiaoxia_autonomy_state():
    data = _load_json_file_or_default(XIAOXIA_AUTONOMY_STATE_PATH, {})
    base = _default_xiaoxia_autonomy_state()
    if isinstance(data, dict):
        base.update(data)
    if not isinstance(base.get("history"), list):
        base["history"] = []
    if not isinstance(base.get("today"), dict):
        base["today"] = {}
    return base


def save_xiaoxia_autonomy_state(data):
    base = _default_xiaoxia_autonomy_state()
    if isinstance(data, dict):
        base.update(data)
    if not isinstance(base.get("history"), list):
        base["history"] = []
    if not isinstance(base.get("today"), dict):
        base["today"] = {}
    # 避免歷史檔太大
    base["history"] = base["history"][-120:]
    with open(XIAOXIA_AUTONOMY_STATE_PATH, "w", encoding="utf-8") as f:
        json.dump(base, f, ensure_ascii=False, indent=2)


def xiaoxia_autonomy_context_for_prompt(now_dt=None):
    """
    v1.5.17 R3：讓一般聊天能接住 /小俠自主 今日 的身歷其境追問。
    這不是重大事件，也不是待辦；是今天已經發生、已經拍照分享的生活片段。
    """
    now_dt = now_dt or datetime.now(TZ_TPE)
    today_key = now_dt.strftime("%Y-%m-%d")
    try:
        state = load_xiaoxia_autonomy_state()
        today = state.get("today") if isinstance(state.get("today"), dict) else {}
        if not today or today.get("date") != today_key or not today.get("photo_sent"):
            return "今天尚未產生小俠自主活動照片。"
        activity_title = _clean_text_compact(today.get("activity_title") or "")
        activity_category = _clean_text_compact(today.get("activity_category") or "")
        visual_mode = _clean_text_compact(today.get("visual_mode") or "")
        scene = _clean_text_compact(today.get("scene") or "")
        wardrobe = _clean_text_compact(((today.get("wardrobe_id") or "") + " " + (today.get("wardrobe_name") or "")).strip())
        wardrobe_source_mode = _clean_text_compact(today.get("wardrobe_source_mode") or "")
        wardrobe_reason = _clean_text_compact(today.get("wardrobe_reason") or "")
        mood = _clean_text_compact(today.get("mood") or "")
        share_text = _clean_text_compact(today.get("share_text") or "")
        sent_at = _clean_text_compact(today.get("sent_at") or "")
        photo_url = _clean_text_compact(today.get("photo_url") or "")

        lines = [
            "【小俠今日自主活動｜身歷其境記憶】",
            "這是今天已經發生、且小俠已拍照分享給大俠的生活片段；不是待辦、不是幻想、不是大俠指派。",
            f"日期/時間：{today_key} {sent_at}",
            f"活動：{activity_title}（{activity_category}）",
            f"照片模式：{visual_mode}",
            f"場景：{scene}",
            f"穿搭：{wardrobe or ('今日使用自創服飾' if wardrobe_source_mode == 'generated_fallback' else '小俠依活動自由搭配')}",
            f"選衣理由：{wardrobe_reason}",
            f"心情/氛圍：{mood}",
            f"小俠當時對大俠的口語分享：{share_text}",
            f"照片網址：{photo_url}",
            "追問規則：若大俠接著問『如何』『好不好玩』『看到什麼』『聽到什麼』『喜歡哪一段』『照片在哪裡拍』等，妳必須以小俠親身經歷口吻自然承接，從上面的場景、穿搭、分享文字延伸所見所聞與體會；不要說不知道、不要說只是照片、不要重問大俠要妳做什麼、不要提 JSON/資料庫/系統。",
        ]
        return "\n".join([x for x in lines if x and not x.endswith("：")])
    except Exception as exc:
        print(f"⚠️ [AUTONOMY_CONTEXT_FAILED] {type(exc).__name__}: {exc}")
        return "今天自主活動狀態暫時讀取失敗；不要主動提及。"




