def _autonomy_theme_key_for_activity(activity):
    activity = activity if isinstance(activity, dict) else {}
    if activity.get("theme_key"):
        return str(activity.get("theme_key")).strip()
    aid = str(activity.get("id") or "").strip()
    category = str(activity.get("category") or "").strip()
    title = str(activity.get("title") or "").strip()
    hay = f"{aid} {category} {title}".lower()

    mapping = [
        ("campus_return", ["campus", "藝術史", "大學", "校園", "研究所", "旁聽"]),
        ("ai_learning", ["learn_ai", "ai", "人工智慧", "電腦"]),
        ("professional_teaching_ai", ["pro_ai", "社區大學", "教長者", "電腦教學"]),
        ("art_teacher", ["pro_art", "畫畫老師", "教小朋友畫畫"]),
        ("art_creation", ["art_paint", "畫畫", "水彩", "創作", "作品集"]),
        ("art_appreciation", ["gallery", "畫展", "美術館", "博物館", "展覽"]),
        ("concert_life", ["concert", "音樂會", "古典"]),
        ("gym_growth", ["gym", "健身房", "重量訓練", "重訓"]),
        ("pilates_growth", ["pilates", "皮拉提斯"]),
        ("running_growth", ["jogging", "慢跑", "跑步"]),
        ("cycling_growth", ["cycling", "腳踏車", "自行車", "河濱"]),
        ("badminton_growth", ["badminton", "羽球"]),
        ("hiking_growth", ["hiking", "健行", "郊山"]),
        ("boxing_fitness_growth", ["boxing", "拳擊有氧"]),
        ("barre_growth", ["barre", "芭蕾雕塑"]),
        ("yoga_growth", ["yoga", "瑜珈", "瑜伽", "嬋柔"]),
        ("dance_growth", ["kpop", "k-pop", "舞蹈", "dance"]),
        ("tennis_growth", ["tennis", "網球"]),
        ("swimming_growth", ["swimming", "游泳", "泳池"]),
        ("city_style", ["outlet", "百貨", "逛街", "香氛", "穿搭", "賣場"]),
        ("volunteer_service", ["volunteer", "志工", "醫院", "圖書館"]),
        ("home_life", ["home_baking", "甜點", "烘焙", "居家生活"]),
        ("reward_eye_candy_home", ["home_reward", "home_wardrobe", "養眼", "驚喜"]),
        ("micro_trip", ["micro_trip", "老街", "旅行", "散步"]),
    ]
    for key, kws in mapping:
        if any(str(k).lower() in hay for k in kws):
            return key
    # fallback：以類別建立主題線，避免空白。
    safe = re.sub(r"[^A-Za-z0-9_\u4e00-\u9fff]+", "_", category or aid or "general").strip("_")
    return "theme_" + safe


def _autonomy_continuity_group_for_activity(activity):
    activity = activity if isinstance(activity, dict) else {}
    if activity.get("continuity_group"):
        return str(activity.get("continuity_group")).strip()
    cat = str(activity.get("category") or "").strip()
    if cat in {"學習成長", "專業自主／教學工作"}:
        return "learning_work_growth"
    if cat in {"藝文創作", "藝文活動"}:
        return "art_culture_growth"
    if cat == "運動健康":
        return "body_health_growth"
    if cat == "公益志工":
        return "volunteer_service_growth"
    if cat in {"城市探索", "旅行微冒險"}:
        return "city_exploration_growth"
    if cat in {"居家生活", "給大俠的小驚喜"}:
        return "home_private_life"
    return "general_autonomy"


def _autonomy_enrich_activity(item):
    if not isinstance(item, dict):
        return item
    out = dict(item)
    out.setdefault("theme_key", _autonomy_theme_key_for_activity(out))
    out.setdefault("continuity_group", _autonomy_continuity_group_for_activity(out))
    return out


def _autonomy_time_bucket(now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    h = int(now_dt.hour)
    if 5 <= h < 11:
        return "morning", "早晨"
    if 11 <= h < 14:
        return "noon", "中午"
    if 14 <= h < 18:
        return "afternoon", "午後"
    if 18 <= h < 22:
        return "evening", "晚間"
    return "night", "夜裡"


def _autonomy_apply_time_context(activity, now_dt=None):
    """v1.5.20：活動名稱與場景要貼合實際觸發時間，避免晚上 8 點還說午後閱讀。"""
    item = _autonomy_enrich_activity(activity)
    if not isinstance(item, dict):
        return item
    bucket, label = _autonomy_time_bucket(now_dt)
    aid = str(item.get("id") or "")
    title = str(item.get("title") or "")
    seed = str(item.get("photo_prompt_seed") or "")

    if aid == "home_reading_afternoon" or "午後閱讀" in title:
        if bucket in {"evening", "night"}:
            item["title"] = "晚間閱讀" if bucket == "evening" else "睡前閱讀"
            item["photo_prompt_seed"] = "小俠在書房或窗邊沙發晚間閱讀，手邊有書與熱茶，燈光溫暖安靜，居家生活感清楚。"
        elif bucket == "morning":
            item["title"] = "晨間閱讀"
            item["photo_prompt_seed"] = "小俠在窗邊或書房晨間閱讀，手邊有書與溫茶，柔和晨光、安靜知性的居家氛圍。"
        else:
            item["title"] = "午後閱讀"
            item["photo_prompt_seed"] = seed or "小俠在書房或窗邊沙發閱讀，手邊有茶與書籤，安靜、知性、溫柔。"
    elif bucket in {"evening", "night"}:
        if "午後" in title:
            item["title"] = title.replace("午後", "晚間" if bucket == "evening" else "睡前")
        if "下午" in str(item.get("title") or ""):
            item["title"] = str(item.get("title") or "").replace("下午", "晚間" if bucket == "evening" else "夜裡")
        if "午後" in seed or "下午" in seed:
            item["photo_prompt_seed"] = seed.replace("午後", "晚間" if bucket == "evening" else "睡前").replace("下午", "晚間" if bucket == "evening" else "夜裡")

    # v1.5.20-R1：所有夜間/晚間活動都要修正光線邏輯，不只閱讀類。
    # 避免 20:00 以後仍出現明亮白天窗光、陽光灑落、柔和自然光等失真場景。
    seed2 = str(item.get("photo_prompt_seed") or "")
    if bucket in {"evening", "night"}:
        replacements = {
            "柔和自然光": "溫暖室內燈光",
            "自然光": "室內暖光",
            "陽光": "室內暖光",
            "晨光": "室內暖光",
            "午後光線": "晚間室內燈光",
            "白天": "晚間",
        }
        for k, v in replacements.items():
            seed2 = seed2.replace(k, v)
        if seed2 and not any(x in seed2 for x in ["夜", "晚間", "室內燈", "暖光", "窗外"]):
            seed2 += "，時間是晚間，窗外應是夜色或暗窗景，主要光源來自室內燈光。"
        elif seed2:
            seed2 += "，請符合當下晚間時間：窗外不能是明亮白天，主要光源來自室內暖燈或教室燈。"
        item["photo_prompt_seed"] = seed2

    item["time_bucket"] = bucket
    item["time_label"] = label
    return item


def _autonomy_all_categories(catalog=None):
    catalog = catalog or load_xiaoxia_activity_catalog()
    cats = []
    for item in catalog:
        cat = str((item or {}).get("category") or "").strip()
        if cat and cat not in cats:
            cats.append(cat)
    return cats


