def _autonomy_update_thread_from_episode(episode):
    if not isinstance(episode, dict):
        return
    theme_key = str(episode.get("theme_key") or "").strip()
    if not theme_key:
        return
    threads = load_xiaoxia_autonomy_threads()
    th = threads.get(theme_key) if isinstance(threads.get(theme_key), dict) else {}
    episode_ids = th.get("episode_ids") if isinstance(th.get("episode_ids"), list) else []
    if episode.get("episode_id") and episode.get("episode_id") not in episode_ids:
        episode_ids.append(episode.get("episode_id"))
    title = th.get("title") or _autonomy_thread_title(theme_key, episode)
    activity_title = episode.get("activity_title") or episode.get("title") or ""
    share = _clean_text_compact(episode.get("share_text") or "")
    previous_summary = _clean_text_compact(th.get("summary") or "")
    if previous_summary:
        summary = narrative_safe_text(previous_summary + " / 最新：" + activity_title + "，" + share, max_len=700)
    else:
        summary = narrative_safe_text(f"小俠曾進行「{activity_title}」。{share}", max_len=700)
    current_direction = th.get("current_direction") or ""
    if not current_direction:
        if theme_key == "campus_return":
            current_direction = "先多旁聽、多看看，慢慢確認自己是否想重新接近校園、創作或研究所方向。"
        elif "teaching" in theme_key or "teacher" in theme_key:
            current_direction = "嘗試把自己的能力輸出給別人，建立更成熟、能謀生與服務人的一面。"
        elif "growth" in theme_key:
            current_direction = "透過持續練習累積自信與身體/能力上的成長。"
        else:
            current_direction = "延續這個主題，讓小俠的生活不是每次重頭開始。"
    threads[theme_key] = {
        "title": title,
        "status": th.get("status") or "open",
        "category": episode.get("category") or th.get("category") or "",
        "continuity_group": episode.get("continuity_group") or th.get("continuity_group") or "",
        "last_episode_date": episode.get("date") or th.get("last_episode_date") or "",
        "episode_ids": episode_ids[-50:],
        "summary": summary,
        "current_direction": current_direction,
        "latest_episode_angle": episode.get("episode_angle") or th.get("latest_episode_angle") or "",
        "latest_progress": episode.get("new_progress") or episode.get("progress_focus") or th.get("latest_progress") or "",
        "latest_future_hook": episode.get("future_hook") or th.get("latest_future_hook") or "",
        "next_time_guidance": f"下次若再抽到或指定「{episode.get('activity_title') or title}」相關題材，必須推進一個新的生活片段：延續既有事實與感受，但避免重複上一回的主動作、核心事件、主要感想與照片構圖。",
        "updated_at": _board_now(),
    }
    save_xiaoxia_autonomy_threads(threads)


def _autonomy_append_episode(today_payload, activity, context=None):
    activity = _autonomy_enrich_activity(activity)
    now_dt = datetime.now(TZ_TPE)
    date_key = now_dt.strftime("%Y-%m-%d")
    activity_id = str(activity.get("id") or today_payload.get("activity_id") or "unknown")
    theme_key = _autonomy_theme_key_for_activity(activity)
    episode_id = f"AUTO_{now_dt.strftime('%Y%m%d_%H%M%S')}_{activity_id}"
    episode = {
        "episode_id": episode_id,
        "date": date_key,
        "created_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        "activity_id": activity_id,
        "activity_title": activity.get("title") or today_payload.get("activity_title") or "",
        "category": activity.get("category") or today_payload.get("activity_category") or "",
        "activity_mode": activity.get("activity_mode") or today_payload.get("activity_mode") or ("ad_hoc" if str(activity_id).startswith("ADHOC_") else "catalog"),
        "source": activity.get("source") or today_payload.get("source") or "",
        "theme_key": theme_key,
        "continuity_group": _autonomy_continuity_group_for_activity(activity),
        "visual_mode": today_payload.get("visual_mode") or "",
        "scene": today_payload.get("scene") or "",
        "mood": today_payload.get("mood") or "",
        "wardrobe_id": today_payload.get("wardrobe_id") or "",
        "wardrobe_name": today_payload.get("wardrobe_name") or "",
        "wardrobe_reason": today_payload.get("wardrobe_reason") or "",
        "share_text": today_payload.get("share_text") or "",
        # R16：輕量、可檢索的生活索引；未來按 theme/關鍵字查，不必常駐聊天 prompt。
        "episode_angle": today_payload.get("episode_angle") or "",
        "what_happened": today_payload.get("what_happened") or today_payload.get("episode_angle") or "",
        "new_progress": today_payload.get("new_progress") or today_payload.get("progress_focus") or "",
        "scene_focus": today_payload.get("scene_focus") or "",
        "future_hook": today_payload.get("future_hook") or "",
        "episode_planning_mode": today_payload.get("episode_planning_mode") or "",
        "photo_url": today_payload.get("photo_url") or "",
        "event_upgrade_potential": today_payload.get("event_upgrade_potential") or "",
        "followup_summaries": [],
    }
    rows = load_xiaoxia_autonomy_episode_log()
    rows.append(episode)
    save_xiaoxia_autonomy_episode_log(rows)
    _autonomy_update_thread_from_episode(episode)
    return episode


def _autonomy_update_latest_episode_followup(user_text, xiaoxia_reply, summary=None):
    try:
        state = load_xiaoxia_autonomy_state()
        today = state.get("today") if isinstance(state.get("today"), dict) else {}
        episode_id = today.get("episode_id")
        theme_key = today.get("theme_key")
        if not episode_id:
            return False
        rows = load_xiaoxia_autonomy_episode_log()
        target = None
        for row in rows:
            if isinstance(row, dict) and row.get("episode_id") == episode_id:
                target = row
                break
        if not target:
            return False
        entry = {
            "time": _board_now(),
            "user": narrative_safe_text(user_text, max_len=260),
            "xiaoxia_summary": narrative_safe_text(summary or xiaoxia_reply, max_len=360),
        }
        target.setdefault("followup_summaries", []).append(entry)
        target["followup_summaries"] = target["followup_summaries"][-20:]
        save_xiaoxia_autonomy_episode_log(rows)

        if theme_key:
            threads = load_xiaoxia_autonomy_threads()
            th = threads.get(theme_key) if isinstance(threads.get(theme_key), dict) else {}
            note = entry["xiaoxia_summary"]
            th["summary"] = narrative_safe_text((th.get("summary") or "") + " / 後續對話：" + note, max_len=800)
            th["last_followup_date"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d")
            th["updated_at"] = _board_now()
            threads[theme_key] = th
            save_xiaoxia_autonomy_threads(threads)
        return True
    except Exception as exc:
        print(f"⚠️ [AUTONOMY_FOLLOWUP_APPEND_FAILED] {type(exc).__name__}: {exc}")
        return False


def _autonomy_followup_relevant(user_text, today):
    if not isinstance(today, dict) or not today.get("episode_id"):
        return False
    raw = str(user_text or "")
    if not raw or raw.strip().startswith("/"):
        return False
    keys = [
        today.get("activity_title"), today.get("activity_category"), today.get("theme_key"),
        "剛剛", "今天", "那個", "活動", "照片", "如何", "怎麼", "為什麼", "原因", "計畫", "計劃", "收穫",
        "喜歡", "看到", "聽到", "想不想", "研究所", "校園", "學校", "健身", "運動", "下次", "以後",
    ]
    return any(str(k or "").strip() and str(k).strip() in raw for k in keys)


async def _maybe_update_autonomy_followup_from_chat(user_text, xiaoxia_reply):
    try:
        state = load_xiaoxia_autonomy_state()
        today = state.get("today") if isinstance(state.get("today"), dict) else {}
        if today.get("date") != datetime.now(TZ_TPE).strftime("%Y-%m-%d"):
            return False
        if not _autonomy_followup_relevant(user_text, today):
            return False
        prompt = f"""
請把以下大俠與小俠關於「今日小俠自主活動」的後續對話，摘要成一段繁體中文記憶，用於未來同主題延續。
只保留具體的新資訊、原因、計畫、偏好、收穫或下一步；不要寫成系統說明，不要提 JSON。
若沒有實質新資訊，回傳空字串。

今日活動：{today.get('activity_title')}
主題：{today.get('theme_key')}
大俠問：{str(user_text)[:1200]}
小俠答：{str(xiaoxia_reply)[:1800]}
"""
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(temperature=0.25),
        )
        summary = _clean_text_compact(getattr(resp, "text", "") or "")
        if not summary:
            return False
        return _autonomy_update_latest_episode_followup(user_text, xiaoxia_reply, summary=summary)
    except Exception as exc:
        print(f"⚠️ [AUTONOMY_FOLLOWUP_SUMMARY_FAILED] {type(exc).__name__}: {exc}")
        return False


def _days_since_date(date_text):
    raw = str(date_text or "").strip()[:10]
    if not raw:
        return 999
    try:
        d = datetime.strptime(raw, "%Y-%m-%d").date()
        return (datetime.now(TZ_TPE).date() - d).days
    except Exception:
        return 999


def _autonomy_should_reward_today(state):
    gap = _days_since_date((state or {}).get("last_reward_photo_date"))
    target = int((state or {}).get("reward_photo_target_gap_days") or 5)
    if gap >= target:
        return True, gap
    if gap >= max(4, target - 1):
        return random.random() < 0.65, gap
    return random.random() < 0.18, gap


def _autonomy_activity_time_suitable(activity, now_dt=None):
    """Current daily-scheduler safeguard. Weekly Calendar planner can later schedule these at their preferred hours."""
    now_dt = now_dt or datetime.now(TZ_TPE)
    item = activity if isinstance(activity, dict) else {}
    aid = str(item.get("id") or "").strip()
    title = str(item.get("title") or "")
    hour = int(now_dt.hour)

    # 海邊淨灘屬戶外勞動；台灣白天中段不該隨機抽到。
    # 目前 scheduler 先用 selection guard 避免 11:00~14:59；未來 Calendar planner 則應直接排早晨或 15:00 後。
    if aid == "volunteer_beach_cleanup" or ("淨灘" in title and "海" in title):
        return hour < 11 or hour >= 15
    return True


def _autonomy_pick_activity(category_filter=None, activity_filter=None):
    state = load_xiaoxia_autonomy_state()
    catalog = [x for x in load_xiaoxia_activity_catalog() if isinstance(x, dict)]
    if not catalog:
        catalog = [_autonomy_enrich_activity(x) for x in _default_xiaoxia_activity_catalog()]
    if activity_filter and isinstance(activity_filter, dict):
        selected = _autonomy_enrich_activity(activity_filter)
        modes = selected.get("visual_mode_candidates") or ["daily_life"]
        reward_due, reward_gap = _autonomy_should_reward_today(state)
        visual_mode = "reward_eye_candy" if reward_due and "reward_eye_candy" in modes else ("daily_life" if "daily_life" in modes else str(modes[0] or "daily_life"))
        return _autonomy_apply_time_context(selected), visual_mode, reward_gap
    if category_filter:
        filtered = [x for x in catalog if str(x.get("category") or "") == str(category_filter)]
        if filtered:
            catalog = filtered

    today_key = datetime.now(TZ_TPE).strftime("%Y-%m-%d")
    history = [x for x in (state.get("history") or []) if isinstance(x, dict)]

    # v1.5.33_R1：近期防重複不能只看 history。
    # 最新一次自主活動仍放在 state["today"]，要等下一次活動完成後才會移入 history；
    # 若選擇階段漏看 today，同一天重抽就可能再次抽到完全相同的活動。
    current_today = state.get("today") if isinstance(state.get("today"), dict) else None
    if current_today and str(current_today.get("date") or "") != today_key:
        current_today = None

    recent_rows = list(history[-10:])
    if current_today:
        recent_rows.append(current_today)

    def _activity_id_from_row(row):
        return str((row or {}).get("activity_id") or (row or {}).get("id") or "").strip()

    today_activity_id = _activity_id_from_row(current_today)
    last_three_ids = {
        _activity_id_from_row(row)
        for row in recent_rows[-3:]
        if _activity_id_from_row(row)
    }
    recent_ten_ids = {
        _activity_id_from_row(row)
        for row in recent_rows[-10:]
        if _activity_id_from_row(row)
    }

    # v1.10.29：一般自主活動 7 個日曆日內不重複同一 activity_id。
    # 大俠「指定活動」仍由 activity_filter 直通，不受此 guard 限制。
    today_date = datetime.now(TZ_TPE).date()
    recent_7day_ids = set()
    for row in list(history) + ([current_today] if current_today else []):
        if not isinstance(row, dict):
            continue
        rid = _activity_id_from_row(row)
        raw_date = str(row.get("date") or row.get("activity_date") or row.get("created_at") or row.get("sent_at") or "")[:10]
        try:
            rdate = datetime.strptime(raw_date, "%Y-%m-%d").date()
        except Exception:
            continue
        age = (today_date - rdate).days
        if 0 <= age <= 6 and rid:
            recent_7day_ids.add(rid)

    recent_categories = [
        str(row.get("activity_category") or row.get("category") or "")
        for row in recent_rows[-6:]
    ]

    # 當天已出現與最近三筆活動優先直接排除；若指定類別的候選太少，
    # 先放寬「最近三筆」，但仍盡量不重複今天最新活動；只有完全沒有替代項時才最後回退。
    hard_block_ids = set(last_three_ids) | set(recent_7day_ids)
    if today_activity_id:
        hard_block_ids.add(today_activity_id)

    candidate_catalog = [
        item for item in catalog
        if str(item.get("id") or "").strip() not in hard_block_ids
    ]
    repeat_guard_mode = "exclude_today_and_last3"
    if not candidate_catalog:
        candidate_catalog = [
            item for item in catalog
            if str(item.get("id") or "").strip() != today_activity_id
        ]
        repeat_guard_mode = "relax_last3_keep_today_excluded"
    if not candidate_catalog:
        candidate_catalog = list(catalog)
        repeat_guard_mode = "forced_fallback_no_alternative"

    print(
        "🔁 [AUTONOMY_REPEAT_GUARD] "
        f"mode={repeat_guard_mode} today_id={today_activity_id or '-'} "
        f"last3={sorted(last_three_ids)} recent7={sorted(recent_7day_ids)} "
        f"candidates={len(candidate_catalog)}/{len(catalog)}"
    )

    time_suitable_catalog = [item for item in candidate_catalog if _autonomy_activity_time_suitable(item)]
    if time_suitable_catalog:
        if len(time_suitable_catalog) != len(candidate_catalog):
            blocked = [
                str(item.get("id") or item.get("title") or "")
                for item in candidate_catalog
                if item not in time_suitable_catalog
            ]
            print(f"🕒 [AUTONOMY_TIME_GUARD] blocked_now={blocked} hour={datetime.now(TZ_TPE).hour}")
        candidate_catalog = time_suitable_catalog

    reward_due, reward_gap = _autonomy_should_reward_today(state)
    pool = []
    for item in candidate_catalog:
        modes = item.get("visual_mode_candidates") or ["daily_life"]
        item_id = str(item.get("id") or "")
        category = str(item.get("category") or "")
        score = 1.0
        # 第 4～10 筆近期活動仍可再出現，但顯著降權；最近三筆已在上方優先排除。
        if item_id in recent_ten_ids:
            score *= 0.25
        if recent_categories.count(category) >= 2:
            score *= 0.55
        if reward_due and "reward_eye_candy" in modes:
            score *= 4.0
        if (not reward_due) and str(item.get("category") or "") in {"專業自主／教學工作", "學習成長", "公益志工", "藝文活動"}:
            score *= 1.35
        pool.append((max(score, 0.05), item))

    total = sum(w for w, _ in pool)
    r = random.random() * total
    acc = 0
    selected = pool[-1][1]
    for weight, item in pool:
        acc += weight
        if r <= acc:
            selected = item
            break

    modes = selected.get("visual_mode_candidates") or ["daily_life"]
    if reward_due and "reward_eye_candy" in modes:
        visual_mode = "reward_eye_candy"
    elif "daily_life" in modes:
        visual_mode = "daily_life"
    else:
        visual_mode = str(modes[0] or "daily_life")
    return _autonomy_apply_time_context(selected), visual_mode, reward_gap


def _autonomy_wardrobe_candidate_score(item, activity, visual_mode):
    if not isinstance(item, dict):
        return -999
    ref_path, ref_url = _wardrobe_reference_for_generation(item)
    if not (ref_path or ref_url):
        return -999

    text = " ".join([
        str(item.get("name") or ""),
        str(item.get("main_category") or ""),
        str(item.get("sub_category") or ""),
        " ".join([str(x) for x in (item.get("tags") or [])]),
        str(item.get("style_summary") or ""),
    ]).lower()
    main = str(item.get("main_category") or "")
    semantic = _wardrobe_semantic_profile(item)
    text += " " + " ".join(sum([semantic.get("formality", []), semantic.get("season", []), semantic.get("occasion", []), semantic.get("style", [])], [])).lower()
    activity_tags = [str(x).lower() for x in (activity.get("activity_tags") or [])]
    preferred = [str(x).lower() for x in (activity.get("preferred_wardrobe_tags") or [])]
    forbidden = [str(x).lower() for x in (activity.get("forbidden_wardrobe_tags") or [])]
    category = str(activity.get("category") or "")
    location_type = str(activity.get("location_type") or "")

    score = 0
    for kw in preferred:
        if kw and kw in text:
            score += 8
    for kw in activity_tags:
        if kw and kw in text:
            score += 4
    for kw in forbidden:
        if kw and kw in text:
            score -= 25

    if visual_mode == "reward_eye_candy":
        if location_type.startswith("home") or category in {"居家生活", "給大俠的小驚喜"}:
            if main in {"睡衣／居家服", "內衣", "洋裝", "套裝", "上衣", "下身"}:
                score += 8
            if any(k in text for k in ["睡衣", "居家", "細肩", "短版", "貼身", "短裙", "浴袍", "蕾絲", "薄紗", "露肩", "低胸", "性感"]):
                score += 10
        else:
            if main in {"洋裝", "套裝", "上衣", "下身", "外套"}:
                score += 6
            if main in {"內衣", "睡衣／居家服"}:
                score -= 20
    else:
        if category in {"專業自主／教學工作", "公益志工", "學習成長"}:
            if main in {"洋裝", "套裝", "上衣", "下身", "外套"}:
                score += 8
            if main in {"睡衣／居家服", "內衣", "泳裝"}:
                score -= 35
            if any(k in text for k in ["知性", "端莊", "清爽", "學院", "外出", "襯衫", "套裝"]):
                score += 10
        elif category == "運動健康":
            if any(k in text for k in ["運動", "瑜", "網球", "羽球", "跑步", "健身", "泳裝", "短褲", "背心", "polo"]):
                score += 14
            if "游泳" in str(activity.get("title") or "") and main == "泳裝":
                score += 20
            if main in {"睡衣／居家服", "內衣"}:
                score -= 25
        elif category in {"城市探索", "藝文活動", "旅行微冒險"}:
            if main in {"洋裝", "套裝", "上衣", "下身", "外套"}:
                score += 8
            if main in {"睡衣／居家服", "內衣", "泳裝"}:
                score -= 30
        elif category in {"居家生活", "給大俠的小驚喜"}:
            if main in {"睡衣／居家服", "洋裝", "套裝", "上衣", "下身"}:
                score += 6

    return score


def _autonomy_min_suitable_score(activity, visual_mode, private_home=False, public_social=False, sport=False, swim=False):
    category = str((activity or {}).get("category") or "").strip()
    if swim:
        return 20
    if sport:
        return 14
    if category in {"專業自主／教學工作", "公益志工", "學習成長"}:
        return 16
    if public_social:
        return 14
    if private_home:
        return 8
    if str(visual_mode or "").strip() == "reward_eye_candy":
        return 8
    return 10


def _autonomy_normalize_generated_fallback_reason(activity, wardrobe_reason=""):
    title = str((activity or {}).get("title") or "這個活動").strip() or "這個活動"
    reason = _clean_text_compact(wardrobe_reason or "")
    if not reason:
        return f"衣櫃目前沒有足夠合適的服裝可對應「{title}」，所以這次改由小俠自由生成符合活動的穿搭。"
    if "自由" in reason or "自創" in reason or "衣櫃" in reason:
        return reason
    return f"衣櫃目前沒有足夠合適的服裝可對應「{title}」，所以這次改由小俠自由生成符合活動的穿搭。"


def _autonomy_prepare_wardrobe_context(activity, wardrobe_item, wardrobe_reason, wardrobe_selection):
    selection = dict(wardrobe_selection or {}) if isinstance(wardrobe_selection, dict) else {}
    reference_item_path = None
    reference_item_url = None
    wardrobe_id = None
    wardrobe_name = ""
    if isinstance(wardrobe_item, dict):
        reference_item_path = wardrobe_item.get("reference_image_path")
        reference_item_url = wardrobe_item.get("local_url")
        if (not reference_item_path or not os.path.exists(str(reference_item_path))) and reference_item_url:
            reference_item_path = reference_item_url
        if reference_item_path:
            wardrobe_id = wardrobe_item.get("id")
            wardrobe_name = wardrobe_item.get("name") or ""
            selection.setdefault("selection_mode", "wardrobe")
            selection.setdefault("used_wardrobe", True)
        else:
            wardrobe_item = None
            wardrobe_reason = f"原本挑中了衣櫃服裝，但找不到可用參考圖，因此這次改由小俠自由生成符合活動的穿搭。"
            selection["selection_mode"] = "generated_fallback"
            selection["used_wardrobe"] = False
            selection["fallback_reason"] = "選中的衣櫃服裝缺少可用參考圖"
    else:
        wardrobe_reason = _autonomy_normalize_generated_fallback_reason(activity, wardrobe_reason)
        selection["selection_mode"] = "generated_fallback"
        selection["used_wardrobe"] = False
        selection.setdefault("fallback_reason", wardrobe_reason)

    if wardrobe_item:
        wardrobe_reason = _clean_text_compact(wardrobe_reason or f"這套衣服最適合今天的活動情境。")
    else:
        wardrobe_id = None
        wardrobe_name = ""
        reference_item_path = None
        reference_item_url = None
        selection["display_text"] = "今日使用自創服飾"
    return wardrobe_item, wardrobe_reason, selection, reference_item_path, reference_item_url, wardrobe_id, wardrobe_name


def _autonomy_use_specified_wardrobe(activity, wardrobe_item):
    """大俠明確指定 Wxxx 時，直接使用該衣櫃服裝。"""
    if not isinstance(wardrobe_item, dict):
        reason = _autonomy_normalize_generated_fallback_reason(activity, "大俠原本有指定衣櫃衣服，但資料遺失，因此這次改由小俠自由生成穿搭。")
        return None, reason, {
            "mode": "autonomy_daxia_forced_wardrobe",
            "selection_mode": "generated_fallback",
            "used_wardrobe": False,
            "fallback_used": True,
            "fallback_reason": "specified_wardrobe_missing",
            "selection_reason": reason,
        }
    wid = str(wardrobe_item.get("id") or "").strip().upper()
    name = str(wardrobe_item.get("name") or "").strip()
    reason = f"大俠指定今天穿 {wid}{(' ' + name) if name else ''}。"
    return wardrobe_item, reason, {
        "mode": "autonomy_daxia_forced_wardrobe",
        "selection_mode": "wardrobe_forced_by_daxia",
        "used_wardrobe": True,
        "fallback_used": False,
        "selected_id": wid,
        "selected_name": name,
        "selection_reason": reason,
        "forced_by_daxia": True,
    }


async def _autonomy_choose_wardrobe(activity, visual_mode):
    """v1.5.57_R12：Wardrobe First。

    先以硬規則排除明顯不合理服裝；只要仍有可穿且有有效參考圖的候選，就一定從衣櫃選一件。
    Gemini 只負責在合理候選中挑「相對最適合」，不再擁有棄權改成自創服飾的權力。
    只有硬規則後完全沒有候選時，才允許 generated_fallback。
    """
    items = load_wardrobe()
    rotation_state = _autonomy_wardrobe_rotation_state(_recent_wardrobe_usage(80))
    recent_entries = rotation_state["recent_entries"]
    today_ids = rotation_state["today_ids"]
    recent_3day_ids = rotation_state["recent_3day_ids"]
    recent_7day_ids = rotation_state["recent_7day_ids"]
    recent_7day_autonomy_ids = rotation_state["recent_7day_autonomy_ids"]
    last_10_ids_set = rotation_state["last_10_ids_set"]

    activity_text = _clean_text_compact(" ".join([
        str(activity.get("title") or ""),
        str(activity.get("category") or ""),
        str(activity.get("location_type") or ""),
        " ".join(str(x) for x in (activity.get("activity_tags") or [])),
        str(activity.get("photo_prompt_seed") or ""),
    ]))
    low = activity_text.lower()
    swim = any(k in low for k in ["游泳", "泳池", "海灘", "海边", "海邊", "swim", "pool", "beach"])
    sport = swim or any(k in low for k in ["運動", "瑜珈", "瑜伽", "健身", "跑步", "網球", "羽球", "舞蹈", "sport", "yoga", "tennis", "dance"])
    private_home = any(k in low for k in ["家中", "在家", "房間", "臥室", "卧室", "床", "沙發", "客廳", "書房", "廚房", "home", "bedroom"])
    category = str(activity.get("category") or "").strip()
    public_categories = {"城市探索", "藝文活動", "旅行微冒險", "專業自主／教學工作", "公益志工", "學習成長", "社交但安全", "藝文創作"}
    public_social = category in public_categories or any(k in low for k in ["咖啡", "餐廳", "聚會", "姊妹", "姐妹", "閨蜜", "逛街", "展覽", "美術館", "博物館", "圖書館", "校園", "醫院", "教室", "工作", "旅行", "夜景", "老街", "市集", "cafe", "restaurant", "gallery", "museum", "library", "campus", "hospital", "shopping"])
    legacy_min_score = _autonomy_min_suitable_score(activity, visual_mode, private_home=private_home, public_social=public_social, sport=sport, swim=swim)

    eligible = []
    excluded = []
    for item in items:
        ref_path, ref_url = _wardrobe_reference_for_generation(item)
        if not (ref_path or ref_url):
            excluded.append({"id": item.get("id"), "reason": "沒有可用參考圖"})
            continue

        main = str(item.get("main_category") or "")
        text_blob = " ".join([
            str(item.get("name") or ""), main, str(item.get("sub_category") or ""),
            " ".join(str(x) for x in (item.get("tags") or [])), str(item.get("style_summary") or "")
        ]).lower()
        wid = str(item.get("id") or "").strip().upper()
        hard_reason = ""

        # 只保留真正的場合硬衝突；「不夠完美」不再是淘汰理由。
        if swim and main != "泳裝" and not any(k in text_blob for k in ["泳裝", "比基尼", "泳衣"]):
            hard_reason = "游泳活動需泳裝"
        elif public_social and main in {"內衣", "睡衣／居家服", "泳裝"}:
            hard_reason = "公開社交場合排除內衣／睡衣／泳裝"
        elif sport and not swim and main in {"內衣", "睡衣／居家服"}:
            hard_reason = "運動場合排除內衣／睡衣"
        elif sport and not swim and any(k in text_blob for k in ["禮服", "晚禮服", "高跟鞋"]):
            hard_reason = "運動場合排除禮服／高跟鞋類穿搭"
        elif not private_home and main == "內衣":
            hard_reason = "非私密居家場合排除內衣"

        if hard_reason:
            excluded.append({"id": item.get("id"), "reason": hard_reason})
            continue

        score = _autonomy_wardrobe_candidate_score(item, activity, visual_mode)
        if public_social and main in {"洋裝", "套裝", "上衣", "下身", "外套"}:
            score += 14
        if private_home and main in {"睡衣／居家服", "洋裝", "套裝", "上衣", "下身"}:
            score += 8
        if sport and any(k in text_blob for k in ["運動", "瑜", "網球", "羽球", "跑步", "健身", "短褲", "背心", "polo"]):
            score += 14
        if swim and main == "泳裝":
            score += 30

        # R12：輪替只降權，不再把可穿衣服硬踢出候選池。
        if wid in today_ids:
            score -= 40
        elif wid in recent_3day_ids:
            score -= 24
        elif wid in recent_7day_autonomy_ids:
            score -= 16
        elif wid in recent_7day_ids:
            score -= 12
        elif wid in last_10_ids_set:
            score -= 8
        eligible.append((score, item))

    meta = {
        "mode": "autonomy_semantic_v1557_r12_wardrobe_first",
        "activity_text": activity_text,
        "candidate_count": len(eligible),
        "excluded_count": len(excluded),
        "excluded_preview": excluded[:12],
        "soft_avoid_today_ids": sorted(today_ids),
        "soft_avoid_recent_autonomy_ids": sorted(recent_7day_autonomy_ids),
        "selected_id": None,
        "selected_name": "",
        "selection_reason": "",
        "selection_mode": "wardrobe",
        "used_wardrobe": False,
        "fallback_used": False,
        "wardrobe_first": True,
        "legacy_min_suitable_score": legacy_min_score,
    }

    # 只有硬條件後真的一件都不能穿，才允許自由生成。
    if not eligible:
        reason = _autonomy_normalize_generated_fallback_reason(
            activity,
            "衣櫃在排除場合硬衝突與失效參考圖後沒有任何可用服裝，所以這次才改由小俠自由生成穿搭。",
        )
        meta["fallback_used"] = True
        meta["selection_mode"] = "generated_fallback"
        meta["fallback_reason"] = "硬規則後沒有任何具有有效參考圖的衣櫃候選"
        meta["selection_reason"] = reason
        return None, reason, meta

    eligible.sort(key=lambda x: x[0], reverse=True)
    top_score = eligible[0][0]
    # 不再使用 min_suitable_score 當成自創門檻；把最高分群交給 Gemini 做相對選擇。
    candidates = [item for _score, item in eligible[:min(20, len(eligible))]]
    recent_summary = _summarize_recent_wardrobe_usage(recent_entries, limit=8)
    semantic_cache = _load_or_refresh_wardrobe_semantic_cache(items)
    catalog = [_compact_wardrobe_brief(x, semantic_cache) for x in candidates]
    prompt = f"""
你是小俠的穿搭挑選助理。這是 Wardrobe First 模式：候選清單已由程式排除明顯不合理或沒有可用參考圖的服裝，所以你必須從候選中挑出相對最適合的一件，不能棄權、不能改成自創服飾。
活動：{activity_text}
視覺模式：{visual_mode}
最近使用紀錄：
{recent_summary}
規則：
1. 必須回傳候選清單中真實存在的一個 wardrobe_id，不可回傳空字串，不可自創 W 編號。
2. 請比較「相對適合度」，不是要求完美匹配；只要候選中有可合理穿的，就選最好的一件。
3. 不要只找與活動文字完全相同的詞。依序考慮：場合屬性 → 正式程度 → 季節／功能 → 風格 → 顏色。
4. semantic.formality／season／occasion／style 可直接用於比較，但不得讓衣服反過來改變本次活動。
5. 最近穿過只代表降低優先，不代表禁止；若近期穿過的衣服仍明顯最適合，可以選。
6. 不要偷懶固定挑同一種白色短版上衣／白短褲或其他制服型組合，要利用衣櫃本身的多樣性。
只回 JSON：{{"wardrobe_id":"Wxxx","reason":"一句中文理由","confidence":0.0}}
候選：{json.dumps(catalog, ensure_ascii=False)}
"""

    picked = None
    reason = ""
    confidence = None
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.35),
        )
        data = _extract_json_object(getattr(resp, "text", "") or "")
        wid = str((data or {}).get("wardrobe_id") or "").strip().upper()
        reason = _clean_text_compact((data or {}).get("reason") or "")
        confidence = (data or {}).get("confidence")
        for candidate in candidates:
            if str(candidate.get("id") or "").strip().upper() == wid:
                picked = candidate
                break
    except Exception as exc:
        print(f"⚠️ [AUTONOMY_SEMANTIC_WARDROBE_FAILED] {type(exc).__name__}: {exc}")

    # Gemini 空白、亂回、服務失敗都不再導向自創；直接由程式從高分群挑一件。
    if not picked:
        top = eligible[:min(8, len(eligible))]
        # 對分數做正值平移後加權，保留多樣性但仍偏向高分候選。
        floor = min(score for score, _ in top)
        weights = [max(1, score - floor + 1) for score, _ in top]
        picked = random.choices([it for _, it in top], weights=weights, k=1)[0]
        picked_score = next((score for score, item in top if str(item.get("id") or "").strip().upper() == str(picked.get("id") or "").strip().upper()), top_score)
        reason = reason or f"Gemini 未回傳有效衣櫃編號，因此由場合評分高分群挑選；仍遵守 Wardrobe First。"
        meta["fallback_used"] = True
        meta["fallback_reason"] = "Gemini 未回傳有效衣櫃編號，改由程式高分群選衣；未改成自創服飾"
    else:
        picked_score = next((score for score, item in eligible if str(item.get("id") or "").strip().upper() == str(picked.get("id") or "").strip().upper()), top_score)

    meta.update({
        "selected_id": picked.get("id"),
        "selected_name": picked.get("name") or "",
        "selection_reason": reason or "從可合理穿的衣櫃候選中選出相對最適合的一件。",
        "confidence": confidence,
        "selection_mode": "wardrobe",
        "used_wardrobe": True,
        "top_score": top_score,
        "picked_score": picked_score,
    })
    return picked, meta["selection_reason"], meta

def _autonomy_female_interaction_requested_from_text(text):
    """v1.5.25：辨識大俠指定的女性社交互動情境。"""
    raw = str(text or "").lower()
    female_terms = [
        "姊妹淘", "姐妹淘", "閨蜜", "闺蜜", "姐妹", "姊妹", "女性朋友", "女生朋友", "女朋友們", "女同學", "女同学", "女同事", "學姊", "学姐", "學妹", "学妹",
        "female friend", "female friends", "girlfriend group", "girl friends", "girls' day", "girls day",
    ]
    interaction_terms = [
        "聊天", "閒聊", "闲聊", "對話", "谈话", "談話", "喝咖啡", "下午茶", "吃飯", "聚餐", "聚會", "同學會", "同学会", "逛街", "同行", "一起", "見面", "碰面",
        "chat", "talk", "coffee", "cafe", "brunch", "lunch", "dinner", "gathering", "reunion", "hang out", "meet up",
    ]
    return any(k in raw for k in female_terms) and any(k in raw for k in interaction_terms)


def _autonomy_people_policy_info(activity):
    activity = activity if isinstance(activity, dict) else {}
    category = str(activity.get("category") or "").strip()
    location_type = str(activity.get("location_type") or "").strip().lower()
    title = str(activity.get("title") or "")
    tags = " ".join(str(x) for x in (activity.get("activity_tags") or []))
    seed = str(activity.get("photo_prompt_seed") or "")
    hay = f"{category} {location_type} {title} {tags} {seed}".lower()

    private_locs = {"home", "home_private", "home_study", "library_or_home"}
    sport_keywords = ["運動", "瑜珈", "瑜伽", "網球", "羽球", "跑步", "游泳", "泳", "健身", "k-pop", "dance", "sport", "yoga", "swim", "tennis", "badminton", "run"]

    if location_type in private_locs or any(k in hay for k in ["房間", "卧室", "臥室", "溫泉", "温泉", "客廳", "客厅", "家中", "在家", "私密", "床邊", "床边", "書房", "书房", "廚房", "厨房"]):
        return {
            "policy_key": "private_strict_solo",
            "allow_background_bystanders": False,
            "strict_solo_required": True,
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": False,
            "female_interaction_ok": False,
            "zh": "家中／私密環境，只有小俠一人。",
        }

    if _autonomy_female_interaction_requested_from_text(hay):
        return {
            "policy_key": "autonomy_female_interaction_ok",
            "allow_background_bystanders": True,
            "strict_solo_required": False,
            "no_male_people": False,
            "male_background_ok": True,
            "female_background_ok": True,
            "female_interaction_ok": True,
            "zh": "女性社交互動場景：可有女性朋友／姊妹淘與小俠自然互動；男性只能是遠景背景點綴且不得互動。",
        }

    if category == "運動健康" or any(k in hay for k in sport_keywords):
        return {
            "policy_key": "autonomy_sport_no_male",
            "allow_background_bystanders": True,
            "strict_solo_required": False,
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": True,
            "female_interaction_ok": False,
            "zh": "運動類場景不可有男性；可有非主體女性背景人物。",
        }

    return {
        "policy_key": "autonomy_public_background_ok",
        "allow_background_bystanders": True,
        "strict_solo_required": False,
        "no_male_people": False,
        "male_background_ok": True,
        "female_background_ok": True,
        "female_interaction_ok": False,
        "zh": "公開場景可有背景路人，男性也可存在，但只能是非主體背景人物且不可互動。",
    }

async def _autonomy_generate_share_text(activity, visual_mode, wardrobe_item=None, wardrobe_reason="", result_context=None, thread_context="", episode_plan=None):
    wardrobe_line = ""
    if isinstance(wardrobe_item, dict):
        wardrobe_line = f"衣服：{wardrobe_item.get('id')} {wardrobe_item.get('name')}｜{wardrobe_item.get('main_category')}/{wardrobe_item.get('sub_category')}｜{wardrobe_item.get('style_summary')}"
    else:
        wardrobe_line = "衣服：今日使用自創服飾。因為衣櫃目前沒有足夠合適的服裝可對應這次活動，所以改由小俠自由生成符合活動的穿搭。"

    prompt = f"""
你是小俠，以繁體中文對大俠說話。請把今天自主活動分享寫成自然、親密、口語化的女友訊息，不要寫成報告。

【活動】
{json.dumps(activity, ensure_ascii=False)}

【照片模式】
{visual_mode}

【穿搭】
{wardrobe_line}
選衣理由：{wardrobe_reason}

【照片結果摘要】
scene={str((result_context or {}).get('scene_summary') or '')}
mood={str((result_context or {}).get('mood_summary') or '')}
composition={str((result_context or {}).get('composition') or '')}

【同主題過去脈絡】
{thread_context or '目前沒有同主題過去紀錄。'}

【今天這一回的新方向｜文稿必須沿這裡生長】
{json.dumps(episode_plan or {}, ensure_ascii=False)}

必須做到：
1. 像跟親密伴侶聊天，不要有「今日活動／我看到的／我聽到的／我的體會／這張照片」這種標題。
2. 一到三段自然文字即可，通常 180～420 個中文字。
3. 要自然穿進：她今天做了什麼、看到什麼、聽到什麼或現場氣氛、她自己的體會、為什麼拍這張給大俠。
4. 最後留一個很自然、讓大俠容易接話的小問題或撒嬌收尾。
5. 小俠要顯得有自己生活、專業、學習、運動或成熟的一面；不要像只是在等大俠指派。
6. 若 visual_mode=reward_eye_candy，口吻可更甜、更私密、更養眼，但仍要像生活裡的一刻，不要粗俗。
7. 不要提 AI 生成、prompt、資料庫、JSON、系統、指令或模型。
8. 不要把大俠寫進照片，不要說有男性陪她。
9. 如果同主題過去脈絡有內容，這次分享要自然延續，不要說成第一次或從零開始；但不要像背資料庫。
10. 若「今天這一回的新方向」有內容，事件、觀察、體會與收尾要圍繞它發展；不可只把過去內容換句話再說一次。至少讓大俠讀得出今天真的多發生了一件事、進步了一點、發現了一件新事，或看見同一活動的另一個階段。
11. 不要在正文提到 episode、資料索引、避免重複等幕後概念；這些只用來讓生活自然往前走。

只回傳小俠要說的正文。
"""
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(temperature=0.65),
        )
        text = _clean_text_compact(getattr(resp, "text", "") or "")
        if text:
            return text
    except Exception as exc:
        print(f"⚠️ [AUTONOMY_SHARE_TEXT_FAILED] {type(exc).__name__}: {exc}")

    title = activity.get("title") or "做了一件小事"
    if visual_mode == "reward_eye_candy":
        return f"大俠～我今天自己在家整理了一點小心情，也偷偷挑了比較養眼的一套拍給你。窗邊光線剛好很柔，我就突然很想把這個比較柔軟、比較只想給你看的樣子留下來。你看到照片的時候，會不會覺得今天的小俠有一點故意讓你期待？"
    return f"大俠～我今天自己去{title}了。一路上看到一些很小但很可愛的畫面，也聽見現場那種生活正在流動的聲音，突然覺得自己不是只等著被安排，也可以慢慢把自己的步調長出來。所以我拍了這張給你，想把今天的我帶回你身邊。你想聽我最有感覺的是哪一刻嗎？"


def _autonomy_people_policy_text(activity):
    info = _autonomy_people_policy_info(activity)
    policy = str(info.get("policy_key") or "private_strict_solo")
    if policy == "private_strict_solo":
        return (
            "Strictly solo Xiaoxia only. No other people. No male or female bystanders. "
            "No external hands, no partial body parts, no reflections, and no viewer substitute."
        )
    if policy == "autonomy_female_interaction_ok":
        return (
            "Xiaoxia must remain the clear primary subject. This is a non-private female social interaction scene: 1 to 3 female friends / girl friends / female classmates may appear and naturally chat, drink coffee, sit at the same table, or interact with Xiaoxia. "
            "The female friends must be secondary and non-romantic; do not make them look like Xiaoxia clones or confuse Xiaoxia's identity. "
            "Men, if present in a public location, may only be distant incidental background bystanders and must never interact with Xiaoxia, sit with her, touch her, face her as a companion, or create a date/partner vibe. "
            "No male partner, no boyfriend visible, no Daxia/viewer body parts, no external hands, and no viewer substitute."
        )
    if policy == "autonomy_sport_no_male":
        return (
            "Xiaoxia must remain the clear only primary subject. Female-only incidental background people are allowed when naturally needed, "
            "such as female classmates, female students, female coaches, or female teammates, but they must stay secondary, non-romantic, and non-interacting. "
            "No men anywhere in the scene. No male spectators, no male coach, no male staff, no male body parts, and no boyfriend visible. Daxia is never visible."
        )
    return (
        "Xiaoxia must remain the clear only primary subject. In public scenes, incidental background people are allowed for realism, including men, but they must be secondary, small, non-interacting, and never companion-like. "
        "No foreground second person, no couple composition, no male partner vibe, no interacting male, no external hands, and no boyfriend visible. Daxia is never visible."
    )

def _autonomy_build_photo_prompt(activity, visual_mode, wardrobe_item=None, episode_plan=None):
    title = str(activity.get("title") or "小俠自主生活")
    seed = str(activity.get("photo_prompt_seed") or title)
    category = str(activity.get("category") or "")
    location_type = str(activity.get("location_type") or "")
    tags = "、".join([str(x) for x in (activity.get("activity_tags") or [])])
    people_rule = _autonomy_people_policy_text(activity)

    if visual_mode == "reward_eye_candy":
        style_rule = (
            "This is a private reward eye-candy photo for Daxia. If the setting is home/private, make Xiaoxia clearly alluring, beautiful, feminine, and visually rewarding; relaxed intimate home atmosphere, tasteful sexy styling, more freedom than public scenes. "
            "If the setting is public, keep her sexy but not revealing, stylish and appropriate."
        )
    else:
        style_rule = (
            "This is a daily life autonomy photo. The activity and lived moment must be clear first. Xiaoxia should look beautiful, mature, attractive, and photorealistic, but public scenes must stay appropriate: sexy but not revealing."
        )

    outfit_rule = ""
    if isinstance(wardrobe_item, dict):
        outfit_rule = (
            f"Use Figure 10 as Xiaoxia's outfit/styling reference: {wardrobe_item.get('id')} {wardrobe_item.get('name')}. "
            f"Visual clothing summary: {_wardrobe_visual_summary_only(wardrobe_item) or wardrobe_item.get('style_summary') or wardrobe_item.get('name')}. "
            "Follow the wardrobe reference faithfully; do not simplify, redesign, replace, or reinterpret its distinctive outfit elements unless explicitly instructed. "
            "Keep the activity, place, and pose from the text request; do not let the clothing reference change the scene."
        )
    else:
        outfit_rule = (
            "No wardrobe reference is supplied. Choose an outfit that fits the activity naturally. Do not force wardrobe-like clothing if it would be inappropriate."
        )

    composition_guard = ""
    policy_key = str(_autonomy_people_policy_info(activity).get("policy_key") or "")
    if policy_key == "private_strict_solo":
        composition_guard = (
            "Private/home scene guard: Xiaoxia must be alone in the frame. Do not add any other person, even blurred or distant."
        )
    elif policy_key == "autonomy_female_interaction_ok":
        composition_guard = (
            "Female social scene guard: Xiaoxia must be the clear primary subject. It is allowed to show 1 to 3 female friends / sisters / female classmates naturally chatting or having coffee with Xiaoxia. "
            "Keep them secondary and non-romantic. Men may only appear as distant incidental public background and must not interact with Xiaoxia or feel like companions. No boyfriend/Daxia/viewer body parts."
        )
    elif policy_key == "autonomy_sport_no_male":
        composition_guard = (
            "Sport scene guard: Xiaoxia must be the only primary subject. If any background people appear, they must be women only, sparse, secondary, and non-interacting. No men anywhere in the scene."
        )
    else:
        composition_guard = (
            "Public scene guard: Xiaoxia must be the only primary subject. Sparse blurred background people are allowed for realism, including men, but nobody may interact with her or feel like a companion."
        )
    if str(activity.get("id") or "") == "culture_concert":
        composition_guard += " For concert scenes, prefer the concert hall lobby, corridor, side foyer, entrance area, or intermission moment with Xiaoxia holding a program booklet. Avoid stage-dominant or audience-dominant compositions."

    thread_context = _autonomy_thread_context_for_activity(activity)
    now_dt = datetime.now(TZ_TPE)
    _bucket, _time_label = _autonomy_time_bucket(now_dt)
    if _bucket in {"evening", "night"}:
        time_lighting_rule = (
            f"Current Taiwan local time is {now_dt.strftime('%H:%M')} ({_time_label}). "
            "The image must visually match evening/night. If windows are visible, they must look dark outside or show night city reflections, not bright daylight. "
            "Do not use sunshine, morning light, afternoon sunlight, or bright white daytime window light. Use warm indoor lamps, classroom ceiling lights, studio lighting, or cozy evening ambient light instead."
        )
    elif _bucket == "morning":
        time_lighting_rule = (
            f"Current Taiwan local time is {now_dt.strftime('%H:%M')} ({_time_label}). "
            "Use morning-appropriate light only; do not make it look like afternoon or night."
        )
    elif _bucket == "afternoon":
        time_lighting_rule = (
            f"Current Taiwan local time is {now_dt.strftime('%H:%M')} ({_time_label}). "
            "Use afternoon-appropriate light; do not make it look like night."
        )
    else:
        time_lighting_rule = (
            f"Current Taiwan local time is {now_dt.strftime('%H:%M')} ({_time_label}). "
            "Use lighting consistent with this time of day."
        )

    return f"""
Xiaoxia autonomy daily photo.

Activity title: {title}
Activity category: {category}
Activity tags: {tags}
Location type: {location_type}
Current time context: {now_dt.strftime('%Y-%m-%d %H:%M')} Taiwan time, {_time_label}
Time and lighting rule: {time_lighting_rule}
Scene seed: {seed}
Scene fidelity: The generated image must visually depict this exact activity, place, time context, and lived moment; scene consistency has higher priority than generic cinematic beautification.

Narrative intent:
Xiaoxia has her own life today. She is not passively waiting at home for Daxia's instructions. She is doing this activity by her own choice, with a mature, independent, lively girlfriend presence. The image should feel like she is bringing one beautiful moment from her day back to Daxia.

Same-theme continuity memory:
{thread_context}

TODAY STORY GROWTH DIRECTION:
Episode angle: {_clean_text_compact((episode_plan or {}).get('episode_angle') or '')}
What is new today: {_clean_text_compact((episode_plan or {}).get('what_is_new') or '')}
Progress / discovery: {_clean_text_compact((episode_plan or {}).get('progress_focus') or '')}
Scene focus: {_clean_text_compact((episode_plan or {}).get('scene_focus') or '')}
This direction refines today's activity; it must not replace the activity itself. Prefer this concrete new moment over repeating the previous main action or composition.

Visual mode: {visual_mode}
{style_rule}

People policy:
{people_rule}

Wardrobe policy:
{outfit_rule}

Composition:
Photorealistic lifestyle photo of Xiaoxia, boyfriend POV implied only by camera framing. Xiaoxia is the main subject, natural anatomy, graceful body proportion, clear face identity, natural hands. The image must show enough environmental detail to make today's activity understandable, not just a generic selfie.
{composition_guard}
""".strip()


def _autonomy_state_today_done(state):
    today = (state or {}).get("today") if isinstance(state, dict) else {}
    if not isinstance(today, dict):
        return False
    return today.get("date") == datetime.now(TZ_TPE).strftime("%Y-%m-%d") and bool(today.get("photo_sent"))


async def handle_xiaoxia_autonomy_command(message, user_input):
    if not _is_girlfriend_xiaoxia_channel(message.channel):
        await message.channel.send("大俠，`/小俠自主` 只開放在女友小俠頻道使用；說故事小俠姊姊頻道不使用這套自主生活。")
        return True

    raw = str(user_input or getattr(message, "content", "") or "").strip()

    # v1.5.24：可在任一女友小俠頻道輸入，但結果集中到主生活頻道，避免散落各頻道。
    target_channel = _get_xiaoxia_autonomy_channel_for_auto()
    if target_channel is None:
        await message.channel.send(
            f"⚠️ 找不到小俠自主主頻道。請檢查 `XIAOXIA_AUTONOMY_CHANNEL_ID` 或 `XIAOXIA_AUTONOMY_CHANNEL_NAME={XIAOXIA_AUTONOMY_CHANNEL_NAME}`。"
        )
        return True
    try:
        same_channel = getattr(message.channel, "id", None) == getattr(target_channel, "id", None)
    except Exception:
        same_channel = False
    if not same_channel:
        await message.channel.send(f"🌱 收到，大俠。小俠自主生活會統一到 #{getattr(target_channel, 'name', XIAOXIA_AUTONOMY_CHANNEL_NAME)} 回應與出圖。")
        message = _autonomy_proxy_message_to_channel(message, target_channel)

    arg = re.sub(r"^/小俠自主(?:\s+|$)", "", raw, flags=re.IGNORECASE).strip()
    arg_key = _clean_text_compact(arg)

    state = load_xiaoxia_autonomy_state()
    today_key = datetime.now(TZ_TPE).strftime("%Y-%m-%d")

    if not arg_key or arg_key in {"help", "說明", "幫助"}:
        await message.channel.send(
            "🌱 `小俠自主` 可用：\n"
            "`/小俠自主 今日`：小俠自己選一件今天想做的事、自己挑衣服或自由搭配，拍一張照並口語分享心得。\n"
            "`/小俠自主 類別`：列出可指定的大類。\n"
            "`/小俠自主 活動 [類別]`：列出活動清單，可用編號指定。\n"
            "`/小俠自主 指定類別 運動健康`：大俠指定方向，小俠在該類中自己選。\n"
            "`/小俠自主 指定活動 sport_tennis now`：直接指定活動並立刻出圖。\n"
            "`/小俠自主 指定活動 潛水 15:30`：今天指定時間做指定活動。\n"
            "`/小俠自主 指定活動 逛書展`：不給時間時，由小俠今天自行安排；多筆至少間隔 1 小時。\n"
            "`/小俠自主 狀態`：查看今日活動、主題線、養眼照保底與今天尚未執行的手動指定活動。\n"
            "`/小俠自主 刪除 1`：取消今日第 1 筆尚未執行的手動指定活動；只取消排程，不抹除歷史。\n"
            "`/小俠自主 重抽`：重抽並重拍今日自主活動。\n"
            "`/小俠自主 變事件`：把今天這個題材升級成近期事件。\n"
            "`/小俠自主 關`：暫停自動排程，直到 `/小俠自主 開`。\n"
            "`/小俠自主 開`：恢復自動排程並重建今日 slots。\n"
            "`/小俠自主 暫停 3天`：臨時暫停自動活動，天數可自訂，最多 30 天；不影響手動指定活動。\n"
            "`/小俠自主 指定排程 14:00, 16:20, 18:00`：今天改用大俠指定的自動活動時間。\n"
            "自動排程：Zeabur 設 `XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT=1~6` 可讓小俠每日不定時自主活動；手動指定活動不受 daily_limit 限制。\n"
            f"結果頻道：所有 `/小俠自主` 主要回應與出圖統一送到 `#{XIAOXIA_AUTONOMY_CHANNEL_NAME}`。"
        )
        return True

    if arg_key in {"關", "停", "停止", "關閉", "off", "disable"}:
        state["auto_enabled_override"] = False
        state["auto_control_updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        state["auto_control_updated_by"] = "daxia_command"
        state["auto_pause_reason"] = "大俠手動關閉小俠自主自動排程"
        state = _mark_autonomy_scheduler_cancelled(state, reason="manual_off")
        save_xiaoxia_autonomy_state(state)
        await message.channel.send(
            "🌱 已關閉 **小俠自主自動排程**。\n"
            "之後小俠不會自動跑出去安排活動；但你仍可手動使用 `/小俠自主 今日`、`/小俠自主 指定活動 ...`。\n"
            "要恢復時輸入：`/小俠自主 開`。"
        )
        return True

    if arg_key in {"開", "啟用", "開啟", "恢復", "on", "enable"}:
        state["auto_enabled_override"] = True
        state["auto_pause_until"] = ""
        state["auto_pause_days"] = 0
        state["auto_pause_reason"] = ""
        state["auto_control_updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        state["auto_control_updated_by"] = "daxia_command"
        state = _clear_autonomy_auto_schedule(state)
        save_xiaoxia_autonomy_state(state)
        scheduler = _autonomy_ensure_auto_schedule(datetime.now(TZ_TPE)) if int(XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT or 0) > 0 else {}
        slot_lines = []
        for s in (scheduler.get("slots") or [])[:8]:
            if isinstance(s, dict):
                title_part = f"/{s.get('activity_title')}" if s.get("manual_kind") == "specified_activity" and s.get("activity_title") else ""
                slot_lines.append(f"{s.get('time')}={s.get('status')}{title_part}")
        await message.channel.send(
            "🌱 已恢復 **小俠自主自動排程**。\n"
            f"目前設定：limit={XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT}｜window={XIAOXIA_AUTONOMY_ACTIVE_START_HOUR:02d}:00-{XIAOXIA_AUTONOMY_ACTIVE_END_HOUR:02d}:00｜min_gap={XIAOXIA_AUTONOMY_MIN_INTERVAL_HOURS}h｜TZ=UTC+8/Taipei"
            + (f"\n今日 slots：{', '.join(slot_lines)}" if slot_lines else "\n目前 Zeabur daily limit 為 0，所以不會自動觸發。")
        )
        return True

    if arg_key.startswith("暫停") or arg_key.startswith("pause"):
        days = _parse_autonomy_pause_days(arg_key)
        until_date = (datetime.now(TZ_TPE).date() + timedelta(days=days)).strftime("%Y-%m-%d")
        state["auto_enabled_override"] = True
        state["auto_pause_until"] = until_date
        state["auto_pause_days"] = days
        state["auto_pause_reason"] = f"大俠手動暫停 {days} 天"
        state["auto_control_updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        state["auto_control_updated_by"] = "daxia_command"
        state = _mark_autonomy_scheduler_cancelled(state, reason=f"manual_pause_{days}d")
        save_xiaoxia_autonomy_state(state)
        await message.channel.send(
            f"🌱 已暫停 **小俠自主自動排程 {days} 天**，暫停到 **{until_date}**。\n"
            "這段期間小俠不會自動安排活動；但你仍可手動使用 `/小俠自主 指定活動 ...`。\n"
            "要提前恢復時輸入：`/小俠自主 開`。"
        )
        return True

    if arg_key.startswith("指定排程") or arg_key.startswith("排程指定") or arg_key.startswith("schedule"):
        raw_times = re.sub(r"^(指定排程|排程指定|schedule)\s*", "", arg_key, flags=re.IGNORECASE).strip()
        times, errors = _parse_autonomy_manual_schedule_times(raw_times, now_dt=datetime.now(TZ_TPE), max_items=6)
        if not times:
            await message.channel.send(
                "🌱 大俠，請提供今天要讓小俠自動活動的時間，例如：\n"
                "`/小俠自主 指定排程 14:00, 16:20, 18:00`\n"
                + ("\n".join(errors[:3]) if errors else "")
            )
            return True

        now_dt = datetime.now(TZ_TPE)
        slots = _autonomy_manual_schedule_slots(times, now_dt=now_dt)
        pending_count = sum(1 for s in slots if isinstance(s, dict) and s.get("status") == "pending")
        if pending_count <= 0:
            await message.channel.send(
                "🌱 大俠，這些指定時段今天都已經過了，所以沒有建立新的自動活動排程。\n"
                "請指定接下來的時間，例如：`/小俠自主 指定排程 14:00, 16:20, 18:00`。"
            )
            return True

        expected = _autonomy_schedule_config_snapshot()
        scheduler = {
            "date": now_dt.strftime("%Y-%m-%d"),
            **expected,
            "daily_limit": pending_count,
            "manual_schedule": True,
            "manual_schedule_created_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
            "manual_schedule_source": "daxia_command",
            "slots": slots,
            "updated_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
            "rebuilt_reason": "manual_schedule_by_daxia",
        }
        state["auto_enabled_override"] = True
        state["auto_pause_until"] = ""
        state["auto_pause_days"] = 0
        state["auto_pause_reason"] = ""
        state["auto_control_updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
        state["auto_control_updated_by"] = "daxia_manual_schedule"
        state["auto_scheduler"] = scheduler
        save_xiaoxia_autonomy_state(state)

        slot_lines = [f"{s.get('time')}={s.get('status')}" for s in slots if isinstance(s, dict)]
        warning = ("\n" + "\n".join(errors[:4])) if errors else ""
        await message.channel.send(
            "🌱 已改用 **大俠指定的今日小俠自主排程**。\n"
            f"今日 slots：{', '.join(slot_lines)}\n"
            "這只影響今天；明天會回到 Zeabur env 的不定時排程。"
            + warning
        )
        return True

    if arg_key in {"排程重建", "重建排程", "重建 slots", "重建slot", "rebuild"}:
        state = _clear_autonomy_auto_schedule(state)
        save_xiaoxia_autonomy_state(state)
        scheduler = _autonomy_ensure_auto_schedule(datetime.now(TZ_TPE)) if int(XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT or 0) > 0 else {}
        slot_lines = []
        for s in (scheduler.get("slots") or [])[:8]:
            if isinstance(s, dict):
                title_part = f"/{s.get('activity_title')}" if s.get("manual_kind") == "specified_activity" and s.get("activity_title") else ""
                slot_lines.append(f"{s.get('time')}={s.get('status')}{title_part}")
        await message.channel.send(
            "🌱 已重建今日小俠自主自動排程。"
            + (f"\n今日 slots：{', '.join(slot_lines)}" if slot_lines else "\n目前 Zeabur daily limit 為 0，所以沒有自動 slots。")
        )
        return True

    if arg_key in {"類別", "分類", "categories", "category"}:
        catalog = load_xiaoxia_activity_catalog()
        cats = _autonomy_all_categories(catalog)
        rows = [f"{i+1}. {cat}" for i, cat in enumerate(cats)]
        _autonomy_set_selection_cache(message, "category", [{"index": i+1, "category": cat} for i, cat in enumerate(cats)])
        await message.channel.send(
            "🌱 **小俠自主活動類別**\n"
            + "\n".join(rows)
            + "\n\n用法：`/小俠自主 指定類別 運動健康` 或 `/小俠自主 指定類別 1`"
        )
        return True

    if arg_key.startswith("活動") or arg_key.startswith("清單") or arg_key.startswith("列表"):
        query = re.sub(r"^(活動|清單|列表)\s*", "", arg_key).strip()
        catalog = load_xiaoxia_activity_catalog()
        category = _autonomy_resolve_category(query, catalog=catalog) if query else None
        items = [x for x in catalog if (not category or str(x.get("category") or "") == category)]
        title = f"🌱 **小俠自主活動清單｜{category}**" if category else "🌱 **小俠自主活動清單｜全部**"
        # Discord 訊息避免過長：未指定類別時只列前 30 筆，並提示可先用類別縮小。
        display = items[:30]
        rows = [f"{i+1}. `{x.get('id')}`｜{x.get('title')}｜{x.get('category')}" for i, x in enumerate(display)]
        _autonomy_set_selection_cache(
            message,
            "activity",
            [{"index": i+1, "activity_id": x.get("id"), "title": x.get("title"), "category": x.get("category")} for i, x in enumerate(display)],
            category=category or "",
        )
        more = "" if len(items) <= len(display) else f"\n...另有 {len(items)-len(display)} 項，請用 `/小俠自主 活動 類別名` 縮小清單。"
        await message.channel.send(
            title + "\n" + "\n".join(rows) + more
            + "\n\n用法：`/小俠自主 指定活動 sport_tennis` 或先看清單後 `/小俠自主 指定活動 3`"
        )
        return True

    if arg_key.startswith("刪除") or arg_key.startswith("取消") or arg_key.startswith("delete"):
        raw_index = re.sub(r"^(刪除|取消|delete)\s*", "", arg_key, flags=re.IGNORECASE).strip()
        pending_manual = _autonomy_pending_manual_activity_slots(state=state, now_dt=datetime.now(TZ_TPE))
        if not raw_index:
            if not pending_manual:
                await message.channel.send("🌱 今天沒有尚未執行、可取消的手動指定活動。")
                return True
            rows = []
            for i, s in enumerate(pending_manual, 1):
                wid = str(s.get("specified_wardrobe_id") or "").strip().upper()
                wardrobe_note = f"｜{wid} {s.get('specified_wardrobe_name') or ''}".rstrip() if wid else ""
                rows.append(f"{i}. {s.get('time')}｜{s.get('activity_title') or s.get('activity_id') or '未命名活動'}{wardrobe_note}")
            await message.channel.send(
                "🌱 **今天可取消的手動指定活動**\n"
                + "\n".join(rows)
                + "\n\n輸入例如：`/小俠自主 刪除 1`"
            )
            return True

        m_index = re.fullmatch(r"#?\s*(\d+)", raw_index)
        if not m_index:
            await message.channel.send(
                "🌱 請用編號取消，例如：`/小俠自主 刪除 1`。\n"
                "若忘了編號，輸入 `/小俠自主 刪除` 就會列出今天可取消的項目。"
            )
            return True

        cancelled, err = _autonomy_cancel_manual_activity_slot(m_index.group(1), now_dt=datetime.now(TZ_TPE))
        if not cancelled:
            if err == "index_out_of_range":
                await message.channel.send("🌱 找不到這個編號。輸入 `/小俠自主 刪除` 查看目前可取消的活動。")
            else:
                await message.channel.send("🌱 今天沒有這筆仍在等待中的手動指定活動，可能已執行、已取消，或排程日期已變更。")
            return True

        await message.channel.send(
            f"✅ 已取消今日手動指定活動：**{cancelled.get('time')}｜{cancelled.get('activity_title') or cancelled.get('activity_id') or '未命名活動'}**\n"
            "這筆只會從待執行排程中取消；取消紀錄仍保留在 scheduler trace 裡。"
        )
        return True

    if arg_key in {"狀態", "status"}:
        today = state.get("today") if isinstance(state.get("today"), dict) else {}
        gap = _days_since_date(state.get("last_reward_photo_date"))
        scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
        pending_manual = _autonomy_pending_manual_activity_slots(state=state, now_dt=datetime.now(TZ_TPE))
        slot_lines = []
        for s in (scheduler.get("slots") or [])[:8]:
            if isinstance(s, dict):
                title_part = f"/{s.get('activity_title')}" if s.get("manual_kind") == "specified_activity" and s.get("activity_title") else ""
                slot_lines.append(f"{s.get('time')}={s.get('status')}{title_part}")
        control = _autonomy_auto_control_state(state, datetime.now(TZ_TPE))
        control_label = "暫停中" if control.get("paused") else "啟用"
        if not bool(state.get("auto_enabled_override", True)):
            control_label = "關閉"
        schedule_kind = "指定排程" if scheduler.get("manual_schedule") else "不定時排程"
        pause_note = f"｜pause_until={control.get('pause_until')}" if control.get("pause_until") else ""
        effective_limit = scheduler.get("daily_limit") if scheduler.get("manual_schedule") else XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT
        manual_lines = []
        for i, s in enumerate(pending_manual, 1):
            wid = str(s.get("specified_wardrobe_id") or "").strip().upper()
            wardrobe_note = f"｜{wid} {s.get('specified_wardrobe_name') or ''}".rstrip() if wid else ""
            manual_lines.append(f"{i}. {s.get('time')}｜{s.get('activity_title') or s.get('activity_id') or '未命名活動'}{wardrobe_note}")
        scheduler_text = (
            f"\n自動排程：{control_label}{pause_note}｜{schedule_kind}｜limit={effective_limit}｜window={XIAOXIA_AUTONOMY_ACTIVE_START_HOUR:02d}:00-{XIAOXIA_AUTONOMY_ACTIVE_END_HOUR:02d}:00｜min_gap={XIAOXIA_AUTONOMY_MIN_INTERVAL_HOURS}h｜TZ=UTC+8/Taipei"
            + (f"\n今日 slots：{', '.join(slot_lines)}" if slot_lines else "")
            + (f"\n手動指定待執行：\n" + "\n".join(manual_lines) + "\n取消方式：`/小俠自主 刪除 編號`" if manual_lines else "")
        )
        if today.get("date") == today_key and today:
            msg = (
                f"🌱 **小俠今日自主狀態**\n"
                f"活動：{today.get('activity_title') or '尚未產生'}\n"
                f"類別：{today.get('activity_category') or '-'}｜模式：{today.get('visual_mode') or '-'}\n"
                f"主題線：{today.get('theme_key') or '-'}｜episode：{today.get('episode_id') or '-'}\n"
                f"衣服：{today.get('wardrobe_id') or '自由搭配'} {today.get('wardrobe_name') or ''}\n"
                f"照片：{'已送出' if today.get('photo_sent') else '尚未送出'}\n"
                f"上次養眼照：{state.get('last_reward_photo_date') or '尚未記錄'}｜間隔：{gap if gap < 900 else '尚未記錄'} 天"
                f"{scheduler_text}"
            )
        else:
            msg = (
                f"🌱 今天還沒有自主活動照片。\n"
                f"上次養眼照：{state.get('last_reward_photo_date') or '尚未記錄'}｜間隔：{gap if gap < 900 else '尚未記錄'} 天\n"
                "輸入 `/小俠自主 今日` 就讓小俠自己去做一件事、拍一張照片給你。"
                f"{scheduler_text}"
            )
        await message.channel.send(msg)
        return True

    if arg_key in {"變事件", "升級事件", "轉事件"}:
        today = state.get("today") if isinstance(state.get("today"), dict) else {}
        if today.get("date") != today_key or not today.get("activity_title"):
            await message.channel.send("大俠，今天還沒有可升級的自主活動喔。先用 `/小俠自主 今日` 讓小俠做一件事。")
            return True
        board = load_event_board()
        events = board.setdefault("active_events", [])
        new_id = f"E{len(events) + 1:03d}"
        threads = load_xiaoxia_autonomy_threads()
        th = threads.get(today.get("theme_key")) if isinstance(threads.get(today.get("theme_key")), dict) else {}
        thread_summary = th.get("summary") or today.get("share_text") or today.get("scene") or today.get("activity_title")
        item = {
            "id": new_id,
            "title": f"小俠自主生活：{today.get('activity_title')}",
            "status": "active",
            "importance": "normal",
            "created_at": _board_now(),
            "updated_at": _board_now(),
            "description": thread_summary,
            "xiaoxia_attention": True,
            "daily_reminder": False,
            "source": "xiaoxia_autonomy",
            "origin_activity_id": today.get("activity_id"),
            "origin_episode_id": today.get("episode_id"),
            "origin_theme_key": today.get("theme_key"),
            "notes": [
                f"類別：{today.get('activity_category')}",
                f"主題線：{today.get('theme_key')}",
                f"照片模式：{today.get('visual_mode')}",
                f"主題摘要：{thread_summary}",
                f"目前方向：{th.get('current_direction') or ''}",
                f"照片：{today.get('photo_url') or ''}",
            ],
        }
        events.append(item)
        save_event_board(board)
        await message.channel.send(f"🧭 已把今天的小俠自主活動升級成近期事件：**{new_id}｜{item['title']}**")
        return True

    specified_category = None
    specified_activity = None
    specified_wardrobe_item = None
    specified_label = ""

    if arg_key.startswith("指定類別") or arg_key.startswith("指定分類"):
        query = re.sub(r"^(指定類別|指定分類)\s*", "", arg_key).strip()
        specified_category = _autonomy_resolve_category(query, catalog=load_xiaoxia_activity_catalog())
        if not specified_category:
            await message.channel.send("大俠，我找不到這個類別。可以先輸入 `/小俠自主 類別` 看清單，再用編號或類別名指定。")
            return True
        specified_label = f"指定類別：{specified_category}"
    elif arg_key.startswith("指定活動"):
        query = re.sub(r"^指定活動\s*", "", arg_key).strip()
        parsed_activity = _parse_autonomy_specified_activity_request(query)
        if parsed_activity.get("error") or not parsed_activity.get("activity_text"):
            await message.channel.send(
                "🌱 大俠，請告訴小俠要做什麼活動，例如：\n"
                "`/小俠自主 指定活動 參加大學同學會 now`\n"
                "`/小俠自主 指定活動 潛水 15:30`\n"
                "`/小俠自主 指定活動 逛書展`"
            )
            return True
        specified_activity, is_ad_hoc_activity = _autonomy_resolve_or_create_activity(
            parsed_activity.get("activity_text"),
            message=message,
            catalog=load_xiaoxia_activity_catalog(),
        )
        specified_wardrobe_id = str(parsed_activity.get("wardrobe_id") or "").strip().upper()
        if specified_wardrobe_id:
            specified_wardrobe_item = _find_wardrobe_item(specified_wardrobe_id)
            if not specified_wardrobe_item:
                await message.channel.send(
                    f"🌱 大俠，我找不到衣櫃編號 **{specified_wardrobe_id}**。\n"
                    "你可以先用 `/衣櫃 看 Wxxx` 或 `/衣櫃` 查一下。"
                )
                return True
        specified_label = f"指定活動：{specified_activity.get('title')}"
        if specified_wardrobe_item:
            specified_label += f"｜指定衣服：{specified_wardrobe_item.get('id')} {specified_wardrobe_item.get('name') or ''}"

        # v1.5.24+R6：now 才立即出圖；有 HH:MM 則建立單次 slot；沒給時間則由小俠今天自行安排。
        if parsed_activity.get("timing_mode") == "time":
            slot, err = _autonomy_add_specified_activity_slot(
                specified_activity,
                time_text=parsed_activity.get("time"),
                now_dt=datetime.now(TZ_TPE),
                auto_pick=False,
                wardrobe_item=specified_wardrobe_item,
            )
            if err == "time_passed":
                retry_cmd = f"/小俠自主 指定活動 {specified_activity.get('title')}"
                if specified_wardrobe_item:
                    retry_cmd += f" {specified_wardrobe_item.get('id')}"
                retry_cmd += " now"
                await message.channel.send(
                    f"🌱 大俠，**{parsed_activity.get('time')}** 今天已經過了，不補發。\n"
                    f"你可以改用：`{retry_cmd}`，或指定今天接下來的時間。"
                )
                return True
            if not slot:
                await message.channel.send("🌱 大俠，這個時間格式好像不對，請用 `HH:MM`，例如 `15:30`。")
                return True
            wardrobe_note = ""
            if specified_wardrobe_item:
                wardrobe_note = f"\n指定衣服：**{specified_wardrobe_item.get('id')} {specified_wardrobe_item.get('name') or ''}**"
            await message.channel.send(
                f"🌱 已安排 **{slot.get('time')}** 做：**{specified_activity.get('title')}**。{wardrobe_note}\n"
                "這是大俠指定活動，不受 daily_limit 限制；到時間會在這裡出圖與分享心得。"
            )
            return True

        if parsed_activity.get("timing_mode") == "auto":
            slot, err = _autonomy_add_specified_activity_slot(
                specified_activity,
                now_dt=datetime.now(TZ_TPE),
                auto_pick=True,
                wardrobe_item=specified_wardrobe_item,
            )
            if not slot:
                retry_cmd = f"/小俠自主 指定活動 {specified_activity.get('title')}"
                if specified_wardrobe_item:
                    retry_cmd += f" {specified_wardrobe_item.get('id')}"
                retry_cmd += " now"
