    await ctx.send(("\n".join(["🎂 紀念日清單",""]+[_format_anniv_item(it,i) for i,it in enumerate(items,1)]+["\n可用：`/紀念日 新增 ...`、`/紀念日 修改`、`/紀念日 刪除` "]))[:1900])
