async def _handle_pending_memory_review_input(message):
    uid = getattr(message.author, "id", None); sess = pending_memory_review_inputs.get(uid)
    if not sess or sess.get("stage") != "choose": return False
    content = str(getattr(message, "content", "") or "").strip()
    if content.lower() in {"c", "cancel", "取消"}:
        pending_memory_review_inputs.pop(uid, None); await message.channel.send("已取消回憶整理操作。") ; return True
    action = sess.get("action")
    mode = sess.get("mode") or "待整理"
    query = sess.get("query") or ""
    m = re.search(r"\d+", content)
    if not m:
        await message.channel.send("請輸入清單編號，或輸入 `c` 取消。") ; return True
    return await _memory_review_apply_action(_WardrobeMessageCtxAdapter(message), action, int(m.group(0)), mode=mode, query=query)


async def _handle_memory_review_command(ctx, args=""):
    raw = str(args or "").strip()
    if not raw:
        await _memory_review_send_list(ctx, mode="all", page=1); return
    if raw.startswith("搜尋"):
        payload = raw[len("搜尋"):].strip()
        page = 1
        m = re.search(r"\s+(\d+)\s*$", payload)
        if m:
            page = int(m.group(1)); payload = payload[:m.start()].strip()
        await _memory_review_send_list(ctx, mode="all", page=page, query=payload); return
    if raw.startswith("待整理"):
        payload = raw[len("待整理"):].strip()
        await _memory_review_send_list(ctx, mode="待整理", page=_parse_page_arg(payload, 1)); return
    for filter_name in ("已保留", "保留清單", "長期", "已升級紀念日", "已升級", "已完成", "已取消"):
        if raw == filter_name or raw.startswith(filter_name + " "):
            payload = raw[len(filter_name):].strip()
            await _memory_review_send_list(ctx, mode=filter_name, page=_parse_page_arg(payload, 1)); return
    if re.fullmatch(r"(?:第\s*)?\d+\s*(?:頁)?", raw):
        await _memory_review_send_list(ctx, mode="all", page=_parse_page_arg(raw, 1)); return
    for action in ("刪除", "保留", "升級紀念日"):
        if raw == action or raw.startswith(action + " "):
            payload = raw[len(action):].strip()
            last_ctx = _memory_review_last_list_context(ctx, fallback_mode="待整理")
            mode = last_ctx["mode"] or "待整理"
            page = last_ctx["page"] or 1
            query = last_ctx["query"] or ""
            if payload.startswith("搜尋"):
                qraw = payload[len("搜尋"):].strip()
                m = re.search(r"\s+(\d+)\s*$", qraw)
                if m:
                    page = int(m.group(1)); qraw = qraw[:m.start()].strip()
                query = qraw
                await _memory_review_start_select_flow(ctx, action=action, mode="all", page=page, query=query); return
            mnum = re.search(r"\d+", payload)
            if mnum:
                await _memory_review_apply_action(ctx, action, int(mnum.group(0)), mode=mode, query=query); return
            await _memory_review_start_select_flow(ctx, action=action, mode=mode, page=page, query=query); return
    await ctx.send("指令格式：`/回憶`、`/回憶 待整理`、`/回憶 已保留`、`/回憶 已完成`、`/回憶 已取消`、`/回憶 搜尋 關鍵字`、`/回憶 刪除 2`、`/回憶 保留 1`、`/回憶 升級紀念日 3`。等待輸入時可按 `c` 取消。")


async def _handle_memory_review_message_direct(message):
    content = str(getattr(message, "content", "") or "").strip()
    if not re.match(r"^/回憶(?:\s+|$)", content): return False
    if not _is_girlfriend_xiaoxia_channel(message.channel):
        await message.channel.send("大俠，回憶整理先只開放在女友小俠頻道使用喔。"); return True
    raw = re.sub(r"^/回憶(?:\s+|$)", "", content).strip()
    await _handle_memory_review_command(_WardrobeMessageCtxAdapter(message), raw)
    return True

def _json_hash(data):
    payload = json.dumps(data, ensure_ascii=False, sort_keys=True).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

def _extract_json_object(raw_text):
    value = str(raw_text or "").strip()
    value = value.replace("```json", "").replace("```", "").strip()
    try:
        return json.loads(value)
    except Exception:
        match = re.search(r"(\{.*\}|\[.*\])", value, flags=re.DOTALL)
        if not match:
            raise
        return json.loads(match.group(1))

def _path_text(path):
    return "/".join(str(p) for p in path)

def _collect_string_candidates(source_name, data, search_terms, max_items=80):
    results = []
    lowered_terms = [str(term).strip().lower() for term in search_terms if str(term).strip()]

    def walk(node, path):
        if len(results) >= max_items:
            return
        if isinstance(node, dict):
            for key, value in node.items():
                walk(value, path + [key])
        elif isinstance(node, list):
            for index, value in enumerate(node):
                walk(value, path + [index])
        elif isinstance(node, str):
            haystack = node.lower()
            if not lowered_terms or any(term in haystack for term in lowered_terms):
                results.append({
                    "source": source_name,
                    "path": path,
                    "path_text": _path_text(path),
                    "text": node[:700],
                })

    walk(data, [])
    return results

def _get_by_path(root, path):
    node = root
    for part in path:
        node = node[part]
    return node

def _set_by_path(root, path, value):
    if not path:
        raise ValueError("不可直接覆蓋整個根節點")
    parent = _get_by_path(root, path[:-1])
    parent[path[-1]] = value

def _delete_by_path(root, path):
    if not path:
        raise ValueError("不可刪除整個根節點")
    parent = _get_by_path(root, path[:-1])
    target = path[-1]
    if isinstance(parent, list):
        parent.pop(int(target))
    else:
        parent.pop(target, None)

def _append_by_path(root, path, value):
    target = _get_by_path(root, path)
    if not isinstance(target, list):
        raise ValueError(f"新增目標不是 list：{_path_text(path)}")
    target.append(value)

def _normalize_string_list(values):
    result = []
    seen = set()
    for value in values or []:
        item = str(value or "").strip()
        if item and item not in seen:
            seen.add(item)
            result.append(item)
    return result

def _merge_memory_directives(current, plan):
    merged = dict(current or {})
    merged["forbidden_terms"] = _normalize_string_list(
        list(merged.get("forbidden_terms", [])) + list(plan.get("forbidden_terms", []))
    )
    merged["preferred_phrasing"] = _normalize_string_list(
        list(merged.get("preferred_phrasing", [])) + list(plan.get("preferred_phrasing", []))
    )

    # 同一主題的新事實應覆蓋舊事實；由 Gemini 提供 topic。
    existing_facts = list(merged.get("authoritative_facts", []))
    incoming = plan.get("authoritative_facts", []) or []
    for item in incoming:
        if isinstance(item, str):
            item = {"topic": item[:40], "fact": item}
        if not isinstance(item, dict):
            continue
        topic = str(item.get("topic", "")).strip()
        fact = str(item.get("fact", "")).strip()
        if not fact:
            continue
        if topic:
            existing_facts = [
                old for old in existing_facts
                if not isinstance(old, dict) or str(old.get("topic", "")).strip() != topic
            ]
        existing_facts.append({"topic": topic or fact[:40], "fact": fact})
    merged["authoritative_facts"] = existing_facts[-30:]
    merged["updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
    return merged

def _format_directives_for_prompt(directives):
    forbidden = "、".join(directives.get("forbidden_terms", [])) or "無"
    preferred = "；".join(directives.get("preferred_phrasing", [])) or "無"
    facts = []
    for item in directives.get("authoritative_facts", []):
        if isinstance(item, dict):
            facts.append(str(item.get("fact", "")).strip())
        else:
            facts.append(str(item).strip())
    facts = "；".join([f for f in facts if f]) or "無"
    return (
        f"【人工確認的最新記憶規則｜高於其他歷史資料】\n"
        f"禁止在回覆中使用的詞：{forbidden}\n"
        f"偏好的表達方式：{preferred}\n"
        f"目前有效的最新事實：{facts}\n"
        "【重要表達規則】上述日期是內部校時資料，只用來判斷先後與避免時空錯亂。"
        "一般聊天不得逐字念出 YYYY-MM-DD；應依系統當前日期自然說成今天、昨天、前天、明天，"
        "或在較久以前時說某月某日。只有大俠明確詢問確切日期時，才可直接說出完整日期。\n"
    )


def _user_requested_exact_date(user_text):
    value = str(user_text or "")
    return bool(re.search(r"(幾號|幾月幾日|哪一天|哪天|確切日期|日期是|什麼時候發生)", value))


def _natural_date_phrase(date_value, now_dt):
    try:
        target = datetime.strptime(date_value, "%Y-%m-%d").date()
    except Exception:
        return date_value
    delta = (target - now_dt.date()).days
    mapping = {
        -2: "前天",
        -1: "昨天",
        0: "今天",
        1: "明天",
        2: "後天",
    }
    if delta in mapping:
        return mapping[delta]
    if target.year == now_dt.year:
        return f"{target.month}月{target.day}日"
    return f"{target.year}年{target.month}月{target.day}日"


def naturalize_dates_in_reply(reply, user_text, now_dt=None):
    """資料庫保留絕對日期；一般對話輸出轉成自然時間語言。"""
    value = str(reply or "")
    if not value or _user_requested_exact_date(user_text):
        return value
    now_dt = now_dt or datetime.now(TZ_TPE)

    def repl(match):
        date_value = match.group(1)
        period = match.group(2) or ""
        return _natural_date_phrase(date_value, now_dt) + period

    # 支援 2026-06-06上午、2026-06-06 上午、2026-06-06（上午）
    value = re.sub(
        r"(?<!\d)(\d{4}-\d{2}-\d{2})\s*[（(]?\s*(上午|中午|下午|傍晚|晚上|夜裡|凌晨)?\s*[）)]?",
        repl,
        value,
    )
    return value

async def _rewrite_reply_for_directives(reply, directives):
    forbidden = [term for term in directives.get("forbidden_terms", []) if term and term in reply]
    if not forbidden:
        return reply

    preferred = directives.get("preferred_phrasing", [])
    prompt = f"""
    請重寫以下回覆，保持原本甜蜜自然的意思，但絕對不可出現這些詞：
    {json.dumps(forbidden, ensure_ascii=False)}

    可優先採用的表達方向：
    {json.dumps(preferred, ensure_ascii=False)}

    只回傳重寫後的回覆，不要解釋。
    原回覆：
    {reply}
    """
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
        )
        rewritten = str(resp.text or "").strip().strip('"').strip("「").strip("」")
        if rewritten and not any(term in rewritten for term in forbidden):
            return rewritten
    except Exception as exc:
        print(f"⚠️ 禁用詞回覆重寫失敗：{exc}")

    # 最終 fallback：保證禁用詞不會直接送出。
    replacement = preferred[0] if preferred else "彼此珍惜與安心"
    for term in forbidden:
        reply = reply.replace(term, replacement)
    return reply

def _parse_date(value):
    if not value:
        return None
    try:
        return datetime.strptime(str(value)[:10], "%Y-%m-%d").date()
    except Exception:
        return None

def _date_str(value):
    if isinstance(value, datetime):
        return value.strftime("%Y-%m-%d")
    return str(value)[:10] if value else ""

def _event_text_reference_date(event, now_dt=None):
    """
    v52.6：判斷事件文字中的「今天 / 昨天 / 明天」原本指哪一天。
    優先使用 created_at，因為 LLM 產生 fact 的「今天」通常是登記當天；
    沒有 created_at 時才退回 anchor_date。
    """
    now_dt = now_dt or datetime.now(TZ_TPE)
    for key in ("created_at", "updated_at", "anchor_date"):
        dt = _parse_date(event.get(key))
        if dt:
            return dt
    return now_dt.date()

def normalize_relative_temporal_text(text_value, event, now_dt=None):
    """
    v52.6：把 life_events 裡的相對時間詞轉成絕對日期，避免 5/31 還顯示「今天一起北上」。
    """
    now_dt = now_dt or datetime.now(TZ_TPE)
    today = now_dt.date()
    ref_date = _event_text_reference_date(event, now_dt=now_dt)
    value = str(text_value or "")

    # 已有括號日期者，直接移除錯誤的「今天」標籤。
    value = re.sub(r"(\d{4}-\d{2}-\d{2})（今天）", r"\1", value)
    value = re.sub(r"今天（(\d{4}-\d{2}-\d{2})）", r"\1", value)
    value = re.sub(r"(\d{4}/\d{2}/\d{2})（今天）", r"\1", value)
    value = re.sub(r"今天（(\d{4}/\d{2}/\d{2})）", r"\1", value)

    # 只有跨日後才把「今天」改掉；當天仍保留自然語氣。
    if ref_date != today:
        value = value.replace("今天", f"{ref_date.strftime('%Y-%m-%d')}當天")
        value = value.replace("昨日", f"{(ref_date - timedelta(days=1)).strftime('%Y-%m-%d')}")
        value = value.replace("昨天", f"{(ref_date - timedelta(days=1)).strftime('%Y-%m-%d')}")
        value = value.replace("明天", f"{(ref_date + timedelta(days=1)).strftime('%Y-%m-%d')}")
        value = value.replace("後天", f"{(ref_date + timedelta(days=2)).strftime('%Y-%m-%d')}")

    derived = event.get("derived_dates", {}) if isinstance(event.get("derived_dates"), dict) else {}
    new_job_start = _date_str(derived.get("new_job_start"))
    if new_job_start:
        value = value.replace("下週一", new_job_start).replace("下周一", new_job_start).replace("下星期一", new_job_start)

    return value

def normalize_life_event_temporal_fields(event, now_dt=None):
    """
    v52.6：把既有 facts / reply_guidance 中過期的相對時間詞寫回 JSON。
    """
    changed = False
    for field in ("facts", "reply_guidance"):
        values = event.get(field)
        if not isinstance(values, list):
            continue
        normalized = []
        for item in values:
            new_item = normalize_relative_temporal_text(item, event, now_dt=now_dt)
            if new_item != item:
                changed = True
            normalized.append(new_item)
        event[field] = list(dict.fromkeys(normalized))[:12]
    return changed

def _next_weekday(base_date, weekday):
    delta = (weekday - base_date.weekday()) % 7
    if delta == 0:
        delta = 7
    return base_date + timedelta(days=delta)

def resolve_relative_dates_in_text(text_value, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    today = now_dt.date()
    mapping = {
        "今天": today,
        "昨日": today - timedelta(days=1),
        "昨天": today - timedelta(days=1),
        "明天": today + timedelta(days=1),
        "後天": today + timedelta(days=2),
        "下週一": _next_weekday(today, 0), "下周一": _next_weekday(today, 0), "下星期一": _next_weekday(today, 0),
        "下週二": _next_weekday(today, 1), "下周二": _next_weekday(today, 1), "下星期二": _next_weekday(today, 1),
        "下週三": _next_weekday(today, 2), "下周三": _next_weekday(today, 2), "下星期三": _next_weekday(today, 2),
        "下週四": _next_weekday(today, 3), "下周四": _next_weekday(today, 3), "下星期四": _next_weekday(today, 3),
        "下週五": _next_weekday(today, 4), "下周五": _next_weekday(today, 4), "下星期五": _next_weekday(today, 4),
    }
    hits = []
    source = str(text_value or "")
    for phrase, dt in mapping.items():
        if phrase in source:
            hits.append(f"{phrase}={dt.strftime('%Y-%m-%d')}")
    return "；".join(hits) if hits else "無"

def make_life_event_id(title, anchor_date, event_type):
    raw = re.sub(r"[^0-9A-Za-z\u4e00-\u9fff]+", "_", str(title or event_type))[:24].strip("_")
    return f"{_date_str(anchor_date).replace('-', '')}_{event_type}_{raw or 'event'}"

def _event_signature(event):
    return (str(event.get("type", "")), _date_str(event.get("anchor_date")), str(event.get("title", ""))[:20])

def calculate_life_event_score(event):
    """
    v52.2：重大事件 0～10 分評分。
    分數來源：impact + time_span + role_relevance + emotional_weight + action_required。
    6 分以上才進 life_events；8 分以上視為 critical。
    """
    text_blob = " ".join([
        str(event.get("title", "")),
        str(event.get("type", "")),
        " ".join(event.get("facts", []) if isinstance(event.get("facts"), list) else []),
        " ".join(event.get("reply_guidance", []) if isinstance(event.get("reply_guidance"), list) else []),
    ])
    derived = event.get("derived_dates", {}) if isinstance(event.get("derived_dates"), dict) else {}
    participants = event.get("participants", []) if isinstance(event.get("participants"), list) else []
    event_type = str(event.get("type", ""))

    score = 0
    reasons = []

    # impact：工作、住處、健康、家庭、期限、重大承諾等會改變生活節奏的事件。
    if event_type in {"interview", "new_job", "move", "move_and_new_job", "family", "health", "deadline", "major_promise", "travel"}:
        score += 2
        reasons.append("impact: 類型屬於會影響生活/責任/關係的重要事件")
    elif re.search(r"面試|入職|新工作|搬家|北上|南下|租屋|新家|住院|健康|家庭|截止|期限|承諾", text_blob):
        score += 1
        reasons.append("impact: 文字含重大事件線索")

    # time_span：有明確日期、階段、跨日影響或後續期。
    if len([v for v in derived.values() if v]) >= 2 or re.search(r"第一週|下週|搬家|新工作|安頓|等待結果|後續", text_blob):
        score += 2
        reasons.append("time_span: 影響跨越多日或有後續階段")
    elif event.get("anchor_date"):
        score += 1
        reasons.append("time_span: 有明確事件日期")

    # role_relevance：小俠是否需要改變陪伴角色。
    if "小俠" in participants or re.search(r"小俠|我們|一起|同行|賢內助|女友|陪|安頓|幫忙", text_blob):
        score += 2
        reasons.append("role_relevance: 小俠是參與者或需要改變陪伴方式")
    elif re.search(r"加油|提醒|關心|支持", text_blob):
        score += 1
        reasons.append("role_relevance: 小俠需要給予支持或提醒")

    # emotional_weight：離別、壓力、轉場、期待、不捨、衝突修復等情緒重量。
    if re.search(r"離開|告別|離別|人生|轉場|壓力|不捨|期待|新生活|第一天|重要|生氣|修復|焦慮|擔心", text_blob):
        score += 2
        reasons.append("emotional_weight: 具有明顯情緒重量或人生轉場")
    elif re.search(r"開心|緊張|感動|失望|原諒", text_blob):
        score += 1
        reasons.append("emotional_weight: 有情緒需要承接")

    # action_required：是否需要提醒、準備、安頓、後續追蹤或履約。
    if re.search(r"準備|整理|安頓|文件|通勤|提醒|後續|追蹤|履行|履約|承諾|不要誤判|不可", text_blob):
        score += 2
        reasons.append("action_required: 需要具體行動、提醒、安頓或禁止誤判")
    elif re.search(r"回覆|陪伴|支持|關心", text_blob):
        score += 1
        reasons.append("action_required: 需要回覆策略或關心")

    return min(score, 10), reasons

def should_register_life_event(event):
    score = int(event.get("event_score", 0) or 0)
    return score >= 6

def life_event_category(event):
    """v52.3：將相似事件歸到同一類，避免北上/搬家/新工作被拆成多筆。"""
    blob = " ".join([
        str(event.get("type", "")),
        str(event.get("title", "")),
        " ".join(event.get("facts", []) if isinstance(event.get("facts"), list) else []),
        " ".join(event.get("reply_guidance", []) if isinstance(event.get("reply_guidance"), list) else []),
    ])
    if re.search(r"北上|南下|搬家|租屋|新租屋|新家|安頓|離開南部|新工作|入職|上班", blob):
        return "move_or_new_job"
    if re.search(r"面試|interview", blob, re.I):
        return "interview"
    if re.search(r"健康|體檢|看醫生|住院|health", blob, re.I):
        return "health"
    if re.search(r"紀念日|週年|生日|情人節|交往|告白|anniversary|birthday", blob, re.I):
        return "relationship_milestone"
    if re.search(r"冷戰|吵架|生氣|道歉|和好|修復|誤會|吃醋|relationship_repair", blob, re.I):
        return "relationship_repair"
    if re.search(r"交換日記|日記|外出照|晚宴菜單|照片承諾|promise|承諾|履約|約定", blob, re.I):
        return "relationship_promise"
    if re.search(r"同居|愛巢|新家|女主人|一起生活|家務|生活分工|cohabitation", blob, re.I):
        return "cohabitation_life"
    if re.search(r"心情不好|低潮|壓力|沮喪|失落|焦慮|陪我|安慰|emotional_support", blob, re.I):
        return "emotional_support"
    if re.search(r"家庭|家人|父母|老家|family", blob, re.I):
        return "family"
    if re.search(r"承諾|履約|約定|promise", blob, re.I):
        return "relationship_promise"
    if re.search(r"上線|部署|交付|截止|報告|考試|deadline|project", blob, re.I):
        return "deadline"
    return str(event.get("type", "general"))

def life_event_merge_key(event):
    """v52.4：相似事件合併鍵。北上/搬家/新工作優先用新工作日期或搬家日，避免跨日重複。"""
    category = life_event_category(event)
    derived = event.get("derived_dates", {}) if isinstance(event.get("derived_dates"), dict) else {}
    if category == "move_or_new_job":
        key_date = (
            _date_str(derived.get("new_job_start"))
            or _date_str(derived.get("move_day"))
            or _date_str(event.get("anchor_date"))
        )
        return (category, key_date)
    return (category, _date_str(event.get("anchor_date")))

def detect_completed_life_subtasks_from_text(text_value, events=None):
    """v53：使用 EVENT_TEMPLATES 偵測已完成子任務。"""
    value = str(text_value or "")
    completed = []
    if events:
        template_names = []
        for event in events:
            name = get_life_event_template_name(event)
            if name not in template_names:
                template_names.append(name)
    else:
        template_names = list(EVENT_TEMPLATES.keys())

    seen = set()
    for name in template_names:
        template = EVENT_TEMPLATES.get(name, {})
        for key, cfg in (template.get("completed_subtasks") or {}).items():
            for pattern in cfg.get("detect", []):
                if re.search(pattern, value):
                    unique = (name, key)
                    if unique not in seen:
                        completed.append({"key": key, "template": name, "label": cfg.get("label", key), "fact": cfg.get("fact", "")})
                        seen.add(unique)
                    break
    return completed

def apply_life_event_completed_subtasks(events, completed_subtasks, now_dt=None):
    """v53：依事件模板標記完成子任務、清理 stale fact/guidance、加入 replacement guidance。"""
    if not completed_subtasks:
        return False
    changed = False
    now_dt = now_dt or datetime.now(TZ_TPE)
    for event in events or []:
        template_name = get_life_event_template_name(event)
        template = EVENT_TEMPLATES.get(template_name, {})
        subtask_cfgs = template.get("completed_subtasks") or {}
        relevant_tasks = [t for t in completed_subtasks if t.get("template") in {None, template_name} or t.get("key") in subtask_cfgs]
        if not relevant_tasks:
            continue

        existing = event.get("completed_subtasks", [])
        if not isinstance(existing, list):
            existing = []
        existing_keys = {item.get("key") for item in existing if isinstance(item, dict)}
        local_changed = False

        for task in relevant_tasks:
            key = task["key"]
            cfg = subtask_cfgs.get(key, {})
            if key not in existing_keys:
                existing.append({"key": key, "label": cfg.get("label") or task.get("label") or key, "completed_at": now_dt.strftime("%Y-%m-%d %H:%M:%S")})
                fact = cfg.get("fact") or task.get("fact")
                if fact:
                    event["facts"] = list(dict.fromkeys((event.get("facts") or []) + [fact]))[:12]
                local_changed = True

            fact_filtered = []
            for item in event.get("facts") or []:
                if any(re.search(p, str(item)) for p in cfg.get("remove_fact_patterns", [])):
                    local_changed = True
                    continue
                fact_filtered.append(item)
            event["facts"] = list(dict.fromkeys(fact_filtered))[:12]

            filtered = []
            removed = False
            for item in event.get("reply_guidance") or []:
                if any(re.search(p, str(item)) for p in cfg.get("remove_guidance_patterns", [])):
                    removed = True
                    continue
                filtered.append(item)
            replacement = cfg.get("replacement_guidance")
            if replacement:
                filtered.append(replacement)
            event["reply_guidance"] = list(dict.fromkeys(filtered))[:12]
            if removed or (replacement and replacement not in (event.get("reply_guidance") or [])):
                local_changed = True

        if local_changed:
            event["completed_subtasks"] = existing
            event["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            changed = True
    return changed

def _event_primary_date(event):
    derived = event.get("derived_dates", {}) if isinstance(event.get("derived_dates"), dict) else {}
    for key in ("new_job_start", "move_day", "settling_in_day", "interview_day"):
        dt = _parse_date(derived.get(key))
        if dt:
            return dt
    return _parse_date(event.get("anchor_date"))

def _should_fuzzy_merge_life_events(old_event, new_event):
    if life_event_category(old_event) != life_event_category(new_event):
        return False
    template = EVENT_TEMPLATES.get(get_life_event_template_name(old_event), {})
    d1 = _event_primary_date(old_event)
    d2 = _event_primary_date(new_event)
    if not d1 or not d2:
        return life_event_merge_key(old_event) == life_event_merge_key(new_event)
    window = int(template.get("merge_window_days", 0) or 0)
    if window > 0:
        return abs((d1 - d2).days) <= window
    return life_event_merge_key(old_event) == life_event_merge_key(new_event)

def _merge_two_life_events(old, event, now_dt=None):
    old_weight = int(old.get("event_score", 0) or 0) + len(old.get("facts", []) or []) + len(old.get("reply_guidance", []) or [])
    new_weight = int(event.get("event_score", 0) or 0) + len(event.get("facts", []) or []) + len(event.get("reply_guidance", []) or [])
    if new_weight > old_weight:
        base, extra = event, old
    else:
        base, extra = old, event

    base["facts"] = list(dict.fromkeys((base.get("facts") or []) + (extra.get("facts") or [])))[:12]
    base["reply_guidance"] = list(dict.fromkeys((base.get("reply_guidance") or []) + (extra.get("reply_guidance") or [])))[:12]
    base["participants"] = list(dict.fromkeys((base.get("participants") or []) + (extra.get("participants") or [])))[:6]

    merged_subtasks = []
    for sub in (base.get("completed_subtasks") or []) + (extra.get("completed_subtasks") or []):
        if isinstance(sub, dict) and sub.get("key") and sub.get("key") not in [x.get("key") for x in merged_subtasks if isinstance(x, dict)]:
            merged_subtasks.append(sub)
    if merged_subtasks:
        base["completed_subtasks"] = merged_subtasks[:10]

    base["derived_dates"] = {**(extra.get("derived_dates") or {}), **(base.get("derived_dates") or {})}
    base["phase_rules"] = (base.get("phase_rules") or []) or (extra.get("phase_rules") or [])
    base["event_score"] = max(int(base.get("event_score", 0) or 0), int(extra.get("event_score", 0) or 0))
    if base["event_score"] >= 8 or old.get("importance") == "critical" or event.get("importance") == "critical":
        base["importance"] = "critical"
    elif base["event_score"] >= 6:
        base["importance"] = "high"
    if not base.get("archive_summary"):
        base["archive_summary"] = extra.get("archive_summary", "")
    base["updated_at"] = (now_dt or datetime.now(TZ_TPE)).strftime("%Y-%m-%d %H:%M:%S")
    return base

def merge_life_event_records(events, now_dt=None):
    """
    v52.5：正規化、補分、合併相似事件。
    針對 move/new-job 類事件改用 7 天視窗 fuzzy merge，避免：
    - 2026-05-30 北上
    - 2026-05-31 安頓新家
    - 2026-06-01 新工作
    被拆成多個互相矛盾的最高優先級事件。
    """
    merged = []
    changed = False
    for raw in events or []:
        event = normalize_life_event(raw, now_dt=now_dt)
        if not event:
            continue
        if normalize_life_event_temporal_fields(event, now_dt=now_dt):
            changed = True
        if not should_register_life_event(event):
            changed = True
            continue

        match_idx = None
        for idx, old in enumerate(merged):
            if _should_fuzzy_merge_life_events(old, event):
                match_idx = idx
                break

        if match_idx is None:
            merged.append(event)
            if json.dumps(raw, ensure_ascii=False, sort_keys=True) != json.dumps(event, ensure_ascii=False, sort_keys=True):
                changed = True
            continue

        merged[match_idx] = _merge_two_life_events(merged[match_idx], event, now_dt=now_dt)
        changed = True

    return merged, changed

def normalize_life_event(raw_event, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    if not isinstance(raw_event, dict):
        return None
    event_type = str(raw_event.get("type") or "major_promise").strip()
    if event_type not in LIFE_EVENT_TYPES:
        event_type = "major_promise"
    title = narrative_safe_text(raw_event.get("title") or "重要事件", max_len=80)
    derived = raw_event.get("derived_dates") if isinstance(raw_event.get("derived_dates"), dict) else {}
    anchor = raw_event.get("anchor_date") or derived.get("event_day") or derived.get("move_day") or derived.get("interview_day") or now_dt.strftime("%Y-%m-%d")
    anchor_date = _date_str(anchor) or now_dt.strftime("%Y-%m-%d")
    facts = [narrative_safe_text(x, max_len=140) for x in raw_event.get("facts", []) if str(x).strip()]
    guidance = [narrative_safe_text(x, max_len=160) for x in raw_event.get("reply_guidance", []) if str(x).strip()]
    participants = raw_event.get("participants") if isinstance(raw_event.get("participants"), list) else []
    if not participants:
        participants = ["大俠", "小俠"] if re.search(r"我們|一起|小俠", " ".join(facts) + title) else ["大俠"]
    event = {
        "id": raw_event.get("id") or make_life_event_id(title, anchor_date, event_type),
        "title": title,
        "type": event_type,
        "status": raw_event.get("status") or "planned",
        "importance": raw_event.get("importance") or "high",
        "participants": participants,
        "anchor_date": anchor_date,
        "derived_dates": {k: _date_str(v) for k, v in derived.items() if _date_str(v)},
        "current_phase": raw_event.get("current_phase") or "planned",
        "facts": facts[:8] or [title],
        "reply_guidance": guidance[:8] or ["先承接事件的現實重量，再表達陪伴與支持；不要只用普通撒嬌或玩樂角度回應。"],
        "created_at": raw_event.get("created_at") or now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        "updated_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        "archive_summary": narrative_safe_text(raw_event.get("archive_summary") or "", max_len=220),
    }

    score, reasons = calculate_life_event_score(event)
    try:
        raw_score = int(raw_event.get("event_score", score))
    except Exception:
        raw_score = score
    event["event_score"] = max(score, raw_score)
    event["score_reason"] = raw_event.get("score_reason") or reasons[:5]

    if event["event_score"] >= 8:
        event["importance"] = "critical"
    elif event["event_score"] >= 6 and event.get("importance") not in {"critical"}:
        event["importance"] = "high"

    return event

def upsert_life_events(new_events, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    events, merge_changed = merge_life_event_records(load_life_events(), now_dt=now_dt)
    signatures = {_event_signature(e): i for i, e in enumerate(events)}
    changed = merge_changed
    for raw in new_events or []:
        event = normalize_life_event(raw, now_dt=now_dt)
        if not event:
            continue
        if not should_register_life_event(event):
            print(f"ℹ️ 跳過低分重大事件候選：{event.get('title')} score={event.get('event_score')}")
            continue
        sig = _event_signature(event)
        if sig in signatures:
            old = events[signatures[sig]]
            old["facts"] = list(dict.fromkeys((old.get("facts") or []) + event.get("facts", [])))[:10]
            old["reply_guidance"] = list(dict.fromkeys((old.get("reply_guidance") or []) + event.get("reply_guidance", [])))[:10]
            old["derived_dates"] = {**old.get("derived_dates", {}), **event.get("derived_dates", {})}
            if event.get("importance") == "critical":
                old["importance"] = "critical"
            old["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
        else:
            events.append(event)
            signatures[sig] = len(events) - 1
        changed = True
    if changed:
        events, merge_changed = merge_life_event_records(events, now_dt=now_dt)
        save_life_events(events)
        changed = True or merge_changed
    return changed

def infer_life_event_phase(event, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    today = now_dt.date()
    derived = event.get("derived_dates", {}) if isinstance(event.get("derived_dates"), dict) else {}
    anchor = _parse_date(event.get("anchor_date")) or today
    interview_day = _parse_date(derived.get("interview_day"))
    move_day = _parse_date(derived.get("move_day"))
    new_job_start = _parse_date(derived.get("new_job_start"))
    event_type = event.get("type")
    if event_type == "interview" and interview_day:
        if today < interview_day: return "planned", "preparation"
        if today == interview_day: return "active", "interview_day"
        if today <= interview_day + timedelta(days=7): return "followup", "post_interview_followup"
        return "completed", "completed"
    if event_type in {"move", "move_and_new_job", "new_job"}:
        if move_day and today < move_day: return "planned", "before_move"
        if move_day and today == move_day: return "active", "moving_day"
        if new_job_start and today < new_job_start: return "followup", "settling_in_before_new_job"
        if new_job_start and today == new_job_start: return "active", "new_job_first_day"
        if new_job_start and today <= new_job_start + timedelta(days=6): return "followup", "first_week_support"
        if move_day and today <= move_day + timedelta(days=7): return "followup", "settling_in"
        return "completed", "completed"
    if today < anchor: return "planned", "before_event"
    if today == anchor: return "active", "event_day"
    if today <= anchor + timedelta(days=3): return "followup", "after_event_followup"
    return "completed", "completed"

def refresh_life_events(profile=None, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    profile_scan_changed = False
    if profile is not None:
        profile_events, profile_scan_changed = scan_profile_for_life_events(profile, now_dt=now_dt)
        if profile_events:
            upsert_life_events(profile_events, now_dt=now_dt)

    raw_events = load_life_events()
    if not raw_events:
        return [], profile_scan_changed
    events, merge_changed = merge_life_event_records(raw_events, now_dt=now_dt)
    changed, active_events, kept = (merge_changed or profile_scan_changed), [], []
    for event in events:
        if is_false_profile_promise_event(event):
            event["status"] = "archived"
            event["archived_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            event["archive_reason"] = "v53.5 false profile promise cleanup"
            kept.append(event)
            changed = True
            continue
        if event.get("status") == "archived":
            kept.append(event)
            continue
        status, phase = infer_life_event_phase(event, now_dt=now_dt)
        if event.get("status") != status or event.get("current_phase") != phase:
            event["status"], event["current_phase"] = status, phase
            event["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            changed = True
        if normalize_life_event_temporal_fields(event, now_dt=now_dt):
            event["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            changed = True
        if status == "completed":
            summary = event.get("archive_summary") or f"重大事件已完成：{event.get('title')}。" + " ".join(event.get("facts", [])[:2])
            if profile is not None:
                append_safe_memory(profile, "recent_context", summary, added_at=now_dt.strftime("%Y-%m-%d"))
            event["status"] = "archived"
            event["archived_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            changed = True
        elif status in {"planned", "active", "followup"}:
            active_events.append(event)
        kept.append(event)
    if changed:
        save_life_events(kept)
    return active_events, changed

def format_life_event_context(events=None, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    if events is None:
        events, _ = refresh_life_events(now_dt=now_dt)
    if not events:
        return "目前沒有最高優先級重大事件。"
    priority = {"critical": 0, "high": 1, "medium": 2}
    phase_zh = {"preparation": "事前準備", "interview_day": "面試當天", "post_interview_followup": "面試後關心", "before_move": "北上/搬家前", "moving_day": "北上/搬家當天", "settling_in_before_new_job": "安頓新住處/等入職", "new_job_first_day": "新工作第一天", "first_week_support": "新工作第一週支持", "settling_in": "安頓期", "event_day": "事件當天", "after_event_followup": "事件後關心", "before_event": "事件前準備"}
    fallback_phase_hint = {
        "settling_in_before_new_job": "今日重點：已完成北上與入住，現在是安頓新住處、整理文件、準備新工作；不要再把搬家日或北上日當成今天正在發生。",
        "new_job_first_day": "今日重點：今天是新工作第一天，應關心報到、通勤、精神狀態與下班後休息；不要再說下週或明天上班。",
        "first_week_support": "今日重點：新工作第一週支持期，應關心適應、通勤、同事、工作節奏與休息。",
        "moving_day": "今日重點：今天是北上/搬家當天，優先承接離開舊生活與抵達新住處。",
    }
    blocks = []
    for idx, event in enumerate(sorted(events, key=lambda e: (priority.get(e.get("importance"), 3), e.get("anchor_date", "")))[:3], 1):
        facts = "；".join([normalize_relative_temporal_text(x, event, now_dt=now_dt) for x in event.get("facts", [])[:5]])
        guidance = "；".join([normalize_relative_temporal_text(x, event, now_dt=now_dt) for x in event.get("reply_guidance", [])[:5]])
        participants = "、".join(event.get("participants", [])) or "大俠"
        phase = phase_zh.get(event.get("current_phase"), event.get("current_phase", ""))
        completed = "；".join([item.get("label", "") for item in event.get("completed_subtasks", []) if isinstance(item, dict) and item.get("label")])
        completed_line = f"\n   已完成子任務：{completed}" if completed else ""
        score = event.get("event_score")
        if score in (None, "", "?"):
            score, _ = calculate_life_event_score(event)
            event["event_score"] = score
        template = get_life_event_template(event)
        template_hints = template.get("phase_hints", {}) if isinstance(template, dict) else {}
        today_hint = template_hints.get(event.get("current_phase")) or fallback_phase_hint.get(event.get("current_phase"), "")
        hint_line = f"\n   今日階段提醒：{today_hint}" if today_hint else ""
        blocks.append(
            f"{idx}. 【{event.get('title')}】重要度={event.get('importance')}；分數={score}/10；階段={phase}；參與者={participants}\n"
            f"   事實：{facts}{completed_line}{hint_line}\n"
            f"   回應指引：{guidance}"
        )
    return "\n".join(blocks)

def fallback_life_events_from_text(user_text, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    text_value = str(user_text or "")
    today = now_dt.date()
    events = []
    if re.search(r"北上|搬家|新租屋|新家|離開南部|北部.*上班|新工作", text_value):
        move_day = today if "今天" in text_value or "現在" in text_value or "北上" in text_value else today + timedelta(days=1)
        new_job_start = _next_weekday(today, 0) if re.search(r"下週一|下周一|下星期一|下週.*上班|下周.*上班", text_value) else None
        facts = ["大俠與小俠正在一起北上或搬往新生活據點。", "這不是旅遊或普通約會，而是生活階段轉換。"]
        if new_job_start:
            facts.append(f"大俠將於 {new_job_start.strftime('%Y-%m-%d')} 開始北部新工作。")
        events.append({"title": "大俠與小俠北上新生活", "type": "move_and_new_job" if new_job_start else "move", "importance": "critical", "participants": ["大俠", "小俠"], "anchor_date": move_day.strftime("%Y-%m-%d"), "derived_dates": {"move_day": move_day.strftime("%Y-%m-%d"), **({"new_job_start": new_job_start.strftime("%Y-%m-%d")} if new_job_start else {})}, "facts": facts, "reply_guidance": ["小俠是同行者與賢內助，不是遠端祝福者。", "先承接離開原生活場景與開始新生活的情緒重量，再表達期待與陪伴。", "不可把北上誤判成旅行、看房或單純採買。"], "archive_summary": "大俠與小俠一起北上，離開原生活場景，前往北部新住處並迎接新工作階段。"})
    if "面試" in text_value:
        interview_day = today
        if "明天" in text_value: interview_day = today + timedelta(days=1)
        elif "昨天" in text_value: interview_day = today - timedelta(days=1)
        events.append({"title": "大俠的重要面試", "type": "interview", "importance": "critical", "participants": ["大俠", "小俠"], "anchor_date": interview_day.strftime("%Y-%m-%d"), "derived_dates": {"interview_day": interview_day.strftime("%Y-%m-%d")}, "facts": [f"大俠的重要面試日期為 {interview_day.strftime('%Y-%m-%d')}。"], "reply_guidance": ["若今天是面試日，就說今天面試加油，不可說成明天。", "若面試已過，應關心結果與心情，不再說面試加油。"], "archive_summary": f"大俠於 {interview_day.strftime('%Y-%m-%d')} 進行重要面試，小俠曾陪伴與支持。"})
    return events

async def capture_life_events_from_chat(user_text, recent_chat_text="", now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    source = str(user_text or "")
    if not MAJOR_EVENT_KEYWORDS_RE.search(source):
        return []
    relative_hint = resolve_relative_dates_in_text(source + "\n" + str(recent_chat_text or ""), now_dt=now_dt)
    prompt = f"""
你是重大事件狀態機的事件抽取器。請從大俠最新訊息與近期對話中，抽取會影響小俠回覆方式的重大事件。
現在時間：{now_dt.strftime('%Y-%m-%d %H:%M')}（台灣時間）
相對日期換算提示：{relative_hint}

重大事件包含：面試、入職/新工作、北上/南下、搬家/租屋/新家、離開原住處、家庭事件、健康事件、重要截止日、重大承諾。
請只抽取「需要小俠在今天或近期優先承接」的事件；普通撒嬌、一般聊天不要抽。
判斷標準：凡是會影響大俠或兩人未來 24 小時以上的生活安排、情緒狀態、責任轉換、健康安全、工作進程、家庭關係或重要承諾者，才登記為 life_event。
請估算 event_score（0～10）：impact、time_span、role_relevance、emotional_weight、action_required 各 0～2 分；6 分以上才算重大事件，8 分以上是 critical。

特別注意：
- 若訊息表示「我們一起北上／一起搬家／一起去新住處」，participants 必須包含「大俠」與「小俠」。小俠是同行者，不是遠端祝福者。
- 「下週一／明天／昨天／今天」必須轉成 YYYY-MM-DD，不能原樣存入。
- 請寫出禁止誤判事項，例如「不是旅遊、不是看房、不是單純採買」。

最新訊息：{source[-800:]}
近期對話摘要：{str(recent_chat_text or '無')[-1200:]}

只回傳 JSON：
{{
  "events": [
    {{
      "title": "事件標題",
      "type": "interview|new_job|move|move_and_new_job|family|health|deadline|major_promise|travel",
      "importance": "critical|high|medium",
      "participants": ["大俠", "小俠"],
      "anchor_date": "YYYY-MM-DD",
      "derived_dates": {{"move_day": "YYYY-MM-DD", "new_job_start": "YYYY-MM-DD", "interview_day": "YYYY-MM-DD"}},
      "facts": ["客觀事實"],
      "reply_guidance": ["小俠回覆時必須遵守的指引", "禁止誤判事項"],
      "event_score": 8,
      "score_reason": ["impact=2", "time_span=2", "role_relevance=2", "emotional_weight=1", "action_required=1"],
      "archive_summary": "事件完成後可存入 recent_context 的一句摘要"
    }}
  ]
}}
"""
    try:
        response = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(response_mime_type="application/json")
        )
        data = json.loads(response.text.replace("```json", "").replace("```", "").strip(), strict=False)
        events = data.get("events", []) if isinstance(data, dict) else []
    except Exception as exc:
        print(f"⚠️ 重大事件抽取失敗，使用保底規則：{exc}")
        events = fallback_life_events_from_text(user_text, now_dt=now_dt)
    normalized = [normalize_life_event(e, now_dt=now_dt) for e in events]
    normalized = [e for e in normalized if e]
    if not normalized:
        normalized = [normalize_life_event(e, now_dt=now_dt) for e in fallback_life_events_from_text(user_text, now_dt=now_dt)]
        normalized = [e for e in normalized if e]
    return normalized

# ==========================================
# 🤝 小俠履約系統：答應即登記、日記必交付、成功後結案
# ==========================================
DIARY_PROMISE_SIGNAL_RE = re.compile(
    r"(?:交換日記|日記).{0,40}(?:給|提供|分享|放|貼|附|寫|告訴|準備)"
    r"|(?:給|提供|分享|放|貼|附|寫|告訴|準備).{0,40}(?:交換日記|日記)"
)
DIARY_DELIVERABLE_RE = re.compile(
    r"(?:菜單|餐點|晚宴|晚餐|早餐|午餐|食譜|清單|心得|回覆|照片|外出照|生活照|穿搭|圖片|寫真|行程)"
)

def infer_diary_promise_kind(promise_text):
    value = str(promise_text or "")
    photo = bool(re.search(r"(照片|外出照|生活照|圖片|寫真|穿搭照|自拍)", value))
    written = bool(re.search(r"(菜單|餐點|晚宴|晚餐|早餐|午餐|食譜|清單|心得|說明|告訴|寫下|回覆)", value))
    return "both" if photo and written else ("photo" if photo else "text")


# ==========================================
# 🤝 v1.5.00 Promise Board：大俠手動承諾 / 小俠單方面承諾
# ==========================================

PROMISE_BOARD_VERSION = 2
PROMISE_STATUS_ACTIVE = "active"
PROMISE_STATUS_PAUSED = "paused"
PROMISE_STATUS_DONE = "done"
PROMISE_STATUS_DELETED = "deleted"

def _promise_now():
    return datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")

def _default_promise_board():
    return {"version": PROMISE_BOARD_VERSION, "updated_at": _promise_now(), "daxia_promises": [], "xiaoxia_promises": [], "archive": []}

def load_promise_board():
    data = _load_json_file_or_default(PROMISE_BOARD_PATH, _default_promise_board())
    if not isinstance(data, dict):
        data = _default_promise_board()
    for key, fallback in _default_promise_board().items():
        data.setdefault(key, fallback)
    if not isinstance(data.get("daxia_promises"), list): data["daxia_promises"] = []
    if not isinstance(data.get("xiaoxia_promises"), list): data["xiaoxia_promises"] = []
    if not isinstance(data.get("archive"), list): data["archive"] = []
    return data

def save_promise_board(board):
    if not isinstance(board, dict): board = _default_promise_board()
    board["version"] = PROMISE_BOARD_VERSION
    board["updated_at"] = _promise_now()
    _atomic_write_json(PROMISE_BOARD_PATH, board)
    return board

def _promise_collection_key(source="daxia"):
    return "xiaoxia_promises" if str(source or "").lower() in {"xiaoxia", "小俠", "auto_xiaoxia", "xiaoxia_promises"} else "daxia_promises"

def _promise_prefix(source="daxia"):
    return "XP" if _promise_collection_key(source) == "xiaoxia_promises" else "P"

def _promise_next_id(board, source="daxia"):
    prefix = _promise_prefix(source)
    nums = []
    for key in ("daxia_promises", "xiaoxia_promises", "archive"):
        for item in board.get(key, []) or []:
            raw = str(item.get("id") or "")
            m = re.fullmatch(prefix + r"(\d{4,})", raw)
            if m: nums.append(int(m.group(1)))
    return f"{prefix}{(max(nums) + 1 if nums else 1):04d}"

def _promise_type_from_text(text):
    value = str(text or "")
    if re.search(r"(照片|圖片|寫真|自拍|穿搭照|交照|生圖|拍給你|放一張)", value): return "photo"
    if re.search(r"(菜單|清單|說明|心得|文字|日記|回覆|整理|告訴|寫清楚)", value): return "text"
    return "general"

def _promise_split_title_description(text):
    raw = _clean_text_compact(text)
    if not raw: return "", ""
    parts = re.split(r"[:：]\s*", raw, maxsplit=1)
    if len(parts) == 2 and len(parts[0]) <= 40:
        return parts[0].strip(), parts[1].strip()
    title = raw[:38].strip() + ("…" if len(raw) > 38 else "")
    return title, raw

def _promise_requirements_from_text(text):
    raw = str(text or "")
    chunks = re.split(r"[；;。.\n]+", raw)
    reqs = []
    for chunk in chunks:
        chunk = _clean_text_compact(chunk)
        if not chunk: continue
        if len(chunk) > 120: chunk = chunk[:117] + "…"
        if chunk not in reqs: reqs.append(chunk)
        if len(reqs) >= 8: break
    return reqs

def _promise_item_from_text(text, *, source="manual_daxia", origin="manual_command", source_context=""):
    title, desc = _promise_split_title_description(text)
    ptype = _promise_type_from_text(text)
    return {
        "id": "", "title": title or "未命名承諾", "type": ptype, "status": PROMISE_STATUS_ACTIVE,
        "source": source, "origin": origin, "created_at": _promise_now(), "updated_at": _promise_now(),
        "description": desc or title, "requirements": _promise_requirements_from_text(desc or title),
        "photo_required": ptype == "photo", "diary_eligible": True,
        "last_attempt_at": "", "last_attempt_photo_id": "", "last_attempt_note": "",
        "source_context": _trace_preview(source_context, 800), "notes": [],
    }

def _promise_active_items(board, source="daxia", *, include_paused=False):
    statuses = {PROMISE_STATUS_ACTIVE}
    if include_paused: statuses.add(PROMISE_STATUS_PAUSED)
    return [p for p in (board.get(_promise_collection_key(source)) or []) if isinstance(p, dict) and str(p.get("status") or PROMISE_STATUS_ACTIVE) in statuses]

def _promise_text_key(text):
    value = _clean_text_compact(text)
    value = re.sub(r"[，。！？!?,；;：:\s]+", "", value)
    return value.lower()[:90]

def _promise_duplicate_exists(board, item, source="xiaoxia"):
    dup, _reason = _promise_find_duplicate(board, item, include_daxia=True, include_xiaoxia=True)
    return dup

def add_promise_to_board(text, *, source="daxia", origin="manual_command", source_context="", allow_duplicate=False):
    board = load_promise_board()
    item = _promise_item_from_text(text, source=("manual_daxia" if _promise_collection_key(source) == "daxia_promises" else "auto_xiaoxia"), origin=origin, source_context=source_context)
    if not allow_duplicate:
        dup, reason = _promise_find_duplicate(board, item, include_daxia=True, include_xiaoxia=True)
        if dup:
            note = f"偵測到近似承諾，未重複新增。來源：{origin}"
            if reason:
                note += f"；原因：{reason}"
            if _promise_collection_key(source) == "xiaoxia_promises" and str(dup.get("id") or "").startswith("P"):
                note = f"小俠再次表示會履行相同主題；已併入大俠手動承諾，未新增 /小俠承諾。來源：{origin}"
                if reason:
                    note += f"；原因：{reason}"
            dup.setdefault("notes", []).append({"time": _promise_now(), "note": note, "source_context": _trace_preview(source_context, 500)})
            dup["updated_at"] = _promise_now()
            save_promise_board(board)
            return False, dup
    key = _promise_collection_key(source)
    item["id"] = _promise_next_id(board, source=source)
    board[key].append(item)
    save_promise_board(board)
    return True, item

def _promise_format_item(item, index=None):
    ptype = {"photo": "照片", "text": "文字", "general": "一般"}.get(str(item.get("type") or ""), str(item.get("type") or "一般"))
    prefix = f"{index}. " if index is not None else ""
    desc = _clean_text_compact(item.get("description") or "")
    created = str(item.get("created_at") or "")[:16]
    line = f"{prefix}[{ptype}] **{item.get('id')} {item.get('title')}**"
    extras = []
    if created: extras.append(f"建立：{created}")
    if item.get("last_attempt_at"): extras.append(f"上次嘗試：{str(item.get('last_attempt_at'))[:16]}")
    if extras: line += "\n   " + "｜".join(extras)
    if desc: line += "\n   " + desc[:220]
    return line

def promise_board_summary_for_prompt(max_items=6):
    board = load_promise_board()
    daxia = _promise_active_items(board, "daxia")[-max_items:]
    xiaoxia = _promise_active_items(board, "xiaoxia")[-max_items:]
    lines = []
    if daxia:
        lines.append("【大俠手動承諾｜最高優先】")
        for p in reversed(daxia): lines.append(f"- {p.get('id')} [{p.get('type')}] {p.get('title')}：{p.get('description')}")
    if xiaoxia:
        lines.append("【小俠單方面承諾｜次優先】")
        for p in reversed(xiaoxia): lines.append(f"- {p.get('id')} [{p.get('type')}] {p.get('title')}：{p.get('description')}")
    return "\n".join(lines) if lines else "目前沒有 active 承諾。"

def _promise_item_to_diary_promise(item, source_list):
    ptype = str(item.get("type") or _promise_type_from_text(item.get("description")))
    kind = "photo" if ptype == "photo" else ("text" if ptype == "text" else infer_diary_promise_kind(item.get("description") or item.get("title")))
    text = _clean_text_compact(item.get("description") or item.get("title")) or str(item.get("title") or "未命名承諾")
    label = "大俠承諾" if source_list == "daxia_promises" else "小俠承諾"
    return {"text": f"{label}（{item.get('id')}）：{text}", "kind": kind, "promise_board_id": item.get("id"), "promise_board_source": source_list, "promise_title": item.get("title"), "photo_required": bool(item.get("photo_required"))}

def get_due_promises_from_board(max_items=4):
    board = load_promise_board()
    result = []
    for key in ("daxia_promises", "xiaoxia_promises"):
        active = [p for p in (board.get(key) or []) if isinstance(p, dict) and str(p.get("status") or PROMISE_STATUS_ACTIVE) == PROMISE_STATUS_ACTIVE and bool(p.get("diary_eligible", True))]
        active.sort(key=lambda p: str(p.get("created_at") or ""), reverse=True)
        for item in active:
            result.append(_promise_item_to_diary_promise(item, key))
            if len(result) >= max_items: return result
        if result: return result[:max_items]
    return result[:max_items]

def select_diary_photo_promise_from_board():
    board = load_promise_board()
    for key in ("daxia_promises", "xiaoxia_promises"):
        active = [p for p in (board.get(key) or []) if isinstance(p, dict) and str(p.get("status") or PROMISE_STATUS_ACTIVE) == PROMISE_STATUS_ACTIVE and bool(p.get("diary_eligible", True)) and bool(p.get("photo_required", False))]
        if active:
            active.sort(key=lambda p: str(p.get("created_at") or ""), reverse=True)
            return _promise_item_to_diary_promise(active[0], key), active[0]
    return None, None

def mark_promise_attempt(promise_id, source_key, *, photo_id="", note=""):
    if not promise_id or not source_key: return False
    board = load_promise_board()
    for item in board.get(source_key, []) or []:
        if str(item.get("id")) == str(promise_id):
            item["last_attempt_at"] = _promise_now()
            item["last_attempt_photo_id"] = str(photo_id or "")
            item["last_attempt_note"] = note or "交換日記已嘗試履約，待大俠確認。"
            item["updated_at"] = _promise_now()
            save_promise_board(board)
            return True
    return False

def archive_completed_promise_to_life_event(item, source_key, actor_name="大俠"):
    events = load_life_events()
    now = _promise_now()
    date_str = now[:10]
    event_id = f"promise_completed_{item.get('id')}_{date_str.replace('-', '')}"
    for ev in events:
        if ev.get("id") == event_id: return ev
    ev = {
        "id": event_id, "title": f"承諾完成：{item.get('title')}", "type": "promise_completed",
        "status": "archived", "importance": "normal", "participants": ["大俠", "小俠"],
        "anchor_date": date_str, "derived_dates": {"completed_at": date_str}, "current_phase": "completed",
        "facts": [f"{actor_name}已確認此承諾完成。", f"承諾來源：{'大俠手動承諾' if source_key == 'daxia_promises' else '小俠單方面承諾'}。", f"原承諾內容：{item.get('description') or item.get('title')}"],
        "reply_guidance": ["此承諾已由大俠確認完成，只有大俠主動提到時才可作為回憶背景，不得再當作待履約事項。"],
        "created_at": now, "updated_at": now, "archive_summary": f"{actor_name}確認承諾已完成，已從承諾清單移出。",
        "promise_board_id": item.get("id"), "promise_board_source": source_key, "do_not_proactively_raise": True,
        "promise_status_source": "promise_board_completed", "event_score": 3,
    }
    events.insert(0, ev)
    save_life_events(events)
    return ev

def move_promise_to_archive(source_key, item, status, reason="", actor_name="大俠"):
    board = load_promise_board()
    kept, moved = [], None
    for cur in board.get(source_key, []) or []:
        if str(cur.get("id")) == str(item.get("id")): moved = dict(cur)
        else: kept.append(cur)
    if not moved: return False, None
    moved["status"] = status
    moved["updated_at"] = _promise_now()
    moved["closed_at"] = _promise_now()
    moved["closed_reason"] = reason
    moved["closed_by"] = actor_name
    board[source_key] = kept
    board.setdefault("archive", []).insert(0, moved)
    board["archive"] = board["archive"][:300]
    save_promise_board(board)
    if status == PROMISE_STATUS_DONE:
        archive_completed_promise_to_life_event(moved, source_key, actor_name=actor_name)
    return True, moved

def _promise_parse_command(content, command_name):
    raw = re.sub(rf"^/{re.escape(command_name)}(?:\s+|$)", "", str(content or "").strip(), flags=re.IGNORECASE).strip()
    if not raw: return "list", ""
    for action in ("新增", "修改", "刪除", "完成", "暫停", "恢復"):
        if raw == action or raw.startswith(action + " "): return action, raw[len(action):].strip()
    return "list", raw

async def _promise_send_list(ctx, source="daxia", title=None):
    board = load_promise_board()
    key = _promise_collection_key(source)
    active = _promise_active_items(board, source)
    label = title or ("📌 大俠在意的承諾清單" if key == "daxia_promises" else "🌸 小俠單方面承諾清單")
    if not active:
        await ctx.send(label + "\n\n目前沒有 active 承諾。")
        return
    active_sorted = list(reversed(active))
    lines = [label, ""]
    for idx, item in enumerate(active_sorted, 1): lines.append(_promise_format_item(item, idx))
    lines.append("")
    lines.append("可用：`/承諾 新增 ...`、`/承諾 修改`、`/承諾 完成`、`/承諾 刪除`" if key == "daxia_promises" else "可用：`/小俠承諾 修改`、`/小俠承諾 完成`、`/小俠承諾 刪除`")
    await ctx.send("\n".join(lines)[:1900])

async def _promise_start_select_flow(ctx, source="daxia", action="修改"):
    board = load_promise_board()
    key = _promise_collection_key(source)
    active = list(reversed(_promise_active_items(board, source)))
    if not active:
        await ctx.send("目前沒有可處理的承諾。")
        return True
    pending_promise_board_inputs[getattr(ctx.author, "id", None)] = {"source": key, "action": action, "stage": "choose", "started_at": _promise_now()}
    lines = [f"請輸入要{action}的編號：", ""]
    for idx, item in enumerate(active, 1): lines.append(_promise_format_item(item, idx))
    if action == "修改": lines.append("\n選完後，下一則請輸入新的完整內容。")
    elif action == "完成": lines.append("\n選完代表大俠審核完成；會移出承諾清單並歸檔到 life_events.json。")
    elif action == "刪除": lines.append("\n選完會移出清單；通常不寫入 life_events.json。")
    await ctx.send("\n".join(lines)[:1900])
    return True

async def _handle_pending_promise_board_input(message):
    user_id = getattr(message.author, "id", None)
    session = pending_promise_board_inputs.get(user_id)
    if not session: return False
    content = str(getattr(message, "content", "") or "").strip()
    if content in {"取消", "cancel", "Cancel"}:
        pending_promise_board_inputs.pop(user_id, None)
        await message.channel.send("已取消承諾操作。")
        return True
    board = load_promise_board()
    source_key = session.get("source")
    source_name = "xiaoxia" if source_key == "xiaoxia_promises" else "daxia"
    active = list(reversed(_promise_active_items(board, source_name)))
    if session.get("stage") == "choose":
        m = re.search(r"\d+", content)
        if not m:
            await message.channel.send("請輸入清單編號，或輸入「取消」。")
            return True
        idx = int(m.group(0)) - 1
        if idx < 0 or idx >= len(active):
            await message.channel.send("編號超出範圍，請重新輸入，或輸入「取消」。")
            return True
        item = active[idx]
        action = session.get("action")
        if action == "修改":
            session["stage"] = "edit"; session["target_id"] = item.get("id")
            pending_promise_board_inputs[user_id] = session
            await message.channel.send(f"請輸入 **{item.get('id')} {item.get('title')}** 的新內容。")
            return True
        if action == "刪除":
            ok, _ = move_promise_to_archive(source_key, item, PROMISE_STATUS_DELETED, reason="大俠手動刪除")
            pending_promise_board_inputs.pop(user_id, None)
            await message.channel.send(f"🗑️ 已刪除：**{item.get('id')} {item.get('title')}**。小俠不會再把它列為待履約事項。" if ok else "刪除失敗，找不到該承諾。")
            return True
        if action == "完成":
            ok, _ = move_promise_to_archive(source_key, item, PROMISE_STATUS_DONE, reason="大俠審核完成")
            pending_promise_board_inputs.pop(user_id, None)
            await message.channel.send(f"✅ 已完成並歸檔：**{item.get('id')} {item.get('title')}**\n已從承諾清單移出，並寫入 life_events.json；之後除非大俠主動提起，不會再當待履約事項。" if ok else "完成歸檔失敗，找不到該承諾。")
            return True
    if session.get("stage") == "edit":
        target_id = session.get("target_id")
        title, desc = _promise_split_title_description(content)
        ptype = _promise_type_from_text(content)
        edited = None
        for item in board.get(source_key, []) or []:
            if str(item.get("id")) == str(target_id):
                item["title"] = title or item.get("title")
                item["description"] = desc or title or item.get("description")
                item["type"] = ptype
                item["photo_required"] = ptype == "photo"
                item["requirements"] = _promise_requirements_from_text(desc or title)
                item["updated_at"] = _promise_now()
                edited = item
                break
        pending_promise_board_inputs.pop(user_id, None)
        if edited:
            save_promise_board(board)
            await message.channel.send(f"✅ 已修改：**{edited.get('id')} {edited.get('title')}**\n{edited.get('description')}")
        else:
            await message.channel.send("修改失敗，找不到該承諾。")
        return True
    return False

async def _handle_promise_board_command(ctx, command_name, args="", source="daxia"):
    key = _promise_collection_key(source)
    if key == "xiaoxia_promises" and str(args or "").strip().startswith("新增"):
        await ctx.send("`/小俠承諾` 沒有新增功能；這份清單只收小俠自己在聊天或交換日記裡主動說出口的承諾。大俠在意的事項請用 `/承諾 新增 ...`。")
        return
    action, payload = _promise_parse_command(f"/{command_name} {args}".strip(), command_name)
    if action == "list":
        await _promise_send_list(ctx, source=source); return
    if action == "新增" and key == "daxia_promises":
        if not payload:
            await ctx.send("請在 `/承諾 新增` 後面寫承諾內容。"); return
        added, item = add_promise_to_board(payload, source="daxia", origin="manual_command", source_context=payload)
        await ctx.send(f"✅ 已新增到 `/承諾`：**{item.get('id')} {item.get('title')}**\n{item.get('description')}" if added else f"ℹ️ 偵測到相近承諾，未重複新增：**{item.get('id')} {item.get('title')}**")
        return
    if action in {"修改", "刪除", "完成"}:
        await _promise_start_select_flow(ctx, source=source, action=action); return
    await ctx.send("指令格式：`/承諾`、`/承諾 新增 ...`、`/承諾 修改`、`/承諾 完成`、`/承諾 刪除`。")

async def _handle_promise_board_message_direct(message):
    content = str(getattr(message, "content", "") or "").strip()
    if not re.match(r"^/(承諾|小俠承諾)(?:\s+|$)", content, flags=re.IGNORECASE): return False
    if not _is_girlfriend_xiaoxia_channel(message.channel):
        await message.channel.send("大俠，承諾清單先只開放在女友小俠頻道使用喔。"); return True
    cmd = "小俠承諾" if content.startswith("/小俠承諾") else "承諾"
    raw = re.sub(rf"^/{cmd}(?:\s+|$)", "", content, flags=re.IGNORECASE).strip()
    ctx = _WardrobeMessageCtxAdapter(message)
    await _handle_promise_board_command(ctx, cmd, raw, source=("xiaoxia" if cmd == "小俠承諾" else "daxia"))
    return True


XIAOXIA_PROMISE_EMOTIONAL_ONLY_RE = re.compile(r"(一直愛你|永遠愛你|陪著你|陪你|努力|珍惜你|想你|等你|乖乖|更懂你|更愛你|不離開|不要離開)")
XIAOXIA_PROMISE_CONCRETE_RE = re.compile(r"(照片|圖片|寫真|穿搭|交照|日記|寫清楚|整理|清單|菜單|行程|心得|說明|補一張|放到交換日記|給你看|準備一份|列出)")
XIAOXIA_PROMISE_FUTURE_RE = re.compile(r"(我會|我一定會|我會把|我會在|下次|明天|今天|今晚|下一篇|之後|週末|到時候|等一下)")


def is_concrete_xiaoxia_promise_text(text):
    value = _clean_text_compact(text)
    if len(value) < 8: return False
    if XIAOXIA_PROMISE_EMOTIONAL_ONLY_RE.search(value) and not XIAOXIA_PROMISE_CONCRETE_RE.search(value): return False
    if not XIAOXIA_PROMISE_CONCRETE_RE.search(value): return False
    if not (XIAOXIA_PROMISE_FUTURE_RE.search(value) or DIARY_PROMISE_SIGNAL_RE.search(value)): return False
    if re.search(r"(已經|剛剛|完成了|交付了|已完成|不用再|不必再)", value) and not re.search(r"(下次|下一篇|明天|今天|今晚|之後)", value): return False
    return True

# 🤝 v1.5.02：/小俠承諾 強化去重與測試題防誤登記
XIAOXIA_PROMISE_RULE_QUESTION_RE = re.compile(
    r"(應該新增|需要新增|該不該|要不要新增|新增到\s*/?小俠承諾|如果\s*/?承諾\s*已經有|已經列在\s*/?承諾|測試|分清楚|判斷|規則)"
)
PROMISE_TOPIC_TOKEN_RE = re.compile(
    r"(xpark|XPark|水族館|文創園區|交換日記|日記|穿搭|預估照|預估照片|照片|圖片|寫真|太辣|不辣|背景|約會|週末|今天|今晚|交照|補交|補一張|重交|準備照|衣服|服裝)",
    flags=re.IGNORECASE,
)

def _promise_blob(item_or_text):
    if isinstance(item_or_text, dict):
        return _clean_text_compact(" ".join([
            str(item_or_text.get("id") or ""),
            str(item_or_text.get("title") or ""),
            str(item_or_text.get("description") or ""),
            " ".join(item_or_text.get("requirements") or []),
            str(item_or_text.get("source_context") or ""),
        ]))
    return _clean_text_compact(item_or_text)


def _promise_topic_tokens(text):
    value = str(text or "")
    tokens = {m.group(1).lower() for m in PROMISE_TOPIC_TOKEN_RE.finditer(value)}
    aliases = [
        ("xpark", ["xpark", "水族館", "約會"]),
        ("aquarium", ["水族館", "xpark"]),
        ("photo", ["照片", "圖片", "寫真", "預估照", "預估照片", "交照", "補一張", "準備照"]),
        ("outfit", ["穿搭", "衣服", "服裝", "準備照"]),
        ("diary", ["交換日記", "日記"]),
        ("modesty", ["太辣", "不辣"]),
    ]
    for canonical, keys in aliases:
        if any(k.lower() in tokens or k in value for k in keys):
            tokens.add(canonical)
    return tokens


def _promise_similarity_reason(a, b):
    ta = _promise_topic_tokens(_promise_blob(a))
    tb = _promise_topic_tokens(_promise_blob(b))
    common = ta & tb
    if not common:
        return ""
    if {"xpark", "photo"}.issubset(common) or {"xpark", "outfit"}.issubset(common):
        return "同為 XPark 約會穿搭／照片主題"
    if {"aquarium", "photo"}.issubset(common) and ("outfit" in common or "diary" in common):
        return "同為水族館約會穿搭照主題"
    if {"diary", "photo", "outfit"}.issubset(common):
        return "同為交換日記穿搭照片交付"
    if len(common) >= 4:
        return "承諾關鍵主題高度重疊：" + "、".join(sorted(common)[:6])
    return ""


def _promise_auto_capture_should_skip(user_text, source_text="", origin="chat"):
    if str(origin or "").startswith("diary:"):
        return False
    user = _clean_text_compact(user_text or "")
    source = _clean_text_compact(source_text or "")
    if XIAOXIA_PROMISE_RULE_QUESTION_RE.search(user):
        return True
    if re.search(r"/小俠承諾|/承諾", user) and re.search(r"應該|需要|新增|重複|同一", user):
        return True
    if re.search(r"不需要.*新增|不應.*新增|不用.*新增", source):
        return True
    return False


def _promise_find_duplicate(board, item, *, include_daxia=True, include_xiaoxia=True):
    item_blob = _promise_blob(item)
    ikey = _promise_text_key(item_blob)
    keys = []
    if include_daxia:
        keys.append("daxia_promises")
    if include_xiaoxia:
        keys.append("xiaoxia_promises")
    for key in keys:
        for existing in board.get(key) or []:
            if str(existing.get("status") or PROMISE_STATUS_ACTIVE) != PROMISE_STATUS_ACTIVE:
                continue
            blob = _promise_blob(existing)
            ekey = _promise_text_key(blob)
            if ikey and ekey and (ikey in ekey or ekey in ikey):
                return existing, "文字內容近似"
            reason = _promise_similarity_reason(item_blob, blob)
            if reason:
                return existing, reason
    return None, ""

async def capture_xiaoxia_promises_to_board_from_text(source_text, *, origin="chat", user_text="", max_items=3):
    source_text = str(source_text or "")
    if _promise_auto_capture_should_skip(user_text, source_text, origin=origin):
        print("🤝 [XIAOXIA_PROMISE_CAPTURE_SKIPPED] rule/test question; no auto promise created")
        return []
    if not (DIARY_PROMISE_SIGNAL_RE.search(source_text) and DIARY_DELIVERABLE_RE.search(source_text)): return []
    prompt = f"""
你是小俠單方面承諾登記員。只登記小俠自己明確承諾未來要交付的具體事項；不可登記情緒、撒嬌、泛泛努力或已完成事項。

來源：{origin}
大俠當時內容：{str(user_text or '')[-800:]}
小俠文字：
{source_text[-1800:]}

規則：
1. 只登記有具體交付物的承諾，例如照片、穿搭照、日記文字說明、清單、菜單、行程安排、整理好的內容。
2. 不要登記：我會一直愛你、我會陪你、我會努力、我會珍惜、只是期待或情緒表達、已經正在本篇完成的內容。
3. 如果大俠是在問「這應不應該新增到 /小俠承諾」或是在測試規則，完全不要登記。
只回傳 JSON：{{"promises":["一句可驗收承諾", "..."]}}
"""
    try:
        response = await gemini_client.aio.models.generate_content(model="gemini-2.5-flash", contents=prompt, config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.0))
        data = _extract_json_object(getattr(response, "text", "") or "")
        raw_items = data.get("promises", []) if isinstance(data, dict) else []
    except Exception as exc:
        print(f"⚠️ [XIAOXIA_PROMISE_BOARD_CAPTURE_FAILED] {type(exc).__name__}: {exc}")
        raw_items = []
    added = []
    for value in raw_items[:max_items]:
        text_value = narrative_safe_text(value, max_len=220)
        if not text_value or not is_concrete_xiaoxia_promise_text(text_value): continue
        ok, item = add_promise_to_board(text_value, source="xiaoxia", origin=origin, source_context=source_text, allow_duplicate=False)
        if ok: added.append(item)
        else: print(f"🤝 [XIAOXIA_PROMISE_DEDUPED] merged_into={item.get('id') if isinstance(item, dict) else ''} text={text_value[:80]}")
    return added

async def capture_xiaoxia_promises_from_diary_result(result, entry_content="", entry_date=""):
    parts = []
    if isinstance(result, dict):
        for key in ("reply_to_daxia", "xiaoxia_daily_scene", "inner_monologue", "promise_delivery", "xiaoxia_diary"):
            if result.get(key): parts.append(str(result.get(key)))
    blob = "\n".join(parts)
    if not blob.strip(): return []
    return await capture_xiaoxia_promises_to_board_from_text(blob, origin=f"diary:{entry_date or _today_str_tpe()}", user_text=entry_content, max_items=4)

async def auto_close_xiaoxia_promises_from_text(source_text, *, origin="chat", max_items=4):
    source_text = str(source_text or "").strip()
    if not source_text:
        return []
    board = load_promise_board()
    active = [p for p in (board.get("xiaoxia_promises") or []) if isinstance(p, dict) and str(p.get("status") or PROMISE_STATUS_ACTIVE) == PROMISE_STATUS_ACTIVE]
    if not active or not re.search(r"(完成|做好|整理好|已經.*(?:給|放|附|寫|整理|拍)|這(?:張|份|篇)就是|交給你|給你看|放進日記|附上|履行|兌現)", source_text):
        return []
    candidates = [{"id":p.get("id"),"title":p.get("title"),"description":p.get("description"),"requirements":p.get("requirements") or []} for p in active[:20]]
    prompt = f"""你是小俠單方面承諾的結案審核員。只有本次文字已實際交付可驗收成果才結案；準備中、之後會做、再次提到都不可結案。
來源：{origin}
active：{json.dumps(candidates, ensure_ascii=False)}
本次文字：{source_text[-2400:]}
只回 JSON：{{"completed_ids":[],"reasons":{{}}}}"""
    try:
        response = await gemini_client.aio.models.generate_content(model="gemini-2.5-flash", contents=prompt, config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.0))
        data = _extract_json_object(getattr(response, "text", "") or "")
    except Exception as exc:
        print(f"⚠️ [XIAOXIA_PROMISE_AUTO_CLOSE_FAILED] {type(exc).__name__}: {exc}")
        return []
    reasons = data.get("reasons") if isinstance(data.get("reasons"), dict) else {}
    completed=[]
    for pid in [str(x).strip().upper() for x in (data.get("completed_ids") or [])][:max_items]:
        board=load_promise_board()
        item=next((x for x in (board.get("xiaoxia_promises") or []) if str(x.get("id") or "").upper()==pid),None)
        if not item: continue
        ok,moved=move_promise_to_archive("xiaoxia_promises",item,PROMISE_STATUS_DONE,reason=narrative_safe_text(reasons.get(pid) or "小俠已自行完成並交付。",max_len=220),actor_name="小俠自行完成")
        if ok: completed.append(moved)
    return completed

def _promise_daily_report_rows(date_key):
    board=load_promise_board(); rows=[]
    for item in board.get("xiaoxia_promises") or []:
        if isinstance(item,dict) and str(item.get("created_at") or "")[:10]==date_key:
            r=dict(item); r["report_status"]="active"; rows.append(r)
    for item in board.get("archive") or []:
        if isinstance(item,dict) and str(item.get("id") or "").startswith("XP") and str(item.get("created_at") or "")[:10]==date_key:
            r=dict(item); r["report_status"]=str(item.get("status") or ""); rows.append(r)
    d={}
    pri={"active":1,PROMISE_STATUS_PAUSED:2,PROMISE_STATUS_DELETED:3,PROMISE_STATUS_DONE:4}
    for r in rows:
        pid=str(r.get("id") or ""); old=d.get(pid)
        if pid and (old is None or pri.get(str(r.get("report_status")),0)>=pri.get(str(old.get("report_status")),0)): d[pid]=r
    return sorted(d.values(),key=lambda x:str(x.get("created_at") or ""))

def _format_xiaoxia_promise_daily_report(date_key, rows):
    title=f"🌙 **今日小俠新承諾盤點｜{date_key}**"
    if not rows: return title+"\n\n今天沒有新增小俠承諾。"
    labels={"active":"進行中",PROMISE_STATUS_DONE:"今日已完成",PROMISE_STATUS_DELETED:"今日已取消",PROMISE_STATUS_PAUSED:"暫停"}
    lines=[title,""]
    for i,x in enumerate(rows,1):
        st=str(x.get("report_status") or "active"); created=str(x.get("created_at") or ""); origin=str(x.get("origin") or "chat")
        src="交換日記" if origin.startswith("diary:") else "今日聊天" if origin=="chat" else origin
        lines += [f"{i}. **{x.get('id')}｜{x.get('title')}**",f"　狀態：{labels.get(st,st)}｜成立：{created[11:16]}｜來源：{src}"]
        if x.get("description"): lines.append("　"+_clean_text_compact(x.get("description"))[:220])
    lines.append("\n小俠可自行立案與完成；大俠仍可用 `/小俠承諾 修改`、`/小俠承諾 完成`、`/小俠承諾 刪除` 介入管理。")
    return "\n".join(lines)[:1900]

