async def _download_image_bytes_for_vision(image_url, max_bytes=8_000_000):
    if not image_url or not str(image_url).startswith("http"):
        return None, None
    try:
        timeout = aiohttp.ClientTimeout(total=60)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.get(str(image_url)) as resp:
                if resp.status != 200:
                    return None, None
                data = await resp.read()
        if not data or len(data) > max_bytes:
            return None, None
        # 粗略從 URL 判斷；gallery 多半是 jpg/png，Gemini 可接受 image/jpeg 作為保底。
        url_lower = str(image_url).lower()
        if ".png" in url_lower:
            mime = "image/png"
        elif ".webp" in url_lower:
            mime = "image/webp"
        else:
            mime = "image/jpeg"
        return data, mime
    except Exception as exc:
        print(f"⚠️ [SOLO_GATE_DOWNLOAD_FAILED] {type(exc).__name__}: {exc}")
        return None, None


async def _vision_check_solo_xiaoxia_image_url(image_url, mode="photo", allow_background_bystanders=False, visual_checklist=None):
    """
    出圖後的輕量驗圖 gate：檢查是否混入不該出現的人物、互動、男性或外來肢體。
    失敗時回傳 (False, reason)；無法檢查時為避免誤殺，回傳 (True, reason)。
    """
    if str(mode or "").lower() not in {"photo_scene", "photo_reference", "diary", "cosplay"}:
        return True, "mode not checked"

    data, mime = await _download_image_bytes_for_vision(image_url)
    if not data:
        return True, "vision skipped: cannot download generated image"

    visual_checklist = visual_checklist if isinstance(visual_checklist, dict) else {}
    specified_character_interaction = bool(visual_checklist.get("specified_character_interaction"))
    people_policy = str(visual_checklist.get("people_policy") or "")
    if specified_character_interaction:
        bystander_rule = (
            "Daxia explicitly requested interaction with a specific character. Allow that specified character interaction, "
            "but do not add unrequested companions or a Daxia/viewer substitute."
        )
    elif people_policy == "autonomy_female_interaction_ok":
        bystander_rule = (
            "This is a female social autonomy scene. Xiaoxia must be the clear primary subject. 1 to 3 female friends / sisters / female classmates may appear and naturally interact with Xiaoxia, such as chatting, drinking coffee, sitting at the same table, or walking together. "
            "Do not fail merely because female friends appear or interact, as long as Xiaoxia remains the clear primary subject and the interaction is non-romantic. Men may appear only as distant incidental background; any male interacting with Xiaoxia, sitting with her, touching her, or looking like a companion/partner must fail."
        )
    elif people_policy == "autonomy_sport_no_male":
        bystander_rule = (
            "This is a sport/activity autonomy scene. Xiaoxia must be the only primary subject. Female-only incidental background people are allowed if clearly secondary and non-interacting. "
            "No men anywhere in the scene. No foreground companion. No interacting person."
        )
    elif people_policy == "autonomy_public_background_ok":
        bystander_rule = (
            "This is a public autonomy scene. Xiaoxia must be the only primary subject. Sparse incidental background people are allowed for realism, including men, "
            "but they must be secondary, not foreground subjects, not interacting with Xiaoxia, and not companion-like or date-like."
        )
    elif allow_background_bystanders:
        bystander_rule = (
            "In this public/travel/outdoor scene, incidental distant or blurred background bystanders are allowed. "
            "They must be clearly secondary, not interacting with Xiaoxia, not foreground subjects, not companions, "
            "not a male partner, and not a substitute for Daxia."
        )
    else:
        bystander_rule = "No additional real human figures are allowed."
    prompt = f"""
You are an image QA checker for a solo character generation pipeline.
Check the image for unwanted additional people while respecting the scene type.

Return JSON only:
{{
  "solo_xiaoxia_only": true/false,
  "xiaoxia_is_only_primary_subject": true/false,
  "human_count": number,
  "has_incidental_background_bystanders": true/false,
  "has_male_or_partner": true/false,
  "has_visible_male_person": true/false,
  "has_prominent_male_person": true/false,
  "has_companion_or_date_vibe": true/false,
  "has_foreground_second_person": true/false,
  "has_interacting_second_person": true/false,
  "has_external_hands_or_body_parts": true/false,
  "has_second_person_reflection_shadow_or_partial": true/false,
  "reason": "short explanation"
}}

Rules:
- Xiaoxia must be the only primary subject.
- {bystander_rule}
- "foreground second person" means a clearly visible non-Xiaoxia person close to camera or visually prominent enough to compete with Xiaoxia.
- "visible male person" means any actual male-presenting real person in the scene, even if background.
- "prominent male person" means a male person who is foreground, medium-shot clear, visually noticeable, interacting, or companion-like.
- "companion_or_date_vibe" means the composition makes another person feel like Xiaoxia's companion, date, helper, escort, audience counterpart, or walking partner.
- Always fail if Daxia/the viewer is visualized as a man, head, hand, shoulder, back, reflection, shadow, cropped body part, or photographer-like person.
- If a specific character interaction was requested, do not fail merely because that requested character appears/interacts; fail only if extra unrequested people appear, a Daxia/viewer substitute appears, or external body parts appear.
- A printed photo, painting, statue, mannequin, or decorative object is not a person unless it appears as a real human in the scene.
"""
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=[types.Part.from_bytes(data=data, mime_type=mime), prompt],
            config=types.GenerateContentConfig(
                response_mime_type="application/json",
                temperature=0.0,
            ),
        )
        result = _safe_json_from_text(resp.text, {})
        if not isinstance(result, dict):
            return True, "vision skipped: invalid JSON"
        external_or_viewer_block = (
            bool(result.get("has_external_hands_or_body_parts"))
            or bool(result.get("has_second_person_reflection_shadow_or_partial"))
        )
        has_visible_male = bool(result.get("has_visible_male_person")) or bool(result.get("has_male_or_partner"))
        has_prominent_male = bool(result.get("has_prominent_male_person")) or bool(result.get("has_male_or_partner"))
        has_companion_vibe = bool(result.get("has_companion_or_date_vibe")) or bool(result.get("has_male_or_partner"))
        has_foreground_second = bool(result.get("has_foreground_second_person"))
        has_interacting_second = bool(result.get("has_interacting_second_person"))
        blocking_people = has_prominent_male or has_foreground_second or has_interacting_second or external_or_viewer_block or has_companion_vibe
        if specified_character_interaction:
            ok = bool(result.get("xiaoxia_is_only_primary_subject", True)) and not external_or_viewer_block
        elif people_policy == "autonomy_female_interaction_ok":
            # 女性社交互動允許女性朋友入鏡與互動；只擋男性互動/伴侶感、Daxia/觀者替身、外部手腳，以及小俠失去主體。
            ok = bool(result.get("xiaoxia_is_only_primary_subject", result.get("solo_xiaoxia_only", True))) and (not has_prominent_male) and (not external_or_viewer_block)
        elif people_policy == "autonomy_sport_no_male":
            ok = bool(result.get("xiaoxia_is_only_primary_subject", result.get("solo_xiaoxia_only", True))) and (not has_visible_male) and (not has_foreground_second) and (not has_interacting_second) and (not external_or_viewer_block) and (not has_companion_vibe)
        elif people_policy == "autonomy_public_background_ok":
            ok = bool(result.get("xiaoxia_is_only_primary_subject", result.get("solo_xiaoxia_only", True))) and (not has_prominent_male) and (not has_foreground_second) and (not has_interacting_second) and (not external_or_viewer_block) and (not has_companion_vibe)
        elif allow_background_bystanders:
            ok = bool(result.get("xiaoxia_is_only_primary_subject", result.get("solo_xiaoxia_only", True))) and not blocking_people
        else:
            ok = bool(result.get("solo_xiaoxia_only")) and int(result.get("human_count", 1) or 1) <= 1 and not blocking_people
        reason = str(result.get("reason") or result)
        return ok, reason[:300]
    except Exception as exc:
        print(f"⚠️ [SOLO_GATE_VISION_FAILED] {type(exc).__name__}: {exc}")
        return True, "vision skipped: checker error"





def _is_pose_critical_request(text):
    raw = str(text or "").lower()
    keywords = ["趴", "俯臥", "俯卧", "躺", "側躺", "侧躺", "跪", "盤腿", "盘腿", "face-down", "face down", "prone", "lying on her stomach", "lying down", "on her stomach"]
    return any(k.lower() in raw for k in keywords)


def _extract_pose_user_request(initial_prompt, visual_dict=None):
    if isinstance(visual_dict, dict):
        state = visual_dict.get("__anchor_state") if isinstance(visual_dict.get("__anchor_state"), dict) else {}
        for key in ("user_scene_hardlock", "user_priority_request", "primary_action", "activity"):
            val = str(state.get(key) or "").strip()
            if val:
                return val
    text = str(initial_prompt or "")
    m = re.search(r"Highest-priority Daxia request to obey literally:\s*(.+?)(?:\n|$)", text, flags=re.I)
    if m:
        return m.group(1).strip(" .")
    return text.strip()




# ==========================================
# 🧭 v1.4.94：Thin Prompt / Visual Checklist / People Policy
# ==========================================
def _contains_any_keyword(text, keywords):
    raw = str(text or "").lower()
    return any(str(k).lower() in raw for k in keywords)


def _visual_policy_source_text(mode="photo", user_text="", visual_dict=None, current_outfit=None, trace_context=None):
    parts = [str(mode or ""), str(user_text or ""), str(current_outfit or "")]
    if isinstance(visual_dict, dict):
        for key in ("composition", "scene", "scene_summary", "action", "activity", "outfit", "outfit_summary"):
            if visual_dict.get(key):
                parts.append(str(visual_dict.get(key)))
        state = visual_dict.get("__anchor_state") if isinstance(visual_dict.get("__anchor_state"), dict) else {}
        for key in ("user_scene_hardlock", "user_priority_request", "primary_action", "activity", "setting_anchor"):
            if state.get(key):
                parts.append(str(state.get(key)))
    if isinstance(trace_context, dict):
        for key in ("user_input", "scene_seed_text", "scene_summary", "action_summary", "outfit_summary", "user_mode_request"):
            if trace_context.get(key):
                parts.append(str(trace_context.get(key)))
        story = trace_context.get("story") if isinstance(trace_context.get("story"), dict) else {}
        for key in ("user_mode_request", "topic", "event", "work_title", "character_name"):
            if story.get(key):
                parts.append(str(story.get(key)))
    return "\n".join(p for p in parts if p).strip()


def _is_private_scene_text(text):
    private_keywords = [
        "家中", "在家", "家裡", "家里", "客廳", "客厅", "臥室", "卧室", "房間", "房间", "床上", "床邊", "床边",
        "廚房", "厨房", "浴室", "洗澡", "泡澡", "淋浴", "更衣室", "旅館房間", "旅馆房间", "飯店房間", "饭店房间",
        "hotel room", "hotel bathroom", "bathroom", "bedroom", "living room", "home", "private room", "民宿房間", "套房",
    ]
    return _contains_any_keyword(text, private_keywords)


def _explicit_solo_or_empty_scene_requested(text):
    keywords = ["空景", "完全獨照", "完全独照", "獨照", "独照", "不要路人", "沒有路人", "无路人", "no bystanders", "no people", "solo only"]
    return _contains_any_keyword(text, keywords)


def _explicit_character_interaction_requested(text):
    raw = str(text or "")
    patterns = [
        r"(?:與|和|跟)\s*[^，。,.、\n]{1,30}\s*(?:互動|合照|對話|聊天|閒聊|並肩|一起|同行|聚會|聚餐|吃飯|喝咖啡|逛街|牽手|打鬥|戰鬥|跳舞|握手|擁抱)",
        r"(?:with|interacting with|chatting with|talking with|having coffee with|posing with|standing with|walking with|hanging out with)\s+[A-Za-z][A-Za-z0-9 _'\-]{1,40}",
    ]
    return any(re.search(p, raw, flags=re.I) for p in patterns)

def _allow_background_bystanders_from_text(text, mode="photo"):
    # 私密空間永遠小俠獨照；使用者明確要求空景/完全獨照時也不允許路人。
    if _is_private_scene_text(text) or _explicit_solo_or_empty_scene_requested(text):
        return False

    raw = str(text or "")
    # v1.8.11：Scene 若明確寫出背景人物，技術 people policy 不得反過來把他們刪掉。
    # 這裡只判斷「是否允許背景人物」，不替 Scene 新增人物或改寫人物關係。
    background_person_terms = (
        "同學", "同学", "學員", "学员", "學生", "学生", "路人", "遊客", "游客", "顧客", "顾客",
        "工作人員", "工作人员", "店員", "店员", "classmate", "classmates", "student", "students",
        "bystander", "bystanders", "crowd", "customers", "staff"
    )
    background_cues = (
        "背景可見", "背景可见", "背景有", "背景裡", "背景里", "背景中的", "遠處", "远处", "模糊",
        "in the background", "background", "distant", "blurred"
    )
    if _contains_any_keyword(raw, background_person_terms) and _contains_any_keyword(raw, background_cues):
        return True

    # 一般公共／課程／活動場所可允許不互動、不搶主體的背景人物。
    public_keywords = [
        "街", "景點", "文創", "園區", "夜市", "市集", "車站", "捷運", "機場", "老街", "展覽", "博物館", "咖啡街",
        "旅行", "旅遊", "戶外", "公園", "海邊", "沙灘", "山", "街頭", "廣場", "餐廳", "酒吧", "舞台", "宮殿", "神殿",
        "教室", "課堂", "课堂", "課程", "课程", "工作坊", "講座", "讲座", "教學", "教学",
        "street", "station", "airport", "market", "museum", "exhibition", "park", "travel", "tourist", "outdoor", "plaza", "bar", "stage",
        "classroom", "class", "course", "workshop", "lecture",
    ]
    if _contains_any_keyword(raw, public_keywords):
        return True
    return str(mode or "").lower() == "cosplay"



