STYLING_BOARD_MAJOR_ACCESSORY_RULES = [
    ("visible bag / handbag / purse from request or Figure 10 styling board", ["包包", "皮包", "手提包", "肩背包", "斜背包", "背包", "托特包", "小包", "bag", "handbag", "purse", "shoulder bag", "crossbody", "tote"]),
    ("visible necklace from request or Figure 10 styling board", ["項鍊", "項链", "頸鍊", "吊墜", "墜飾", "necklace", "pendant", "choker"]),
    ("visible earrings from request or Figure 10 styling board", ["耳環", "耳环", "耳飾", "耳饰", "earrings", "earring"]),
    ("visible bracelet / wrist accessory from request or Figure 10 styling board", ["手鍊", "手链", "手環", "手环", "bracelet", "bangle", "wrist accessory"]),
    ("visible scarf / neck scarf from request or Figure 10 styling board", ["領巾", "丝巾", "絲巾", "圍巾", "围巾", "scarf", "neck scarf"]),
    ("visible sunglasses or glasses from request or Figure 10 styling board", ["太陽眼鏡", "太阳眼镜", "墨鏡", "墨镜", "眼鏡", "眼镜", "sunglasses", "glasses"]),
    ("visible hat / hair accessory from request or Figure 10 styling board", ["帽子", "草帽", "貝雷帽", "髮飾", "发饰", "髮夾", "发夹", "hat", "cap", "beret", "hair accessory", "hair clip"]),
    ("visible belt / waist accessory from request or Figure 10 styling board", ["腰帶", "腰带", "belt"]),
    ("visible shoes from request or Figure 10 styling board", ["鞋子", "高跟鞋", "靴子", "涼鞋", "拖鞋", "sneakers", "heels", "boots", "sandals", "shoes"]),
]

def _extract_requested_styling_accessory_requirements(text):
    raw = str(text or "")
    low = raw.lower()
    out = []
    for label, keys in STYLING_BOARD_MAJOR_ACCESSORY_RULES:
        if any(str(k).lower() in low for k in keys):
            out.append(label)
    return _dedupe_keep_order(out)

def _extract_visual_must_have(text, mode="photo", visual_dict=None, trace_context=None):
    raw = str(text or "")
    low = raw.lower()
    items = []
    def add(label, *keys):
        if any(k.lower() in low for k in keys):
            items.append(label)
    add("requested main scene/location", "文創", "園區", "老街", "夜市", "街", "景點", "客廳", "臥室", "房間", "旅館", "飯店", "浴室", "廚房", "sofa", "bed", "street", "hotel", "bathroom", "kitchen")
    add("requested body pose/action", "趴", "俯臥", "俯卧", "躺", "側躺", "坐", "站", "跪", "抱枕", "拿", "端", "走", "做菜", "煮", "自拍", "prone", "face-down", "lying", "sitting", "standing", "holding", "cooking")
    add("requested outfit color/material/cut", "白色", "黑色", "紅色", "藍色", "無袖", "短袖", "低胸", "開胸", "短版", "短裙", "長靴", "手套", "帽", "雨傘", "sleeveless", "short-sleeve", "low-cut", "crop top", "mini skirt", "gloves", "boots")
    add("requested prop/accessory", "雨傘", "手套", "項鍊", "項链", "耳環", "耳环", "手鍊", "手链", "領巾", "絲巾", "圍巾", "太陽眼鏡", "墨鏡", "帽", "鞋", "包包", "皮包", "手提包", "肩背包", "斜背包", "劍", "法杖", "麥克風", "抱枕", "umbrella", "gloves", "hat", "sword", "staff", "microphone", "pillow", "bag", "handbag", "purse", "necklace", "earrings", "bracelet", "scarf", "sunglasses", "glasses", "shoes")
    items.extend(_extract_requested_styling_accessory_requirements(raw))
    if str(mode or "").lower() == "photo_reference":
        # v1.5.11: When a Figure 10 styling board is supplied, text-mentioned accessories are hard visible requirements.
        items.append("Figure 10 styling board: match the main clothing first, then preserve any text-mentioned major accessory visibly")
    if str(mode or "").lower() == "cosplay":
        anchors = []
        if isinstance(trace_context, dict):
            anchors += [str(x) for x in (trace_context.get("cosplay_anchor_lines") or []) if str(x).strip()]
            vibe_zh = str(((trace_context.get("vibe_mode") or {}) if isinstance(trace_context.get("vibe_mode"), dict) else {}).get("zh") or "")
            state = trace_context.get("cosplay_state") if isinstance(trace_context.get("cosplay_state"), dict) else {}
            vibe_zh = vibe_zh or str(state.get("vibe_target_zh") or "")
            if vibe_zh == "魅" or trace_context.get("default_allure_hard_lock") or trace_context.get("user_requested_hard_sexy"):
                items.append("L0 default allure: visibly readable chest allure through role-coherent open neckline, low neckline, collarbones, natural cleavage, or bust contour")
                items.append("L0 default allure: visible second attraction point as legline or waist-abdomen curve, or both when natural")
        if anchors:
            items.extend(["cosplay anchor: " + x[:120] for x in anchors[:8]])
        else:
            items.append("recognizable requested cosplay character and source-world visual anchors")
    return _dedupe_keep_order(items)[:14]


def _extract_visual_must_not_have(text, mode="photo", visual_dict=None, trace_context=None):
    raw = str(text or "")
    low = raw.lower()
    items = [
        "Daxia/viewer visually depicted as a man, head, hand, shoulder, back, reflection, shadow, or cropped body part",
        "unrequested foreground second person or interacting companion",
    ]
    if _is_private_scene_text(raw):
        items.append("any additional person in a private home/hotel/bathroom/room scene")
    if "無袖" in raw or "sleeveless" in low:
        items.append("short-sleeve or covered shoulders if sleeveless was explicitly requested")
    if any(k in low for k in ["低胸", "開胸", "open neckline", "open chest", "low-cut", "cleavage"]):
        items.append("closed collar or fully buttoned conservative neckline if open neckline/low-cut was requested")
    if str(mode or "").lower() == "cosplay":
        items += ["generic glamour outfit replacing role costume", "unrelated indoor room/cafe/bedroom when source-world scene was requested"]
        if isinstance(trace_context, dict):
            vibe_zh = str(((trace_context.get("vibe_mode") or {}) if isinstance(trace_context.get("vibe_mode"), dict) else {}).get("zh") or "")
            state = trace_context.get("cosplay_state") if isinstance(trace_context.get("cosplay_state"), dict) else {}
            vibe_zh = vibe_zh or str(state.get("vibe_target_zh") or "")
            if vibe_zh == "魅" or trace_context.get("default_allure_hard_lock") or trace_context.get("user_requested_hard_sexy"):
                items.append("fully closed conservative neckline or fully buttoned conservative outfit in default L0 allure cosplay")
                items.append("allure satisfied only by expression/pose while garment structure remains conservative")
                items.append("legline-only styling with weak or absent chest allure in default L0 allure cosplay")
    return _dedupe_keep_order(items)[:14]


def _dedupe_keep_order(seq):
    out, seen = [], set()
    for item in seq or []:
        text = _clean_text_compact(str(item or ""))
        key = text.lower()
        if text and key not in seen:
            seen.add(key); out.append(text)
    return out


def _build_visual_checklist(mode="photo", user_text="", visual_dict=None, current_outfit=None, trace_context=None):
    source = _visual_policy_source_text(mode, user_text, visual_dict, current_outfit, trace_context)
    private = _is_private_scene_text(source)
    explicit_solo = _explicit_solo_or_empty_scene_requested(source)
    character_interaction = (not private) and _explicit_character_interaction_requested(source)
    allow_bystanders = (not private) and (not explicit_solo) and _allow_background_bystanders_from_text(source, mode=mode)
    checklist = {
        "mode": str(mode or "photo"),
        "private_scene": bool(private),
        "strict_solo_required": bool(private or explicit_solo),
        "allow_background_bystanders": bool(allow_bystanders),
        "specified_character_interaction": bool(character_interaction),
        "people_policy": (
            "private_strict_solo" if private or explicit_solo else
            "specified_character_interaction_allowed" if character_interaction else
            "public_background_bystanders_allowed" if allow_bystanders else "solo_primary_subject"
        ),
        "must_have": _extract_visual_must_have(source, mode=mode, visual_dict=visual_dict, trace_context=trace_context),
        "must_not_have": _extract_visual_must_not_have(source, mode=mode, visual_dict=visual_dict, trace_context=trace_context),
    }
    if current_outfit:
        checklist.setdefault("outfit_lock", str(current_outfit)[:500])

    custom_people_policy = ""
    if isinstance(trace_context, dict):
        custom_people_policy = str(trace_context.get("custom_people_policy") or trace_context.get("autonomy_people_policy") or "").strip()
    if custom_people_policy == "private_strict_solo":
        checklist.update({
            "private_scene": True,
            "strict_solo_required": True,
            "allow_background_bystanders": False,
            "specified_character_interaction": False,
            "people_policy": "private_strict_solo",
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": False,
        })
        checklist["must_not_have"] = _dedupe_keep_order((checklist.get("must_not_have") or []) + [
            "any additional real human figure in this private/home scene",
        ])
    elif custom_people_policy == "autonomy_female_interaction_ok":
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "allow_background_bystanders": True,
            "specified_character_interaction": False,
            "people_policy": "autonomy_female_interaction_ok",
            "no_male_people": False,
            "male_background_ok": True,
            "female_background_ok": True,
            "female_interaction_ok": True,
        })
        # 移除通用的「互動同伴」禁項，女性社交活動本來就允許女性朋友互動。
        checklist["must_not_have"] = [
            x for x in (checklist.get("must_not_have") or [])
            if "interacting companion" not in str(x).lower()
        ]
        checklist["must_not_have"] = _dedupe_keep_order((checklist.get("must_not_have") or []) + [
            "Daxia/viewer visually depicted as a man, head, hand, shoulder, back, reflection, shadow, or cropped body part",
            "male person interacting with Xiaoxia or sitting/standing as her companion",
            "male partner vibe, date vibe, boyfriend substitute, or romantic/couple composition",
            "female companions becoming the primary subject or confusing Xiaoxia identity",
        ])
    elif custom_people_policy == "autonomy_sport_no_male":
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "allow_background_bystanders": True,
            "specified_character_interaction": False,
            "people_policy": "autonomy_sport_no_male",
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": True,
            "female_interaction_ok": False,
        })
        checklist["must_not_have"] = _dedupe_keep_order((checklist.get("must_not_have") or []) + [
            "any male person in the scene",
            "male coach, male teammate, male staff, male spectator, or male background bystander",
            "foreground second person or interacting companion",
        ])
    elif custom_people_policy == "autonomy_public_background_ok":
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "allow_background_bystanders": True,
            "specified_character_interaction": False,
            "people_policy": "autonomy_public_background_ok",
            "no_male_people": False,
            "male_background_ok": True,
            "female_background_ok": True,
            "female_interaction_ok": False,
        })
        checklist["must_not_have"] = _dedupe_keep_order((checklist.get("must_not_have") or []) + [
            "foreground second person or interacting companion",
            "male partner vibe, date vibe, or companion-like composition",
        ])

    # v1.5.42_R1 — Daxia writes the story; the program supplies the people guard.
    # Unless the actual request explicitly describes another interacting character,
    # every generation defaults to a solo Xiaoxia photograph, regardless of public venue or activity catalog.
    explicit_character = bool(character_interaction)
    checklist["specified_character_interaction"] = explicit_character
    if explicit_character:
        checklist.update({
            "strict_solo_required": False,
            "allow_background_bystanders": False,
            "people_policy": "specified_character_interaction_allowed",
            "female_interaction_ok": False,
        })
        checklist["must_not_have"] = _dedupe_keep_order([
            x for x in (checklist.get("must_not_have") or [])
            if "interacting companion" not in str(x).lower()
        ] + [
            "any person not explicitly described in Daxia's request",
            "additional people becoming more visually prominent or more voluptuous than Xiaoxia",
            "Daxia/viewer visually depicted as a person or body part",
        ])
    else:
        checklist.update({
            "strict_solo_required": True,
            "allow_background_bystanders": False,
            "people_policy": "default_strict_solo",
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": False,
            "female_interaction_ok": False,
        })
        checklist["must_not_have"] = _dedupe_keep_order((checklist.get("must_not_have") or []) + [
            "any additional human figure, companion, bystander, external hand, reflection, or visible viewer body part",
        ])
    return checklist


def _visual_checklist_brief(checklist, max_items=10):
    if not isinstance(checklist, dict):
        return "{}"
    compact = {
        "people_policy": checklist.get("people_policy"),
        "strict_solo_required": checklist.get("strict_solo_required"),
        "allow_background_bystanders": checklist.get("allow_background_bystanders"),
        "specified_character_interaction": checklist.get("specified_character_interaction"),
        "no_male_people": checklist.get("no_male_people"),
        "male_background_ok": checklist.get("male_background_ok"),
        "female_background_ok": checklist.get("female_background_ok"),
        "female_interaction_ok": checklist.get("female_interaction_ok"),
        "diary_user_constraints": checklist.get("diary_user_constraints"),
        "future_event_constraints": checklist.get("future_event_constraints"),
        "must_have": (checklist.get("must_have") or [])[:max_items],
        "must_not_have": (checklist.get("must_not_have") or [])[:max_items],
    }
    try:
        return json.dumps(compact, ensure_ascii=False)
    except Exception:
        return str(compact)


def _seedream_people_policy_line(checklist=None):
    checklist = checklist if isinstance(checklist, dict) else {}
    if checklist.get("specified_character_interaction"):
        return (
            "People rule: include only the character or characters explicitly described in Daxia's request. "
            "All additional people are understated supporting characters. Xiaoxia remains the most eye-catching subject, "
            "with the strongest full-bust, narrow-waist hourglass silhouette. Do not add anyone else and never visualize Daxia/viewer."
        )
    return (
        "People rule: solo Xiaoxia only. Xiaoxia is the only visible human figure. "
        "No companions, bystanders, external hands, reflections of another person, or visible viewer body parts."
    )


def _context_seedream_model_id(context=None, trace_context=None):
    for src in (trace_context, context):
        if isinstance(src, dict):
            mid = src.get("seedream_model_id_override") or src.get("seedream_model_id") or src.get("model_id")
            if mid:
                return str(mid)
    return SEEDREAM_V45_MODEL_ID


def _seedream_model_label_from_id(model_id):
    mid = str(model_id or "")
    if "v5" in mid or "/v5/" in mid:
        return "Seedream v5.0 Pro"
    return "Seedream v4.5"


def _context_seedream_model_label(context=None):
    if isinstance(context, dict) and context.get("seedream_model_label"):
        return str(context.get("seedream_model_label"))
    return _seedream_model_label_from_id(_context_seedream_model_id(context=context))


def _seedream_request_args(model_id, final_prompt, image_urls, enable_safety_checker=None):
    if enable_safety_checker is None:
        enable_safety_checker = SEEDREAM_ENABLE_SAFETY_CHECKER
    args = {
        "prompt": final_prompt,
        "image_urls": image_urls,
        "image_size": SEEDREAM_V45_IMAGE_SIZE,
        "num_images": 1,
        "enable_safety_checker": bool(enable_safety_checker),
    }
    # v4.5 舊 endpoint 可吃 max_images；v5 Pro 文件未列此參數，避免多傳。
    if str(model_id) == str(SEEDREAM_V45_MODEL_ID):
        args["max_images"] = 1
    return args

def _build_pose_critical_seedream_prompt(user_request, has_reference=False, current_outfit=None, retry_reason="", visual_checklist=None):
    user_request = _clean_text_compact(user_request or "")
    retry_reason = _clean_text_compact(retry_reason or "")
    lines = [
        "FIGURE ROLE MAP — obey these roles strictly.",
        "",
        "Figures 1-9 are identity-only reference images of Xiaoxia.",
        "Use Figures 1-9 only to preserve Xiaoxia's face identity, fair luminous skin, adult East Asian appearance, long brown hair, tall slim feminine body, clearly defined waist, naturally very full and elegant bust, strong bust-to-waist contrast, soft hourglass silhouette, and overall recognizable Xiaoxia look. Even in full-body, long-shot, or side-facing compositions, keep that contrast clearly visible without exaggerating anatomy. Clothing should naturally complement and flatter her signature hourglass figure rather than minimizing it.",
        "Do NOT copy the pose, background, room, chair, standing posture, sitting posture, lighting setup, or composition from Figures 1-9.",
        "",
        "Create a new solo photorealistic lifestyle image of Xiaoxia.",
        _seedream_people_policy_line(visual_checklist),
    ]
    if has_reference:
        lines += [
            "",
            "Use Figure 10 as the primary garment and styling reference. Follow it faithfully: do not simplify, redesign, replace, or reinterpret the outfit or its distinctive design elements unless explicitly instructed.",
            "The text request remains authoritative for the scene, action, pose, camera, lighting, and composition; Figure 10 must not redirect or weaken them.",
        ]
    else:
        lines += ["", "No Figure 10 is supplied. Choose clothing only from the explicit text request or a simple natural outfit suitable for the scene."]
    if current_outfit:
        lines += ["", f"Current outfit continuity, clothing only: {str(current_outfit).strip()}. It must not override pose or scene."]
    if retry_reason:
        lines += ["", "PREVIOUS OUTPUT WAS REJECTED:", retry_reason, "Correct the failure now. The required pose/action must be obeyed before beauty, fashion display, or flattering framing."]
    lines += ["", "TEXT REQUEST — this controls the final scene, pose, action, and composition:", "", user_request, "", "Mandatory obedience rules:", "- The requested body pose and scene must be visually clear.", "- Do not replace a lying/prone/face-down request with sitting, standing, kneeling, leaning, side-lying, reading, or posing beside the furniture.", "- If the request says chest/abdomen touching bed/sofa, the torso must be horizontal and supported by that surface.", "- If the request says pillow, show the pillow action clearly.", "- Natural anatomy, single person only, candid lifestyle photo."]
    return "\n".join(lines).strip()


