DANBOORU_ALLOWED_IMAGE_HOST_SUFFIXES = (".donmai.us",)

# v1.10.31：Danbooru tag 只做寬鬆候選搜尋；真正「是不是這個角色/作品」
# 改由 Gemini Vision 依圖片的非臉部證據做相容性 Gate，再送 Nano Banana 2 Lite。
DANBOORU_VISION_GATE_MODEL = (os.environ.get("DANBOORU_VISION_GATE_MODEL", "gemini-2.5-flash") or "gemini-2.5-flash").strip()
DANBOORU_VISION_GATE_MIN_CONFIDENCE = _env_int("DANBOORU_VISION_GATE_MIN_CONFIDENCE", 70, 0, 100)
DANBOORU_VISION_GATE_MAX_CANDIDATES = _env_int("DANBOORU_VISION_GATE_MAX_CANDIDATES", 5, 1, 10)


def _danbooru_auth():
    if not DANBOORU_LOGIN or not DANBOORU_API_KEY:
        return None
    return aiohttp.BasicAuth(DANBOORU_LOGIN, DANBOORU_API_KEY)


def _danbooru_headers():
    who = DANBOORU_LOGIN or "anonymous"
    return {"User-Agent": f"XiaoxiaCosplayBot/{LOBSTER_VERSION} (Danbooru user {who})"}


def _dedupe_casefold_list(values, limit=None):
    out = []
    seen = set()
    for value in values or []:
        item = _clean_text_compact(value or "").strip()
        if not item:
            continue
        key = item.casefold()
        if key in seen:
            continue
        seen.add(key)
        out.append(item)
        if limit and len(out) >= int(limit):
            break
    return out


def _danbooru_name_variants(value):
    raw = _clean_text_compact(value or "")
    if not raw:
        return []
    candidates = []
    parens = re.findall(r"[（(]([^()（）]{1,80})[)）]", raw)
    stripped = re.sub(r"[（(][^()（）]*[)）]", " ", raw).strip()
    normalized = raw.replace("－", "-").replace("—", "-").replace("–", "-").replace("／", "/").replace("｜", "|")
    parts = [p.strip() for p in re.split(r"\s*[-—–/:|｜]\s*", normalized) if p.strip()]
    ascii_chunks = re.findall(r"[A-Za-z0-9][A-Za-z0-9 ._:'\-]{0,80}", raw)
    cjk_chunks = re.findall(r"[㐀-鿿]{1,24}", raw)
    for item in [raw, normalized, stripped] + parens + parts + ascii_chunks + cjk_chunks:
        item = _clean_text_compact(item).strip(" -_/,:;()（）[]【】")
        if item:
            candidates.append(item)
    return _dedupe_casefold_list(candidates, limit=12)


def _danbooru_match_pattern(value):
    value = _clean_text_compact(value or "").lower()
    parts = re.findall(r"[a-z0-9]+", value)
    if not parts:
        return ""
    if len(parts) == 1:
        token = parts[0]
        return f"{token}*" if len(token) >= 3 else f"*{token}*"
    return "*" + "*".join(parts[:6]) + "*"


def _danbooru_character_suffix_aliases(values):
    """Extract likely character-only aliases from combined work+character aliases.

    Examples:
    - 'Frieren: Beyond Journey's End Fern' -> 'Fern'
    - 'The King of Fighters May Lee' -> 'May Lee', 'Lee'
    - 'Spy x Family Yor Forger' -> 'Yor Forger', 'Forger'
    """
    out = []
    for value in values or []:
        raw = _clean_text_compact(value or "")
        if not raw:
            continue
        cleaned = re.sub(r"[（(][^()（）]{1,80}[)）]", " ", raw)
        cleaned = re.sub(r"[:/|｜]", " ", cleaned)
        cleaned = re.sub(r"[-—–]", " ", cleaned)
        cleaned = _clean_text_compact(cleaned)
        if not cleaned:
            continue
        # CJK suffixes: keep the last short block, useful when a combined alias ends with a Chinese/Japanese character name.
        cjk_parts = re.findall(r"[㐀-鿿]{1,24}", cleaned)
        if cjk_parts:
            out.append(cjk_parts[-1])
        # ASCII suffixes: last 1~3 tokens often capture the character name.
        ascii_tokens = re.findall(r"[A-Za-z0-9][A-Za-z0-9'._-]*", cleaned)
        if ascii_tokens:
            max_take = min(3, len(ascii_tokens))
            for n in range(1, max_take + 1):
                out.append(" ".join(ascii_tokens[-n:]))
    return _dedupe_casefold_list(out, limit=16)


def _build_danbooru_tag_search_aliases(character_aliases, work_aliases, combined_aliases):
    """Build search aliases in character-first order for Danbooru character-tag lookup."""
    char_aliases = _dedupe_casefold_list(character_aliases or [], limit=12)
    work_aliases = _dedupe_casefold_list(work_aliases or [], limit=12)
    combined_aliases = _dedupe_casefold_list(combined_aliases or [], limit=12)
    suffix_aliases = _danbooru_character_suffix_aliases(char_aliases + combined_aliases)

    aliases = []
    # 1) Prefer explicit character aliases.
    aliases.extend(char_aliases)
    # 2) Then likely extracted character-only suffixes such as 'Fern' or 'May Lee'.
    aliases.extend(suffix_aliases)
    # 3) Only then use combined aliases; they are helpful as a backup but poor as a primary tag query.
    aliases.extend(combined_aliases)
    # 4) Avoid work-only aliases at this stage: they are useful for scoring, but too noisy for character-tag retrieval.
    return _dedupe_casefold_list(aliases, limit=18)


def _danbooru_token_set(value):
    stop = {"the", "of", "and", "a", "an", "series", "movie", "film", "game", "anime", "character"}
    return {x for x in re.findall(r"[a-z0-9]+", str(value or "").lower()) if len(x) >= 2 and x not in stop}


def _score_danbooru_character_tag(tag, character_name="", work_title=""):
    name = str((tag or {}).get("name") or "").lower()
    if not name:
        return -9999
    score = 0.0
    if int((tag or {}).get("category") or -1) == 4:
        score += 100.0
    char_tokens = _danbooru_token_set(character_name)
    work_tokens = _danbooru_token_set(work_title)
    name_tokens = _danbooru_token_set(name.replace("_", " "))
    score += 18.0 * len(char_tokens & name_tokens)
    score += 8.0 * len(work_tokens & name_tokens)
    if char_tokens and char_tokens.issubset(name_tokens):
        score += 35.0
    if work_tokens and (work_tokens & name_tokens):
        score += 12.0
    try:
        score += min(20.0, math.log10(max(1, int((tag or {}).get("post_count") or 0))) * 4.0)
    except Exception:
        pass
    return score


def _danbooru_post_tags(post):
    chunks = []
    for key in ("tag_string", "tag_string_general", "tag_string_character", "tag_string_copyright", "tag_string_meta"):
        value = str((post or {}).get(key) or "").strip()
        if value:
            chunks.append(value)
    return set(" ".join(chunks).split())


def _danbooru_has_multi_subject_tags(tags):
    tags = set(tags or [])
    if any(x in tags for x in {"multiple_girls", "multiple_boys", "multiple_others", "group", "duo", "trio"}):
        return True
    for tag in tags:
        m = re.match(r"^(\d+)(girls|boys|others|people|persons)$", str(tag))
        if m:
            try:
                if int(m.group(1)) >= 2:
                    return True
            except Exception:
                pass
    return False


def _score_danbooru_reference_post(post):
    tags = _danbooru_post_tags(post)
    if _danbooru_has_multi_subject_tags(tags):
        return None
    if any(x in tags for x in {"comic", "manga_(style)", "4koma", "text_focus"}):
        return None
    rating = str((post or {}).get("rating") or "").lower()
    if rating == "e":
        return None
    file_url = str((post or {}).get("file_url") or (post or {}).get("large_file_url") or "").strip()
    if not file_url:
        return None

    score = 0.0
    if "solo" in tags:
        score += 55
    elif "1girl" in tags or "1boy" in tags:
        score += 18

    if "full_body" in tags:
        score += 55
    elif "standing" in tags:
        score += 8

    for good, points in {
        "official_art": 24, "game_cg": 16, "simple_background": 10,
        "looking_at_viewer": 4, "weapon": 4, "holding_weapon": 6,
        "boots": 2, "shoes": 2, "long_sleeves": 1,
    }.items():
        if good in tags:
            score += points

    for bad, points in {
        "upper_body": 40, "portrait": 55, "close-up": 55, "cropped": 26,
        "cowboy_shot": 18, "knees_up": 18, "chibi": 70, "super_deformed": 70,
        "from_behind": 20, "monochrome": 10, "sketch": 8,
    }.items():
        if bad in tags:
            score -= points

    try:
        width = int((post or {}).get("image_width") or 0)
        height = int((post or {}).get("image_height") or 0)
        pixels = width * height
        if pixels >= 2_000_000:
            score += 12
        elif pixels >= 1_000_000:
            score += 6
        if height >= width:
            score += 5
    except Exception:
        pass
    try:
        score += min(20.0, max(-10.0, float((post or {}).get("score") or 0) / 10.0))
    except Exception:
        pass
    if rating == "g":
        score += 6
    elif rating == "s":
        score += 3

    # Keep broad search permissive, but filter out obviously poor references.
    if score < -15:
        return None
    return score


def _strip_cosplay_category_prefix(value):
    raw = _clean_text_compact(value or "")
    if not raw:
        return ""
    # Remove leading category markers such as （動畫）, (電玩), 【電影】, [文學].
    raw = re.sub(r"^\s*[（(【\[]\s*[^）)】\]]{1,12}\s*[）)】\]]\s*", "", raw).strip()
    return raw


def _split_explicit_cosplay_identity(raw_request):
    """Best-effort deterministic parser for explicit requests such as '（動畫）葬送的芙莉蓮-費倫'."""
    raw = _strip_cosplay_category_prefix(raw_request)
    if not raw:
        return "", ""
    normalized = raw.replace("－", "-").replace("—", "-").replace("–", "-").replace("｜", "|")
    # For a user-specified work-character form, split only once from the right so work titles may contain punctuation.
    if "-" in normalized:
        left, right = normalized.rsplit("-", 1)
        work = _clean_text_compact(left).strip(" -_/,:;()（）[]【】")
        char = _clean_text_compact(right).strip(" -_/,:;()（）[]【】")
        if work and char:
            return work, char
    for sep in ("／", "/", "|", "｜"):
        if sep in normalized:
            left, right = normalized.rsplit(sep, 1)
            work = _clean_text_compact(left).strip(" -_/,:;()（）[]【】")
            char = _clean_text_compact(right).strip(" -_/,:;()（）[]【】")
            if work and char:
                return work, char
    return "", ""


async def _infer_danbooru_story_identity(story):
    """Fill missing work_title / character_name before any Danbooru API search."""
    story = story if isinstance(story, dict) else {}
    candidate = story.get("cosplay_topic_candidate") if isinstance(story.get("cosplay_topic_candidate"), dict) else {}
    character_name = _clean_text_compact(story.get("character_name") or candidate.get("character_name") or "")
    work_title = _clean_text_compact(story.get("work_title") or candidate.get("work_title") or "")
    raw_request = _clean_text_compact(story.get("user_mode_request") or story.get("topic") or "")
    inference = {
        "source": "existing" if character_name else "",
        "raw_request": raw_request,
        "character_name_before": character_name,
        "work_title_before": work_title,
    }
    if character_name:
        inference.update({"character_name": character_name, "work_title": work_title})
        return character_name, work_title, inference

    # First use the user's explicit syntax; this is deterministic and avoids an unnecessary LLM call.
    parsed_work, parsed_char = _split_explicit_cosplay_identity(raw_request)
    if parsed_char:
        character_name = parsed_char
        if not work_title:
            work_title = parsed_work
        inference["source"] = "raw_request_split"

    # If the request is only a character name (e.g. '/cosplay 費倫'), let Gemini identify the likely canonical work/name.
    if not character_name:
        stripped = _strip_cosplay_category_prefix(raw_request)
        persona = _clean_text_compact(story.get("persona") or "")
        topic = _clean_text_compact(story.get("topic") or "")
        try:
            prompt = f"""
Identify the fictional cosplay character explicitly requested by the user. Return JSON only.
Do not invent a character when the request is a generic profession, generic archetype, or original concept.
If a known character is present, provide a concise canonical work title and character name, preferably with English/romanized alias in parentheses when useful for search.

Return JSON:
{{"character_name":"", "work_title":"", "confidence":0}}

raw_request: {stripped or raw_request or 'N/A'}
topic: {topic or 'N/A'}
persona: {persona or 'N/A'}
"""
            response = await gemini_client.aio.models.generate_content(
                model="gemini-2.5-flash",
                contents=prompt,
                config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.0),
            )
            parsed = _safe_json_from_text(getattr(response, "text", "") or "", {})
            confidence = int(parsed.get("confidence") or 0) if isinstance(parsed, dict) else 0
            guessed_char = _clean_text_compact(parsed.get("character_name") or "") if isinstance(parsed, dict) else ""
            guessed_work = _clean_text_compact(parsed.get("work_title") or "") if isinstance(parsed, dict) else ""
            if guessed_char and confidence >= 60:
                character_name = guessed_char
                if not work_title:
                    work_title = guessed_work
                inference["source"] = "gemini_identity_resolver"
                inference["confidence"] = confidence
        except Exception as exc:
            inference["gemini_error"] = f"{type(exc).__name__}: {exc}"
            print(f"⚠️ [DANBOORU_IDENTITY_INFER_FAILED] {type(exc).__name__}: {exc}")

    if character_name:
        story["character_name"] = character_name
    if work_title:
        story["work_title"] = work_title
    inference.update({"character_name": character_name, "work_title": work_title})
    return character_name, work_title, inference


async def _resolve_danbooru_alias_hints(character_name="", work_title="", raw_request=""):
    base_character = _danbooru_name_variants(character_name)
    base_work = _danbooru_name_variants(work_title)
    base_request = _danbooru_name_variants(raw_request)
    result = {
        "character_aliases": list(base_character),
        "work_aliases": list(base_work),
        "combined_aliases": [],
    }
    try:
        prompt = f"""
You help prepare search aliases for Danbooru character tags.
Input may be Chinese, Japanese, or English.
Return JSON only.

Rules:
- Prefer short, searchable aliases.
- Include likely official English titles when known.
- Include likely romanized Japanese titles when known.
- Include likely English or romanized character names when known.
- Do not explain anything.
- Keep each list concise.

Return JSON:
{{
  "character_aliases": ["up to 8 items"],
  "work_aliases": ["up to 8 items"],
  "combined_aliases": ["up to 8 items"]
}}

character_name: {character_name or 'N/A'}
work_title: {work_title or 'N/A'}
raw_request: {raw_request or 'N/A'}
"""
        response = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.1),
        )
        parsed = _safe_json_from_text(getattr(response, "text", "") or "", {})
        if isinstance(parsed, dict):
            result["character_aliases"] = _dedupe_casefold_list(base_character + list(parsed.get("character_aliases") or []), limit=12)
            result["work_aliases"] = _dedupe_casefold_list(base_work + list(parsed.get("work_aliases") or []), limit=12)
            result["combined_aliases"] = _dedupe_casefold_list(base_request + list(parsed.get("combined_aliases") or []), limit=12)
    except Exception as exc:
        print(f"⚠️ [DANBOORU_ALIAS_HINT_FAILED] {type(exc).__name__}: {exc}")
    if not result["combined_aliases"]:
        combined = []
        for char in result["character_aliases"][:4]:
            combined.append(char)
            for work in result["work_aliases"][:3]:
                combined.append(f"{char} {work}")
        result["combined_aliases"] = _dedupe_casefold_list(base_request + combined, limit=12)
    return result


async def _danbooru_api_get(path, params=None):
    url = DANBOORU_API_BASE.rstrip("/") + "/" + str(path or "").lstrip("/")
    timeout = aiohttp.ClientTimeout(total=25, connect=8, sock_read=18)
    async with aiohttp.ClientSession(timeout=timeout, headers=_danbooru_headers(), auth=_danbooru_auth()) as session:
        async with session.get(url, params=params or {}, allow_redirects=False) as resp:
            if resp.status != 200:
                body = (await resp.text())[:300]
                raise RuntimeError(f"DANBOORU_HTTP_{resp.status}: {body}")
            return await resp.json(content_type=None)


async def _download_and_sanitize_danbooru_image(url, *, post_id=None):
    raw_url = str(url or "").strip()
    parsed = urlparse(raw_url)
    host = (parsed.hostname or "").lower()
    if parsed.scheme != "https" or not any(host.endswith(suffix) for suffix in DANBOORU_ALLOWED_IMAGE_HOST_SUFFIXES):
        raise RuntimeError(f"DANBOORU_IMAGE_HOST_REJECTED:{host or 'missing'}")
    timeout = aiohttp.ClientTimeout(total=35, connect=8, sock_read=25)
    async with aiohttp.ClientSession(timeout=timeout, headers=_danbooru_headers()) as session:
        async with session.get(raw_url, allow_redirects=False) as resp:
            if resp.status != 200:
                raise RuntimeError(f"DANBOORU_IMAGE_HTTP_{resp.status}")
            ctype = str(resp.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
            if not ctype.startswith("image/"):
                raise RuntimeError(f"DANBOORU_IMAGE_BAD_MIME:{ctype or 'missing'}")
            try:
                announced = int(resp.headers.get("Content-Length") or 0)
            except Exception:
                announced = 0
            if announced and announced > DANBOORU_REF_MAX_BYTES:
                raise RuntimeError("DANBOORU_IMAGE_TOO_LARGE")
            chunks, total = [], 0
            async for chunk in resp.content.iter_chunked(64 * 1024):
                total += len(chunk)
                if total > DANBOORU_REF_MAX_BYTES:
                    raise RuntimeError("DANBOORU_IMAGE_TOO_LARGE")
                chunks.append(chunk)
    raw = b"".join(chunks)
    try:
        with Image.open(io.BytesIO(raw)) as im:
            im.load()
            width, height = im.size
            if width <= 0 or height <= 0 or width * height > DANBOORU_REF_MAX_PIXELS:
                raise RuntimeError("DANBOORU_IMAGE_BAD_DIMENSIONS")
            clean = ImageOps.exif_transpose(im).convert("RGB")
            max_side = 3200
            if max(clean.size) > max_side:
                clean.thumbnail((max_side, max_side), Image.Resampling.LANCZOS)
            os.makedirs(OUTPUT_DIR, exist_ok=True)
            filename = f"danbooru_cosplay_source_{post_id or 'post'}_{uuid.uuid4().hex[:8]}.jpg"
            path = os.path.join(OUTPUT_DIR, filename)
            clean.save(path, format="JPEG", quality=94, optimize=True)
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(f"DANBOORU_IMAGE_DECODE_FAILED:{type(exc).__name__}") from exc
    return path, f"https://xiaoxia0320.zeabur.app/gallery/{filename}"


async def _verify_danbooru_candidate_with_vision(
    local_path,
    *,
    character_name="",
    work_title="",
    character_tag="",
    post=None,
):
    """
    v1.10.31:
    Danbooru tags stay permissive. Gemini Vision is the actual compatibility gate.

    Important boundary:
    - Do NOT identify or name a real person from the image.
    - Do NOT rely on facial identity.
    - Judge whether the visual depiction is plausibly compatible with the requested fictional
      character/work using non-face evidence: medium, costume, hair/head features, props,
      species/creature type, franchise/world cues, text/signage if visible, and overall design.
    - Missing work tags or generic backgrounds are NOT automatic failures.
    - Clear contradiction (wrong franchise, robot/animal/childlike cartoon vs live-action adult detective,
      incompatible costume/props/world, etc.) should fail.
    - If evidence is too generic/uncertain to confirm, fail safe and let the next candidate try.
    """
    if not local_path or not os.path.exists(str(local_path)):
        raise RuntimeError("DANBOORU_VISION_IMAGE_MISSING")

    data = await asyncio.to_thread(Path(str(local_path)).read_bytes)
    mime = _local_image_mime_type(local_path)
    post = post if isinstance(post, dict) else {}

    prompt = f"""
You are a strict but practical visual compatibility gate for a cosplay reference pipeline.

TARGET FICTIONAL CHARACTER:
- character: {character_name or 'unknown'}
- work/franchise: {work_title or 'unknown'}
- Danbooru character tag candidate: {character_tag or 'unknown'}

Your task is NOT to identify a real person and NOT to perform face recognition.
Do not name any real actor/person visible in the image.

Judge only whether this IMAGE is plausibly compatible with the requested fictional character/work
using NON-FACE visual evidence such as:
- illustration/live-action/3D medium and overall franchise/world style
- costume silhouette and colors
- hairstyle/hair color/head features without using facial identity
- signature props/weapons/accessories
- species/robot/animal/human presentation
- setting/world cues or visible text if useful

Rules:
1. Danbooru tags are only weak hints. Missing work/copyright tags is NOT a reason to reject.
2. A generic image can pass only if its visible design is still reasonably consistent with the target.
3. If the image clearly belongs to another franchise/character/world, reject.
4. If the evidence is too ambiguous to confidently say it is compatible, reject safely; the pipeline can try another candidate.
5. Also judge whether this image is useful as a costume/appearance reference. Crowded group shots, tiny subjects,
   severe occlusion, extreme chibi, or mostly unrelated scenery should be rejected.

Return JSON only:
{{
  "compatible": true,
  "confidence": 0,
  "usable_reference": true,
  "reason": "brief Traditional Chinese explanation",
  "visual_evidence": ["up to 5 concise non-face cues"],
  "obvious_conflict": "brief contradiction if any, else empty"
}}

Danbooru metadata (weak hints only):
- post_id: {post.get('id') or ''}
- tag_string_character: {str(post.get('tag_string_character') or '')[:500]}
- tag_string_copyright: {str(post.get('tag_string_copyright') or '')[:500]}
- tag_string_general: {str(post.get('tag_string_general') or '')[:800]}
"""
    response = await gemini_client.aio.models.generate_content(
        model=DANBOORU_VISION_GATE_MODEL,
        contents=[types.Part.from_bytes(data=data, mime_type=mime), prompt],
        config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.0),
    )
    parsed = _safe_json_from_text(getattr(response, "text", "") or "", {})
    if not isinstance(parsed, dict):
        raise RuntimeError("DANBOORU_VISION_BAD_JSON")

    compatible = bool(parsed.get("compatible"))
    usable = bool(parsed.get("usable_reference"))
    try:
        confidence = int(float(parsed.get("confidence") or 0))
    except Exception:
        confidence = 0
    confidence = max(0, min(100, confidence))

    reason = _clean_text_compact(parsed.get("reason") or "")[:500]
    conflict = _clean_text_compact(parsed.get("obvious_conflict") or "")[:500]
    evidence = [
        _clean_text_compact(x)[:160]
        for x in (parsed.get("visual_evidence") or [])[:5]
        if _clean_text_compact(x)
    ]

    accepted = bool(
        compatible
        and usable
        and confidence >= int(DANBOORU_VISION_GATE_MIN_CONFIDENCE)
    )
    return {
        "accepted": accepted,
        "compatible": compatible,
        "usable_reference": usable,
        "confidence": confidence,
        "min_confidence": int(DANBOORU_VISION_GATE_MIN_CONFIDENCE),
        "reason": reason,
        "visual_evidence": evidence,
        "obvious_conflict": conflict,
        "model": DANBOORU_VISION_GATE_MODEL,
    }


async def _find_danbooru_cosplay_reference(story):
    """Best-effort resolver: permissive tag search -> ranked post candidates -> Gemini Vision gate -> Nano only after a pass."""
    story = story if isinstance(story, dict) else {}
    character_name, work_title, identity_inference = await _infer_danbooru_story_identity(story)
    raw_request = _clean_text_compact(story.get("user_mode_request") or story.get("topic") or "")
    trace = {
        "matched": False,
        "character_name": character_name,
        "work_title": work_title,
        "raw_request": raw_request,
        "failure_reason": "",
        "tag_queries": [],
        "tag_candidates": [],
        "selected_character_tags": [],
        "post_queries": [],
        "candidate_posts": [],
        "download_attempts": [],
        "vision_checks": [],
        "identity_inference": identity_inference,
    }
    if not DANBOORU_LOGIN or not DANBOORU_API_KEY:
        trace["failure_reason"] = "env_missing"
        print("ℹ️ [DANBOORU_REF] env missing; fallback to scene-only cosplay")
        return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}
    if not character_name:
        trace["failure_reason"] = "no_character_name"
        print("ℹ️ [DANBOORU_REF] no character name; fallback to scene-only cosplay")
        return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}

    try:
        alias_hints = await _resolve_danbooru_alias_hints(character_name, work_title, raw_request)
        trace["alias_hints"] = alias_hints
        tag_candidates = {}
        search_aliases = _build_danbooru_tag_search_aliases(
            alias_hints.get("character_aliases") or [],
            alias_hints.get("work_aliases") or [],
            alias_hints.get("combined_aliases") or [],
        )
        trace["search_aliases"] = list(search_aliases)
        for alias in search_aliases:
            pattern = _danbooru_match_pattern(alias)
            if not pattern:
                continue
            rows = await _danbooru_api_get("tags.json", {
                "search[name_matches]": pattern,
                "search[category]": 4,
                "search[order]": "count",
                "limit": 20,
            })
            top_names = []
            for row in rows if isinstance(rows, list) else []:
                name = str((row or {}).get("name") or "").strip()
                if name:
                    top_names.append(name)
                    tag_candidates[name] = row
            trace["tag_queries"].append({
                "alias": alias,
                "pattern": pattern,
                "result_count": len(top_names),
                "top_results": top_names[:8],
            })
            if len(tag_candidates) >= 30:
                break

        ranked_tags = sorted(
            tag_candidates.values(),
            key=lambda row: _score_danbooru_character_tag(row, character_name, work_title),
            reverse=True,
        )[:6]
        trace["tag_candidates"] = [
            {
                "name": str((row or {}).get("name") or ""),
                "post_count": int((row or {}).get("post_count") or 0),
                "score": round(_score_danbooru_character_tag(row, character_name, work_title), 2),
            }
            for row in ranked_tags
        ]
        trace["selected_character_tags"] = [x.get("name") for x in trace["tag_candidates"] if x.get("name")]
        if not ranked_tags:
            trace["failure_reason"] = "no_character_tag"
            print(f"ℹ️ [DANBOORU_REF] no character tag: {character_name} / {work_title}")
            return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}

        post_pool = {}
        # Danbooru basic/API searches may reject queries with too many tags.
        # Keep each network query to character + at most one qualifier, then let
        # our local scorer prefer posts that actually contain BOTH solo and full_body.
        query_specs = [
            ("solo", lambda tag_name: f"{tag_name} solo", 40),
            ("full_body", lambda tag_name: f"{tag_name} full_body", 40),
            ("broad", lambda tag_name: f"{tag_name}", 40),
        ]
        for tag in ranked_tags[:4]:
            tag_name = str(tag.get("name") or "").strip()
            if not tag_name:
                continue
            for query_mode, builder, query_limit in query_specs:
                tag_query = builder(tag_name)
                rows = await _danbooru_api_get("posts.json", {
                    "tags": tag_query,
                    "limit": query_limit,
                    "page": 1,
                })
                rows = rows if isinstance(rows, list) else []
                trace["post_queries"].append({
                    "character_tag": tag_name,
                    "mode": query_mode,
                    "tags": tag_query,
                    "result_count": len(rows),
                })
                for post in rows:
                    pid = str((post or {}).get("id") or "")
                    if pid and pid not in post_pool:
                        post_pool[pid] = (post, tag_name, query_mode)
            if len(post_pool) >= 120:
                break

        scored = []
        for post, tag_name, query_mode in post_pool.values():
            score = _score_danbooru_reference_post(post)
            if score is None:
                continue
            score += _score_danbooru_character_tag(tag_candidates.get(tag_name) or {"name": tag_name, "category": 4}, character_name, work_title) * 0.18
            if query_mode == "solo":
                score += 2
            elif query_mode == "full_body":
                score += 2
            scored.append((score, post, tag_name, query_mode))
        scored.sort(key=lambda x: x[0], reverse=True)
        trace["candidate_posts"] = [
            {
                "post_id": int((post or {}).get("id") or 0),
                "character_tag": tag_name,
                "query_mode": query_mode,
                "score": round(float(score), 2),
                "rating": str((post or {}).get("rating") or ""),
                "tag_string": str((post or {}).get("tag_string") or "")[:240],
            }
            for score, post, tag_name, query_mode in scored[:12]
        ]
        if not scored:
            trace["failure_reason"] = "no_acceptable_post"
            print(f"ℹ️ [DANBOORU_REF] no acceptable reference post: {character_name} / {work_title}")
            return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}

        last_error = None
        attempted_candidates = 0
        for score, post, tag_name, query_mode in scored[:max(1, int(DANBOORU_VISION_GATE_MAX_CANDIDATES))]:
            attempted_candidates += 1
            file_url = str(post.get("file_url") or post.get("large_file_url") or "").strip()
            source_path = None
            try:
                source_path, local_url = await _download_and_sanitize_danbooru_image(file_url, post_id=post.get("id"))

                # v1.10.31：tag 只負責把候選送到這裡；是否真的相容，由 Vision 看圖決定。
                try:
                    vision = await _verify_danbooru_candidate_with_vision(
                        source_path,
                        character_name=character_name,
                        work_title=work_title,
                        character_tag=tag_name,
                        post=post,
                    )
                except Exception as vision_exc:
                    vision = {
                        "accepted": False,
                        "compatible": False,
                        "usable_reference": False,
                        "confidence": 0,
                        "min_confidence": int(DANBOORU_VISION_GATE_MIN_CONFIDENCE),
                        "reason": f"Vision gate error: {type(vision_exc).__name__}: {str(vision_exc)[:300]}",
                        "visual_evidence": [],
                        "obvious_conflict": "",
                        "model": DANBOORU_VISION_GATE_MODEL,
                        "error": f"{type(vision_exc).__name__}: {str(vision_exc)[:500]}",
                    }

                vision_row = {
                    "post_id": post.get("id"),
                    "character_tag": tag_name,
                    "query_mode": query_mode,
                    "score": round(float(score), 2),
                    **vision,
                }
                trace["vision_checks"].append(vision_row)

                if not vision.get("accepted"):
                    print(
                        f"ℹ️ [DANBOORU_VISION_REJECT] post={post.get('id')} tag={tag_name} "
                        f"confidence={vision.get('confidence')} reason={vision.get('reason')}"
                    )
                    # Rejected candidates are not useful after Vision gate; avoid cluttering /data/output.
                    try:
                        if source_path and os.path.exists(str(source_path)):
                            os.remove(str(source_path))
                    except Exception:
                        pass
                    continue

                result = {
                    "matched": True,
                    "source": "danbooru",
                    "source_path": source_path,
                    "source_url": file_url,
                    "source_local_url": local_url,
                    "source_page_url": f"{DANBOORU_API_BASE}/posts/{post.get('id')}",
                    "post_id": post.get("id"),
                    "character_tag": tag_name,
                    "rating": post.get("rating"),
                    "score": round(float(score), 2),
                    "query_mode": query_mode,
                    "character_name": character_name,
                    "work_title": work_title,
                    "vision_gate": dict(vision),
                    "trace": trace,
                }
                trace["matched"] = True
                trace["selected_post"] = {
                    "post_id": post.get("id"),
                    "character_tag": tag_name,
                    "query_mode": query_mode,
                    "score": result["score"],
                    "source_url": file_url,
                    "vision_confidence": vision.get("confidence"),
                    "vision_reason": vision.get("reason"),
                }
                print(
                    f"✅ [DANBOORU_REF] selected post={post.get('id')} tag={tag_name} "
                    f"mode={query_mode} score={result['score']} vision={vision.get('confidence')}"
                )
                return result
            except Exception as exc:
                last_error = exc
                trace["download_attempts"].append({
                    "post_id": post.get("id"),
                    "character_tag": tag_name,
                    "query_mode": query_mode,
                    "error": f"{type(exc).__name__}: {exc}",
                })
                print(f"⚠️ [DANBOORU_REF_CANDIDATE_FAILED] post={post.get('id')} {type(exc).__name__}: {exc}")

        # Downloads may have succeeded but all candidates can still fail Vision.
        if trace.get("vision_checks") and not trace.get("matched"):
            trace["failure_reason"] = "vision_rejected_all_candidates"
            print(
                f"ℹ️ [DANBOORU_REF] Vision rejected all {len(trace.get('vision_checks') or [])} "
                f"candidate(s): {character_name} / {work_title}"
            )
            return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}

        if last_error:
            trace["failure_reason"] = "candidate_download_failed"
            print(f"⚠️ [DANBOORU_REF] all candidate downloads failed: {type(last_error).__name__}: {last_error}")
        return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}
    except Exception as exc:
        trace["failure_reason"] = f"exception:{type(exc).__name__}"
        trace["exception"] = f"{type(exc).__name__}: {exc}"
        trace["exception_message"] = str(exc)[:800]
        print(f"⚠️ [DANBOORU_REF_FAILED] {type(exc).__name__}: {exc}")
        return {"matched": False, "trace": trace, "character_name": character_name, "work_title": work_title}


def _cosplay_reference_title_from_story(story):
    story = story if isinstance(story, dict) else {}
    work = _clean_text_compact(story.get("work_title") or (story.get("cosplay_topic_candidate") or {}).get("work_title") or "")
    char = _clean_text_compact(story.get("character_name") or (story.get("cosplay_topic_candidate") or {}).get("character_name") or "")
    if work and char:
        return f"{work}－{char}"
    return char or work or _clean_text_compact(story.get("topic") or "")


def _local_image_mime_type(path):
    ext = os.path.splitext(str(path or ""))[1].lower()
    if ext == ".png":
        return "image/png"
    if ext == ".webp":
        return "image/webp"
    return "image/jpeg"


def _genai_inline_image_bytes(response):
    candidates = getattr(response, "candidates", None) or []
    for cand in candidates:
        content = getattr(cand, "content", None)
        parts = getattr(content, "parts", None) or []
        for part in parts:
            inline = getattr(part, "inline_data", None) or getattr(part, "inlineData", None)
            if not inline:
                continue
            data = getattr(inline, "data", None)
            mime = getattr(inline, "mime_type", None) or getattr(inline, "mimeType", None) or "image/png"
            if not data:
                continue
            if isinstance(data, str):
                try:
                    raw = base64.b64decode(data)
                except Exception:
                    raw = data.encode("utf-8", errors="ignore")
            else:
                raw = data
            if raw:
                return raw, mime
    return None, None


def _save_generated_bytes_to_output(raw, *, prefix="nano_cosplay_ref", mime_type="image/png"):
    if not raw:
        raise RuntimeError("COSPLAY_REF_BYTES_EMPTY")
    ext = ".png"
    mime = str(mime_type or "").lower()
    if "webp" in mime:
        ext = ".webp"
    elif "jpeg" in mime or "jpg" in mime:
        ext = ".jpg"
    filename = f"{prefix}_{datetime.now(TZ_TPE).strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:8]}{ext}"
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    path = os.path.join(OUTPUT_DIR, filename)
    with open(path, "wb") as f:
        f.write(raw)
    return path, f"https://xiaoxia0320.zeabur.app/gallery/{filename}"


async def _analyze_cosplay_clothing_reference_image(local_path, *, title_hint=""):
    if not local_path or not os.path.exists(str(local_path)):
        raise RuntimeError("COSPLAY_REF_ANALYZE_IMAGE_MISSING")
    data = await asyncio.to_thread(Path(str(local_path)).read_bytes)
    mime = _local_image_mime_type(local_path)
    title_text = _clean_text_compact(title_hint or "")
    prompt = f"""
你是 cosplay 造型分析員。請只分析圖片中的可見角色造型，不要評論人物臉型、五官身份或身材，也不要猜測看不見的細節。
請抽取可供重建的髮型／髮色、頭部非身份特徵（如尖耳、額紋、髮飾）、服裝、鞋襪、配件與武器。
角色題材提示：{title_text or '未提供'}

只回 JSON：
{{
  "outfit_summary": "100字內，清楚描述髮型髮色、主服裝、鞋襪與主要道具",
  "hair_and_head_features": ["最多5個髮型／髮色／尖耳／額紋／髮飾等非身份特徵"],
  "key_items": ["最多8個重點服裝、鞋襪、配件或武器"],
  "main_colors": ["最多6個主色"],
  "must_keep_details": ["最多10個要保留的版型／剪裁／圖樣／飾件／武器重點"],
  "negative_avoid": ["最多5個不能亂改的點"]
}}
"""
    response = await gemini_client.aio.models.generate_content(
        model="gemini-2.5-flash",
        contents=[types.Part.from_bytes(data=data, mime_type=mime), prompt],
        config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.1),
    )
    parsed = _safe_json_from_text(getattr(response, "text", "") or "", {})
    summary = _clean_text_compact(parsed.get("outfit_summary"))
    hair_and_head_features = [_clean_text_compact(x)[:70] for x in (parsed.get("hair_and_head_features") or [])[:5] if _clean_text_compact(x)]
    key_items = [_clean_text_compact(x)[:60] for x in (parsed.get("key_items") or [])[:8] if _clean_text_compact(x)]
    colors = [_clean_text_compact(x)[:24] for x in (parsed.get("main_colors") or [])[:6] if _clean_text_compact(x)]
    must_keep = [_clean_text_compact(x)[:80] for x in (parsed.get("must_keep_details") or [])[:10] if _clean_text_compact(x)]
    negative_avoid = [_clean_text_compact(x)[:60] for x in (parsed.get("negative_avoid") or [])[:5] if _clean_text_compact(x)]
    if not summary:
        summary = "忠實保留圖中 cosplay 服裝的版型、層次與主要配件。"
    return {
        "outfit_summary": summary,
        "hair_and_head_features": hair_and_head_features,
        "key_items": key_items,
        "main_colors": colors,
        "must_keep_details": must_keep,
        "negative_avoid": negative_avoid,
    }


def _build_cosplay_clothing_ref_prompt_suffix(analysis):
    analysis = analysis if isinstance(analysis, dict) else {}
    summary = _clean_text_compact(analysis.get("outfit_summary") or "")
    hair_features = ", ".join([x for x in (analysis.get("hair_and_head_features") or []) if x])
    key_items = ", ".join([x for x in (analysis.get("key_items") or []) if x])
    colors = ", ".join([x for x in (analysis.get("main_colors") or []) if x])
    must_keep = "; ".join([x for x in (analysis.get("must_keep_details") or []) if x])
    avoid = "; ".join([x for x in (analysis.get("negative_avoid") or []) if x])
    lines = [
        "FIGURE 10 COSTUME OVERRIDE — clothing only.",
        "Figure 10 is the outfit authority for this cosplay run. Preserve the visible costume faithfully instead of loosely restyling it.",
    ]
    if summary:
        lines.append(f"Costume summary: {summary}")
    if hair_features:
        lines.append(f"Role appearance anchors to keep without copying another face: {hair_features}")
    if key_items:
        lines.append(f"Key visible items/accessories to keep: {key_items}")
    if colors:
        lines.append(f"Main colors to preserve: {colors}")
    if must_keep:
        lines.append(f"Must-keep design details: {must_keep}")
    if avoid:
        lines.append(f"Do not drift into these mistakes: {avoid}")
    lines.append("Figure 10 controls clothing and visible costume accessories only. It must not change Xiaoxia's face, body identity, or the story written in TODAY SCENE.")
    return "\n".join(lines).strip()


async def _generate_nano_cosplay_clothing_reference_board(local_path, *, analysis=None, title_hint=""):
    if not local_path or not os.path.exists(str(local_path)):
        raise RuntimeError("COSPLAY_REF_SOURCE_MISSING")
    data = await asyncio.to_thread(Path(str(local_path)).read_bytes)
    mime = _local_image_mime_type(local_path)
    analysis = analysis if isinstance(analysis, dict) else {}
    summary = _clean_text_compact(analysis.get("outfit_summary") or "")
    must_keep = "; ".join([x for x in (analysis.get("must_keep_details") or []) if x])
    title_text = _clean_text_compact(title_hint or "")
    hair_features = "; ".join([x for x in (analysis.get("hair_and_head_features") or []) if x])
    prompt = f"""
Transform the provided character reference into a clean, photorealistic cosplay appearance reference board for a later image-generation model.

Create ONE identity-neutral, faceless full-body costume figure on a plain light studio background.
IMPORTANT: keep the HEAD and HAIR because hairstyle, hair color, ears, forehead marks, headwear, and hair accessories may be essential cosplay features.
The face area itself must be blank / smooth / featureless: no eyes, no nose, no mouth, no recognizable facial identity, and no realistic person's face.
Preserve the costume's real-world wearable structure, silhouette, colors, layers, trims, footwear, accessories, and weapon/prop shapes as faithfully as possible.
Convert illustrated/anime materials into plausible real fabrics, leather, metal, gems, and props without redesigning the costume.
Keep important items in their natural body-relative positions. If a weapon or accessory would obscure the outfit, it may also be shown cleanly beside the figure.
No scene background, no magic effects, no flowers, no extra people, no text labels, no watermark, no UI.

Role hint: {title_text or 'cosplay outfit'}.
Appearance anchors: {hair_features or 'preserve visible hairstyle/hair color and non-face head features from the source'}.
Outfit summary: {summary or 'preserve the visible costume faithfully'}.
Must-keep details: {must_keep or 'preserve silhouette, colors, layers, trims, footwear, accessories, and weapons'}.
"""
    response = await gemini_client.aio.models.generate_content(
        model=COSPLAY_NANO_CLOTHING_REF_MODEL_ID,
        contents=[types.Part.from_bytes(data=data, mime_type=mime), prompt],
        config=types.GenerateContentConfig(response_modalities=["TEXT", "IMAGE"]),
    )
    raw, out_mime = _genai_inline_image_bytes(response)
    if not raw:
        raise RuntimeError("COSPLAY_REF_NANO_NO_IMAGE")
    return _save_generated_bytes_to_output(raw, prefix="nano_cosplay_ref", mime_type=out_mime)


async def _prepare_cosplay_clothing_reference(message, *, title_hint="", external_source=None):
    external_source = external_source if isinstance(external_source, dict) else None
    attachment = None
    if external_source:
        source_path = external_source.get("source_path")
        if not source_path or not os.path.exists(str(source_path)):
            raise RuntimeError("COSPLAY_EXTERNAL_REF_SOURCE_MISSING")
        source_kind = str(external_source.get("source") or "external")
        source_original_url = external_source.get("source_url")
        source_local_url = external_source.get("source_local_url")
        source_page_url = external_source.get("source_page_url")
    else:
        attachment, error = await _get_photo_reference_attachment(message)
        if error:
            raise RuntimeError(error)
        if not attachment:
            return None
        source_path = await _download_photo_reference_attachment(attachment)
        source_kind = "manual_attachment"
        source_original_url = getattr(attachment, "url", None)
        source_local_url = None
        source_page_url = None

    analysis = None
    try:
        analysis = await _analyze_cosplay_clothing_reference_image(source_path, title_hint=title_hint)
    except Exception as exc:
        print(f"⚠️ [COSPLAY_REF_ANALYZE_FAILED] {type(exc).__name__}: {exc}")
        analysis = {"outfit_summary": "忠實保留圖中 cosplay 造型、服裝與可見配件。", "hair_and_head_features": [], "key_items": [], "main_colors": [], "must_keep_details": [], "negative_avoid": []}
    try:
        board_path, board_url = await _generate_nano_cosplay_clothing_reference_board(source_path, analysis=analysis, title_hint=title_hint)
        ref_path, ref_url = board_path, board_url
        provider = (f"Danbooru → {COSPLAY_NANO_CLOTHING_REF_LABEL}" if source_kind == "danbooru" else COSPLAY_NANO_CLOTHING_REF_LABEL)
    except Exception as exc:
        print(f"⚠️ [COSPLAY_REF_NANO_GENERATE_FAILED] model={COSPLAY_NANO_CLOTHING_REF_MODEL_ID} {type(exc).__name__}: {exc}")
        raise RuntimeError(
            f"Nano 服裝前處理失敗（{COSPLAY_NANO_CLOTHING_REF_MODEL_ID}）：{type(exc).__name__}: {str(exc)[:700]}。"
            "為避免把原角色臉直接當 Figure 10、也避免白燒 Seedream 圖錢，本次 Cosplay 已停止，沒有呼叫 v4.5。"
        ) from exc
    return {
        "source_kind": source_kind,
        "source_attachment_url": getattr(attachment, "url", None) if attachment else None,
        "source_original_url": source_original_url,
        "source_local_url": source_local_url,
        "source_page_url": source_page_url,
        "source_path": source_path,
        "reference_path": ref_path,
        "reference_url": ref_url,
        "provider": provider,
        "analysis": analysis,
        "prompt_suffix": _build_cosplay_clothing_ref_prompt_suffix(analysis),
        "summary": _clean_text_compact((analysis or {}).get("outfit_summary") or "")[:300],
        "danbooru": dict(external_source or {}) if source_kind == "danbooru" else None,
    }


@girlfriend_bot.command(name='cosplay')
async def cosplay(ctx, *, mode: str = "auto"):
    if not check_daily_limit():
        await ctx.send("💦 大俠～小俠今天累了，明天再拍好不好？（抱）")
        return
    
    if mode == "auto":
        mode = "每日動態選角"

    vibe_mode = _extract_vibe_mode(mode)
    if not vibe_mode:
        vibe_mode = {"zh": "魅", "en": "alluring-max", "level": 6}
    story_mode = mode
    if vibe_mode:
        story_mode = mode
        for alias in VIBE_KEYWORDS.get(vibe_mode.get("zh"), []):
            story_mode = re.sub(re.escape(alias), "", story_mode, flags=re.IGNORECASE)
