def _load_json_file_safe(path, fallback):
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception as exc:
        print(f"⚠️ JSON 讀取失敗 {path}: {exc}")
    return fallback


def _save_json_file_atomic(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp_path = f"{path}.tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    os.replace(tmp_path, path)


def _seedream_reference_paths(selected_figure_indexes=None):
    """讀取 /data/memory/seedream_v45 內的 Seedream_01~09 參考底稿。"""
    manifest_path = os.path.join(SEEDREAM_V45_REF_DIR, "manifest.txt")
    paths = []
    if os.path.exists(manifest_path):
        with open(manifest_path, "r", encoding="utf-8") as f:
            for line in f:
                value = line.strip()
                if value:
                    paths.append(value if os.path.isabs(value) else os.path.join(SEEDREAM_V45_REF_DIR, value))
    if not paths:
        for index in range(1, 10):
            paths.append(os.path.join(SEEDREAM_V45_REF_DIR, f"Seedream_{index:02d}.png"))

    existing = [p for p in paths if os.path.exists(p)]
    if len(existing) < 1:
        raise FileNotFoundError(
            f"找不到 Seedream v4.5 參考底稿，請確認已上傳至 {SEEDREAM_V45_REF_DIR}/Seedream_01.png~Seedream_09.png"
        )
    existing = existing[:9]
    if not selected_figure_indexes:
        return existing

    selected = []
    seen = set()
    for raw_index in selected_figure_indexes:
        try:
            index = int(raw_index)
        except Exception:
            continue
        if index < 1 or index > len(existing) or index in seen:
            continue
        selected.append(existing[index - 1])
        seen.add(index)
    return selected or existing


def _get_fal_client():
    try:
        import fal_client
        return fal_client
    except ImportError:
        print("⚠️ fal_client 未安裝，嘗試即時安裝 fal-client...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "fal-client"])
        import fal_client
        return fal_client


async def _seedream_upload_reference_images(force_refresh=False, selected_figure_indexes=None):
    """將本機 /data/memory/seedream_v45 參考圖上傳到 fal 檔案服務並快取 URL。

    fal media URL 可能過期或失效；若後續 Seedream 回 file_download_error，
    呼叫端會用 force_refresh=True 重新上傳 1-9 號人物底稿再重試。
    selected_figure_indexes 可指定只取其中幾張（仍沿用同一份快取）。
    """
    fal_client = _get_fal_client()
    cache = _load_json_file_safe(SEEDREAM_V45_UPLOAD_CACHE_PATH, {})
    if force_refresh or not isinstance(cache, dict):
        cache = {}
    changed = bool(force_refresh)
    urls = []
    for path in _seedream_reference_paths(selected_figure_indexes=selected_figure_indexes):
        stat = os.stat(path)
        key = os.path.basename(path)
        cached = cache.get(key, {}) if isinstance(cache, dict) else {}
        valid = (
            not force_refresh
            and cached.get("path") == path
            and cached.get("mtime") == stat.st_mtime
            and cached.get("size") == stat.st_size
            and str(cached.get("url", "")).startswith("http")
        )
        if valid:
            url = cached["url"]
        else:
            print(f"🌱 [SEEDREAM_UPLOAD] uploading {path} force={force_refresh}")
            url = await asyncio.to_thread(fal_client.upload_file, path)
            cache[key] = {
                "path": path,
                "mtime": stat.st_mtime,
                "size": stat.st_size,
                "url": url,
                "uploaded_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
            }
            changed = True
        urls.append(url)
    if changed:
        _save_json_file_atomic(SEEDREAM_V45_UPLOAD_CACHE_PATH, cache)
    return urls


def _v5_background_upgrade_identity_figures():
    # v1.5.58_R3：hybrid 路線改用 Figure 1~8 作身份底圖。
    # Figure 09 為 90° 側面、人物一致性較弱，因此只從 hybrid 路線排除；
    # 純 v4.5 的原 9 張身份圖機制完全不動。
    raw = os.environ.get("SEEDREAM_V5_BG_UPGRADE_REF_FIGURES", "1,2,3,4,5,6,7,8")
    values = []
    seen = set()
    for chunk in re.split(r"[^0-9]+", str(raw or "")):
        if not chunk:
            continue
        try:
            idx = int(chunk)
        except Exception:
            continue
        if 1 <= idx <= 9 and idx not in seen:
            values.append(idx)
            seen.add(idx)
    if len(values) != 8:
        values = [1, 2, 3, 4, 5, 6, 7, 8]
    return values


def _apply_v5_background_role_handoff_prompt(final_prompt, has_reference=False, reference_allure_unlock=False):
    """Hybrid-only role handoff. Normal reference runs keep Figure 10 strict; ONLY-FOR-DAXIA keeps Figure 10 as role/costume identity base while TODAY SCENE remains final outfit authority."""
    text = str(final_prompt or "").strip()
    if not text:
        return text
    text = re.sub(r"\bFigures 1-9\b", "Figures 1-8", text)
    prefix_lines = [
        "BACKGROUND HANDOFF ROLE MAP — this override is mandatory for this HYBRID v4.5 + v5 background run.",
        "- Figures 1-8 collectively have exclusive authority over Xiaoxia's facial identity and core body identity. Preserve the same recognizable Xiaoxia: sweet refined adult East Asian face, fair luminous skin, natural long brown-family hair, tall and slim stature, distinctly narrow waist, naturally very full and visibly prominent elegant bust, strong bust-to-waist contrast, refined hourglass silhouette, and graceful long legs.",
        "- Do not let any non-identity reference average, soften, shorten, broaden, flatten, or normalize Xiaoxia's established proportions. Keep her tall, slim, narrow-waisted, full-busted, and recognizably Xiaoxia in standing, seated, three-quarter, side-facing, and full-body compositions while maintaining natural anatomy.",
        "- Figure 9 is a background-only reference image generated by Seedream v5.0 Pro. Use Figure 9 only for the environment, location, set dressing, architecture, landscape, perspective depth, atmosphere, lighting richness, and physically coherent spatial relationships.",
        "- Never use Figure 9 to change Xiaoxia's face, body identity, body proportions, hairstyle, outfit, or visible accessories.",
        "- Any mentioned time is scene context only. Do not render timestamps, clock readouts, UI overlays, watermarks, captions, labels, subtitles, or any visible text unless explicitly requested by Daxia.",
    ]
    if has_reference and reference_allure_unlock:
        prefix_lines += [
            "- ONLY-FOR-DAXIA reference rule: Figure 10 is the character/costume IDENTITY BASE, not an exact wardrobe lock. Use it to keep the role recognizable through selected cues such as color family, role-specific hair/head traits, costume mood, iconic layers/motifs, footwear/accessory language, props or weapons.",
            "- TODAY SCENE is the FINAL authority for the redesigned outfit. If a conservative Figure 10 construction conflicts with TODAY SCENE's alluring design, change that garment construction while preserving enough selected role cues to remain recognizable.",
            "- Do not force exact preservation of Figure 10 neckline, collar, sleeve structure, length, layering, openings, opacity placement, or other construction details in ONLY-FOR-DAXIA mode.",
            "- Do not apply one recurring sexy template. Let TODAY SCENE choose a different creative, role-coherent alluring redesign when appropriate.",
        ]
    elif has_reference:
        prefix_lines += [
            "- Figure 10 is the exact wardrobe authority for this hybrid run. Preserve the garment faithfully rather than merely matching its general style.",
            "- Preserve Figure 10's garment category, silhouette, cut, neckline, strap/sleeve structure, length, layering, asymmetry, transparency-versus-opacity placement, fabric/material, color, pattern/embroidery placement, trim, closures, and other distinctive visible design details.",
            "- Do not redesign, simplify, replace, recolor, restyle, or reinterpret Figure 10 into a visually similar but different garment. Figure 10 controls clothing and visible fashion accessories only; it must not override the requested scene, action, pose, camera, or background.",
        ]
    else:
        prefix_lines.append("- No Figure 10 is supplied unless this run explicitly includes one.")
    prefix_lines.append("- This hybrid role override takes precedence over any generic Figures 1-9 or weaker Figure 10 wording that may still appear later in the shared prompt.")
    return "\n\n".join(["\n".join(prefix_lines).strip(), text]).strip()


def _seedream_cosplay_prompt(custom_prompt):
    return (
        "Use all input images as reference sheets for the same adult fictional character, Xiaoxia. "
        "Preserve her recognizable sweet East Asian facial identity, fair luminous skin, tall slim feminine figure, clearly defined waist, naturally very full and elegant bust, strong bust-to-waist contrast, long graceful legs with an elegant lower-leg line, gentle youthful-adult aura, and natural body proportions from the references. "
        "Apply Xiaoxia Aesthetic as the default baseline even in cosplay: refined feminine allure, a naturally very full and elegant bust with strong bust-to-waist contrast and a soft hourglass silhouette as part of Xiaoxia's core body identity, with that bust-to-waist contrast as the primary charm point, and the most suitable secondary charm point chosen between waistline, leg line, or both according to the role, outfit structure, pose logic, and scene mood. "
        "Daxia's current request still overrides this baseline. If Daxia asks for stronger role fidelity, fuller bust, slimmer body, longer lower legs, or another targeted adjustment, obey that request first while still keeping Xiaoxia recognizable. "
        "Do not copy any one reference pose or background exactly; create a new cosplay image according to the prompt. "
        "Only Xiaoxia may appear. No man, no male head, no male face, no male hair, no male hands, no male arms, no male shoulder, no male back, no male torso, no other people, no reflections of other people. "
        "Do not show Daxia, the camera holder, or any visible body part of the viewer. No blurred male foreground figure, no cropped male body parts, no male silhouette, no male reflection, and no foreground viewer hand/arm/shoulder. The POV must be implied only through framing, Xiaoxia's gaze, and composition. "
        "Keep anatomy natural, hands plausible; Xiaoxia's posture, limbs, joints, hands, and fingers must be physically plausible and normal, with no awkward body mechanics. "
        "For cosplay, Xiaoxia's face identity must remain recognizable first. Hairstyle and hair color may adapt to the role when needed for recognizable cosplay fidelity, but the result must still clearly read as Xiaoxia cosplaying the role rather than the original actor or a different woman. "
        "Maximize visual impact: explicitly allow extreme cinematic angles, dramatic chiaroscuro lighting, highly detailed fabric textures (including translucent, wet, or form-fitting materials), and alluring/seductive expressions if requested. "
        "The result should be a highly polished cinematic cosplay photograph with vivid character storytelling and intense visual appeal. Preserve the source character's recognizable visual language through at least 2 or 3 anchors such as color palette, costume silhouette, emblem or motif, prop, hairstyle or hair color, environment, or role task. Do not turn the role into unrelated generic black lingerie, demon wings, or arbitrary glamour styling unless that is truly part of the source role.\n\n"
        f"COSPLAY EDIT REQUEST:\n{custom_prompt}"
    )


def _seedream_error_is_retryable(value):
    raw = str(value or "").lower()
    return any(token in raw for token in (
        "moderation", "safety", "safe", "policy", "blocked", "violation", "sexual", "nsfw", "not allowed", "content"
    ))


async def generate_seedream_v45_cosplay(custom_prompt, enable_safety_checker=None, trace_context=None, input_image_urls_override=None):
    """呼叫 fal-ai/bytedance/seedream/v4.5/edit，用 9 張 Zeabur 參考底稿做 image-to-image。"""
    fal_client = _get_fal_client()
    model_id = _context_seedream_model_id(trace_context=trace_context)
    model_label = _seedream_model_label_from_id(model_id)
    if isinstance(trace_context, dict):
        trace_context["seedream_model_id"] = model_id
        trace_context["seedream_model_label"] = model_label
    override_urls = list(input_image_urls_override or ((trace_context or {}).get("seedream_input_images_override") if isinstance(trace_context, dict) else []) or [])
    if override_urls:
        image_urls = override_urls[:10]
    else:
        selected_figures = (trace_context or {}).get("seedream_identity_selected_figures") if isinstance(trace_context, dict) else None
        image_urls = await _seedream_upload_reference_images(selected_figure_indexes=selected_figures)
    if isinstance(trace_context, dict) and trace_context.get("cosplay_scene_only"):
        final_prompt = str(custom_prompt or "").strip()
    elif str(custom_prompt or "").lstrip().startswith("FIGURE ROLE MAP"):
        final_prompt = str(custom_prompt or "").strip()
    else:
        final_prompt = _seedream_cosplay_prompt(custom_prompt)
    if isinstance(trace_context, dict) and trace_context.get("v5_background_role_handoff"):
        final_prompt = _apply_v5_background_role_handoff_prompt(
            final_prompt,
            has_reference=bool(trace_context.get("figure10_present") or trace_context.get("reference_item_path") or trace_context.get("reference_item_url")),
            reference_allure_unlock=bool(trace_context.get("cosplay_reference_allure_unlock")),
        )
    if isinstance(trace_context, dict):
        trace_context["seedream_input_images"] = list(image_urls)
        role_override = trace_context.get("seedream_input_image_roles_override")
        if isinstance(role_override, list) and role_override:
            trace_context["seedream_input_image_roles"] = role_override
    _trace_stage(trace_context, "seedream_cosplay_final_prompt", prompt=final_prompt, data={"model": model_id, "model_label": model_label, "image_size": SEEDREAM_V45_IMAGE_SIZE, "raw_seedream_mode": (trace_context or {}).get("raw_seedream_mode"), "enable_safety_checker": bool(enable_safety_checker), "input_count": len(image_urls)})

    def _subscribe():
        def on_queue_update(update):
            try:
                if isinstance(update, fal_client.InProgress):
                    for log in update.logs:
                        print(f"🌱 [SEEDREAM_QUEUE] {log.get('message', '')}")
            except Exception:
                pass
        return fal_client.subscribe(
            model_id,
            arguments=_seedream_request_args(model_id, final_prompt, image_urls, enable_safety_checker=enable_safety_checker),
            with_logs=True,
            on_queue_update=on_queue_update,
        )

    try:
        result = await asyncio.to_thread(_subscribe)
    except Exception as exc:
        if _is_fal_content_policy_error(exc):
            raise RuntimeError(
                "WARDROBE_CLEANUP_CONTENT_POLICY：這張圖被 fal.ai / Seedream 的圖片安全檢查擋下，無法自動去人。"
                "請換一張更像商品平鋪照、模特兒露膚較少的圖，或先用 `/衣櫃 新增 名稱` 直接收藏原圖。"
            ) from exc
        raise
    images = result.get("images") if isinstance(result, dict) else None
    if not images:
        return f"{model_label} 沒有回傳圖片：{result}"
    first = images[0]
    if isinstance(first, dict) and first.get("url"):
        return first["url"]
    return f"{model_label} 圖片欄位格式異常：{result}"



def _diary_guard_source_blob(initial_prompt="", visual_dict=None, trace_context=None):
    parts = [str(initial_prompt or "")]
    if isinstance(visual_dict, dict):
        for key in ("composition", "mood", "message", "image_prompt"):
            if visual_dict.get(key):
                parts.append(str(visual_dict.get(key)))
        task = visual_dict.get("__diary_photo_task")
        if isinstance(task, dict):
            parts.append(json.dumps(task, ensure_ascii=False))
        anchor = visual_dict.get("__anchor_state")
        if isinstance(anchor, dict):
            parts.append(json.dumps(anchor, ensure_ascii=False))
    if isinstance(trace_context, dict):
        for key in ("user_input", "scene_seed_text", "diary_forced_scene"):
            if trace_context.get(key):
                parts.append(str(trace_context.get(key)))
        for key in ("committed_diary_photo_task", "due_promises"):
            if trace_context.get(key):
                try:
                    parts.append(json.dumps(trace_context.get(key), ensure_ascii=False))
                except Exception:
                    parts.append(str(trace_context.get(key)))
    return "\n".join(parts)


def _diary_extract_prompt_line(label, text):
    m = re.search(rf"(?im)^\s*{re.escape(label)}\s*:\s*(.+?)\s*$", str(text or ""))
    return _clean_text_compact(m.group(1)) if m else ""


def _diary_contains_any(text, keywords):
    hay = str(text or "").lower()
    return any(str(k).lower() in hay for k in keywords)


def _diary_build_visual_guard_context(initial_prompt="", visual_dict=None, trace_context=None):
    """v1.4.99: keep diary photo constraints alive after minimalization."""
    visual_dict = visual_dict if isinstance(visual_dict, dict) else {}
    trace_context = trace_context if isinstance(trace_context, dict) else {}
    task = visual_dict.get("__diary_photo_task")
    if not isinstance(task, dict):
        task = trace_context.get("committed_diary_photo_task") if isinstance(trace_context.get("committed_diary_photo_task"), dict) else {}
    anchor = visual_dict.get("__anchor_state") if isinstance(visual_dict.get("__anchor_state"), dict) else {}

    source = _diary_guard_source_blob(initial_prompt, visual_dict, trace_context)
    scene = _clean_text_compact(task.get("scene") or anchor.get("setting_anchor") or _diary_extract_prompt_line("Scene", initial_prompt) or visual_dict.get("composition") or "")
    action = _clean_text_compact(task.get("action") or anchor.get("primary_action") or _diary_extract_prompt_line("Action", initial_prompt) or visual_dict.get("composition") or initial_prompt)
    outfit = _clean_text_compact(task.get("outfit") or anchor.get("outfit_intent") or _diary_extract_prompt_line("Outfit", initial_prompt) or "")
    visual_request = _clean_text_compact(task.get("visual_request_zh") or trace_context.get("diary_forced_scene") or visual_dict.get("composition") or action)

    # Future event guard: "準備/預告/週末/未來" + a location keyword must not become current location.
    aquarium_terms = ["水族館", "aquarium", "fish tank", "underwater tunnel", "海生館"]
    future_terms = ["週末", "本週末", "下週", "明天", "之後", "未來", "預告", "準備", "約會前", "行程", "到時候", "future", "upcoming", "prepare"]
    has_aquarium = _diary_contains_any(source, aquarium_terms)
    future_boundary = bool(has_aquarium and _diary_contains_any(source, future_terms))
    forbidden_locations = []
    if has_aquarium and future_boundary:
        forbidden_locations = [
            "aquarium interior",
            "fish tank background",
            "underwater tunnel",
            "ocean exhibition hall",
            "blue aquarium display background",
            "inside an aquarium visit",
        ]

    not_too_spicy = _diary_contains_any(source, [
        "不要太辣", "別太辣", "不能太辣", "不要穿太辣", "日常", "適合日常生活",
        "不要以裸露", "不要以身體部位", "not too spicy", "not too sexy",
        "avoid exposed body parts", "daily life",
    ])
    # v1.5.07: diary defaults are attractive/sexy again. Only explicit Daxia modesty words activate not_too_spicy.
    # Do not auto-convert generic outfit-preparation/date looks into conservative mode.

    if not scene:
        scene = "小俠家中或試衣間"
    if future_boundary and _diary_contains_any(scene, aquarium_terms):
        scene = "小俠家中或試衣間"

    if not outfit or outfit in {"水族館約會穿搭", "約會穿搭", "穿搭look", "look"}:
        outfit_spec = "attractive, feminine, date-ready outfit prepared for the future aquarium date; allow tasteful sensual charm unless Daxia explicitly says not too spicy"
    else:
        outfit_spec = outfit

    if not_too_spicy:
        outfit_spec = (
            f"{outfit_spec}; keep it pretty, feminine, date-ready, and suitable for daily life; "
            "do not make cleavage, exposed body parts, lingerie-like styling, bikini-like styling, or overly sexy posing the visual focus"
        )

    constraints = {
        "not_too_spicy": bool(not_too_spicy),
        "forbid_current_aquarium_scene": bool(future_boundary),
        "aquarium_is_future_plan": bool(future_boundary),
    }
    future_event_constraints = {
        "future_event": "水族館約會" if has_aquarium else "",
        "time_hint": "future/週末/準備" if future_boundary else "",
        "forbidden_current_locations": forbidden_locations,
    }
    return {
        "visual_request": visual_request,
        "scene": scene,
        "action": action,
        "outfit_spec": outfit_spec,
        "user_constraints": constraints,
        "future_event_constraints": future_event_constraints,
        "forbidden_locations": forbidden_locations,
        "source_preview": _trace_preview(source, 1200),
    }


def _build_diary_guarded_minimal_prompt(initial_prompt="", visual_dict=None, trace_context=None, visual_checklist=None, retry_reason=""):
    """v1.4.99: diary minimal prompt that preserves scene, future-event boundary, outfit, and modesty constraints."""
    guard = _diary_build_visual_guard_context(initial_prompt, visual_dict=visual_dict, trace_context=trace_context)
    if isinstance(trace_context, dict):
        trace_context["diary_text_outfit_spec"] = guard.get("outfit_spec")
        trace_context["diary_user_constraints"] = guard.get("user_constraints")
        trace_context["future_event_constraints"] = guard.get("future_event_constraints")
        trace_context["diary_minimal_anchor_preserved"] = True
    lines = [
        "FIGURE ROLE MAP — obey these roles strictly.",
        "",
        "Figures 1-9 are identity-only reference images of Xiaoxia.",
        "Use Figures 1-9 only to preserve Xiaoxia's recognizable face identity, fair skin, adult East Asian appearance, long brown hair, tall slim feminine body, defined waist, and overall Xiaoxia look.",
        "Do NOT copy pose, background, room, outfit, lighting setup, or composition from Figures 1-9.",
        "",
        "DIARY VISUAL REQUEST — obey literally. This controls the final scene, action, outfit, mood, and composition.",
        "Keep it as one single visual moment. Do not mix in other diary scenes, optional promises, bedroom defaults, or unrelated romantic diary imagery.",
        "",
        f"Actual scene/location: {guard.get('scene')}",
    ]
    if guard.get("user_constraints", {}).get("forbid_current_aquarium_scene"):
        lines += [
            "",
            "FUTURE EVENT BOUNDARY — critical:",
            "The aquarium is only the future weekend plan, NOT today's photo location.",
            "Do NOT place Xiaoxia inside an aquarium, underwater tunnel, aquarium hall, fish tank corridor, ocean exhibition, or blue aquarium display background.",
        ]
    lines += [
        "",
        f"Action: {guard.get('action')}",
        f"Outfit: Use the same outfit specification intended by today's diary/photo promise: {guard.get('outfit_spec')}",
    ]
    if guard.get("user_constraints", {}).get("not_too_spicy"):
        lines += [
            "",
            "MODESTY / STYLE BOUNDARY — critical:",
            "Daxia explicitly wants this not too spicy. The outfit should be pretty, feminine, date-ready, and suitable for daily life.",
            "Do not make cleavage, exposed body parts, lingerie-like styling, bikini-like styling, or overly sexy posing the focus.",
        ]
    if retry_reason:
        lines += [
            "",
            "PREVIOUS OUTPUT WAS REJECTED:",
            str(retry_reason)[:900],
            "Correct the failure now. The diary photo promise, actual scene/location, future-event boundary, outfit specification, and any explicit modesty boundary must all be obeyed.",
        ]
    lines += [
        "",
        "Mandatory people rule: " + _seedream_people_policy_line(visual_checklist),
        "Natural anatomy, plausible hands, candid photorealistic lifestyle photo.",
    ]
    return "\n".join(lines).strip()


def _augment_diary_visual_checklist(checklist, trace_context=None):
    if not isinstance(checklist, dict):
        checklist = {}
    trace_context = trace_context if isinstance(trace_context, dict) else {}
    constraints = trace_context.get("diary_user_constraints") if isinstance(trace_context.get("diary_user_constraints"), dict) else {}
    future = trace_context.get("future_event_constraints") if isinstance(trace_context.get("future_event_constraints"), dict) else {}
    must_have = list(checklist.get("must_have") or [])
    must_not = list(checklist.get("must_not_have") or [])
    if trace_context.get("diary_text_outfit_spec"):
        must_have.append("outfit must match diary_text_outfit_spec: " + str(trace_context.get("diary_text_outfit_spec"))[:300])
    if constraints.get("forbid_current_aquarium_scene"):
        must_have.append("actual current photo location must be home / fitting room / dressing area, not the future aquarium visit")
        must_not += [
            "aquarium interior as current location",
            "fish tank background",
            "underwater tunnel",
            "ocean exhibition hall",
            "blue aquarium display background",
        ]
    if constraints.get("not_too_spicy"):
        must_not += [
            "overly spicy or lingerie-like styling",
            "bikini-like styling",
            "image focused on cleavage or exposed body parts instead of the diary outfit look",
        ]
    checklist["must_have"] = [x for i, x in enumerate(must_have) if x and x not in must_have[:i]][:14]
    checklist["must_not_have"] = [x for i, x in enumerate(must_not) if x and x not in must_not[:i]][:18]
    checklist["diary_user_constraints"] = constraints
    checklist["future_event_constraints"] = future
    return checklist


def _seedream_diary_prompt(custom_prompt, visual_checklist=None):
    raw = str(custom_prompt or "").strip()
    if "FIGURE ROLE MAP" in raw and "TEXT REQUEST" in raw:
        if re.search(r"background bystanders|public/travel|public scene|路人|背景", raw, re.I):
            return raw + "\n\nFinal safety: Xiaoxia must be the only primary subject. Incidental distant/blurred background bystanders may remain only in public scenes, but no companion, no male partner, no foreground second person, no interacting person, no external hands, natural anatomy."
        return raw + "\n\nFinal safety: strictly only Xiaoxia appears; no man, no second person, no external hands, natural anatomy."
    return (
        "FIGURE ROLE MAP — obey these roles strictly.\n\n"
        "Figures 1-9 are identity-only reference images of Xiaoxia. Use them only to preserve Xiaoxia's recognizable face identity, fair skin, adult East Asian appearance, long brown hair, tall slim feminine body, defined waist, and overall Xiaoxia look.\n"
        "Do NOT copy pose, background, room, outfit, lighting setup, or composition from Figures 1-9.\n\n"
        "DIARY VISUAL REQUEST — this controls the final scene, action, outfit, mood, and composition. Keep it as one single visual moment. Do not mix in other diary scenes or optional promises.\n\n"
        f"{raw}\n\n"
        "Mandatory people rule: " + _seedream_people_policy_line(visual_checklist) + " Natural anatomy, plausible hands, candid photorealistic lifestyle photo."
    )


async def generate_seedream_v45_diary(custom_prompt, enable_safety_checker=None, trace_context=None, input_image_urls_override=None):
    """呼叫 fal-ai/bytedance/seedream/v4.5/edit，用 9 張 Zeabur 參考底稿做交換日記 image-to-image。"""
    fal_client = _get_fal_client()
    model_id = _context_seedream_model_id(trace_context=trace_context)
    model_label = _seedream_model_label_from_id(model_id)
    if isinstance(trace_context, dict):
        trace_context["seedream_model_id"] = model_id
        trace_context["seedream_model_label"] = model_label
    override_urls = list(input_image_urls_override or ((trace_context or {}).get("seedream_input_images_override") if isinstance(trace_context, dict) else []) or [])
    if override_urls:
        image_urls = override_urls[:10]
    else:
        selected_figures = (trace_context or {}).get("seedream_identity_selected_figures") if isinstance(trace_context, dict) else None
        image_urls = await _seedream_upload_reference_images(selected_figure_indexes=selected_figures)
    has_reference = bool((trace_context or {}).get("figure10_present") or (trace_context or {}).get("reference_item_path") or (trace_context or {}).get("reference_item_url")) if isinstance(trace_context, dict) else False
    diary_prompt_result = _seedream_diary_prompt(
        custom_prompt,
        has_reference=has_reference,
        current_outfit=(trace_context or {}).get("current_outfit_for_seedream") if isinstance(trace_context, dict) else None,
        visual_checklist=(trace_context or {}).get("visual_checklist") if isinstance(trace_context, dict) else None,
    )
    # R13: v1.5.28+ diary prompt builder returns (prompt_string, stats_dict).
    # The dedicated diary path previously forwarded that tuple directly to fal.ai,
    # so the API received [prompt, stats] instead of a string and rejected every retry.
    if isinstance(diary_prompt_result, tuple):
        final_prompt, diary_prompt_stats = diary_prompt_result
    else:
        final_prompt, diary_prompt_stats = diary_prompt_result, None
    final_prompt = str(final_prompt or "").strip()
    if not final_prompt:
        raise RuntimeError("SEEDREAM_DIARY_PROMPT_EMPTY")
    if isinstance(trace_context, dict):
        trace_context["seedream_prompt_exact"] = final_prompt
        trace_context["diary_seedream_prompt_exact"] = final_prompt
        if diary_prompt_stats is not None:
            trace_context["diary_prompt_stats"] = diary_prompt_stats
    if isinstance(trace_context, dict) and trace_context.get("v5_background_role_handoff"):
        final_prompt = _apply_v5_background_role_handoff_prompt(
            final_prompt,
            has_reference=has_reference,
            reference_allure_unlock=bool(trace_context.get("cosplay_reference_allure_unlock")),
        )
    if isinstance(trace_context, dict):
        trace_context["seedream_input_images"] = list(image_urls)
        role_override = trace_context.get("seedream_input_image_roles_override")
        if isinstance(role_override, list) and role_override:
            trace_context["seedream_input_image_roles"] = role_override

    def _subscribe():
        def on_queue_update(update):
            try:
                if isinstance(update, fal_client.InProgress):
                    for log in update.logs:
                        print(f"🌱 [SEEDREAM_DIARY_QUEUE] {log.get('message', '')}")
            except Exception:
                pass
        return fal_client.subscribe(
            model_id,
            arguments=_seedream_request_args(model_id, final_prompt, image_urls, enable_safety_checker=enable_safety_checker),
            with_logs=True,
            on_queue_update=on_queue_update,
        )

    result = await asyncio.to_thread(_subscribe)
    images = result.get("images") if isinstance(result, dict) else None
    if not images:
        return f"{model_label} 沒有回傳交換日記圖片：{result}"
    first = images[0]
    if isinstance(first, dict) and first.get("url"):
        return first["url"]
    return f"{model_label} 交換日記圖片欄位格式異常：{result}"



