WARDROBE_CATEGORY_ALIASES = {
    "睡衣/居家服": "睡衣／居家服", "睡衣／居家": "睡衣／居家服", "睡衣": "睡衣／居家服", "居家服": "睡衣／居家服", "居家": "睡衣／居家服",
    "cosplay": "Cosplay／特殊服裝", "Cosplay": "Cosplay／特殊服裝", "特殊服裝": "Cosplay／特殊服裝", "角色服": "Cosplay／特殊服裝",
    "連體褲": "連身褲", "連衣褲": "連身褲", "jumpsuit": "連身褲", "romper": "連身褲",
    "鞋": "鞋子", "包": "包包", "飾品": "配件", "配飾": "配件",
}


def _normalize_wardrobe_main_category(value, fallback=None):
    raw = _clean_text_compact(value).replace("/", "／")
    if not raw:
        return fallback if fallback in WARDROBE_MAIN_CATEGORIES else "上衣"
    if raw in WARDROBE_MAIN_CATEGORIES:
        return raw
    if raw in WARDROBE_CATEGORY_ALIASES:
        return WARDROBE_CATEGORY_ALIASES[raw]
    if raw == "睡衣／居家服":
        return "睡衣／居家服"
    return fallback if fallback in WARDROBE_MAIN_CATEGORIES else None


def _normalize_wardrobe_sub_category(main_category, value):
    """將新資料的子分類收斂到固定白名單；不會批次改寫既有衣櫃 JSON。"""
    main_category = _normalize_wardrobe_main_category(main_category, fallback="上衣") or "上衣"
    options = WARDROBE_SUBCATEGORY_OPTIONS.get(main_category, [main_category])
    raw = _clean_text_compact(value)
    if not raw:
        return options[0]

    aliases = {
        "連衣裙": "洋裝", "連身裙": "洋裝", "連身洋裝": "洋裝", "背心裙": "洋裝",
        "小洋裝": "短洋裝", "迷你洋裝": "短洋裝", "連身短洋裝": "短洋裝",
        "中長洋裝": "洋裝", "茶歇裙": "洋裝", "日常洋裝": "洋裝",
        "小禮服": "禮服", "晚宴禮服": "禮服", "舞台洋裝": "禮服",
        "連體褲": "連身褲", "連衣褲": "連身褲", "短連體褲": "短連身褲", "短連衣褲": "短連身褲",
        "長連體褲": "長連身褲", "長連衣褲": "長連身褲", "jumpsuit": "連身褲", "romper": "短連身褲",
        "半裙": "半身裙", "裙": "半身裙", "褲裙": "褲裙",
        "短裙套裝": "裙裝套裝", "百褶裙套裝": "裙裝套裝", "長裙套裝": "裙裝套裝",
        "連衣裙套裝": "裙裝套裝", "上衣長裙套裝": "裙裝套裝", "蓬裙套裝": "裙裝套裝",
        "短褲套裝": "褲裝套裝", "甜美褲裝套裝": "褲裝套裝",
        "運動服裝套裝": "運動套裝", "運動居家套裝": "運動套裝",
        "兩件式套裝": "上下身套裝", "三件式套裝": "上下身套裝",
        "休閒套裝": "上下身套裝", "甜美套裝": "上下身套裝", "休閒時尚套裝": "上下身套裝",
        "睡衣": "睡衣套裝", "性感睡衣": "睡衣套裝", "睡袍／罩衫": "睡袍",
        "居家長洋裝": "居家服", "衣服": options[0],
    }
    normalized = aliases.get(raw, raw)
    if normalized in options:
        return normalized

    # 對 AI 產生的自由文字做有限關鍵字歸併，仍只輸出白名單值。
    if main_category == "洋裝":
        if any(k in raw for k in ("禮服", "晚宴", "舞台")): return "禮服"
        if any(k in raw for k in ("短", "迷你")): return "短洋裝"
        if any(k in raw for k in ("長", "及踝", "拖地")): return "長洋裝"
        return "洋裝"
    if main_category == "連身褲":
        if any(k in raw.lower() for k in ("短", "romper", "playsuit")): return "短連身褲"
        if any(k in raw.lower() for k in ("長", "及踝", "寬褲", "jumpsuit")): return "長連身褲"
        return "連身褲"
    if main_category == "套裝":
        if "運動" in raw: return "運動套裝"
        if "居家" in raw: return "居家套裝"
        if "圍裙" in raw: return "圍裙套裝"
        if "褲裙" in raw: return "褲裙套裝"
        if "裙" in raw: return "裙裝套裝"
        if "褲" in raw: return "褲裝套裝"
        return "上下身套裝"
    if main_category == "下身":
        if "褲裙" in raw: return "褲裙"
        if "短裙" in raw: return "短裙"
        if "長裙" in raw: return "長裙"
        if "裙" in raw: return "半身裙"
        if "短褲" in raw: return "短褲"
        if "褲" in raw: return "褲子"
    return options[0]


def _wardrobe_tags_from_text(*parts, limit=8):
    blob = " ".join(str(p or "") for p in parts)
    tokens = [x for x in re.split(r"[\s,，、/／「」()（）]+", blob) if x]
    result = []
    for token in tokens:
        token = _clean_text_compact(token)
        if token and token not in result:
            result.append(token)
        if len(result) >= limit:
            break
    return result


def _clean_text_compact(value):
    return re.sub(r"\s+", " ", str(value or "")).strip()


def _today_outfit_reset_if_needed(state_data):
    today = _today_str_tpe()
    if state_data.get("current_outfit_date") != today:
        state_data["current_outfit_date"] = today
        state_data["current_outfit"] = None
    return state_data


def _get_current_outfit_state():
    state_data = load_state()
    state_data = _today_outfit_reset_if_needed(state_data)
    save_state(state_data)
    return state_data.get("current_outfit")


def _set_current_outfit_state(outfit_payload):
    state_data = load_state()
    state_data = _today_outfit_reset_if_needed(state_data)
    state_data["current_outfit"] = outfit_payload
    state_data["current_outfit_date"] = _today_str_tpe()
