def _get_pending_wardrobe_state():
    state_data = load_state()
    return state_data.get("photo_pending_wardrobe")


def _refresh_pending_wardrobe_from_current_db(pending_item):
    """photo_pending_wardrobe 可能是換圖前的舊快照；每次 /photo 前用目前 wardrobe DB 重新取一次。"""
    if not isinstance(pending_item, dict):
        return pending_item
    wid = str(pending_item.get("id") or "").strip().upper()
    if not wid:
        return pending_item
    current = _find_wardrobe_item(wid)
    if isinstance(current, dict):
        return current
    return pending_item


def _sync_pending_wardrobe_if_same_item(updated_item):
    """若目前已預選同一件衣服，換圖/修正後同步 pending，避免 /photo 繼續拿舊 URL。"""
    if not isinstance(updated_item, dict):
        return
    wid = str(updated_item.get("id") or "").strip().upper()
    if not wid:
        return
    state_data = load_state()
    pending = state_data.get("photo_pending_wardrobe")
    if isinstance(pending, dict) and str(pending.get("id") or "").strip().upper() == wid:
        state_data["photo_pending_wardrobe"] = updated_item
        save_state(state_data)


def _pending_wardrobe_has_usable_reference(item):
    """預選衣櫃必須真的有可用圖片；否則清掉，避免 /photo 被切到 photo_reference 但拿到 None。"""
    if not isinstance(item, dict):
        return False
    ref_path = str(item.get("reference_image_path") or "").strip()
    ref_url = str(item.get("local_url") or item.get("reference_item_url") or "").strip()
    if ref_path and os.path.exists(ref_path):
        return True
    if ref_url.startswith("http"):
        return True
    return False


def _extract_current_outfit_reference(outfit_state):
    """延續今日穿著時，優先回到最新衣櫃資料；若舊 Figure 10 已失效，退回純文字延續，避免 /photo 因舊 URL 404 而失敗。"""
    if not isinstance(outfit_state, dict):
        return None

    wardrobe_id = str(outfit_state.get("wardrobe_id") or "").strip().upper() or None
    if wardrobe_id:
        latest_item = _find_wardrobe_item(wardrobe_id)
        latest_ref_path, latest_ref_url = _wardrobe_reference_for_generation(latest_item) if latest_item else (None, None)
        if latest_ref_path or latest_ref_url:
            return {
                "reference_item_path": latest_ref_path or None,
                "reference_item_url": latest_ref_url or None,
                "wardrobe_id": wardrobe_id,
            }

    def _normalize_candidate(value):
        raw = str(value or "").strip()
        if not raw:
            return ""
        if raw.startswith("http"):
            if "/gallery/" in raw:
                candidate_local = _gallery_url_to_local_path(raw)
                return candidate_local if candidate_local and os.path.exists(candidate_local) else ""
            return raw
        return raw if os.path.exists(raw) else ""

    ref_path = _normalize_candidate(outfit_state.get("reference_item_path"))
    ref_url = str(outfit_state.get("reference_item_url") or "").strip()
    if not ref_path:
        fallback_candidate = _normalize_candidate(ref_url)
        if fallback_candidate:
            ref_path = fallback_candidate
        elif ref_url.startswith("http") and "/gallery/" in ref_url:
            # 舊 gallery URL 已經沒有對應本機檔案時，不再硬餵給 Seedream，避免 404。
            ref_url = ""

    if not ref_path and not ref_url and not wardrobe_id:
        return None
    return {
        "reference_item_path": ref_path or None,
        "reference_item_url": ref_url or None,
        "wardrobe_id": wardrobe_id,
    }


