def _photo_requests_outfit_change(raw_scene_text):
    text_value = str(raw_scene_text or "")
    patterns = [
        r"換成", r"換上", r"改穿", r"穿上", r"改成.*(?:衣|裙|褲|外套|睡衣|泳裝|內衣)",
        r"今天穿", r"想讓她穿", r"套用衣櫃", r"穿這件", r"穿那件"
    ]
    return any(re.search(pattern, text_value) for pattern in patterns)


def _build_outfit_state_from_context(context):
    if not context:
        return None
    wardrobe_id = context.get("wardrobe_id")
    source_mode = str(context.get("source_mode") or "").strip().lower()
    has_outfit_reference = bool(context.get("reference_item_path") or context.get("reference_item_url"))
    if wardrobe_id or (source_mode == "photo_reference" and has_outfit_reference):
        stored_reference_path = context.get("reference_item_path") or context.get("local_path")
        stored_reference_url = context.get("reference_item_url") or context.get("local_url") or context.get("image_url")
    else:
        # 非衣櫃／附件延續時，優先記住已存入 gallery 的穩定輸出，避免日後再抓 Discord/CDN 臨時網址。
        stored_reference_path = context.get("local_path") or context.get("reference_item_path")
        stored_reference_url = context.get("local_url") or context.get("reference_item_url") or context.get("image_url")
    return {
        "date": _today_str_tpe(),
        "description": _wardrobe_visual_summary_only(context.get("outfit_summary") or "自然日常穿搭") or _clean_text_compact(context.get("outfit_summary") or "自然日常穿搭"),
        "source": context.get("source_mode", "photo_scene"),
        "scene_summary": _clean_text_compact(context.get("scene_summary") or ""),
        "reference_item_path": stored_reference_path,
        "reference_item_url": stored_reference_url,
        "wardrobe_id": wardrobe_id,
        "updated_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
    }


def _log_wardrobe_usage_from_context(context, purpose="photo"):
    if not isinstance(context, dict):
        return
    wid = str(context.get("wardrobe_id") or "").strip().upper()
    if not wid:
        return
    item = _find_wardrobe_item(wid)
    if not item:
        item = {
            "id": wid,
            "name": context.get("outfit_summary") or wid,
            "main_category": "",
            "sub_category": "",
        }
    _log_wardrobe_usage(
        item,
        purpose=purpose,
        scene_text=context.get("scene_text") or context.get("scene_summary") or context.get("composition") or "",
        extra={
            "source_mode": context.get("source_mode"),
            "mood": _clean_text_compact(context.get("mood_summary") or context.get("mood") or ""),
        },
    )


def _wardrobe_item_short(item):
    return f"{item.get('id')}｜{item.get('name')}｜{item.get('main_category')}/{item.get('sub_category')}"


def _extract_category_prefixed_name(name_hint):
    """
    支援：
    /衣櫃 新增 內衣 米白色珍珠結構款套裝
    /衣櫃 新增 泳裝 黑色...
    第一個詞若是主分類，就當分類提示，不把它留在名稱裡。
    """
    raw = _clean_text_compact(name_hint)
    if not raw:
        return "", ""
    for cat in sorted(WARDROBE_MAIN_CATEGORIES, key=len, reverse=True):
        if raw == cat:
            return cat, raw
        if raw.startswith(cat + " "):
            return cat, raw[len(cat):].strip()
    return "", raw


def _wardrobe_item_generation_hint(item, include_scene_suggestion=False):
    """把衣櫃資料轉成 /photo 的硬提示，避免「套裝」被誤解成西裝/長袖套裝。

    include_scene_suggestion=True 僅供「衣櫃自由」選衣時使用；其餘流程只允許衣服的視覺資訊進 prompt，
    不讓衣櫃建議場景干擾大俠當次指定的場景。
    """
    if not isinstance(item, dict):
        return ""
    item_id = item.get("id", "")
    name = _clean_text_compact(item.get("name", ""))
    main = _clean_text_compact(item.get("main_category", ""))
    sub = _clean_text_compact(item.get("sub_category", ""))
    summary = _clean_text_compact(item.get("style_summary", ""))
    # 視覺摘要盡量保留材質 / 類型 / 顏色，不讓「適合某場景」在非衣櫃自由模式下進 prompt 干擾場景。
    visual_summary = re.sub(r"(?:，|。)?\s*適合[^。]*", "", summary).strip(" ，。") or summary
    tags = "、".join(item.get("tags") or [])
    hint = (
        f"Selected wardrobe item {item_id}: {name}. "
        f"Category: {main}/{sub}. Tags: {tags}. Visual summary: {visual_summary}. "
        "Image 10 is the exact visual reference and must dominate the text label. "
        "Preserve the actual garment type shown in Image 10; do not reinterpret the Chinese word '套裝' as a blazer, jacket, suit, formal set, dress suit, or long-sleeve outerwear. "
        "'套裝' here means a matching clothing set unless the image clearly shows a blazer/suit. "
    )
    if include_scene_suggestion:
        scene_suggestion = _clean_text_compact(
            item.get("recommended_scene") or item.get("suggested_scene") or item.get("scene_hint") or ""
        )
        if not scene_suggestion and summary != visual_summary:
            scene_suggestion = summary.replace(visual_summary, "").strip(" ，。")
        if scene_suggestion:
            hint += (
                "Wardrobe free-mode scene suitability hint (for clothing selection only, not for overriding Daxia's explicit scene): "
                f"{scene_suggestion}. "
            )
    else:
        hint += "Do not use this wardrobe metadata to override Daxia's explicitly requested scene, action, pose, or story context. "
    if main in {"內衣", "泳裝", "睡衣／居家服"} or any(k in (name + summary + tags) for k in ("內衣", "胸罩", "bra", "lingerie", "泳裝", "泳衣", "睡衣")):
        hint += (
            "This wardrobe category may be underwear/lingerie, swimwear, or sleepwear. "
            "If Image 10 shows a bra-and-bottom, lingerie set, swimwear, or sleepwear, keep that exact category and do not convert it into a jacket, blouse, blazer, long sleeves, or ordinary outerwear. "
            "Style it tastefully and safely in a fitting private or appropriate scene. "
        )
    return hint.strip()




def _extract_wardrobe_ids_from_text(text_value):
    """抓出 W003 / w003 這類衣櫃編號。"""
    return [m.group(0).upper() for m in re.finditer(r"\bW\d{3,4}\b", str(text_value or ""), flags=re.IGNORECASE)]


def _find_first_wardrobe_item_in_text(text_value):
    """文字有指定衣櫃編號時，必須回到衣櫃資料，不可只靠名稱腦補。"""
    for wid in _extract_wardrobe_ids_from_text(text_value):
        item = _find_wardrobe_item(wid)
        if item:
            return item
    return None


def _wardrobe_reference_for_generation(item):
    """回傳可餵給 Seedream 的衣櫃參考圖路徑/URL。找不到就回 None，避免望名自創。"""
    if not isinstance(item, dict):
        return None, None
    ref_path = str(item.get("reference_image_path") or "").strip()
    ref_url = str(item.get("local_url") or item.get("reference_item_url") or "").strip()
    if ref_path and os.path.exists(ref_path):
        return ref_path, ref_url or None
    if ref_url.startswith("http"):
        return ref_url, ref_url
    return None, ref_url or None


