# 📸 Seedream v4.5 /photo 統一照片工作台
# ==========================================
def _is_girlfriend_xiaoxia_channel(channel) -> bool:
    """女友小俠可互動頻道：私人伺服器內，除說故事小俠姊姊與公開服務頻道外皆可。"""
    if channel is None:
        return False
    if is_story_channel_or_thread(channel) or is_public_service_channel(channel):
        return False
    guild_id = getattr(getattr(channel, "guild", None), "id", None)
    if guild_id != PRIVATE_GUILD_ID:
        return False
    channel_name = str(getattr(channel, "name", "") or "")
    blocked_name_tokens = ("故事", "story", "小俠姊姊")
    if any(token in channel_name for token in blocked_name_tokens):
        return False
    return True


def _supported_photo_attachment(attachment) -> bool:
    content_type = (getattr(attachment, "content_type", "") or "").lower()
    filename = (getattr(attachment, "filename", "") or "").lower()
    return (
        content_type in {"image/png", "image/jpeg", "image/jpg", "image/webp"}
        or filename.endswith((".png", ".jpg", ".jpeg", ".webp"))
    )


async def _get_photo_reference_attachment(message):
    """回傳 (attachment, error_message)。先看本訊息，再看 reply 訊息。"""
    attachments = [a for a in list(getattr(message, "attachments", []) or []) if _supported_photo_attachment(a)]
    raw_attachments = list(getattr(message, "attachments", []) or [])
    if len(raw_attachments) > 1:
        return None, "大俠，這次先讓我一次只看一張衣服或一張飾品圖片，好嗎？\n你先選一張給我，我就幫你拍一張看看。"
    if len(raw_attachments) == 1 and not attachments:
        return None, "大俠，這個檔案我沒辦法當作參考圖耶。\n你給我一張 PNG、JPG 或 WebP 圖片就可以了。"
    if attachments:
        return attachments[0], None

    ref = getattr(message, "reference", None)
    if ref:
        ref_msg = getattr(ref, "resolved", None)
        if ref_msg is None and getattr(ref, "message_id", None):
            try:
                ref_msg = await message.channel.fetch_message(ref.message_id)
            except Exception as exc:
                print(f"⚠️ [PHOTO_REPLY_FETCH_FAILED] {type(exc).__name__}: {exc}")
                ref_msg = None
        if ref_msg:
            ref_raw = list(getattr(ref_msg, "attachments", []) or [])
            ref_images = [a for a in ref_raw if _supported_photo_attachment(a)]
            if len(ref_raw) > 1:
                return None, "大俠，被回覆的訊息裡有多張圖片；第一版 /photo 先一次只支援一張參考圖。"
            if len(ref_raw) == 1 and not ref_images:
                return None, "大俠，被回覆的附件不是我能使用的圖片格式。請給我 PNG、JPG 或 WebP。"
            if ref_images:
                return ref_images[0], None
    return None, None


async def _download_photo_reference_attachment(attachment):
    """
    Discord 附圖保底下載。
    不再優先用 attachment.read()；改用 attachment.url / proxy_url 下載，
    避免某些手機端或編輯附件情境下 read() 取不到內容或內部拋 NoneType path。
    """
    global PHOTO_USER_REF_DIR
    if not PHOTO_USER_REF_DIR:
        PHOTO_USER_REF_DIR = os.path.join(SEEDREAM_V45_REF_DIR, "user_refs")
    os.makedirs(PHOTO_USER_REF_DIR, exist_ok=True)
    if attachment is None:
        raise RuntimeError("PHOTO_REF_ATTACHMENT_NONE：沒有取得可下載的圖片附件。")

    filename_raw = str(getattr(attachment, "filename", "") or "")
    content_type = str(getattr(attachment, "content_type", "") or "").lower()
    ext = Path(filename_raw).suffix.lower() if filename_raw else ""
    if ext not in {".jpg", ".jpeg", ".png", ".webp"}:
        ext = ".png" if "png" in content_type else (".webp" if "webp" in content_type else ".jpg")

    filename = f"photo_ref_{datetime.now(TZ_TPE).strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:8]}{ext}"
    path = os.path.join(PHOTO_USER_REF_DIR, filename)

    url_candidates = [
        getattr(attachment, "url", None),
        getattr(attachment, "proxy_url", None),
    ]
    data = None
    last_error = None

    for url in [u for u in url_candidates if u]:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as resp:
                    if resp.status == 200:
                        data = await resp.read()
                        if data:
                            break
                    last_error = f"HTTP {resp.status} from {url}"
        except Exception as exc:
            last_error = f"{type(exc).__name__}: {exc}"

    if not data:
        # 最後才退回 attachment.read()
        try:
            data = await attachment.read()
        except Exception as exc:
            last_error = f"attachment.read failed: {type(exc).__name__}: {exc}"

    if not data:
        raise RuntimeError(f"PHOTO_REF_DOWNLOAD_EMPTY：圖片附件下載後沒有內容。last_error={last_error}")

    with open(path, "wb") as f:
        f.write(data)

    if not os.path.exists(path) or os.path.getsize(path) <= 0:
        raise RuntimeError(f"PHOTO_REF_SAVE_FAILED：圖片附件保存失敗 path={path}")

    print(f"✅ [PHOTO_REF_ATTACHMENT_SAVED] path={path} size={os.path.getsize(path)} filename={filename_raw} content_type={content_type}")
    return path


async def _download_url_to_output(image_url, prefix="wardrobe"):
    """把外部圖片 URL 下載到 OUTPUT_DIR，避免 save_to_vault 失敗時拿到 None path。"""
    if not image_url or not str(image_url).startswith("http"):
        return None, None
    ext = ".jpg"
    clean = str(image_url).split("?", 1)[0].split("#", 1)[0].lower()
    for candidate in (".png", ".jpg", ".jpeg", ".webp"):
        if clean.endswith(candidate):
            ext = candidate
            break
    filename = f"{prefix}_{datetime.now(TZ_TPE).strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:8]}{ext}"
    path = os.path.join(OUTPUT_DIR, filename)
    async with aiohttp.ClientSession() as session:
        async with session.get(image_url) as resp:
            if resp.status != 200:
                raise RuntimeError(f"下載圖片失敗 HTTP {resp.status}")
            data = await resp.read()
    if not data:
        raise RuntimeError("下載圖片後沒有內容。")
    with open(path, "wb") as f:
        f.write(data)
    return path, f"https://xiaoxia0320.zeabur.app/gallery/{filename}"


async def _seedream_download_remote_reference(url):
    if not url or not str(url).startswith("http"):
        raise RuntimeError(f"SEEDREAM_REMOTE_REFERENCE_INVALID_URL：{url}")
    raw_url = str(url)
    cleaned_url = raw_url.split("?", 1)[0]
    suffix = Path(cleaned_url).suffix.lower()
    if suffix not in {".png", ".jpg", ".jpeg", ".webp"}:
        suffix = ".png"
    digest = hashlib.md5(raw_url.encode("utf-8")).hexdigest()
    local_path = os.path.join(SEEDREAM_V45_REMOTE_CACHE_DIR, f"{digest}{suffix}")
    timeout = aiohttp.ClientTimeout(total=60)
    headers = {
        "User-Agent": "Mozilla/5.0 XiaoxiaBot/1.0",
        "Accept": "image/avif,image/webp,image/apng,image/*,*/*;q=0.8",
    }
    async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
        async with session.get(raw_url) as resp:
            if resp.status != 200:
                raise RuntimeError(f"SEEDREAM_REMOTE_REFERENCE_DOWNLOAD_FAILED：HTTP {resp.status} url={raw_url}")
            data = await resp.read()
    if not data:
        raise RuntimeError(f"SEEDREAM_REMOTE_REFERENCE_EMPTY：{raw_url}")
    with open(local_path, "wb") as f:
        f.write(data)
    return local_path


def _gallery_url_to_local_path(url):
    value = str(url or "").strip()
    if not value:
        return None
    # 目前 gallery route 對應 OUTPUT_DIR 內檔案。
    if "/gallery/" in value:
        filename = value.split("/gallery/", 1)[-1].split("?", 1)[0].split("#", 1)[0].strip()
        if filename:
            return os.path.join(OUTPUT_DIR, os.path.basename(filename))
    return None


def _wardrobe_local_reference_ok(item):
    ref = str((item or {}).get("reference_image_path") or "").strip()
    if ref and not ref.startswith("http") and os.path.exists(ref):
        return True
    local_url = str((item or {}).get("local_url") or "").strip()
    candidate = _gallery_url_to_local_path(local_url)
    return bool(candidate and os.path.exists(candidate))


def _wardrobe_reference_candidates(item):
    candidates = []
    for key in ("reference_image_path", "local_url", "reference_url", "source_attachment_url", "source_path"):
        value = str((item or {}).get(key) or "").strip()
        if value and value not in candidates:
            candidates.append(value)
    return candidates


async def _wardrobe_url_reachable(url):
    value = str(url or "").strip()
    if not value.startswith("http"):
        return False, "not_http"
    try:
        timeout = aiohttp.ClientTimeout(total=20)
        headers = {"User-Agent": "Mozilla/5.0 XiaoxiaBot/1.0"}
        async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
            async with session.get(value) as resp:
                if resp.status == 200:
                    # 不用整包讀完；讀一小段確認有資料即可。
                    chunk = await resp.content.read(64)
                    return bool(chunk), "ok" if chunk else "empty"
                return False, f"HTTP {resp.status}"
    except Exception as exc:
        return False, f"{type(exc).__name__}: {exc}"


async def _localize_wardrobe_item_image(item):
    """
    將衣櫃項目的圖片轉存到 Zeabur /data/output。
    成功回傳 (True, updated_item, reason)，失敗回傳 (False, original_item, reason)。
    """
    if not isinstance(item, dict):
        return False, item, "invalid item"

    updated = dict(item)
    wid = str(updated.get("id") or "").strip()

    # 1. reference_image_path 已是本地檔
    ref = str(updated.get("reference_image_path") or "").strip()
    if ref and not ref.startswith("http") and os.path.exists(ref):
        filename = os.path.basename(ref)
        updated["reference_image_path"] = ref
        updated["local_url"] = f"https://xiaoxia0320.zeabur.app/gallery/{filename}"
        updated["image_storage"] = "zeabur_local"
        return True, updated, "local file exists"

    # 2. local_url 是 Zeabur gallery 且本地檔存在
    local_path = _gallery_url_to_local_path(updated.get("local_url"))
    if local_path and os.path.exists(local_path):
        filename = os.path.basename(local_path)
        updated["reference_image_path"] = local_path
        updated["local_url"] = f"https://xiaoxia0320.zeabur.app/gallery/{filename}"
        updated["image_storage"] = "zeabur_local"
        return True, updated, "gallery file exists"

    # 3. 嘗試從任何 URL 候選下載轉存
    last_reason = "no usable image candidate"
    for candidate in _wardrobe_reference_candidates(updated):
        if not str(candidate).startswith("http"):
            continue
        local_filename = await save_to_vault(candidate)
        if local_filename:
            local_ref = os.path.join(OUTPUT_DIR, local_filename)
            updated["reference_image_path"] = local_ref
            updated["local_url"] = f"https://xiaoxia0320.zeabur.app/gallery/{local_filename}"
            updated["image_storage"] = "zeabur_localized_from_remote"
            updated["image_localized_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
            updated["updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
            return True, updated, f"downloaded from {candidate[:80]}"
        ok, reason = await _wardrobe_url_reachable(candidate)
        last_reason = reason

    return False, updated, last_reason


async def _handle_wardrobe_healthcheck(ctx):
    items = load_wardrobe()
    if not items:
        await ctx.send("衣櫃目前是空的，或 `xiaoxia_wardrobe.json` 格式不是 list。")
        return

    local_ok, remote_ok, broken, unknown = [], [], [], []
    status = await ctx.send(f"🩺 小俠正在幫衣櫃做圖片健檢，共 {len(items)} 件...")

    for item in items:
        wid = str(item.get("id") or "?")
        if _wardrobe_local_reference_ok(item):
            local_ok.append(wid)
            continue

        reachable = False
        last_reason = "no candidate"
        for candidate in _wardrobe_reference_candidates(item):
            if str(candidate).startswith("http"):
                ok, reason = await _wardrobe_url_reachable(candidate)
                last_reason = reason
                if ok:
                    reachable = True
                    break
        if reachable:
            remote_ok.append(wid)
        elif last_reason and ("HTTP 404" in last_reason or "404" in last_reason):
            broken.append(wid)
        else:
            unknown.append(f"{wid}({last_reason})")

    def _fmt(seq, maxn=25):
        if not seq:
            return "無"
        short = seq[:maxn]
        more = f" ...等 {len(seq)} 件" if len(seq) > maxn else ""
        return ", ".join(short) + more

    msg = (
        f"🩺 **衣櫃圖片健檢完成**\\n"
        f"✅ 已本地化可用：{len(local_ok)} 件\\n"
        f"🟡 遠端仍抓得到、可修復：{len(remote_ok)} 件\\n"
        f"❌ 遠端已失效/404：{len(broken)} 件\\n"
        f"⚠️ 其他不明狀態：{len(unknown)} 件\\n\\n"
        f"🟡 可自動修復：{_fmt(remote_ok)}\\n"
        f"❌ 需重補圖：{_fmt(broken)}"
    )
    await status.edit(content=msg[:1900])


async def _handle_wardrobe_repair_images(ctx):
    items = load_wardrobe()
    if not items:
        await ctx.send("衣櫃目前是空的，或 `xiaoxia_wardrobe.json` 格式不是 list。")
        return

    status = await ctx.send(f"🛠️ 小俠正在把衣櫃圖片轉存到 Zeabur，本次會盡量補救 {len(items)} 件...")
    repaired, already_ok, failed = [], [], []
    new_items = []

    for item in items:
        wid = str(item.get("id") or "?")
        was_local = _wardrobe_local_reference_ok(item)
        ok, updated, reason = await _localize_wardrobe_item_image(item)
        new_items.append(updated if ok else item)

        if ok and was_local:
            already_ok.append(wid)
        elif ok:
            repaired.append(wid)
        else:
            failed.append(f"{wid}({reason})")

    save_wardrobe(new_items)

    def _fmt(seq, maxn=25):
        if not seq:
            return "無"
        short = seq[:maxn]
        more = f" ...等 {len(seq)} 件" if len(seq) > maxn else ""
        return ", ".join(short) + more

    msg = (
        f"🛠️ **衣櫃圖片修復完成**\\n"
        f"✅ 原本就可用：{len(already_ok)} 件\\n"
        f"✅ 本次成功轉存：{len(repaired)} 件\\n"
        f"❌ 仍需重補圖：{len(failed)} 件\\n\\n"
        f"成功轉存：{_fmt(repaired)}\\n"
        f"需重補圖：{_fmt(failed, maxn=18)}"
    )
    await status.edit(content=msg[:1900])


async def _seedream_upload_single_file(path):
    if not path:
        raise RuntimeError("SEEDREAM_UPLOAD_PATH_NONE：要上傳給 Seedream 的圖片路徑是 None。")
    upload_path = str(path)
    if upload_path.startswith("http"):
        upload_path = await _seedream_download_remote_reference(upload_path)
    elif not os.path.exists(upload_path):
        raise RuntimeError(f"SEEDREAM_UPLOAD_PATH_MISSING：找不到要上傳給 Seedream 的圖片：{path}")
    fal_client = _get_fal_client()
    return await asyncio.to_thread(fal_client.upload_file, upload_path)


def _v1527_extract_explicit_time_bucket(text):
    """從 prompt 中抽取明確時間上下文；若有明示時間，優先服從，不再被其他關鍵字誤導。"""
    raw = str(text or "")
    patterns = [
        r"Current time context:\s*[^\n]*?(\d{1,2}):(\d{2})",
        r"Current Taiwan local time is\s*(\d{1,2}):(\d{2})",
        r"Taiwan time[,，]\s*(\d{1,2}):(\d{2})",
    ]
    for pattern in patterns:
        m = re.search(pattern, raw, flags=re.I)
        if not m:
            continue
        hh = int(m.group(1))
        mm = int(m.group(2))
        probe_dt = datetime.now(TZ_TPE).replace(hour=hh, minute=mm, second=0, microsecond=0)
        bucket, label = _autonomy_time_bucket(probe_dt)
        return bucket, label, f"{hh:02d}:{mm:02d}"
    return None, "", ""


def _v1527_scene_hard_requirements(text):
    """Extract only decisive scene/time locks and place them at the top of the Seedream prompt."""
    raw = str(text or "")
    low = raw.lower()
    rules = []

    # v1.5.57_R7: if prompt already contains an explicit time context, obey it first.
    explicit_bucket, _explicit_label, _explicit_time = _v1527_extract_explicit_time_bucket(raw)
    if explicit_bucket in {"evening", "night"}:
        rules += [
            "The scene MUST visibly take place at night/evening.",
            "Daylight, sunshine, bright daytime windows, morning light, and afternoon light are incorrect.",
            "If windows or outdoor areas are visible, show darkness, night reflections, or night city lights.",
            "Use believable indoor evening illumination such as warm cafe lamps or ceiling lights."
        ]
    elif explicit_bucket in {"morning", "noon", "afternoon"}:
        rules.append("The scene MUST visibly match the requested daytime period; do not turn it into a night scene.")
    else:
        night_terms = ("晚間", "晚上", "夜裡", "夜晚", "深夜", "night", "evening", "22:", "21:", "20:", "19:")
        day_terms = ("白天", "上午", "早上", "午後", "下午", "daytime", "morning", "afternoon")
        if any(x in low for x in night_terms):
            rules += [
                "The scene MUST visibly take place at night/evening.",
                "Daylight, sunshine, bright daytime windows, morning light, and afternoon light are incorrect.",
                "If windows or outdoor areas are visible, show darkness, night reflections, or night city lights.",
                "Use believable indoor evening illumination such as warm cafe lamps or ceiling lights."
            ]
        elif any(x in low for x in day_terms):
            rules.append("The scene MUST visibly match the requested daytime period; do not turn it into a night scene.")

    if any(x in low for x in ("咖啡廳", "咖啡店", "cafe", "coffee shop")):
        rules.append("The location MUST clearly read as a cafe/coffee shop, with recognizable tables, drinks, seating, and cafe interior details.")
    if any(x in low for x in ("姊妹淘", "姐妹淘", "閨蜜", "闺蜜", "female friends", "girls' night", "girls night")):
        rules.append("The requested female-friends social interaction MUST be visibly present; do not replace it with a solo reading, walking, or park scene.")
    if any(x in low for x in ("聊天", "交談", "談話", "chatting", "conversation")):
        rules.append("Show a natural active conversation through seating, gaze, expressions, and gestures; do not depict an unrelated solitary activity.")
    return "\n".join(f"- {x}" for x in rules)


def _v1527_strip_prompt_conflicts(prompt):
    """Remove historical duplicated/contradictory people blocks without deleting the requested scene."""
    text = str(prompt or "").strip()

    # When an older builder already wrapped the request in a Figure Role Map, keep only its TEXT REQUEST payload.
    if text.startswith("FIGURE ROLE MAP") and "TEXT REQUEST" in text:
        text = text.split("TEXT REQUEST", 1)[1]
        text = re.sub(r"^\s*[—–-]*\s*this controls[^\n]*\n*", "", text, flags=re.I)

    # Remove exact large policy blocks added by v1.5.26/R2; v1.5.27 adds one concise policy later.
    for block_name in ("XIAOXIA_UNIFIED_PEOPLE_POLICY", "XIAOXIA_SUPPORTING_WOMEN_IDENTITY_ISOLATION"):
        block = globals().get(block_name)
        if block:
            text = text.replace(str(block).strip(), "")

    # Remove repeated one-line people summaries and legacy universal solo instructions.
    text = re.sub(r"(?mi)^People rule:.*$", "", text)
    text = re.sub(r"(?mi)^Female social scene guard:.*$", "", text)
    conflict_patterns = [
        r"Create a new solo photorealistic lifestyle image of Xiaoxia\.?",
        r"Only Xiaoxia appears\.?\s*No man, no second person, no external hands, no viewer body parts, no reflections or shadows of another person\.?",
        r"Strictly solo Xiaoxia only\.?",
        r"Strictly only Xiaoxia appears in the image\.?",
        r"The frame must contain exactly one human figure:\s*Xiaoxia\.?",
        r"No other people of any gender\.?",
        r"No second person\.?",
    ]
    for pat in conflict_patterns:
        text = re.sub(pat, "", text, flags=re.I)

    # Remove duplicated headings left empty after block removal.
    text = re.sub(r"(?mi)^UNIFIED PEOPLE AND INTERACTION POLICY[^\n]*\n?", "", text)
    text = re.sub(r"(?mi)^SUPPORTING WOMEN IDENTITY ISOLATION[^\n]*\n?", "", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text


def _is_face_closeup_request_text(text):
    raw = str(text or "")
    low = raw.lower()
    zh_keys = [
        "臉部特寫", "脸部特写", "臉部美容特寫", "脸部美容特写", "近拍臉部", "近拍脸部",
        "臉部近拍", "脸部近拍", "臉部大特寫", "脸部大特写", "鎖骨以上", "锁骨以上",
        "肩膀以上", "肩膀以上", "頭肩特寫", "头肩特写", "頭像照", "头像照",
    ]
    en_keys = [
        "face close-up", "face closeup", "beauty close-up", "beauty closeup", "close-up beauty portrait",
        "closeup beauty portrait", "headshot", "head shot", "collarbone-up", "shoulders-up", "shoulder-up",
        "chest-up only", "face fills most of the frame", "face beauty close-up",
    ]
    return any(k in raw for k in zh_keys) or any(k in low for k in en_keys)


def _seedream_face_closeup_prompt(custom_prompt, has_reference=False, current_outfit=None, visual_checklist=None):
    """v1.5.49: special prompt for face close-ups only. Deliberately avoids body-shape global traits."""
    raw_prompt = str(custom_prompt or "")
    camera_override = ""
    marker = "[[CAMERA_OVERRIDE]]"
    if marker in raw_prompt:
        raw_prompt, camera_override = raw_prompt.rsplit(marker, 1)
        camera_override = _clean_text_compact(camera_override)[:420]
    cleaned_request = _v1527_strip_prompt_conflicts(raw_prompt)
    hard = _v1527_scene_hard_requirements(cleaned_request or custom_prompt)
    people = _v1527_concise_people_policy(visual_checklist)

    sections = [
        "FIGURE ROLE MAP — obey these roles strictly.",
        (
            "Figures 1-9 are identity-only references for Xiaoxia. Apply their face identity, hairstyle identity, and overall recognizable adult East Asian appearance only to Xiaoxia. "
            "Do not copy their pose, outfit, background, lighting, or composition."
        ),
        "FACE CLOSE-UP MODE — this request is a beauty close-up, not a body shot.",
        (
            "Mandatory framing: collarbone-up or shoulders-up only. Xiaoxia's face must occupy most of the frame. "
            "Show only the visible neckline / shoulder area of the outfit if naturally present. "
            "Do not show waist, hips, thighs, knees, legs, or a full-body composition."
        ),
        (
            "Beauty focus: emphasize Xiaoxia's eyes, skin texture, lips, hair, expression, and subtle facial contour. "
            "Use flattering natural light and let the background remain secondary and softly unobtrusive."
        ),
    ]
    if hard:
        sections.append("HARD SCENE REQUIREMENTS — failure on any item is incorrect:\n" + hard)
    sections.append("PEOPLE POLICY:\n" + people)

    if has_reference:
        sections.append(
            "FIGURE 10 WARDROBE ROLE:\n"
            "- Figure 10 controls the visible clothing neckline / shoulder details and visible fashion accessories only.\n"
            "- Preserve its color, material, pattern, and key visible details if they appear inside the close-up crop.\n"
            "- Figure 10 must not control scene, pose, background, camera angle, or composition."
        )
    elif current_outfit:
        sections.append(
            "VISIBLE OUTFIT CONTINUITY:\n"
            f"- {str(current_outfit).strip()}\n"
            "- Only preserve the visible neckline / shoulder styling that can naturally appear within a face close-up crop."
        )
    else:
        sections.append("OUTFIT ROLE:\n- No Figure 10 is supplied; keep only simple, natural visible neckline styling appropriate to the scene.")

    sections.append("TEXT REQUEST — highest authority for scene, time, action, pose, and composition:\n" + cleaned_request)
    sections.append(
        "QUALITY:\n"
        "- Photorealistic beauty portrait, natural anatomy and hands, especially around the face and neckline.\n"
        "- This is a face-focused image, not a fashion full-body image.\n"
        "- Do not zoom out to show torso, waist, hips, or legs just to satisfy styling continuity."
    )
    final = "\n\n".join(s for s in sections if str(s).strip()).strip()
    if camera_override:
        final += "\n\nCAMERA OVERRIDE — this framing is mandatory:\n" + camera_override
    print(
        f"🧭 [FACE_CLOSEUP_PROMPT_STATS_V1549] total_chars={len(final)} "
        f"request_chars={len(cleaned_request)} hard_chars={len(hard)} people_chars={len(people)}"
    )
    return final

def _v1527_concise_people_policy(checklist=None):
    c = checklist if isinstance(checklist, dict) else {}
    policy = str(c.get("people_policy") or "")
    if c.get("strict_solo_required") or policy == "private_strict_solo":
        return (
            "- Private/explicit-solo scene: Xiaoxia is the only human figure.\n"
            "- Never show Daxia/viewer body parts, another person, reflection, shadow, or partial figure."
        )
    if c.get("female_interaction_ok") or policy == "autonomy_female_interaction_ok":
        return (
            "- Xiaoxia is the unmistakable visual protagonist, with the most refined facial beauty and elegant styling. Supporting people remain attractive, natural, and role-appropriate, while Xiaoxia remains the primary visual focus.\n"
            "- Show 1-3 female friends naturally interacting with Xiaoxia when requested; they remain secondary.\n"
            "- Figures 1-9 define Xiaoxia only. Supporting women must have clearly different faces, hairstyles, outfits, and natural body builds; no clones or twins.\n"
            "- Men may exist only as incidental public background and must not interact with Xiaoxia in any way.\n"
            "- Never visualize Daxia/viewer or external viewer body parts."
        )
    if c.get("allow_background_bystanders") or policy in {"autonomy_public_background_ok", "public_background_bystanders_allowed"}:
        return (
            "- Xiaoxia is the unmistakable visual protagonist, with the most refined facial beauty and elegant styling. Supporting people remain attractive, natural, and role-appropriate, while Xiaoxia remains the primary visual focus.\n"
            "- Public background people may appear for realism. Men must remain incidental and completely non-interacting with Xiaoxia.\n"
            "- No companion/date framing and never visualize Daxia/viewer body parts."
        )
    return (
        "- Xiaoxia is the unmistakable main character and only primary subject.\n"
        "- Do not add a companion. No male interaction. Never visualize Daxia/viewer body parts."
    )


def _seedream_photo_prompt(custom_prompt, has_reference=False, current_outfit=None, visual_checklist=None, semantic_contract_locked=False):
    """Seedream photo prompt. v1.8.11: preserve Title + Scene verbatim; add only short technical reference rules."""
    if semantic_contract_locked:
        contract = str(custom_prompt or "").strip()
        c = visual_checklist if isinstance(visual_checklist, dict) else {}
        if c.get("strict_solo_required") or str(c.get("people_policy") or "") == "private_strict_solo":
            people_line = "People: only Xiaoxia is visible; never show Daxia/viewer or any external body part."
        elif c.get("female_interaction_ok"):
            people_line = "People: Xiaoxia is primary; Scene-specified female companions may interact as secondary characters; men may only be distant non-interacting background; never show Daxia/viewer."
        elif c.get("allow_background_bystanders"):
            people_line = "People: Xiaoxia is primary; Scene-specified background people may appear only as secondary non-interacting figures; no male interaction; never show Daxia/viewer."
        else:
            people_line = "People: Xiaoxia is the only primary subject; no companion, no male interaction, and never show Daxia/viewer."
        sections = [
            "REFERENCES: Figures 1-9 preserve Xiaoxia identity/body only; do not copy their pose, outfit, background or composition.",
            "Keep Xiaoxia's established adult East Asian face and tall, slim, narrow-waisted, naturally full-busted hourglass body identity with natural anatomy.",
            people_line,
        ]
        if has_reference:
            sections.append("FIGURE 10: exact clothing / visible fashion-accessory authority only; preserve its actual design and do not let it change Scene, action, pose, camera or background.")
        elif current_outfit:
            sections.append("OUTFIT CONTINUITY: " + str(current_outfit).strip())
        sections.append("TITLE + SCENE — use both for generation understanding; Scene facts are mandatory and must not be summarized, replaced or simplified:\n" + contract)
        sections.append("QUALITY: photorealistic, natural anatomy/hands, believable lighting; do not substitute a generic portrait or different activity/location.")
        return "\n\n".join(s for s in sections if str(s).strip()).strip()

    if _is_face_closeup_request_text(custom_prompt):
        return _seedream_face_closeup_prompt(
            custom_prompt,
            has_reference=has_reference,
            current_outfit=current_outfit,
            visual_checklist=visual_checklist,
        )

    raw_prompt = str(custom_prompt or "")
    camera_override = ""
    marker = "[[CAMERA_OVERRIDE]]"
    if marker in raw_prompt:
        raw_prompt, camera_override = raw_prompt.rsplit(marker, 1)
        camera_override = _clean_text_compact(camera_override)[:420]
    cleaned_request = _v1527_strip_prompt_conflicts(raw_prompt)
    hard = _v1527_scene_hard_requirements(cleaned_request or custom_prompt)
    people = _v1527_concise_people_policy(visual_checklist)

    sections = [
        "FIGURE ROLE MAP — obey these roles strictly.",
        (
            "Figures 1-9 are identity-only references for Xiaoxia. Apply their face/body identity only to Xiaoxia. "
            "Do not copy their pose, outfit, background, lighting, or composition."
        ),
    ]
    if hard:
        sections.append("HARD SCENE REQUIREMENTS — failure on any item is incorrect:\n" + hard)
    sections.append("PEOPLE POLICY:\n" + people)

    if has_reference:
        sections.append(
            "FIGURE 10 WARDROBE ROLE:\n"
            "- Figure 10 controls clothing and visible fashion accessories only.\n"
            "- Preserve its category, color, silhouette, cut, length, material, pattern, and key details.\n"
            "- Figure 10 must not control scene, pose, background, camera angle, or composition."
        )
    else:
        sections.append("OUTFIT ROLE:\n- No Figure 10 is supplied; use the explicit outfit request or a simple scene-appropriate outfit.")

    if current_outfit:
        sections.append(f"OUTFIT CONTINUITY:\n- {str(current_outfit).strip()}\n- Styling continuity must not override the requested scene or action.")

    sections.append("TEXT REQUEST — highest authority for scene, time, action, pose, and composition:\n" + cleaned_request)
    sections.append(
        "QUALITY:\n"
        "- Photorealistic lifestyle photography, natural anatomy and hands, clear activity context, believable lighting.\n"
        "- Do not substitute a generic park, reading, walking, or solo portrait when a specific location or social action is requested."
    )
    final = "\n\n".join(s for s in sections if str(s).strip()).strip()
    if camera_override:
        # Keep this at the absolute end. Seedream v4.5 tends to ignore camera intent buried in long prompts.
        final += "\n\nCAMERA OVERRIDE — this framing is mandatory:\n" + camera_override
    print(
        f"🧭 [PROMPT_STATS_V1527] total_chars={len(final)} "
        f"request_chars={len(cleaned_request)} hard_chars={len(hard)} people_chars={len(people)}"
    )
    return final


def _build_diary_lightweight_request(diary_visual, result=None, forced_scene="", autonomy_topic=None, season_rule=""):
    """Build a compact request from structured diary fields instead of forwarding the director's full verbose prompt."""
    visual = diary_visual if isinstance(diary_visual, dict) else {}
    result = result if isinstance(result, dict) else {}
    state = visual.get("__anchor_state") if isinstance(visual.get("__anchor_state"), dict) else {}
    lines = []
    if forced_scene:
        lines.append(f"Mandatory scene: {forced_scene}")
    authoritative_scene = _clean_text_compact(visual.get("authoritative_scene") or state.get("authoritative_scene") or "")
    if authoritative_scene:
        lines.append(f"Authoritative scene: {authoritative_scene[:900]}")
    if autonomy_topic:
        lines.append(f"Source layer: today autonomy activity rewash, new diary image only; activity: {autonomy_topic.get('activity_title') or ''}")
        if autonomy_topic.get("composition"):
            lines.append(f"Activity context: {_clean_text_compact(autonomy_topic.get('composition'))[:300]}")
        lines.append("Do not use, imitate, or reference the previously generated autonomy photo; create a different moment, pose, framing, and lighting.")
    composition = _clean_text_compact(visual.get("composition") or result.get("scenario_tw") or result.get("scenario") or "")
    if composition:
        lines.append(f"Diary moment: {composition[:700]}")
    for label, key in [
        ("Main activity", "activity"),
        ("Primary action", "primary_action"),
        ("Setting", "setting_anchor"),
        ("Visible environment", "environment_trace"),
        ("Time", "time_anchor"),
        ("Lighting", "lighting_mood"),
        ("Outfit intent", "outfit_intent"),
        ("Camera framing", "camera_framing"),
    ]:
        val = _clean_text_compact(state.get(key) or "")
        if val:
            lines.append(f"{label}: {val[:260]}")
    mood = _clean_text_compact(visual.get("mood") or "")
    if mood:
        lines.append(f"Mood: {mood[:220]}")
    if season_rule:
        compact_season = _clean_text_compact(season_rule)
        lines.append(f"Season/outfit boundary: {compact_season[:380]}")
    lines.append("One place, one time, one main activity. Show visible environmental clues and a natural task-based action.")
    return "\n".join(_dedupe_keep_order([x for x in lines if x])).strip()


def _seedream_diary_prompt(custom_prompt, has_reference=False, current_outfit=None, visual_checklist=None):
    """v1.8.19: scene-only exchange-diary prompt builder shared by Pure / Hybrid / More / Dice / Repair lineage."""
    cleaned_request = _v1527_strip_prompt_conflicts(custom_prompt)
    hard = _v1527_scene_hard_requirements(cleaned_request or custom_prompt)
    people_line = _seedream_people_policy_line(visual_checklist)
    bystanders_allowed = bool((visual_checklist or {}).get("allow_background_bystanders"))
    sections = [
        "DIARY FIGURE ROLE MAP — obey these roles strictly.",
        (
            "Figures 1-9 are identity-only references for Xiaoxia. Apply their face and body identity only to Xiaoxia. "
            "Do not copy their pose, outfit, room, background, lighting, props, or composition."
        ),
        _v1540_compact_identity_line(),
        "DIARY SCENE CONTRACT:\n"
        "- Treat the DIARY TEXT REQUEST below as the single authoritative story source for this image.\n"
        "- Do not pull in other diary paragraphs, old memories, bedroom defaults, optional ideas, continuation notes, reroll notes, or generic glamour substitutions.\n"
        "- Keep one place, one time, one main activity, and one coherent lived-in moment.",
    ]
    if hard:
        sections.append("DIARY HARD SCENE REQUIREMENTS — every item must be visible:\n" + hard)
    people_lines = [
        f"- {people_line}",
        "- Daxia is an invisible camera viewpoint only; never show a visible viewer body part, reflection, shadow, or partial person.",
        "- Keep Xiaoxia's anatomy, hands, fingers, posture, and movement natural.",
    ]
    if bystanders_allowed:
        people_lines.append("- If the scene is public, incidental background people may remain only as distant secondary realism; they must never become a companion or interact with Xiaoxia.")
    sections.append("DIARY PEOPLE POLICY:\n" + "\n".join(people_lines))
    if has_reference:
        sections.append(
            "FIGURE 10 WARDROBE ROLE:\n"
            "- Figure 10 controls Xiaoxia's clothing and visible fashion accessories only.\n"
            "- Preserve its garment category, color, silhouette, cut, length, material, pattern, and key details.\n"
            "- Figure 10 must not change the diary scene, action, pose, camera angle, or background."
        )
    else:
        sections.append(
            "OUTFIT ROLE:\n"
            "- No Figure 10 is supplied. Choose one natural, season-appropriate outfit fitting this diary moment.\n"
            "- Do not import clothing from yesterday, another photo, or old memory."
        )
    if current_outfit:
        sections.append(
            "OUTFIT NOTE:\n- " + str(current_outfit).strip() +
            "\n- This note controls styling only and must not override the diary scene or action."
        )
    sections.append(
        "DIARY TEXT REQUEST — highest authority for today's location, time, activity, mood, pose, props, and composition:\n"
        + cleaned_request
    )
    sections.append(
        "DIARY QUALITY:\n"
        "- Create a new photorealistic, candid, lived-in daily-life moment, not a generic glamour portrait or fashion advertisement.\n"
        "- The requested location and activity must be immediately understandable from visible environmental clues and natural action.\n"
        "- Preserve only one time and one place; never combine sequential events into one image.\n"
        "- Do not replace the requested moment with a generic sofa pose, bedroom pose, reading pose, park scene, or camera-facing portrait unless the text explicitly asks for it."
    )
    final = "\n\n".join(x for x in sections if str(x).strip()).strip()
    stats = {
        "total_chars": len(final),
        "request_chars": len(cleaned_request),
        "hard_chars": len(hard),
        "solo_phrase_count": len(re.findall(r"\\bsolo\\b|only visible human|only human figure", final, flags=re.I)),
        "conflict_phrase_count": len(re.findall(r"female friends may|supporting women|background bystanders", final, flags=re.I)),
        "bystanders_allowed": bystanders_allowed,
        "people_policy": str((visual_checklist or {}).get("people_policy") or ""),
    }
    print("🧭 [DIARY_PROMPT_STATS_V1819] " + " ".join(f"{k}={v}" for k, v in stats.items()))
    return final, stats

async def generate_seedream_v45_photo(custom_prompt, reference_image_path=None, enable_safety_checker=None, current_outfit=None, trace_context=None, input_image_urls_override=None):
    """Seedream v4.5 統一 /photo：無參考圖=情境照；有參考圖=換裝/飾品融合。"""
    if enable_safety_checker is None:
        enable_safety_checker = SEEDREAM_ENABLE_SAFETY_CHECKER
    fal_client = _get_fal_client()
    model_id = _context_seedream_model_id(trace_context=trace_context)
    model_label = _seedream_model_label_from_id(model_id)
    trace_kind = str((trace_context or {}).get("kind") or "photo").strip().lower() if isinstance(trace_context, dict) else "photo"
    if trace_kind == "diary":
        final_prompt, diary_prompt_stats = _seedream_diary_prompt(
            custom_prompt,
            has_reference=bool(reference_image_path),
            current_outfit=current_outfit,
            visual_checklist=(trace_context or {}).get("visual_checklist") if isinstance(trace_context, dict) else None,
        )
        print("✅ [PROMPT_ENGINE_ACTIVE] v1.5.42_R2 diary prompt + shared compact identity")
    else:
        final_prompt = _seedream_photo_prompt(
            custom_prompt,
            has_reference=bool(reference_image_path),
            current_outfit=current_outfit,
            visual_checklist=(trace_context or {}).get("visual_checklist") if isinstance(trace_context, dict) else None,
            semantic_contract_locked=bool((trace_context or {}).get("semantic_contract_locked")) if isinstance(trace_context, dict) else False,
        )
        diary_prompt_stats = None
        print("✅ [PROMPT_ENGINE_ACTIVE] v1.5.30 conflict-free photo prompt builder")
    if isinstance(trace_context, dict) and trace_context.get("v5_background_role_handoff"):
        final_prompt = _apply_v5_background_role_handoff_prompt(
            final_prompt,
            has_reference=bool(reference_image_path),
            reference_allure_unlock=bool(trace_context.get("cosplay_reference_allure_unlock")),
        )
    if isinstance(trace_context, dict):
        trace_context["seedream_model_id"] = model_id
        trace_context["seedream_model_label"] = model_label
        trace_context["seedream_prompt_exact"] = final_prompt
        if bool(trace_context.get("semantic_contract_locked")) and trace_kind != "diary":
            trace_context["prompt_engine_version"] = "v1.8.16"
            trace_context["prompt_engine_marker"] = "TITLE_SCENE_SEMANTIC_CONTRACT_V1816"
        else:
            trace_context["prompt_engine_version"] = "v1.5.42_R2"
            trace_context["prompt_engine_marker"] = "DIARY_SHARED_IDENTITY_V1542_R2" if trace_kind == "diary" else "HARD_SCENE_REQUIREMENTS_V1527"
        if diary_prompt_stats is not None:
            trace_context["diary_prompt_stats"] = diary_prompt_stats
            trace_context["diary_seedream_prompt_exact"] = final_prompt
    _trace_stage(trace_context, "seedream_photo_final_prompt", prompt=final_prompt, data={"has_reference": bool(reference_image_path), "current_outfit": current_outfit, "model": model_id, "model_label": model_label, "image_size": SEEDREAM_V45_IMAGE_SIZE, "enable_safety_checker": bool(enable_safety_checker)})

    override_urls = list(input_image_urls_override or ((trace_context or {}).get("seedream_input_images_override") if isinstance(trace_context, dict) else []) or [])
    override_roles = (trace_context or {}).get("seedream_input_image_roles_override") if isinstance(trace_context, dict) else None
    selected_figures = (trace_context or {}).get("seedream_identity_selected_figures") if isinstance(trace_context, dict) else None

    async def _build_image_urls(force_reference_refresh=False):
        if override_urls:
            return override_urls[:10]
        urls = await _seedream_upload_reference_images(force_refresh=force_reference_refresh, selected_figure_indexes=selected_figures)
        if reference_image_path:
            # 不直接把外部 URL 丟給 Seedream；先由本機下載後再上傳到 fal，避免 Discord CDN / 外部圖床過期。
            urls.append(await _seedream_upload_single_file(reference_image_path))
        return urls[-10:] if len(urls) > 10 else urls

    def _subscribe(image_urls):
        def on_queue_update(update):
            try:
                if isinstance(update, fal_client.InProgress):
                    for log in update.logs:
                        print(f"📸 [SEEDREAM_PHOTO_QUEUE] {log.get('message', '')}")
            except Exception:
                pass
        return fal_client.subscribe(
            model_id,
            arguments=_seedream_request_args(model_id, final_prompt, image_urls, enable_safety_checker=enable_safety_checker),
            with_logs=True,
            on_queue_update=on_queue_update,
        )

    image_urls = await _build_image_urls(force_reference_refresh=False)
    if isinstance(trace_context, dict):
        trace_context["seedream_input_images"] = list(image_urls)
        if isinstance(override_roles, list) and override_roles:
            trace_context["seedream_input_image_roles"] = override_roles
        else:
            trace_context["seedream_input_image_roles"] = [
                {"figure": idx + 1, "role": "xiaoxia_identity" if idx < 9 else "wardrobe_reference", "url": url}
                for idx, url in enumerate(image_urls)
            ]
        trace_context["seedream_request_payload"] = {
            "model": model_id,
            "model_label": model_label,
            "prompt": final_prompt,
            "image_urls": list(image_urls),
            "image_size": SEEDREAM_V45_IMAGE_SIZE,
            "num_images": 1,
            "max_images": 1,
            "enable_safety_checker": bool(enable_safety_checker),
        }
    _trace_stage(trace_context, "seedream_input_images", data={"count": len(image_urls), "images": list(image_urls), "figure_10_present": bool(reference_image_path)})
    try:
        result = await asyncio.to_thread(_subscribe, image_urls)
    except Exception as exc:
        if _is_fal_file_download_error(exc):
            print(f"⚠️ [SEEDREAM_PHOTO_FILE_DOWNLOAD_ERROR] refresh reference uploads and retry once: {exc}")
            image_urls = await _build_image_urls(force_reference_refresh=True)
            try:
                result = await asyncio.to_thread(_subscribe, image_urls)
            except Exception as retry_exc:
                if _is_fal_file_download_error(retry_exc) and reference_image_path and str(reference_image_path).startswith("http"):
                    raise RuntimeError(
                        "SEEDREAM_PHOTO_REFERENCE_URL_EXPIRED：Seedream 無法下載其中一張輸入圖。"
                        "我已重新上傳小俠 1-9 號人物底稿並重試一次，仍失敗。"
                        "最可能是衣櫃圖片或附件的外部 URL 已過期或無法被 fal.ai 讀取。"
                        "請用 `/衣櫃 換圖 Wxxx` 或 `/衣櫃 換圖去人 Wxxx` 把該衣櫃項目換成新的可用圖片後再試。"
                    ) from retry_exc
                raise
        else:
            raise

    images = result.get("images") if isinstance(result, dict) else None
    if not images:
        return f"{model_label} 沒有回傳 /photo 圖片：{result}"
    first = images[0]
    if isinstance(first, dict) and first.get("url"):
        return first["url"]
    return f"{model_label} /photo 圖片欄位格式異常：{result}"

def _repair_context_mode(context):
    return str((context or {}).get("source_mode") or (context or {}).get("type") or "photo").strip().lower()


def _repair_clean_line(value, limit=260):
    text = _clean_text_compact(str(value or ""))
    return text[:limit] if limit and len(text) > limit else text


def _repair_collect_history(context, latest_request="", limit=4):
    items = []
    existing = (context or {}).get("repair_history")
    if isinstance(existing, list):
        items.extend([_repair_clean_line(x, 220) for x in existing if str(x or "").strip()])
    prior = _repair_clean_line((context or {}).get("repair_request"), 220)
    if prior:
        items.append(prior)
    latest = _repair_clean_line(latest_request, 220)
    if latest:
        items.append(latest)
    deduped = []
    seen = set()
    for item in items:
        key = item.strip().lower()
        if not item or key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped[-max(1, int(limit or 4)):]




REPAIR_AESTHETIC_GUARD = """
REVISION AESTHETIC GUARD:
- Treat comparative appearance requests as controlled refinements, not maximum-strength transformations.
- All requested body and beauty adjustments must remain subtle, natural, elegant, and anatomically plausible unless Daxia explicitly asks for an extreme change.
- Preserve Xiaoxia's established overall proportions, facial identity, posture, clothing structure, fabric behavior, and scene continuity.
- When changing bust, waist, body slimness, leg length, or skin appearance, adjust only the requested characteristic and keep surrounding anatomy naturally integrated.
- Avoid exaggerated anatomy, balloon-like volume, extreme waist compression, unnaturally stretched limbs, plastic skin, or clothing that no longer fits or behaves realistically.
""".strip()


def _rewrite_repair_request_for_aesthetics(custom_prompt):
    """v1.5.30：將常見外貌微調語句改寫為小幅、自然且可追蹤的修圖指令。"""
    original = _repair_clean_line(custom_prompt, 500)
    if not original:
        return {
            "original": "",
            "rewritten": "",
            "matched_adjustments": [],
            "aesthetic_rewrite_applied": False,
        }

    rewritten = original
    matched = []
    substitutions = [
        (r"(?:上圍|胸部|胸型|胸圍)(?:再|更)?(?:雄偉|豐滿|豐盈|飽滿|大)(?:一點|一些|些|點)?",
         "subtly and naturally enhance her bust volume by a modest amount while preserving realistic anatomy, balanced bust-to-waist proportions, natural clothing fit, fabric drape, posture, and overall elegance",
         "bust_subtle_enhancement"),
        (r"(?:上圍|胸部|胸型|胸圍)(?:再|更)?(?:小|縮小|收斂)(?:一點|一些|些|點)?",
         "subtly reduce her bust volume by a modest amount while preserving realistic anatomy, balanced proportions, natural clothing fit, posture, and overall elegance",
         "bust_subtle_reduction"),
        (r"(?:身材|身形|體態)(?:再|更)?(?:苗條|纖細|瘦)(?:一點|一些|些|點)?|(?:再|更)(?:苗條|纖細|瘦)(?:一點|一些|些|點)?",
         "slightly refine and slim her silhouette while preserving a healthy feminine figure, realistic anatomy, natural curves, and the original pose",
         "silhouette_subtle_slimming"),
        (r"(?:腰|腰身|腰線)(?:再|更)?(?:細|纖細|收窄)(?:一點|一些|些|點)?",
         "slightly refine her waistline while preserving realistic torso anatomy, natural ribcage and hip proportions, and a balanced elegant silhouette",
         "waist_subtle_refinement"),
        (r"(?:小腿|腿部|雙腿|腿)(?:再|更)?(?:長|修長)(?:一點|一些|些|點)?",
         "slightly lengthen the requested leg proportions while preserving realistic joints, balanced thigh-to-lower-leg ratios, the original pose, and natural body scale",
         "legs_subtle_lengthening"),
        (r"(?:皮膚|膚色|肌膚)(?:再|更)?(?:白皙|白|亮|透亮)(?:一點|一些|些|點)?|(?:再|更)(?:白皙|白|亮)(?:一點|一些|些|點)?",
         "slightly brighten her fair luminous skin while preserving natural skin texture, realistic tonal variation, and the original lighting direction",
         "skin_subtle_brightening"),
        (r"(?:皮膚|肌膚)(?:再|更)?(?:水嫩|水潤|細緻)(?:一點|一些|些|點)?|(?:再|更)?(?:水嫩|水潤)(?:一點|一些|些|點)?",
         "subtly improve healthy skin hydration and refinement while preserving natural pores, texture, and realistic lighting, avoiding a plastic or over-smoothed look",
         "skin_subtle_refinement"),
    ]
    for pattern, replacement, tag in substitutions:
        rewritten_new, count = re.subn(pattern, replacement, rewritten, flags=re.IGNORECASE)
        if count:
            rewritten = rewritten_new
            if tag not in matched:
                matched.append(tag)
    rewritten = re.sub(r"\s+", " ", rewritten).strip()
    if matched:
        rewritten += (
            ". This is a controlled refinement only: make the smallest clearly visible change needed, "
            "keep the result natural and elegant, and preserve every unrequested element of Image 10."
        )
    return {
        "original": original,
        "rewritten": rewritten,
        "matched_adjustments": matched,
        "aesthetic_rewrite_applied": bool(matched),
    }




async def generate_seedream_v45_repair(original_image_path, repair_request, enable_safety_checker=False, trace_context=None, source_context=None):
    """Seedream v4.5 修正版：Image 10 是要修的原圖，只改指定瑕疵，保留構圖與氛圍。"""
    if not original_image_path:
        raise RuntimeError("REPAIR_IMAGE_PATH_NONE：沒有可修正的原圖。")
    fal_client = _get_fal_client()
    model_id = _context_seedream_model_id(context=source_context, trace_context=trace_context)
    model_label = _seedream_model_label_from_id(model_id)
    if isinstance(trace_context, dict):
        trace_context["seedream_model_id"] = model_id
        trace_context["seedream_model_label"] = model_label
    image_urls = await _seedream_upload_reference_images()
    image_urls.append(await _seedream_upload_single_file(original_image_path))
    image_urls = image_urls[-10:] if len(image_urls) > 10 else image_urls
    interpreted_request = _rewrite_repair_request_for_aesthetics(repair_request)
    if isinstance(trace_context, dict):
        trace_context["user_revision_text"] = interpreted_request.get("original")
        trace_context["rewritten_revision_prompt"] = interpreted_request.get("rewritten")
        trace_context["revision_aesthetic_rewrite_applied"] = bool(interpreted_request.get("aesthetic_rewrite_applied"))
        trace_context["revision_aesthetic_matches"] = list(interpreted_request.get("matched_adjustments") or [])
        trace_context["revision_aesthetic_guard"] = REPAIR_AESTHETIC_GUARD
    _trace_stage(
        trace_context,
        "repair_aesthetic_interpreter",
        prompt=interpreted_request.get("rewritten"),
        data={
            "user_revision_text": interpreted_request.get("original"),
            "rewritten_revision_prompt": interpreted_request.get("rewritten"),
            "matched_adjustments": interpreted_request.get("matched_adjustments"),
            "aesthetic_rewrite_applied": interpreted_request.get("aesthetic_rewrite_applied"),
        },
    )
    final_prompt = _seedream_repair_prompt(repair_request, context=source_context, interpreted_request=interpreted_request)
    _trace_stage(trace_context, "seedream_repair_final_prompt", prompt=final_prompt, data={"original_image_path": original_image_path, "model": model_id, "model_label": model_label, "image_size": SEEDREAM_V45_IMAGE_SIZE})

    def _subscribe():
        def on_queue_update(update):
            try:
                if isinstance(update, fal_client.InProgress):
                    for log in update.logs:
                        print(f"🩹 [SEEDREAM_REPAIR_QUEUE] {log.get('message', '')}")
            except Exception:
                pass
        return fal_client.subscribe(
            model_id,
            arguments=_seedream_request_args(model_id, final_prompt, image_urls, enable_safety_checker=enable_safety_checker),
            with_logs=True,
            on_queue_update=on_queue_update,
        )

    result = await asyncio.to_thread(_subscribe)
    images = result.get("images") if isinstance(result, dict) else None
    if not images:
        return f"{model_label} 修圖沒有回傳圖片：{result}"
    first = images[0]
    if isinstance(first, dict) and first.get("url"):
        return first["url"]
    return f"{model_label} 修圖圖片欄位格式異常：{result}"


async def _ensure_context_local_path(context):
    local_path = str(context.get("local_path") or "").strip()
    if local_path and os.path.exists(local_path):
        return local_path
    local_filename = str(context.get("local_filename") or "").strip()
    if local_filename:
        candidate = os.path.join(OUTPUT_DIR, os.path.basename(local_filename))
        if os.path.exists(candidate):
            return candidate
    image_url = context.get("local_url") or context.get("image_url")
    if not image_url:
        raise RuntimeError("這張照片沒有可修正的圖片 URL。")
    downloaded_path, _downloaded_url = await _download_url_to_output(image_url, prefix="repair_src")
    return downloaded_path


async def _repair_photo_context(context, repair_request, msg=None):
    repair_history = _repair_collect_history(context, repair_request, limit=4)
    trace_context = {
        "kind": "repair",
        "action": "photo_repair",
        "source_mode": context.get("source_mode") or context.get("type") or "photo",
        "original_trace_id": context.get("trace_id"),
        "repair_request": str(repair_request or "").strip(),
        "repair_history": repair_history,
        "allow_background_bystanders": bool(context.get("allow_background_bystanders") or context.get("diary_allow_background_bystanders")),
        "original_context": context,
    }
    _trace_stage(trace_context, "repair_context_input", data=context, prompt=repair_request)
    source_path = await _ensure_context_local_path(context)
    if msg:
        await msg.edit(content="🩹 小俠正在保留原本構圖與氛圍，只修大俠指定的地方…")
    generated_image_url = await generate_seedream_v45_repair(source_path, repair_request, enable_safety_checker=False, trace_context=trace_context, source_context=context)
    if not generated_image_url or not str(generated_image_url).startswith("http"):
        raise RuntimeError(f"修圖失敗：{generated_image_url}")

    local_filename = await save_to_vault(generated_image_url)
    local_url = f"https://xiaoxia0320.zeabur.app/gallery/{local_filename}" if local_filename else generated_image_url
    local_path = os.path.join(OUTPUT_DIR, local_filename) if local_filename else None

    repaired = dict(context)
    repaired.update({
        "id": str(uuid.uuid4()),
        "image_url": generated_image_url,
        "local_url": local_url,
        "local_filename": local_filename,
        "local_path": local_path,
        "repair_request": str(repair_request or "").strip(),
        "repair_history": repair_history,
        "trace_id": trace_context.get("trace_id"),
        "repaired_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "composition": context.get("composition") or context.get("scene_summary") or "修正版照片",
        "mood_summary": context.get("mood_summary") or context.get("mood") or "保留原本氛圍的修正版",
        "message": context.get("message") or "大俠，這張我保留原本氣氛，悄悄整理得更好了。",
        "source_mode": context.get("source_mode", context.get("type", "photo_repair")),
        "type": context.get("type", context.get("source_mode", "photo")),
        "final_level": context.get("final_level") or context.get("generation_level") or "REPAIR",
        "generation_level": context.get("final_level") or context.get("generation_level") or "REPAIR",
        "allow_background_bystanders": bool(context.get("allow_background_bystanders") or context.get("diary_allow_background_bystanders")),
        "diary_allow_background_bystanders": bool(context.get("diary_allow_background_bystanders")),
    })
    repaired = _inherit_autonomy_presentation(context, repaired)
    trace_context["result_url"] = local_url
    _write_generation_trace("repair", trace_context)
    return repaired



async def _summarize_scene_for_photo(raw_scene_text, source_mode, has_reference, current_outfit=None, keep_today_outfit=False, pending_wardrobe_name="", wardrobe_scene_hint_allowed=False):
    """v1.8.05：/photo planner 改為 scene-only。先由 Gemini 產出唯一可視化場景，再交給 Seedream。"""
    recent_context = "\n".join(daily_chat_logs[-20:])
    default_scene = "溫馨自然的家中居家場景" if has_reference else "依照最近對話中的當下生活情境"
    prompt = f"""
你是小俠照片導演。請根據大俠的 /photo 指令與最近對話，整理出唯一一段「可直接拿去生圖」的場景短文。

【/photo 模式】：{source_mode}
【大俠指定內容】：{raw_scene_text or '無'}
【最近 20 則對話】：
{recent_context or '無'}
【今日既有衣著連貫】：{current_outfit or '無'}
【是否優先延續今日衣著】：{'是' if keep_today_outfit else '否'}
【若有預選衣櫃項目】：{pending_wardrobe_name or '無'}
【衣櫃建議場景是否可介入】：{'是（僅衣櫃自由選衣階段）' if wardrobe_scene_hint_allowed else '否'}

請只回傳 JSON：
{{
  "authoritative_scene": "唯一場景短文。這一段必須直接寫出場景、光線/氛圍、服裝、主要動作、表情或視線，以及 1~2 個必要環境錨點。希望成圖一定出現的東西，都要直接寫在這段裡。",
  "scene_summary": "給 Discord 顯示的短場景摘要，40字內",
  "outfit_summary": "服裝重點摘要，30字內",
  "action_summary": "主要動作摘要，30字內",
  "mood_summary": "氛圍與光線摘要，30字內",
  "camera_framing": "half_body 或 full_body",
  "photo_prompt": "與 authoritative_scene 同義；給內部流程沿用即可"
}}

規則：
0. 優先順序：A. 大俠本次明確要求（場景／動作／姿勢／服裝／身形修正） > B. 衣服視覺參考圖 > C. 今日衣著連貫 > D. 最近 20 則對話靈感。
1. authoritative_scene 要寫成自然短文，不要清單腔，不要英文 prompt 腔。
2. 若大俠指定內容不為無，authoritative_scene 必須以指定內容為主，而且畫面中必須清楚可見；不可被衣櫃資料、最近對話或模型自行腦補覆蓋。
3. 若沒有衣櫃/附圖，而場景中仍需要衣服，請在 authoritative_scene 內主動把衣服寫具體一點（顏色、版型、材質或風格至少其一），不要只寫「自然穿搭」。
4. 若「是否優先延續今日衣著」為是，且沒有新的衣服參考圖，authoritative_scene 與 outfit_summary 都必須延續今日既有衣著，不要自行換裝。
5. 若有參考圖，請在 authoritative_scene 的服裝描述中明確反映它，但不要讓衣服覆蓋大俠指定場景。
6. 衣櫃建議場景只有在「衣櫃自由」挑衣時可作為選衣輔助；即使允許參考，也不得覆蓋大俠明確指定的場景。
7. 不可加入大俠沒有要求的第二人物。即使是男友視角，也不可畫出大俠本人、任何男性、任何男性肢體，或鏡頭前景中的手、肩、背影；只能用構圖暗示 POV。
8. 小俠的動作、手勢、四肢、關節、手指都必須自然正常，不可出現不合理姿勢。
9. Xiaoxia Aesthetic 要作為預設美感底盤：{XIAOXIA_SCENE_WRITER_BODY_BASELINE_ZH} 若大俠有明確修正詞，必須以大俠修正為優先。
"""
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=prompt,
            config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.2),
        )
        data = _extract_json_object(resp.text)
        if isinstance(data, dict):
            authoritative = _clean_text_compact(data.get("authoritative_scene") or data.get("photo_prompt") or data.get("scene_summary") or "")
            if authoritative:
                data["authoritative_scene"] = authoritative
                data["photo_prompt"] = authoritative
                data["scene_summary"] = _clean_text_compact(data.get("scene_summary") or authoritative)[:80]
                return data
    except Exception as exc:
        print(f"⚠️ [PHOTO_SCENE_SUMMARY_FAILED] {type(exc).__name__}: {exc}")

    fallback_scene = _clean_text_compact(raw_scene_text.strip() if raw_scene_text else default_scene)
    fallback_outfit = current_outfit if (keep_today_outfit and current_outfit) else "符合場景的自然完整日常穿搭"
    authoritative = _clean_text_compact(
        f"小俠在{fallback_scene}，穿著{fallback_outfit}，自然地停留在這個生活片刻裡，光線溫暖柔和，畫面保留清楚的場景線索與真實生活感。"
    )
    return {
        "authoritative_scene": authoritative,
        "scene_summary": fallback_scene,
        "outfit_summary": fallback_outfit,
        "action_summary": "小俠自然地待在場景中，像被大俠拍下的生活片刻",
        "mood_summary": "溫暖自然光、生活感、真實照片氛圍",
        "camera_framing": "half_body",
        "photo_prompt": authoritative,
    }



