def _photobook_more_image_url(context):
    return str((context or {}).get("local_url") or (context or {}).get("image_url") or "").strip()


async def _analyze_photobook_more_scene(image_url):
    """Vision 只輸出可供程式篩選的現場條件，不寫 prompt、不替大俠選鏡頭。"""
    fallback = {
        "current_framing": "unknown", "current_viewpoint": "unknown", "current_angle": "unknown",
        "left_access": True, "right_access": True, "side_access": True,
        "rear_access": False, "full_body_possible": True,
        "low_angle_access": True, "high_angle_access": True,
        "background_depth": True, "foreground_available": False,
        "window_present": False, "reflection_surface": False,
        "hand_near_face": False, "confidence": 0.0,
    }
    data, mime = await _download_image_bytes_for_vision(image_url)
    if not data:
        return fallback
    prompt = """
你是寫真攝影的現場勘景器。只根據附圖判斷「攝影師還能從哪些方向與景別拍攝」，不要提出美感建議、不要寫生圖提示詞。
請回傳 JSON，欄位不可增減：
{
  "current_framing": "closeup|bust|half|three_quarter|full|wide|unknown",
  "current_viewpoint": "front|left45|right45|side|rear|rear45|reflection|unknown",
  "current_angle": "high|eye|low|unknown",
  "left_access": true,
  "right_access": true,
  "side_access": true,
  "rear_access": true,
  "full_body_possible": true,
  "low_angle_access": true,
  "high_angle_access": true,
  "background_depth": true,
  "foreground_available": true,
  "window_present": true,
  "reflection_surface": true,
  "hand_near_face": true,
  "confidence": 0.0
}
判斷原則：
- 若人物背部貼牆、貼窗、緊靠大型家具或後方明顯無攝影空間，rear_access=false。
- full_body_possible 表示依現場與姿勢，退遠後合理拍到完整全身，不是指目前照片是否已拍全身。
- reflection_surface 只在可用的鏡子、玻璃反射面清楚存在時為 true。
- 不確定時採保守判斷，尤其 rear_access 與 reflection_surface。
只回傳 JSON。
"""
    try:
        response = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=[types.Part.from_bytes(data=data, mime_type=mime), prompt],
            config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.0),
        )
        raw = _safe_json_from_text(response.text, {})
        if not isinstance(raw, dict):
            return fallback
        result = dict(fallback)
        for key in result:
            if key in raw:
                result[key] = raw[key]
        for key in (
            "left_access", "right_access", "side_access", "rear_access", "full_body_possible",
            "low_angle_access", "high_angle_access", "background_depth", "foreground_available",
            "window_present", "reflection_surface", "hand_near_face",
        ):
            result[key] = bool(result.get(key))
        try:
            result["confidence"] = max(0.0, min(1.0, float(result.get("confidence") or 0.0)))
        except Exception:
            result["confidence"] = 0.0
        return result
    except Exception as exc:
        print(f"⚠️ [PHOTOBOOK_MORE_VISION_FAILED] {type(exc).__name__}: {exc}")
        return fallback


def _photobook_more_requirement_ok(scene, requirement):
    return bool(scene.get(requirement))


def _select_photobook_more_options(scene, context):
    """硬排除不可拍鏡頭，再排除與目前主構圖幾乎相同的項目。"""
    scene = scene if isinstance(scene, dict) else {}
    current_axis = (
        str(scene.get("current_framing") or "unknown"),
        str(scene.get("current_viewpoint") or "unknown"),
        str(scene.get("current_angle") or "unknown"),
    )
    used = set()
    user_id = (context or {}).get("request_user_id")
    session = _photobook_session_for_user(user_id, auto_close_stale=False) if user_id else None
    if isinstance(session, dict):
        used = {str(x) for x in (session.get("used_more_shot_ids") or [])}

    eligible = []
    for shot in PHOTOBOOK_SHOT_LIBRARY:
        if any(not _photobook_more_requirement_ok(scene, req) for req in shot.get("needs", ())):
            continue
        axis = tuple(shot.get("axis") or ())
        if len(axis) >= 3 and axis[:3] == current_axis:
            continue
        item = dict(shot)
        item["used"] = item.get("id") in used
        item["difference"] = sum(1 for a, b in zip(axis[:3], current_axis) if a != b and b != "unknown")
        eligible.append(item)

    if len(eligible) < 5:
        safe_ids = {"face_closeup", "bust_portrait", "half_body_side", "high_angle_half", "low_angle_half", "telephoto", "negative_space"}
        for shot in PHOTOBOOK_SHOT_LIBRARY:
            if shot["id"] in safe_ids and not any(x["id"] == shot["id"] for x in eligible):
                item = dict(shot)
                item["used"] = item.get("id") in used
                item["difference"] = 1
                eligible.append(item)

    eligible.sort(key=lambda x: (bool(x.get("used")), -int(x.get("difference") or 0), x.get("name", "")))
    return eligible[:20]


def _format_photobook_more_options(options):
    rows = ["📷 **目前可用的 More 拍攝手法**", ""]
    for idx, item in enumerate(options, start=1):
        rows.append(f"**{idx}.** {item.get('name')}")
    rows.extend(["", f"請直接輸入 **1～{len(options)}**。", "輸入 **0**，由系統從本次可用鏡頭中挑選。"])
    return "\n".join(rows)


async def _prepare_photobook_more_choices(interaction, context):
    image_url = _photobook_more_image_url(context)
    if not image_url:
        await interaction.followup.send("⚠️ 找不到這張照片，無法分析可用鏡頭。", ephemeral=True)
        return
    scene = await _analyze_photobook_more_scene(image_url)
    context = dict(context or {})
    context["request_user_id"] = interaction.user.id
    options = _select_photobook_more_options(scene, context)
    if not options:
        await interaction.followup.send("⚠️ 目前沒有找到適合且差異足夠的 More 鏡頭。", ephemeral=True)
        return
    pending_photobook_more_choices[interaction.user.id] = {
        "channel_id": interaction.channel_id,
        "base_message_id": getattr(interaction.message, "id", None),
        "context": context,
        "scene": scene,
        "options": options,
        "created_at": _photobook_now(),
        "created_ts": datetime.now(TZ_TPE).timestamp(),
    }
    await interaction.followup.send(_format_photobook_more_options(options))


def _consume_pending_photobook_more_choice(message):
    pending = pending_photobook_more_choices.get(message.author.id)
    if not isinstance(pending, dict):
        return None
    if int(pending.get("channel_id") or 0) != int(getattr(message.channel, "id", 0) or 0):
        return None
    raw = str(message.content or "").strip()
    if not re.fullmatch(r"\d+", raw):
        return None
    try:
        if datetime.now(TZ_TPE).timestamp() - float(pending.get("created_ts") or 0) > 900:
            pending_photobook_more_choices.pop(message.author.id, None)
            return {"error": "⏳ More 鏡頭清單已超過 15 分鐘，請回到照片重新按 More。"}
    except Exception:
        pass
    options = list(pending.get("options") or [])
    choice = int(raw)
    if choice == 0:
        unused = [x for x in options if not x.get("used")]
        pool = unused or options
        selected = random.choice(pool) if pool else None
    elif 1 <= choice <= len(options):
        selected = options[choice - 1]
    else:
        return {"error": f"⚠️ 請輸入 0～{len(options)}。"}
    if not selected:
        return {"error": "⚠️ 目前沒有可用的 More 鏡頭。"}
    pending_photobook_more_choices.pop(message.author.id, None)
    return {"pending": pending, "selected": selected, "choice": choice}


async def _review_photobook_more_result(image_url, shot):
    """Camera Vision：純工程驗收，不帶小俠人格，也不向小俠暴露 Edit/Generate 流程。"""
    fallback = {
        "passed": None,
        "score": 0.0,
        "actual": "無法判定",
        "reason": "驗收暫時無法完成",
    }
    data, mime = await _download_image_bytes_for_vision(str(image_url or ""))
    if not data:
        return fallback
    target = str((shot or {}).get("name") or "指定鏡頭")
    recipe = str((shot or {}).get("prompt") or "")
    prompt = f"""
你是 Camera Vision，一個沒有情感、沒有人格的攝影構圖品管器。
只驗收附圖是否符合指定鏡頭，不評論人物美貌，不角色扮演，不安慰，不提供生圖建議。

指定拍法：{target}
明確構圖要求：{recipe}

只回傳 JSON，欄位不可增減：
{{
  "passed": true,
  "score": 0.0,
  "actual": "實際景別與角度，15字內",
  "reason": "符合或失敗原因，30字內"
}}

score 為 0.0～1.0 的符合程度。
判斷必須嚴格：
- 要求臉部特寫，若未收在鎖骨以上或肩膀以上，或仍出現腰部以下、腿部、明顯胸腰身材構圖、或接近全身，passed=false。
- 要求胸像／半身，若人物仍接近全身，passed=false。
- 要求全身，若頭或腳被裁掉，passed=false。
- 要求背後、側面、俯拍或仰拍，若視點沒有清楚改變，passed=false。
只回傳 JSON。
"""
    try:
        resp = await gemini_client.aio.models.generate_content(
            model="gemini-2.5-flash",
            contents=[types.Part.from_bytes(data=data, mime_type=mime), types.Part.from_text(text=prompt)],
            config=types.GenerateContentConfig(response_mime_type="application/json", temperature=0.0),
        )
        obj = _extract_json_object(getattr(resp, "text", "") or "") or {}
        passed = obj.get("passed")
        if not isinstance(passed, bool):
            passed = None
        try:
            score = max(0.0, min(1.0, float(obj.get("score") or 0.0)))
        except Exception:
            score = 0.0
        return {
            "passed": passed,
            "score": score,
            "actual": _clean_text_compact(obj.get("actual") or "無法判定")[:40],
            "reason": _clean_text_compact(obj.get("reason") or "")[:80],
        }
    except Exception as exc:
        print(f"⚠️ [PHOTOBOOK_CAMERA_GATE_FAILED] {type(exc).__name__}: {exc}")
        return fallback


def _photobook_more_candidate_image(context):
    return str(
        (context or {}).get("local_path")
        or (context or {}).get("local_url")
        or (context or {}).get("image_url")
        or ""
    ).strip()


async def _generate_photobook_more_edit_candidate(base_context, shot, status=None):
    """第一階段：以目前照片為 Figure 1，走 Seedream Edit；只改攝影手法。"""
    context = dict(base_context or {})
    fal_client = _get_fal_client()
    model_id = SEEDREAM_V45_MODEL_ID
    base_image = _photobook_more_candidate_image(context)
    if not base_image:
        raise RuntimeError("PHOTOBOOK_MORE_EDIT_NO_BASE_IMAGE：找不到 More 的基準照片。")

    base_url = await _seedream_upload_single_file(base_image)
    identity_urls = list(await _seedream_upload_reference_images())
    wardrobe_ref = context.get("reference_item_path") or context.get("reference_item_url")
    image_urls = [base_url]
    if wardrobe_ref:
        image_urls.extend(identity_urls[:8])
        image_urls.append(await _seedream_upload_single_file(wardrobe_ref))
        role_note = (
            "Figure 1 is the photograph to edit. Figures 2-9 are identity-only references of Xiaoxia. "
            "Figure 10 is the outfit reference."
        )
    else:
        image_urls.extend(identity_urls[:9])
        role_note = (
            "Figure 1 is the photograph to edit. Figures 2-10 are identity-only references of Xiaoxia."
        )

    camera_recipe = str((shot or {}).get("prompt") or "Use a clearly different camera composition.").strip()
    shot_title = context.get("shot_title") or context.get("title") or context.get("album_title") or "這一張寫真"
    content_scene = context.get("photobook_content_scene") or context.get("scene_summary") or ""
    more_scene = _compose_photobook_scene(content_scene, camera_recipe)
    semantic_contract = _compose_title_scene_render_prompt("photobook", shot_title, more_scene)
    if str((shot or {}).get("id") or "") == "face_closeup":
        final_prompt = (
            f"{role_note}\n{semantic_contract}\n"
            "Figure 1 is the current execution state. Keep the same content scene, identity, outfit, location and lighting; change camera only. "
            "FACE BEAUTY CLOSE-UP ONLY: collarbone-up or shoulders-up; face fills most of frame; "
            "do not show waist, hips, thighs, knees, legs, or full body."
        )
    else:
        final_prompt = (
            f"{role_note}\n{semantic_contract}\n"
            "Figure 1 is the current execution state. Keep the same content scene, identity, outfit, location and lighting; change camera treatment only."
        )
    print(f"🧪 [PHOTOBOOK_MORE_EDIT_QUEUE] shot={shot.get('id')} inputs={len(image_urls)}")

    def _subscribe():
        def on_queue_update(update):
            try:
                if isinstance(update, fal_client.InProgress):
                    for log in update.logs:
                        print(f"🌱 [PHOTOBOOK_MORE_EDIT] {log.get('message', '')}")
            except Exception:
                pass
        return fal_client.subscribe(
            model_id,
            arguments=_seedream_request_args(
                model_id,
                final_prompt,
                image_urls,
                enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            ),
            with_logs=True,
            on_queue_update=on_queue_update,
        )

    result = await asyncio.to_thread(_subscribe)
    images = result.get("images") if isinstance(result, dict) else None
    if not images or not isinstance(images[0], dict) or not images[0].get("url"):
        raise RuntimeError(f"PHOTOBOOK_MORE_EDIT_NO_IMAGE：{result}")
    generated_url = images[0]["url"]
    local_filename = await save_to_vault(generated_url)
    local_url = f"https://xiaoxia0320.zeabur.app/gallery/{local_filename}" if local_filename else generated_url
    local_path = os.path.join(OUTPUT_DIR, local_filename) if local_filename else None
    candidate = dict(context)
    candidate.update({
        "image_url": generated_url,
        "local_url": local_url,
        "local_filename": local_filename,
        "local_path": local_path,
        "created_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "seedream_model_id": model_id,
        "seedream_model_label": _seedream_model_label_from_id(model_id),
        "more_engine": "edit",
        "more_shot_id": shot.get("id"),
        "more_shot_name": shot.get("name"),
        "photobook_camera_scene": camera_recipe,
        "authoritative_scene": more_scene,
        "root_prompt_base": semantic_contract,
        "prompt_base": semantic_contract,
    })
    return candidate


async def _generate_photobook_more_generate_candidate(base_context, shot, status=None):
    """第二階段回退：Camera Gate 不通過時才重新 Generate 一次。"""
    context = dict(base_context or {})
    context.pop("__trace_context", None)
    context["trace_action"] = "photobook_more_generate_fallback"
    context["more_shot_id"] = shot.get("id")
    context["more_shot_name"] = shot.get("name")
    camera_recipe = str((shot or {}).get("prompt") or "Use a clearly different camera composition.").strip()
    context["camera_override"] = camera_recipe
    shot_title = context.get("shot_title") or context.get("title") or context.get("album_title") or "這一張寫真"
    content_scene = context.get("photobook_content_scene") or context.get("scene_summary") or ""
    more_scene = _compose_photobook_scene(content_scene, camera_recipe)
    root_prompt = _compose_title_scene_render_prompt("photobook", shot_title, more_scene)
    context["photobook_camera_scene"] = camera_recipe
    context["authoritative_scene"] = more_scene
    context["root_prompt_base"] = root_prompt
    context["prompt_base"] = root_prompt
    if str((shot or {}).get("id") or "") == "face_closeup":
        context["prompt_base"] += (
            "\nTECHNICAL CAMERA LOCK: FACE BEAUTY CLOSE-UP ONLY. Keep the image collarbone-up or shoulders-up only. "
            "Her face fills most of the frame. Do not show waist, hips, thighs, knees, legs, or a full-body composition."
        )
    generated = await _generate_photo_from_context(context, msg=status)
    generated["more_engine"] = "generate_fallback"
    generated["more_shot_id"] = shot.get("id")
    generated["more_shot_name"] = shot.get("name")
    return generated


def _photobook_more_candidate_score(candidate):
    gate = (candidate or {}).get("camera_gate") or {}
    try:
        return float(gate.get("score") or 0.0)
    except Exception:
        return 0.0


async def _generate_photobook_more_choice(message, request):
    pending = request.get("pending") or {}
    shot = request.get("selected") or {}
    base_context = dict(pending.get("context") or {})
    base_context.pop("__trace_context", None)
    base_context["trace_action"] = "photobook_more_dual_vision"
    base_context["more_shot_id"] = shot.get("id")
    base_context["more_shot_name"] = shot.get("name")
    base_context["user_input"] = f"More camera choice: {shot.get('name')}"
    status = await message.channel.send(f"📷 正在使用「{shot.get('name')}」拍攝 More…")

    edit_candidate = None
    generate_candidate = None
    try:
        # 1) 一律先試 Edit。
        edit_candidate = await _generate_photobook_more_edit_candidate(base_context, shot, status=status)
        edit_url = edit_candidate.get("local_url") or edit_candidate.get("image_url")
        edit_gate = await _review_photobook_more_result(edit_url, shot)
        edit_candidate["camera_gate"] = edit_gate
        print(
            f"🧪 [PHOTOBOOK_CAMERA_GATE] engine=edit passed={edit_gate.get('passed')} "
            f"score={edit_gate.get('score')} actual={edit_gate.get('actual')}"
        )

        # 2) Edit 未通過才回退 Generate；每個 More 最多只多試一次。
        if edit_gate.get("passed") is not True:
            try:
                await status.edit(content=f"📷 「{shot.get('name')}」第一次取景未通過，正在自動換一種生成方式重拍…")
            except Exception:
                pass
            generate_candidate = await _generate_photobook_more_generate_candidate(base_context, shot, status=status)
            generate_url = generate_candidate.get("local_url") or generate_candidate.get("image_url")
            generate_gate = await _review_photobook_more_result(generate_url, shot)
            generate_candidate["camera_gate"] = generate_gate
            print(
                f"🧪 [PHOTOBOOK_CAMERA_GATE] engine=generate passed={generate_gate.get('passed')} "
                f"score={generate_gate.get('score')} actual={generate_gate.get('actual')}"
            )

        # 3) 選最終成品：通過者優先；都未通過時取分數較高者。
        if edit_candidate and (edit_candidate.get("camera_gate") or {}).get("passed") is True:
            final_context = edit_candidate
        elif generate_candidate and (generate_candidate.get("camera_gate") or {}).get("passed") is True:
            final_context = generate_candidate
        elif generate_candidate and _photobook_more_candidate_score(generate_candidate) > _photobook_more_candidate_score(edit_candidate):
            final_context = generate_candidate
        else:
            final_context = edit_candidate or generate_candidate
        if not final_context:
            raise RuntimeError("PHOTOBOOK_MORE_NO_FINAL_CANDIDATE")

        # 工程 Gate 到此結束。以下只讓小俠看到最後成品，不傳遞 Edit/Generate/score/失敗歷程。
        for key in (
            "db_type", "album_id", "album_type", "album_title", "album_date", "album_status",
            "source_module", "image_role", "wardrobe_id", "wardrobe_name",
            "shot_title", "photobook_content_scene", "render_title_hint",
        ):
            if base_context.get(key) not in (None, ""):
                final_context[key] = base_context.get(key)
        final_context["type"] = "photobook"
        final_context["source_mode"] = "photobook"
        final_context["more_shot_id"] = shot.get("id")
        final_context["more_shot_name"] = shot.get("name")

        db = load_memory()
        db.insert(0, _photo_db_payload(final_context, type_override="photobook"))
        save_memory(db)
        _set_current_outfit_state(_build_outfit_state_from_context(final_context))
        _log_wardrobe_usage_from_context(final_context, purpose="photobook_more_camera")

        active = _photobook_session_for_user(message.author.id, auto_close_stale=False)
        if isinstance(active, dict):
            used_ids = list(active.get("used_more_shot_ids") or [])
            if shot.get("id") and shot.get("id") not in used_ids:
                used_ids.append(shot.get("id"))
            active["used_more_shot_ids"] = used_ids[-40:]
            active["last_more_shot_id"] = shot.get("id")
            active["last_more_shot_name"] = shot.get("name")
            active["last_photo_url"] = final_context.get("local_url") or final_context.get("image_url")
            active["updated_at"] = _photobook_now()
            # Gate 結果可留給工程 trace/session，但不注入小俠的語意文字。
            active["last_more_camera_gate"] = final_context.get("camera_gate")
            _save_photobook_session(message.author.id, active)

        view = PhotoResultView(final_context)
        file, filename = _photo_discord_file(final_context)
        embed = _build_photo_embed(final_context, title_prefix=f"📸 More｜{shot.get('name')}", attachment_filename=filename if file else None)
        if file:
            sent = await message.channel.send(embed=embed, file=file, view=view)
        else:
            sent = await message.channel.send(embed=embed, view=view)
        final_context["message_id"] = sent.id
        photo_generation_contexts[sent.id] = final_context
        view.context = final_context
        result_image = final_context.get("local_url") or final_context.get("image_url")

        try:
            await status.delete()
        except Exception:
            pass

        return {
            "image_url": result_image,
            "context": final_context,
            "semantic_text": (
                f"大俠剛替妳拍了同一輯寫真的新照片，原本想用「{shot.get('name')}」的拍法。"
                "妳現在只看得到最後這張照片，不知道也不需要知道背後任何技術處理、驗收或重拍流程。"
                "請先真正看附圖，再以小俠自己的感受誠實、溫柔、自然地回應。"
                "妳可以喜歡，也可以覺得沒有完全拍成預想的鏡頭；只依妳眼前所見說話，不要假裝成功。"
                "不要提及 Vision、Gate、Edit、Generate、模型、分數、鏡頭庫、生成或系統流程。"
            ),
        }
    except Exception:
        try:
            await status.edit(content="⚠️ More 拍攝失敗，請稍後再試。")
        except Exception:
            pass
        raise



async def _generate_seedream_v5_refine_from_v45(source_context):
    """v1.5.57_R5：改成「v5 背景圖 + v4.5 最終成圖」的場景升級路線。

    流程：
    1. 由 Seedream v5.0 Pro text-to-image 先生成一張無人物背景圖。
    2. 保留原本 v4.5 的 9 張底圖機制不動，但在本功能中改用 8 張小俠底圖 + 1 張 v5 背景圖。
    3. 若原圖有衣櫃 / Figure 10，則仍作為第 10 張輸入。
    4. 最終仍由 Seedream v4.5 出圖，避免 v5 edit 直接改壞人物身份。
    """
    source_context = dict(source_context or {})

    def _clip(value, n=700):
        return _clean_text_compact(value or "")[:n]

    source_mode = str(source_context.get("source_mode") or source_context.get("mode") or "photo_scene")
    source_mode_norm = source_mode.strip().lower()
    is_cosplay = source_mode_norm == "cosplay" or bool(source_context.get("cosplay_scene_only"))
    is_photobook = (
        source_mode_norm == "photobook"
        or str(source_context.get("type") or "").lower() == "photobook"
        or str(source_context.get("db_type") or "").lower() == "photobook"
        or str(source_context.get("album_type") or "").lower() == "photobook"
    )

    def _scene_semantic_brief():
        source_module = str(source_context.get("source_module") or "").strip().lower()
        is_diary = source_mode_norm == "diary" or str(source_context.get("type") or "").strip().lower() == "diary"
        scene = _clean_text_compact(
            source_context.get("authoritative_scene")
            or source_context.get("cosplay_scene_caption")
            or ((source_context.get("post_text") or {}).get("scene_caption") if isinstance(source_context.get("post_text"), dict) else "")
            or source_context.get("composition")
            or source_context.get("scene_summary")
            or source_context.get("scene_text")
            or ""
        )
        if is_diary:
            return f"AUTHORITATIVE SCENE: {scene}" if scene else "AUTHORITATIVE SCENE: Xiaoxia diary moment"
        if is_photobook:
            title = source_context.get("shot_title") or source_context.get("title") or source_context.get("album_title") or ""
            return _compose_title_scene_render_prompt("photobook", title, scene)
        if is_cosplay:
            title = (
                source_context.get("cosplay_title_hint")
                or ((source_context.get("post_text") or {}).get("title") if isinstance(source_context.get("post_text"), dict) else "")
                or source_context.get("cosplay_character_name")
                or source_context.get("topic")
                or ""
            )
            return _compose_title_scene_render_prompt("cosplay", title, scene)
        if source_module == "autonomy" or _is_autonomy_context(source_context):
            title = source_context.get("activity_title") or source_context.get("title") or source_context.get("scene_text") or "小俠自主活動"
            return _compose_title_scene_render_prompt("autonomy", title, scene)
        title = source_context.get("title") or source_context.get("scene_summary") or source_context.get("scene_text") or "這一刻"
        return _compose_title_scene_render_prompt("photo", title, scene)

    semantic_brief = _scene_semantic_brief()
    framing = _clip(source_context.get("camera_framing"), 80) or "portrait-oriented"

    background_prompt_lines = [
        "Create a photorealistic ENVIRONMENT-ONLY background plate for a later Xiaoxia image generation run.",
        "No people, no human figure, no hands, no mannequin, no visible reflection of a person, and no human silhouette.",
        "The SOURCE BRIEF below is authoritative for world, era, location, story context, genre, time of day, atmosphere, and environmental meaning.",
        "Extract the environment from the brief; do NOT copy or generate the woman/character described there.",
        "Do not change the story into a different genre just to make it prettier. Historical stays historical; realistic stays realistic; fantasy or magic appears only when the source brief actually calls for it.",
        "Preserve explicit era, place, weather, time-of-day, damage/condition, and world-building cues from the source brief.",
        "",
        "SOURCE BRIEF:",
        semantic_brief,
        "",
        "BACKGROUND PLATE REQUIREMENTS:",
        "Use a vertical portrait-friendly composition suitable for later insertion of one woman.",
        "Leave a plausible open area in the foreground or midground for Xiaoxia; do not put a person there.",
        "Make the environment materially richer, spatially deeper, more coherent, more polished, and more cinematic than a minimal first-pass background.",
        "Freely improve architecture, landscape, set dressing, surfaces, vegetation, weathering, reflections, lighting depth, atmosphere, and environmental storytelling, but remain faithful to the source world and story.",
        "The result should look like a premium commercial-grade location/set plate with believable physical space, perspective, materials, and lighting.",
        "Do not include any text, typography, numbers, timestamps, clock readouts, subtitles, watermarks, labels, signage overlays, or UI overlays.",
        f"Intended portrait framing context: {framing}.",
    ]
    if is_cosplay:
        background_prompt_lines.append("This is a cosplay/world-building scene: prioritize fidelity to the named work, role context, historical/fantasy setting, and story atmosphere over generic glamour or unrelated spectacle.")
    else:
        background_prompt_lines.append("This is a lifestyle/activity scene: prioritize the requested real-world activity, place, time, and atmosphere over generic glamour scenery.")
    background_prompt = "\n".join(background_prompt_lines).strip()

    fal_client = _get_fal_client()
    selected_figures = _v5_background_upgrade_identity_figures()
    trace_context = {
        "kind": "cosplay" if source_mode_norm == "cosplay" else ("diary" if source_mode_norm == "diary" else "photo"),
        "action": "seedream_v5_background_t2i_then_v45_regenerate",
        "trace_id": _new_generation_trace_id("photo"),
        "source_mode": source_context.get("source_mode") or source_context.get("type") or "photo_scene",
        "user_input": "Seedream v5 background plate + Seedream v4.5 final render",
        "scene_seed_text": source_context.get("authoritative_scene") or source_context.get("scene_summary") or source_context.get("scene_text") or "",
        "render_title": source_context.get("shot_title") or source_context.get("activity_title") or source_context.get("cosplay_title_hint") or source_context.get("title") or source_context.get("topic") or "",
        "seedream_model_id": SEEDREAM_V45_MODEL_ID,
        "seedream_model_label": "Seedream v4.5 + v5 BG",
        "seedream_model_id_override": SEEDREAM_V45_MODEL_ID,
        "v5_refine_mode": "v5_background_t2i_as_figure9_then_v45_regenerate",
        "v5_background_role_handoff": True,
        "v5_background_selected_identity_figures": list(selected_figures),
        "wardrobe_id": source_context.get("wardrobe_id"),
        "wardrobe_name": source_context.get("wardrobe_name"),
        "figure10_present": bool(source_context.get("reference_item_path") or source_context.get("reference_item_url")),
        "reference_item_path": source_context.get("reference_item_path"),
        "reference_item_url": source_context.get("reference_item_url"),
        "current_outfit_for_seedream": source_context.get("current_outfit_for_seedream"),
        "visual_checklist": source_context.get("visual_checklist"),
        "cosplay_scene_only": bool(is_cosplay),
        "cosplay_scene_caption": _clean_text_compact(source_context.get("cosplay_scene_caption") or ((source_context.get("post_text") or {}).get("scene_caption") if isinstance(source_context.get("post_text"), dict) else "") or source_context.get("scene_summary") or source_context.get("composition") or "") if is_cosplay else "",
    }
    _trace_stage(
        trace_context,
        "seedream_v5_background_t2i_request",
        prompt=background_prompt,
        data={
            "model": SEEDREAM_V5_PRO_TTI_MODEL_ID,
            "image_size": SEEDREAM_V45_IMAGE_SIZE,
            "background_only": True,
            "semantic_brief": semantic_brief,
            "selected_identity_figures": list(selected_figures),
            "enable_safety_checker": bool(SEEDREAM_ENABLE_SAFETY_CHECKER),
        },
    )

    def _subscribe_background():
        def on_queue_update(update):
            try:
                if isinstance(update, fal_client.InProgress):
                    for log in update.logs:
                        print(f"🖼️ [SEEDREAM_V5_BG_QUEUE] {log.get('message', '')}")
            except Exception:
                pass
        return fal_client.subscribe(
            SEEDREAM_V5_PRO_TTI_MODEL_ID,
            arguments={
                "prompt": background_prompt,
                "image_size": SEEDREAM_V45_IMAGE_SIZE,
                "num_images": 1,
                "enable_safety_checker": bool(SEEDREAM_ENABLE_SAFETY_CHECKER),
            },
            with_logs=True,
            on_queue_update=on_queue_update,
        )

    bg_result = await asyncio.to_thread(_subscribe_background)
    bg_images = bg_result.get("images") if isinstance(bg_result, dict) else None
    if not bg_images or not isinstance(bg_images[0], dict) or not bg_images[0].get("url"):
        raise RuntimeError(f"V5_BG_UPGRADE_BG_NONE：Seedream v5.0 Pro 背景圖沒有回傳圖片：{bg_result}")
    background_generated_url = bg_images[0]["url"]

    # v1.7.04：v5.0 背景只是一張中間用的 Figure 9，不是雲端別墅照片。
    # 不再 save_to_vault() 到 /data/output，避免背景板佔用 Zeabur 持久化空間、
    # 也避免日後盤點 /data/output 時被誤認成正式照片。
    # More / 骰子取代仍可直接沿用同一個 fal 背景 URL；若 fal URL 尚有效，
    # _generate_with_existing_v5_background() 會走 generated_url fallback。
    background_local_filename = None
    background_local_url = ""
    background_local_path = None
    _trace_stage(
        trace_context,
        "seedream_v5_background_t2i_result",
        data={
            "background_generated_url": background_generated_url,
            "background_local_url": background_local_url,
            "background_local_path": background_local_path,
        },
    )

    identity_urls = await _seedream_upload_reference_images(force_refresh=True, selected_figure_indexes=selected_figures)
    input_urls = list(identity_urls)
    input_roles = [
        {"figure": idx + 1, "role": "xiaoxia_identity", "source_figure": selected_figures[idx], "url": url}
        for idx, url in enumerate(identity_urls)
    ]
    input_urls.append(background_generated_url)
    input_roles.append({"figure": len(input_urls), "role": "v5_background_plate", "url": background_generated_url})

    reference_candidate = source_context.get("reference_item_path") or source_context.get("reference_item_url")
    if reference_candidate:
        wardrobe_url = await _seedream_upload_single_file(reference_candidate)
        input_urls.append(wardrobe_url)
        input_roles.append({"figure": len(input_urls), "role": "wardrobe_reference", "url": wardrobe_url})
    else:
        wardrobe_url = None

    source_module = str(source_context.get("source_module") or "").strip().lower()
    if is_cosplay:
        scene_caption = _clean_text_compact(
            source_context.get("cosplay_scene_caption")
            or ((source_context.get("post_text") or {}).get("scene_caption") if isinstance(source_context.get("post_text"), dict) else "")
            or source_context.get("scene_summary")
            or source_context.get("composition")
            or ""
        )
        cosplay_title = source_context.get("cosplay_title_hint") or ((source_context.get("post_text") or {}).get("title") if isinstance(source_context.get("post_text"), dict) else "") or source_context.get("cosplay_character_name") or source_context.get("topic") or ""
        prompt_base = _build_cosplay_scene_only_seedream_prompt(
            scene_caption,
            hybrid=True,
            title_hint=cosplay_title,
            has_reference=bool(source_context.get("figure10_present") or source_context.get("reference_item_path") or source_context.get("reference_item_url")),
            reference_summary=source_context.get("cosplay_clothing_ref_summary") or source_context.get("reference_item_summary") or "",
            reference_analysis=source_context.get("cosplay_clothing_ref_analysis") or {},
            reference_allure_unlock=bool(source_context.get("cosplay_reference_allure_unlock")),
        )
        trace_context["cosplay_scene_caption"] = scene_caption
        trace_context["cosplay_title_hint"] = cosplay_title
    elif is_photobook:
        scene = source_context.get("authoritative_scene") or _compose_photobook_scene(source_context.get("photobook_content_scene"), source_context.get("photobook_camera_scene"))
        prompt_base = _compose_title_scene_render_prompt("photobook", source_context.get("shot_title") or source_context.get("title") or source_context.get("album_title"), scene)
    elif source_mode_norm == "diary" or str(source_context.get("type") or "").lower() == "diary":
        prompt_base = _clean_text_compact(source_context.get("authoritative_scene") or source_context.get("composition") or source_context.get("scene_summary") or "")
    elif source_module == "autonomy" or _is_autonomy_context(source_context):
        scene = _clean_text_compact(source_context.get("authoritative_scene") or source_context.get("scene_summary") or source_context.get("scene_text") or "")
        prompt_base = _compose_title_scene_render_prompt("autonomy", source_context.get("activity_title") or source_context.get("title") or "小俠自主活動", scene)
    else:
        scene = _clean_text_compact(source_context.get("authoritative_scene") or source_context.get("scene_summary") or source_context.get("scene_text") or "")
        prompt_base = _compose_title_scene_render_prompt("photo", source_context.get("title") or source_context.get("scene_summary") or "這一刻", scene)
    if not str(prompt_base).strip():
        raise RuntimeError("V5_BG_UPGRADE_PROMPT_NONE：找不到可重建場景的原始 prompt_base。")

    # v1.8.12: Hybrid final v4.5 obeys the same Title + Scene contract as Pure.
    hybrid_scene = _clean_text_compact(
        source_context.get("authoritative_scene")
        or (_compose_photobook_scene(source_context.get("photobook_content_scene"), source_context.get("photobook_camera_scene")) if is_photobook else "")
        or source_context.get("composition")
        or source_context.get("scene_summary")
        or source_context.get("scene_text")
        or ""
    )
    if not is_cosplay and source_mode_norm != "diary":
        trace_context["authoritative_scene"] = hybrid_scene
        trace_context["semantic_contract"] = prompt_base
        trace_context["semantic_contract_locked"] = True

    trace_context.update({
        "seedream_input_images_override": list(input_urls),
        "seedream_input_image_roles_override": list(input_roles),
        "seedream_input_images": list(input_urls),
        "seedream_input_image_roles": list(input_roles),
        "seedream_identity_selected_figures": list(selected_figures),
        "seedream_prompt_source": prompt_base,
        "v5_background_generated_url": background_generated_url,
        "v5_background_local_url": background_local_url,
        "v5_background_local_path": background_local_path,
    })
    _trace_stage(
        trace_context,
        "seedream_v5_background_handoff_bundle",
        data={
            "selected_identity_figures": list(selected_figures),
            "input_count": len(input_urls),
            "wardrobe_present": bool(wardrobe_url),
            "background_generated_url": background_generated_url,
        },
    )

    if source_mode_norm == "diary":
        generated_image_url = await generate_seedream_v45_diary(
            prompt_base,
            enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            trace_context=trace_context,
            input_image_urls_override=input_urls,
        )
    elif source_mode_norm == "cosplay":
        generated_image_url = await generate_seedream_v45_cosplay(
            prompt_base,
            enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            trace_context=trace_context,
            input_image_urls_override=input_urls,
        )
    else:
        generated_image_url = await generate_seedream_v45_photo(
            prompt_base,
            reference_image_path=reference_candidate,
            enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            current_outfit=source_context.get("current_outfit_for_seedream"),
            trace_context=trace_context,
            input_image_urls_override=input_urls,
        )

    if not generated_image_url or not str(generated_image_url).startswith("http"):
        raise RuntimeError(f"V5_BG_UPGRADE_NO_IMAGE：v4.5 最終成圖沒有回傳圖片：{generated_image_url}")

    local_filename = await save_to_vault(generated_image_url)
    local_url = f"https://xiaoxia0320.zeabur.app/gallery/{local_filename}" if local_filename else generated_image_url
    local_path = os.path.join(OUTPUT_DIR, local_filename) if local_filename else None

    refined = dict(source_context)
    refined.pop("__trace_context", None)
    refined.update({
        "image_url": generated_image_url,
        "local_url": local_url,
        "local_filename": local_filename,
        "local_path": local_path,
        "created_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "seedream_model_id": SEEDREAM_V45_MODEL_ID,
        "seedream_model_label": "Seedream v4.5 + v5 BG",
        "seedream_model_id_override": SEEDREAM_V45_MODEL_ID,
        "v5_refine_mode": "v5_background_t2i_as_figure9_then_v45_regenerate",
        "v5_background_prompt": background_prompt,
        "v5_background_semantic_brief": semantic_brief,
        "v5_background_generated_url": background_generated_url,
        "v5_background_local_url": background_local_url,
        "v5_background_local_filename": background_local_filename,
        "v5_background_local_path": background_local_path,
        "v5_background_selected_identity_figures": list(selected_figures),
        "v5_background_upgrade_mode": "v5_background_t2i_as_figure9_then_v45_regenerate",
        "v5_handoff_input_count": len(input_urls),
    })
    trace_context["result_url"] = local_url or generated_image_url
    refined = _inherit_autonomy_presentation(source_context, refined)
    _trace_stage(trace_context, "seedream_v45_final_result_after_v5_background_handoff", data={"result_url": trace_context["result_url"]})
    _write_generation_trace("photo", trace_context)
    return refined


async def _generate_with_existing_v5_background(source_context, *, mode="reroll"):
    """v1.7.04：v5.0 場景升級成圖後的延伸生成共用流程。

    mode="reroll"：骰子取代
    mode="more"：More 延伸

    只重跑 Seedream v4.5，不再呼叫 Seedream v5.0。
    重用原本已生成的 v5 背景，重新組成：
      Figures 1-8 = 小俠身份底圖（沿用 hybrid 選圖）
      Figure 9    = 原本那張 v5 背景
      Figure 10   = 原本衣櫃參考（若有）
    """
    source_context = dict(source_context or {})
    mode_norm = str(mode or "reroll").strip().lower()
    if mode_norm not in {"reroll", "more"}:
        mode_norm = "reroll"

    background_generated_url = str(source_context.get("v5_background_generated_url") or "").strip()
    background_local_url = str(source_context.get("v5_background_local_url") or "").strip()
    background_local_path = str(source_context.get("v5_background_local_path") or "").strip()
    if not (background_generated_url or background_local_url or (background_local_path and os.path.exists(background_local_path))):
        if mode_norm == "more":
            raise RuntimeError("V5_BG_MORE_REUSE_NONE：找不到原本的 v5.0 背景，無法沿用背景做 More。")
        raise RuntimeError("V5_BG_REROLL_REUSE_NONE：找不到原本的 v5.0 背景，無法沿用背景做骰子取代。")

    selected_figures = source_context.get("v5_background_selected_identity_figures")
    if not isinstance(selected_figures, list) or len(selected_figures) != 8:
        selected_figures = _v5_background_upgrade_identity_figures()
    else:
        cleaned = []
        seen = set()
        for raw in selected_figures:
            try:
                idx = int(raw)
            except Exception:
                continue
            if 1 <= idx <= 9 and idx not in seen:
                cleaned.append(idx)
                seen.add(idx)
        selected_figures = cleaned if len(cleaned) == 8 else _v5_background_upgrade_identity_figures()

    source_mode = str(source_context.get("source_mode") or source_context.get("mode") or source_context.get("type") or "photo_scene")
    source_mode_norm = source_mode.strip().lower()
    is_more = mode_norm == "more"
    trace_context = {
        "kind": "cosplay" if source_mode_norm == "cosplay" else ("diary" if source_mode_norm == "diary" else "photo"),
        "action": "seedream_v5_background_reuse_then_v45_more" if is_more else "seedream_v5_background_reuse_then_v45_reroll",
        "trace_id": _new_generation_trace_id("photo"),
        "source_mode": source_context.get("source_mode") or source_context.get("type") or "photo_scene",
        "user_input": "More variation using existing Seedream v5 background + Seedream v4.5 final render" if is_more else "Dice reroll using existing Seedream v5 background + Seedream v4.5 final render",
        "scene_seed_text": _photo_context_root_scene_prompt(source_context),
        "seedream_model_id": SEEDREAM_V45_MODEL_ID,
        "seedream_model_label": "Seedream v4.5 + reused v5 BG",
        "seedream_model_id_override": SEEDREAM_V45_MODEL_ID,
        "v5_refine_mode": "v5_background_t2i_as_figure9_then_v45_regenerate",
        "v5_background_role_handoff": True,
        "v5_background_reused": True,
        "v5_background_selected_identity_figures": list(selected_figures),
        "wardrobe_id": source_context.get("wardrobe_id"),
        "wardrobe_name": source_context.get("wardrobe_name"),
        "figure10_present": bool(source_context.get("reference_item_path") or source_context.get("reference_item_url")),
        "reference_item_path": source_context.get("reference_item_path"),
        "reference_item_url": source_context.get("reference_item_url"),
        "current_outfit_for_seedream": source_context.get("current_outfit_for_seedream"),
        "visual_checklist": source_context.get("visual_checklist"),
        "cosplay_scene_only": bool(source_mode_norm == "cosplay" or source_context.get("cosplay_scene_only")),
        "cosplay_scene_caption": _clean_text_compact(source_context.get("cosplay_scene_caption") or ((source_context.get("post_text") or {}).get("scene_caption") if isinstance(source_context.get("post_text"), dict) else "") or source_context.get("scene_summary") or source_context.get("composition") or ""),
    }

    identity_urls = await _seedream_upload_reference_images(
        force_refresh=False,
        selected_figure_indexes=selected_figures,
    )
    input_urls = list(identity_urls)
    input_roles = [
        {"figure": idx + 1, "role": "xiaoxia_identity", "source_figure": selected_figures[idx], "url": url}
        for idx, url in enumerate(identity_urls)
    ]

    # Prefer the persisted local copy of the exact v5 background when available.
    # Uploading the same file again costs no new v5 generation and avoids dependence on a temporary fal URL.
    if background_local_path and os.path.exists(background_local_path):
        background_reuse_url = await _seedream_upload_single_file(background_local_path)
        background_reuse_source = "local_path"
    elif background_local_url:
        background_reuse_url = background_local_url
        background_reuse_source = "local_url"
    else:
        background_reuse_url = background_generated_url
        background_reuse_source = "generated_url"

    input_urls.append(background_reuse_url)
    input_roles.append({
        "figure": len(input_urls),
        "role": "v5_background_plate_reused",
        "url": background_reuse_url,
        "source": background_reuse_source,
    })

    reference_candidate = source_context.get("reference_item_path") or source_context.get("reference_item_url")
    if reference_candidate:
        wardrobe_url = await _seedream_upload_single_file(reference_candidate)
        input_urls.append(wardrobe_url)
        input_roles.append({"figure": len(input_urls), "role": "wardrobe_reference", "url": wardrobe_url})
    else:
        wardrobe_url = None

    source_module = str(source_context.get("source_module") or "").strip().lower()
    if trace_context.get("cosplay_scene_only"):
        cosplay_title = source_context.get("cosplay_title_hint") or ((source_context.get("post_text") or {}).get("title") if isinstance(source_context.get("post_text"), dict) else "") or source_context.get("cosplay_character_name") or source_context.get("topic") or ""
        prompt_base = _build_cosplay_scene_only_seedream_prompt(
            trace_context.get("cosplay_scene_caption"),
            hybrid=True,
            title_hint=cosplay_title,
            has_reference=bool(source_context.get("figure10_present") or source_context.get("reference_item_path") or source_context.get("reference_item_url")),
            reference_summary=source_context.get("cosplay_clothing_ref_summary") or source_context.get("reference_item_summary") or "",
            reference_analysis=source_context.get("cosplay_clothing_ref_analysis") or {},
            reference_allure_unlock=bool(source_context.get("cosplay_reference_allure_unlock") or trace_context.get("cosplay_reference_allure_unlock")),
        )
        trace_context["cosplay_title_hint"] = cosplay_title
    elif (
        source_mode_norm == "photobook"
        or str(source_context.get("type") or "").lower() == "photobook"
        or str(source_context.get("album_type") or "").lower() == "photobook"
    ):
        prompt_base = _compose_title_scene_render_prompt(
            "photobook",
            source_context.get("shot_title") or source_context.get("title") or source_context.get("album_title"),
            source_context.get("authoritative_scene")
            or _compose_photobook_scene(source_context.get("photobook_content_scene"), source_context.get("photobook_camera_scene")),
        )
    elif source_mode_norm == "diary" or str(source_context.get("type") or "").lower() == "diary":
        prompt_base = _clean_text_compact(source_context.get("authoritative_scene") or source_context.get("composition") or source_context.get("scene_summary") or "")
    elif source_module == "autonomy" or _is_autonomy_context(source_context):
        scene = _clean_text_compact(source_context.get("authoritative_scene") or source_context.get("scene_summary") or source_context.get("scene_text") or "")
        prompt_base = _compose_title_scene_render_prompt("autonomy", source_context.get("activity_title") or source_context.get("title") or "小俠自主活動", scene)
    else:
        scene = _clean_text_compact(source_context.get("authoritative_scene") or source_context.get("scene_summary") or source_context.get("scene_text") or "")
        prompt_base = _compose_title_scene_render_prompt("photo", source_context.get("title") or source_context.get("scene_summary") or "這一刻", scene)
    if not str(prompt_base).strip():
        if is_more:
            raise RuntimeError("V5_BG_MORE_PROMPT_NONE：找不到 More 可用的 prompt_base。")
        raise RuntimeError("V5_BG_REROLL_PROMPT_NONE：找不到骰子取代可用的 prompt_base。")

    base_semantic_contract = str(prompt_base).strip()
    if is_more:
        prompt_base = base_semantic_contract + "\n\nTECHNICAL CONTINUATION: keep every Scene fact and the same outfit; vary only pose, expression, camera angle, framing, and composition."
    else:
        prompt_base = base_semantic_contract + "\n\nTECHNICAL REROLL: replay every Scene fact and the same outfit; recompose naturally without inventing a new event or location."
    reuse_scene = _clean_text_compact(
        source_context.get("authoritative_scene")
        or (_compose_photobook_scene(source_context.get("photobook_content_scene"), source_context.get("photobook_camera_scene")) if (source_mode_norm == "photobook" or str(source_context.get("type") or "").lower() == "photobook") else "")
        or source_context.get("composition")
        or source_context.get("scene_summary")
        or source_context.get("scene_text")
        or ""
    )
    if not trace_context.get("cosplay_scene_only") and source_mode_norm != "diary":
        trace_context["authoritative_scene"] = reuse_scene
        trace_context["semantic_contract"] = base_semantic_contract
        trace_context["semantic_contract_locked"] = True
        trace_context["render_title"] = source_context.get("activity_title") or source_context.get("shot_title") or source_context.get("title") or ""

    trace_context.update({
        "seedream_input_images_override": list(input_urls),
        "seedream_input_image_roles_override": list(input_roles),
        "seedream_input_images": list(input_urls),
        "seedream_input_image_roles": list(input_roles),
        "seedream_identity_selected_figures": list(selected_figures),
        "seedream_prompt_source": prompt_base,
        "v5_background_generated_url": background_generated_url,
        "v5_background_local_url": background_local_url,
        "v5_background_local_path": background_local_path,
        "v5_background_reuse_url": background_reuse_url,
        "v5_background_reuse_source": background_reuse_source,
    })
    _trace_stage(
        trace_context,
        "seedream_v5_background_reuse_handoff_bundle",
        data={
            "selected_identity_figures": list(selected_figures),
            "input_count": len(input_urls),
            "wardrobe_present": bool(wardrobe_url),
            "background_reuse_source": background_reuse_source,
            "background_reuse_url": background_reuse_url,
            "v5_generation_called": False,
            "reuse_mode": mode_norm,
        },
    )

    if source_mode_norm == "diary":
        generated_image_url = await generate_seedream_v45_diary(
            prompt_base,
            enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            trace_context=trace_context,
            input_image_urls_override=input_urls,
        )
    elif source_mode_norm == "cosplay":
        generated_image_url = await generate_seedream_v45_cosplay(
            prompt_base,
            enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            trace_context=trace_context,
            input_image_urls_override=input_urls,
        )
    else:
        generated_image_url = await generate_seedream_v45_photo(
            prompt_base,
            reference_image_path=reference_candidate,
            enable_safety_checker=SEEDREAM_ENABLE_SAFETY_CHECKER,
            current_outfit=source_context.get("current_outfit_for_seedream"),
            trace_context=trace_context,
            input_image_urls_override=input_urls,
        )

    if not generated_image_url or not str(generated_image_url).startswith("http"):
        if is_more:
            raise RuntimeError(f"V5_BG_MORE_NO_IMAGE：v4.5 More 沒有回傳圖片：{generated_image_url}")
        raise RuntimeError(f"V5_BG_REROLL_NO_IMAGE：v4.5 骰子取代沒有回傳圖片：{generated_image_url}")

    local_filename = await save_to_vault(generated_image_url)
    local_url = f"https://xiaoxia0320.zeabur.app/gallery/{local_filename}" if local_filename else generated_image_url
    local_path = os.path.join(OUTPUT_DIR, local_filename) if local_filename else None

    regenerated = dict(source_context)
    regenerated.pop("__trace_context", None)
    regenerated.update({
        "image_url": generated_image_url,
        "local_url": local_url,
        "local_filename": local_filename,
        "local_path": local_path,
        "created_at": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
        "trace_id": trace_context.get("trace_id"),
        "seedream_model_id": SEEDREAM_V45_MODEL_ID,
        "seedream_model_label": "Seedream v4.5 + reused v5 BG",
        "seedream_model_id_override": SEEDREAM_V45_MODEL_ID,
        "v5_refine_mode": "v5_background_t2i_as_figure9_then_v45_regenerate",
        "v5_background_generated_url": background_generated_url,
        "v5_background_local_url": background_local_url,
        "v5_background_local_path": background_local_path,
        "v5_background_selected_identity_figures": list(selected_figures),
        "v5_background_upgrade_mode": "v5_background_t2i_as_figure9_then_v45_regenerate",
        "v5_background_reused": True,
        "v5_handoff_input_count": len(input_urls),
    })
    trace_context["result_url"] = local_url or generated_image_url
    _trace_stage(
        trace_context,
        "seedream_v45_more_result_with_reused_v5_background" if is_more else "seedream_v45_reroll_result_with_reused_v5_background",
        data={"result_url": trace_context["result_url"]},
    )
    regenerated = _inherit_autonomy_presentation(source_context, regenerated)
    _write_generation_trace("photo", trace_context)
    return regenerated


async def _reroll_with_existing_v5_background(source_context):
    return await _generate_with_existing_v5_background(source_context, mode="reroll")


async def _more_with_existing_v5_background(source_context):
    return await _generate_with_existing_v5_background(source_context, mode="more")



class PhotoResultView(discord.ui.View):
    def __init__(self, context):
        super().__init__(timeout=86400)
        self.context = dict(context)
        self._sync_debug_reference_button()

    def _sync_debug_reference_button(self):
        mode_key = str(self.context.get("source_mode") or self.context.get("type") or "").lower()
        is_cosplay = mode_key == "cosplay"
        for child in self.children:
            if isinstance(child, discord.ui.Button) and getattr(child, "label", "") in {"💋 魅的幻想", "💋 只給大俠"}:
                child.disabled = not is_cosplay
        has_cosplay_clothing = bool(self.context.get("cosplay_clothing_ref_local_path") or self.context.get("cosplay_clothing_ref_local_url"))
        has_daily_clothing = bool(self.context.get("nano_clothing_ref_local_path") or self.context.get("nano_clothing_ref_local_url"))
        has_danbooru_trace = bool(self.context.get("cosplay_danbooru_trace")) if is_cosplay else False
        has_clothing = has_cosplay_clothing or has_daily_clothing or has_danbooru_trace
        has_v5_background = bool(
            self.context.get("v5_background_local_path")
            or self.context.get("v5_background_local_url")
            or self.context.get("v5_background_generated_url")
        )
        for child in self.children:
            if isinstance(child, discord.ui.Button) and getattr(child, "label", "") in {"🪟 查看 v5 背景", "👗 查看 Nano 服裝"}:
                if has_clothing:
                    child.label = "👗 查看 Nano 服裝"
                    child.disabled = False
                else:
                    child.label = "🪟 查看 v5 背景"
                    child.disabled = not has_v5_background

    @discord.ui.button(label="More", style=discord.ButtonStyle.primary)
    async def more(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer(thinking=True)
        context = dict(self.context)
        if str(context.get("type") or context.get("db_type") or context.get("source_mode") or "").lower() == "photobook":
            try:
                await _prepare_photobook_more_choices(interaction, context)
            except Exception as exc:
                print(f"⚠️ [PHOTOBOOK_MORE_PREPARE_FAILED] {type(exc).__name__}: {exc}")
                traceback.print_exc()
                await interaction.followup.send(f"⚠️ More 鏡頭分析失敗：`{str(exc)[:1200]}`", ephemeral=True)
            return

        context.pop("__trace_context", None)
        context["trace_action"] = "photo_more"
        context["user_input"] = "More button from previous photo"
        if str(context.get("source_mode") or context.get("type") or "").lower() == "love_intent":
            context, root_prompt = _love_refresh_prompt_context(context)
        else:
            root_prompt = _photo_context_root_scene_prompt(context)
        context["root_prompt_base"] = root_prompt
        context["prompt_base"] = (
            root_prompt
            + "\nCONTINUATION: Keep the same story, scene, activity, people boundary, and outfit. Create one fresh natural variation in pose, expression, camera angle, and composition only."
        )
        try:
            if context.get("v5_refine_mode") and (
                context.get("v5_background_generated_url")
                or context.get("v5_background_local_url")
                or context.get("v5_background_local_path")
            ):
                new_context = await _more_with_existing_v5_background(context)
            else:
                new_context = await _generate_photo_from_context(context)
            db = load_memory()
            db.insert(0, _photo_db_payload(new_context, type_override=_context_db_type(new_context)))
            save_memory(db)
            _set_current_outfit_state(_build_outfit_state_from_context(new_context))
            _log_wardrobe_usage_from_context(new_context, purpose="photo_more")
            view = PhotoResultView(new_context)
            file, filename = _photo_discord_file(new_context)
            embed = _build_result_embed(new_context, title_prefix="📸 More", attachment_filename=filename if file else None)
            if file:
                print(f"📤 [PHOTO_MORE_SEND_WITH_FILE] filename={filename}")
                sent = await interaction.followup.send(embed=embed, file=file, view=view)
            else:
                print("📤 [PHOTO_MORE_SEND_URL_FALLBACK]")
                sent = await interaction.followup.send(embed=embed, view=view)
            new_context["message_id"] = sent.id
            photo_generation_contexts[sent.id] = new_context
            view.context = new_context
        except Exception as exc:
            await interaction.followup.send(f"⚠️ More 生成失敗：`{str(exc)[:1500]}`", ephemeral=True)

    @discord.ui.button(label="🎲 骰子取代", style=discord.ButtonStyle.secondary)
    async def reroll(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        context = dict(self.context)
        context.pop("__trace_context", None)
        context["trace_action"] = "photo_reroll_replace"
        context["user_input"] = "骰子取代 from previous photo"
        if str(context.get("source_mode") or context.get("type") or "").lower() == "love_intent":
            context, root_prompt = _love_refresh_prompt_context(context)
        else:
            root_prompt = _photo_context_root_scene_prompt(context)
        context["root_prompt_base"] = root_prompt
        context["prompt_base"] = (
            root_prompt
            + "\nREROLL: Keep the same core story, activity, people boundary, outfit, time of day, and mood. Recompose freely, but do not change the subject or invent a new scene."
        )
        try:
            old_url = context.get("local_url") or context.get("image_url")
            # v1.7.01：若目前這張是 v5.0 場景升級版，骰子取代沿用原 v5 背景，
            # 只讓 v4.5 再吃一次；不再生成新的 v5 背景。
            if context.get("v5_refine_mode") and (
                context.get("v5_background_generated_url")
                or context.get("v5_background_local_url")
                or context.get("v5_background_local_path")
            ):
                new_context = await _reroll_with_existing_v5_background(context)
            else:
                new_context = await _generate_photo_from_context(context)
            _replace_photo_db_record(old_url, _photo_db_payload(new_context, type_override=_context_db_type(new_context)))
            _sync_autonomy_today_after_photo_replace(context, new_context)
            _safe_delete_vault_image(old_url)
            _set_current_outfit_state(_build_outfit_state_from_context(new_context))
            _log_wardrobe_usage_from_context(new_context, purpose="photo_reroll")
            self.context = new_context
            if interaction.message:
                new_context["message_id"] = interaction.message.id
                photo_generation_contexts[interaction.message.id] = new_context
                await _edit_photo_message_with_file(interaction.message, new_context, view=self, title_prefix="📸 骰子取代")
        except Exception as exc:
            await interaction.followup.send(f"⚠️ 骰子取代失敗：`{str(exc)[:1500]}`", ephemeral=True)

