@girlfriend_bot.command(name='more')
async def more(ctx):
    if not state["current_topic_data"]:
        await ctx.send("❓ 還沒決定題材呢！")
        return
    if not check_daily_limit(): return
    msg = await ctx.send("✨ 收到！正在為大俠構思另一個完美視角的高級時尚寫真...")
    try:
        story = state["current_topic_data"]
        
        # 1. 在同一題材下改變自然瞬間，而不是單純重跑模特兒 pose
        _cosplay_state, visual = await create_cosplay_visual(story, state["retry_count"] >= 2, alternative=True)
        scene_prompt = visual['image_prompt']

        # 👇 替換為以下這一行呼叫
        generated_image_url, visual = await execute_safe_generation(
            discord_image_url=None, 
            base_filename="base_xiaoxia.jpg", 
            mode="cosplay", 
            initial_prompt=scene_prompt, 
            visual_dict=visual, 
            msg=msg
        )

        state["daily_gen_count"] += 1
        
        # 4. 存檔與發送
        local_filename = await save_to_vault(generated_image_url)
        local_url = f"https://xiaoxia0320.zeabur.app/gallery/{local_filename}" if local_filename else generated_image_url
        
        payload = {
            "id": str(uuid.uuid4()),
            "publish_date": datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S"),
            "topic": f"【加洗】{story['topic']}",
            "event": story["event"],
            "composition": visual["composition"],
            "mood": visual["mood"],
            "message": visual["message"],
            "image_url": generated_image_url,
            "local_url": local_url,
            "final_level": visual.get("final_level"),
            "generation_level": visual.get("generation_level") or visual.get("final_level")
        }
        db = load_memory()
        db.insert(0, payload)
        save_memory(db)

        embed = discord.Embed(title=f"【加洗】{story['topic']}", color=0xffb6c1)
        embed.set_image(url=local_url)
        embed.add_field(name="💌 專屬留言", value=visual["message"], inline=False)
        embed.set_footer(text=f"今日額度: {state['daily_gen_count']}/12 | Seedream v4.5 image-to-image{_generation_level_footer(payload)}")

        await msg.delete()
        new_msg = await ctx.send(embed=embed)
        await new_msg.add_reaction("➕") 
        await new_msg.add_reaction("🎲") 
        await new_msg.add_reaction("🗑️") 
    except Exception as e: 
        await msg.edit(content=f"⚠️ 失敗：{e}")

async def _send_wardrobe_browse_message(ctx, query="", page=0):
    """安全送出 /衣櫃 分頁；Discord embed 限制失敗時退回純文字清單。"""
    content, embeds, page, _total_pages, total = _wardrobe_browse_payload(query=query, page=page)
    view = WardrobeBrowseView(query=query, page=page)
    try:
        await ctx.send(content=content, embeds=embeds, view=view)
        return
    except Exception as exc:
        print(f"⚠️ [WARDROBE_BROWSE_SEND_FAILED] {type(exc).__name__}: {exc}")
        matched = _wardrobe_filtered_items(query)
        start = max(0, int(page or 0)) * WARDROBE_PAGE_SIZE
        page_items = matched[start:start + WARDROBE_PAGE_SIZE]
        lines = [content, "", "⚠️ 圖片卡片太多或字數超過 Discord 限制，先用純文字列出本頁："]
        for item in page_items:
            lines.append(f"- **{item.get('id')}** {item.get('name')}｜{item.get('main_category')}/{item.get('sub_category')}")
        lines.append("\n可用 `/衣櫃看 Wxxx` 查看單件大圖，或 `/衣櫃穿 Wxxx` 套用到下一張 `/photo`。")
        await ctx.send("\n".join(lines)[:1900], view=view if total else None)



@girlfriend_bot.command(name='trace')
async def generation_trace_command(ctx, *, args: str = "最近"):
    if not _is_girlfriend_xiaoxia_channel(ctx.channel):
        await ctx.send("大俠，`/trace` 先只開放在女友小俠頻道使用喔。")
        return
    raw = str(args or "最近").strip()
    parts = raw.split()
    kind = "all"
    limit = 1
    if parts:
        if parts[0] in {"最近", "latest", "last"}:
            kind = "all"
            if len(parts) > 1 and parts[1].isdigit():
                limit = int(parts[1])
        else:
            kind = parts[0].lower()
            if len(parts) > 1 and parts[1].isdigit():
                limit = int(parts[1])
    aliases = {"照片": "photo", "修圖": "repair", "修正": "repair", "交換日記": "diary", "日記": "diary", "角色": "cosplay"}
    kind = aliases.get(kind, kind)
    rows = _load_recent_generation_traces(kind=kind, limit=max(1, min(limit, 5)))
    if not rows:
        await ctx.send("🧭 目前還沒有可讀的 generation trace。先跑一次 `/photo`、`/cosplay` 或修正圖後再查。")
        return
    # 最舊到最新讀入，顯示時最新優先。
    for row in reversed(rows):
        await ctx.send("🧭 **Generation Trace**\n```\n" + _format_trace_for_discord(row) + "\n```")

@girlfriend_bot.command(name='衣櫃')
async def wardrobe_command(ctx, *, args: str = ""):
    if not _is_girlfriend_xiaoxia_channel(ctx.channel):
        await ctx.send("大俠，`/衣櫃` 先只開放在女友小俠頻道使用喔。")
        return

    action, payload = _parse_wardrobe_command(ctx.message.content)
    if action == "browse":
        await _send_wardrobe_browse_message(ctx, query="", page=0)
        return
    if action == "search":
        await _send_wardrobe_browse_message(ctx, query=payload, page=0)
        return
    if action == "新增":
        await _handle_wardrobe_add_command(ctx, payload, remove_person=False)
        return
    if action == "去人":
        await _handle_wardrobe_add_command(ctx, payload, remove_person=True)
        return
    if action == "健檢":
        await _handle_wardrobe_healthcheck(ctx)
        return
    if action in {"修復圖片", "圖片修復"}:
        await _handle_wardrobe_repair_images(ctx)
        return
    if action == "換圖":
        await _handle_wardrobe_replace_image_command(ctx, payload, remove_person=False)
        return
    if action in {"換圖去人", "換圖去人化"}:
        await _handle_wardrobe_replace_image_command(ctx, payload, remove_person=True)
        return
    if action == "問小俠":
        await _ask_xiaoxia_about_wardrobe(ctx, payload)
        return
    if action == "看":
        item = _find_wardrobe_item(payload)
        if not item:
            await ctx.send("找不到這個衣櫃編號喔。請先 `/衣櫃` 看看目前有哪些收藏。")
            return
        await ctx.send(embed=_wardrobe_embed_for_item(item), view=WardrobeApplyView(item))
        return
    if action == "穿":
        item = _find_wardrobe_item(payload)
        if item:
            _set_pending_wardrobe_state(item)
            await ctx.send(f"✅ 已選定 **{item.get('id')} {item.get('name')}**。下一張 `/photo` 若沒有另外附衣服圖，就會優先套用這件。")
            return

        attachment, attachment_error = await _get_photo_reference_attachment(ctx.message)
        if attachment_error:
            await ctx.send(attachment_error)
            return
        if not attachment:
            await ctx.send("找不到這個衣櫃編號喔；若你是要用附圖臨時穿，請在 `/衣櫃 穿` 同時附上一張人物穿搭照。")
            return

        status = await ctx.send("👗 小俠正在把附圖整理成可穿的 Nano 服裝參考，等等喔...")
        try:
            temp_item = await _prepare_temporary_wear_reference_from_attachment(attachment, name_hint=payload)
            _set_pending_wardrobe_state(temp_item)
            await status.edit(
                content=(
                    f"✅ 已從附圖整理出臨時穿搭參考：**{temp_item.get('name')}**。\n"
                    "下一張 `/photo` 或 `/寫真 ...` 會優先套用這套穿搭；這次只是暫時穿上，尚未收藏進衣櫃。\n"
                    "等照片生成後，你可以用結果下方的 **👗 查看 Nano 服裝** 檢查參考圖，也可直接按 **收藏到衣櫃** 保存。"
                )
            )
        except Exception as exc:
            await status.edit(content=f"⚠️ 臨時穿搭整理失敗：`{str(exc)[:1500]}`")
        return
    if action == "修正":
        ok, result = _update_wardrobe_item_from_command(payload)
        if not ok:
            await ctx.send(f"⚠️ {result}")
            return
        await ctx.send(f"✅ 已修正衣櫃項目：**{result.get('id')} {result.get('name')}** → {result.get('main_category')}/{result.get('sub_category')}", embed=_wardrobe_embed_for_item(result))
        return
    if action == "刪除":
        target = _find_wardrobe_item(payload)
        if not target:
            await ctx.send("找不到要刪除的衣櫃編號。")
            return
        items = [item for item in load_wardrobe() if str(item.get('id')) != str(target.get('id'))]
        save_wardrobe(items)
        await ctx.send(f"🗑️ 已刪除衣櫃項目：**{target.get('id')} {target.get('name')}**")
        return


class _WardrobeMessageCtxAdapter:
    """讓 /衣櫃 可以直接由 on_message 攔截處理，避免 prefix command parser 在部分頻道/手機輸入時無聲失敗。"""
    def __init__(self, message):
        self.message = message
        self.channel = message.channel
        self.author = message.author
        self.guild = getattr(message, "guild", None)

    async def send(self, *args, **kwargs):
        return await self.channel.send(*args, **kwargs)


async def _handle_diary_wardrobe_message_direct(message):
    """
    交換日記快捷指令：
    /交換日記 穿 W011
    /交換日記 穿 W011 文創園區自拍
    /交換日記 衣櫃自由
    /交換日記 衣櫃自由 文創園區自拍
    /交換日記 文創園區自拍
    僅作用於今天的交換日記。
    """
    content = str(getattr(message, "content", "") or "").strip()
    if not re.match(r"^/交換日記(?:\s+|$)", content, flags=re.IGNORECASE):
        return False

    if not _is_girlfriend_xiaoxia_channel(message.channel):
        await message.channel.send("大俠，`/交換日記 ...` 先只開放在女友小俠頻道使用喔。")
        return True

    raw = re.sub(r"^/交換日記(?:\s+|$)", "", content, flags=re.IGNORECASE).strip()
    today = datetime.now(TZ_TPE).strftime("%Y-%m-%d")

    help_text = (
        "大俠，交換日記模式可用：\n"
        "• `/交換日記 穿 W011` → 指定穿 W011，場景自由發揮\n"
        "• `/交換日記 穿 W011 文創園區自拍` → 指定穿 W011，並指定場景\n"
        "• `/交換日記 衣櫃自由` → 小俠自行從衣櫃挑衣，場景自由發揮\n"
        "• `/交換日記 衣櫃自由 文創園區自拍` → 小俠自行從衣櫃挑衣，並指定場景\n"
        "• `/交換日記 文創園區自拍` → 服裝自由發揮，但場景照你指定\n"
        "若沒有下這類指令，今天的交換日記就維持 default 自由發揮。"
    )

    if not raw:
        await message.channel.send(help_text)
        return True

    m = re.match(r"^穿\s+(W\d{3,4})(?:\s+(.+))?$", raw, flags=re.IGNORECASE)
    if m:
        wid = m.group(1).upper()
        scene_request = _clean_text_compact(m.group(2) or "")
        item = _find_wardrobe_item(wid)
        if not item:
            await message.channel.send(f"找不到衣櫃項目 **{wid}**。請先 `/衣櫃` 看看目前有哪些收藏。")
            return True
        ref_path, _ref_url = _wardrobe_reference_for_generation(item)
        if not ref_path:
            await message.channel.send(
                f"⚠️ **{wid} {item.get('name', '')}** 目前沒有可用的本地衣櫃圖片，所以暫時不能指定給今日交換日記。\n"
                f"請先用 `/衣櫃 換圖 {wid}` 更新成可用圖片。"
            )
            return True
        set_diary_wardrobe_pref("specified", wardrobe_id=wid, target_date=today, scene_request=scene_request)
        extra = f"\n📍 場景：{scene_request}" if scene_request else ""
        await message.channel.send(
            f"✅ 已設定 **{today}** 的交換日記指定穿 **{wid} {item.get('name', '')}**。{extra}\n"
            "這個設定只對今天有效，不會改變 `/photo` 目前的已穿狀態。"
        )
        return True

    m = re.match(r"^衣櫃自由(?:\s+(.+))?$", raw, flags=re.IGNORECASE)
    if m:
        scene_request = _clean_text_compact(m.group(1) or "")
        set_diary_wardrobe_pref("free", wardrobe_id="", target_date=today, scene_request=scene_request)
        extra = f"\n📍 場景：{scene_request}" if scene_request else ""
        await message.channel.send(
            f"✅ 已設定 **{today}** 的交換日記為 **衣櫃自由**。{extra}\n"
            "今晚小俠會依當天心情與日記情境，自己從衣櫃挑一件最適合的穿搭。"
        )
        return True

    scene_request = _clean_text_compact(raw)
    # v1481: silently tolerate older wording if the user still types it, but do not expose it in help text.
    scene_request = re.sub(r"^指定場景\s+", "", scene_request).strip()
    if scene_request:
        set_diary_wardrobe_pref("scene_only", wardrobe_id="", target_date=today, scene_request=scene_request)
        await message.channel.send(
            f"✅ 已設定 **{today}** 的交換日記場景：{scene_request}\n"
            "今晚小俠會把這個場景當成硬條件；服裝則由她自由發揮，不受衣櫃限制。"
        )
        return True

    await message.channel.send(help_text)
    return True


async def _handle_wardrobe_message_direct(message):
    """
    /衣櫃 文字指令的保險通道。
    原本也註冊成 discord.py prefix command，但實測有時 process_commands 沒有觸發；
    這裡直接解析 message.content，確保前台一定有回應或錯誤訊息。
    """
    content = str(getattr(message, "content", "") or "").strip()
    if not re.match(r"^/衣櫃(?:\s+|$)", content, flags=re.IGNORECASE):
        return False

    ctx = _WardrobeMessageCtxAdapter(message)
    try:
        if not _is_girlfriend_xiaoxia_channel(message.channel):
            await ctx.send("大俠，`/衣櫃` 先只開放在女友小俠頻道使用喔。")
            return True

        action, payload = _parse_wardrobe_command(content)

        if action == "browse":
            await _send_wardrobe_browse_message(ctx, query="", page=0)
            return True

        if action == "search":
            await _send_wardrobe_browse_message(ctx, query=payload, page=0)
            return True

        if action == "新增":
            await _handle_wardrobe_add_command(ctx, payload, remove_person=False)
            return True

        if action == "去人":
            await _handle_wardrobe_add_command(ctx, payload, remove_person=True)
            return True

        if action == "健檢":
            await _handle_wardrobe_healthcheck(ctx)
            return True

        if action in {"修復圖片", "圖片修復"}:
            await _handle_wardrobe_repair_images(ctx)
            return True

        if action == "換圖":
            await _handle_wardrobe_replace_image_command(ctx, payload, remove_person=False)
            return True

        if action in {"換圖去人", "換圖去人化"}:
            await _handle_wardrobe_replace_image_command(ctx, payload, remove_person=True)
            return True

        if action == "問小俠":
            await _ask_xiaoxia_about_wardrobe(ctx, payload)
            return True

        if action == "看":
            item = _find_wardrobe_item(payload)
            if not item:
                await ctx.send("找不到這個衣櫃編號喔。請先 `/衣櫃` 看看目前有哪些收藏。")
                return True
            await ctx.send(embed=_wardrobe_embed_for_item(item), view=WardrobeApplyView(item))
            return True

        if action == "穿":
            item = _find_wardrobe_item(payload)
            if not item:
                await ctx.send("找不到這個衣櫃編號喔。")
                return True
            _set_pending_wardrobe_state(item)
            await ctx.send(f"✅ 已選定 **{item.get('id')} {item.get('name')}**。下一張 `/photo` 若沒有另外附衣服圖，就會優先套用這件。")
            return True

        if action == "修正":
            ok, result = _update_wardrobe_item_from_command(payload)
            if not ok:
                await ctx.send(f"⚠️ {result}")
                return True
            await ctx.send(
                f"✅ 已修正衣櫃項目：**{result.get('id')} {result.get('name')}** → {result.get('main_category')}/{result.get('sub_category')}",
                embed=_wardrobe_embed_for_item(result),
            )
            return True

        if action == "刪除":
            target = _find_wardrobe_item(payload)
            if not target:
                await ctx.send("找不到要刪除的衣櫃編號。")
                return True
            items = [item for item in load_wardrobe() if str(item.get('id')) != str(target.get('id'))]
            save_wardrobe(items)
            await ctx.send(f"🗑️ 已刪除衣櫃項目：**{target.get('id')} {target.get('name')}**")
            return True

        await ctx.send("大俠，這個 `/衣櫃` 指令我看不懂。可用：`/衣櫃`、`/衣櫃看 W001`、`/衣櫃穿 W001`、`/衣櫃 新增 名稱`、`/衣櫃 換圖 W001`、`/衣櫃 健檢`、`/衣櫃 修復圖片`。")
        return True

    except Exception as exc:
        print(f"⚠️ [WARDROBE_DIRECT_HANDLER_FAILED] {type(exc).__name__}: {exc}")
        traceback.print_exc()
        try:
            await ctx.send(f"⚠️ `/衣櫃` 發生錯誤：`{str(exc)[:1200]}`")
        except Exception:
            pass
        return True



