async def _send_discord_chunks(send_target, content, *, prefix="", limit=1900):
    """Send long Discord text safely, keeping each message under 2000 chars."""
    text = str(content or "")
    if not text:
        return []
    sent = []
    max_len = max(500, min(int(limit or 1900), 1900))
    chunks = []
    current = ""
    for line in text.splitlines(True):
        if len(line) > max_len:
            if current:
                chunks.append(current)
                current = ""
            for i in range(0, len(line), max_len):
                chunks.append(line[i:i+max_len])
            continue
        if len(current) + len(line) > max_len:
            chunks.append(current)
            current = line
        else:
            current += line
    if current:
        chunks.append(current)
    for idx, chunk in enumerate(chunks):
        body = (prefix if idx == 0 else "") + chunk
        if len(body) > 1990:
            body = body[:1980] + "…"
        sent.append(await send_target.send(body))
    return sent


def _cosplay_record_time_key(record):
    """v1.4.98: sort cosplay records by actual timestamp, not list insertion order."""
    if not isinstance(record, dict):
        return datetime.min.replace(tzinfo=TZ_TPE)
    candidates = [
        record.get("publish_date"),
        record.get("created_at"),
        record.get("updated_at"),
        record.get("timestamp"),
        record.get("date"),
    ]
    for raw in candidates:
        text = str(raw or "").strip()
        if not text:
            continue
        normalized = text.replace("/", "-").replace(".", "-")
        normalized = re.sub(r"\s+", " ", normalized)
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
            try:
                dt = datetime.strptime(normalized[:19] if fmt.endswith('%S') else normalized[:16] if fmt.endswith('%M') else normalized[:10], fmt)
                return dt.replace(tzinfo=TZ_TPE)
            except Exception:
                pass
        m = re.search(r"(\d{4})[-.\/](\d{1,2})[-.\/](\d{1,2})(?:[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?", text)
        if m:
            try:
                year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
                hour = int(m.group(4) or 0)
                minute = int(m.group(5) or 0)
                second = int(m.group(6) or 0)
                return datetime(year, month, day, hour, minute, second, tzinfo=TZ_TPE)
            except Exception:
                pass
    return datetime.min.replace(tzinfo=TZ_TPE)


def _vault_record_delete_label(record):
    """金庫刪除清單的人類可讀摘要；寫真完整 prompt 仍留在原始紀錄。"""
    if not isinstance(record, dict):
        return "未命名紀錄"

    record_type = str(record.get("type") or "").strip().lower()
    album_type = str(record.get("album_type") or "").strip().lower()
    source_mode = str(record.get("source_mode") or "").strip().lower()
    is_photobook = record_type == "photobook" or album_type == "photobook" or source_mode.startswith("photobook")

    if not is_photobook:
        return str(record.get("topic") or record.get("event") or "未命名 cosplay").strip()

    raw_topic = _clean_text_compact(record.get("topic") or "")
    raw_topic = re.sub(r"^【Photo】\s*", "", raw_topic, flags=re.IGNORECASE)
    # 舊寫真把整段技術 prompt 寫進 topic；只保留第一段大俠實際指定的拍攝內容。
    scene = re.split(
        r"Suggested photographic treatment for this shot:|PHOTOBOOK SESSION LOCK:",
        raw_topic,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" ，。｜|")
    if not scene:
        scene = _clean_text_compact(record.get("album_title") or record.get("composition") or "今日寫真")
    if len(scene) > 72:
        scene = scene[:72].rstrip(" ，。｜|") + "…"

    wardrobe_id = str(record.get("wardrobe_id") or "").strip().upper()
    wardrobe_name = _clean_text_compact(record.get("wardrobe_name") or "")
    if wardrobe_id and not wardrobe_name:
        try:
            wardrobe_item = _find_wardrobe_item(wardrobe_id)
            if isinstance(wardrobe_item, dict):
                wardrobe_name = _clean_text_compact(wardrobe_item.get("name") or "")
        except Exception:
            wardrobe_name = ""

    wardrobe_label = ""
    if wardrobe_id:
        wardrobe_label = f"｜{wardrobe_id}{(' ' + wardrobe_name) if wardrobe_name else ''}"
    return f"【寫真】{scene}{wardrobe_label}"


async def _cosplay_delete_flow(send_target, author, channel, date_str: str = None, raw_content: str = ""):
    """v1.4.96: shared implementation for prefix command and direct on_message fallback."""
    db = load_memory()
    if not db:
        await send_target.send("❓ 金庫目前是空的！")
        return

    raw_date = str(date_str or "").strip()
    if not raw_date and raw_content:
        m = re.search(r"^\s*/cosplay_delete(?:\s+([^\s]+))?", str(raw_content or ""), flags=re.IGNORECASE)
        if m:
            raw_date = str(m.group(1) or "").strip()

    if raw_date:
        search_date = _normalize_command_date(raw_date)
        if not search_date:
            await send_target.send("⚠️ 日期格式錯誤。請使用：`/cosplay_delete 2026.07.20` 或 `/cosplay_delete 2026-7-20`")
            return
        matching_records = [
            (idx, rec)
            for idx, rec in enumerate(db)
            if str(rec.get("publish_date") or "").startswith(search_date)
        ]
        matching_records.sort(key=lambda pair: _cosplay_record_time_key(pair[1]), reverse=True)
        msg_prefix = f"📅 找到 {search_date} 的紀錄（新到舊）："
    else:
        matching_records = list(enumerate(db))
        matching_records.sort(key=lambda pair: _cosplay_record_time_key(pair[1]), reverse=True)
        matching_records = matching_records[:5]
        msg_prefix = f"📅 這是金庫最新的 {len(matching_records)} 筆紀錄（新到舊）："

    if not matching_records:
        await send_target.send("找不到符合的紀錄喔！(格式範例: `/cosplay_delete 2026.07.20` 或 `/cosplay_delete 2026-7-20`)")
        return

    msg_content = (
        f"{msg_prefix}\n"
        f"大俠，你要刪除哪幾組圖文？可單選或複選：\n"
        f"- 單筆：`2`\n"
        f"- 複選：`1,3,5` 或 `1 3 5`\n"
        f"- 連續：`2-4`\n"
        f"- 混合：`1,3-5`\n"
        f"輸入 `c` 取消。可選範圍：1-{len(matching_records)}\n\n"
    )
    for i, (original_idx, record) in enumerate(matching_records):
        topic = _vault_record_delete_label(record)
        publish_date = str(record.get('publish_date') or '')
        msg_content += f"**{i+1}.** {topic} *(時間: {publish_date})*\n"

    await _send_discord_chunks(send_target, msg_content)

    def check(m):
        return m.author == author and m.channel == channel

    pending_inputs.add(author.id)
    try:
        msg = await girlfriend_bot.wait_for('message', timeout=60.0, check=check)
    except asyncio.TimeoutError:
        await send_target.send("⏳ 超過 60 秒未回覆，刪除操作已自動取消。")
        return
    finally:
        pending_inputs.discard(author.id)

    raw_choice = str(msg.content or "").strip()
    if raw_choice.lower() == 'c':
        await send_target.send("✅ 已取消刪除。")
        return

    def _parse_delete_choices(raw_text: str, max_choice: int):
        normalized = re.sub(r"[，、;；]+", ",", str(raw_text or "").strip())
        normalized = re.sub(r"\s+", ",", normalized)
        tokens = [t.strip() for t in normalized.split(",") if t.strip()]
        if not tokens:
            raise ValueError("empty")

        selected = set()
        for token in tokens:
            range_match = re.fullmatch(r"(\d+)\s*[-~～]\s*(\d+)", token)
            if range_match:
                start_num = int(range_match.group(1))
                end_num = int(range_match.group(2))
                if start_num > end_num:
                    start_num, end_num = end_num, start_num
                if start_num < 1 or end_num > max_choice:
                    raise IndexError("out_of_range")
                selected.update(range(start_num, end_num + 1))
                continue

            if not re.fullmatch(r"\d+", token):
                raise ValueError("bad_token")
            number = int(token)
            if number < 1 or number > max_choice:
                raise IndexError("out_of_range")
            selected.add(number)

        return sorted(selected)

    try:
        selected_numbers = _parse_delete_choices(raw_choice, len(matching_records))
    except IndexError:
        await send_target.send(f"⚠️ 選項超出範圍，請輸入 1-{len(matching_records)} 之間的數字；刪除操作已取消。")
        return
    except ValueError:
        await send_target.send("⚠️ 格式錯誤。可輸入 `2`、`1,3,5`、`2-4` 或 `1,3-5`；刪除操作已取消。")
        return

    # matching_records 是顯示順序；真正刪除 db 時必須依原始 index 由大到小，避免前一筆 pop 後 index 位移。
    selected_pairs = [matching_records[number - 1] for number in selected_numbers]
    selected_pairs.sort(key=lambda pair: pair[0], reverse=True)

    deleted_records = []
    for target_idx, _record in selected_pairs:
        if 0 <= target_idx < len(db):
            deleted_record = db.pop(target_idx)
            deleted_records.append(deleted_record)

    if not deleted_records:
        await send_target.send("⚠️ 沒有成功選到可刪除的紀錄，操作已取消。")
        return

    save_memory(db)

    removed_files = 0
    for deleted_record in deleted_records:
        local_url = str(deleted_record.get("local_url") or "")
        if local_url:
            filename = local_url.split("/")[-1]
            filepath = os.path.join(OUTPUT_DIR, filename)
            if os.path.exists(filepath):
                try:
                    os.remove(filepath)
                    removed_files += 1
                except Exception as exc:
                    print(f"⚠️ [COSPLAY_DELETE_FILE_FAILED] {type(exc).__name__}: {exc} | {filepath}")

    deleted_records.reverse()  # 回復成使用者選擇的顯示順序，方便閱讀。
    deleted_labels = [
        _vault_record_delete_label(record)
        for record in deleted_records
    ]
    if len(deleted_labels) == 1:
        await send_target.send(
            f"🗑️ 成功銷毀：**{deleted_labels[0]}** "
            f"(文字紀錄已刪除；圖片檔案已同步處理)"
        )
    else:
        summary_lines = "\n".join(f"- {label}" for label in deleted_labels[:20])
        extra = "" if len(deleted_labels) <= 20 else f"\n…另有 {len(deleted_labels) - 20} 筆"
        await send_target.send(
            f"🗑️ 已批次銷毀 **{len(deleted_labels)} 筆**紀錄：\n"
            f"{summary_lines}{extra}\n"
            f"📁 同步刪除本地圖片檔案：{removed_files} 個"
        )


async def _handle_cosplay_delete_message_direct(message):
    """v1.4.96: direct fallback because discord.py command parser can silently skip underscore command on some mobile/channel paths."""
    raw = str(getattr(message, "content", "") or "").strip()
    if not re.match(r"^/cosplay_delete(?:\s|$)", raw, flags=re.IGNORECASE):
        return False
    m = re.match(r"^/cosplay_delete(?:\s+([^\s]+))?", raw, flags=re.IGNORECASE)
    date_str = (m.group(1).strip() if m and m.group(1) else None)
    try:
        await _cosplay_delete_flow(message.channel, message.author, message.channel, date_str=date_str, raw_content=raw)
    except Exception as exc:
        print(f"⚠️ [COSPLAY_DELETE_DIRECT_FAILED] {type(exc).__name__}: {exc}")
        traceback.print_exc()
        await message.channel.send(f"⚠️ `/cosplay_delete` 發生錯誤：`{str(exc)[:1200]}`")
    return True


