# ==========================================
# 🌱 v1.5.20 小俠自主自動活動排程
# ==========================================
def _autonomy_auto_control_state(state=None, now_dt=None):
    state = state if isinstance(state, dict) else load_xiaoxia_autonomy_state()
    now_dt = now_dt or datetime.now(TZ_TPE)
    today_key = now_dt.strftime("%Y-%m-%d")
    auto_enabled = bool(state.get("auto_enabled_override", True))
    pause_until = str(state.get("auto_pause_until") or "").strip()
    paused = False
    reason = ""
    if not auto_enabled:
        paused = True
        reason = "manual_off"
    elif pause_until:
        try:
            pause_date = datetime.strptime(pause_until, "%Y-%m-%d").date()
            if now_dt.date() <= pause_date:
                paused = True
                reason = f"paused_until_{pause_until}"
            else:
                # 到期自動清掉，避免狀態永遠掛著舊字串。
                state["auto_pause_until"] = ""
                state["auto_pause_days"] = 0
                state["auto_pause_reason"] = ""
                state["auto_pause_expired_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
                save_xiaoxia_autonomy_state(state)
        except Exception:
            state["auto_pause_until"] = ""
            save_xiaoxia_autonomy_state(state)
    return {
        "auto_enabled": auto_enabled,
        "pause_until": state.get("auto_pause_until") or "",
        "paused": paused,
        "reason": reason,
        "today": today_key,
    }


def _parse_autonomy_pause_days(text):
    raw = str(text or "").strip()
    if not raw:
        return 1
    m = re.search(r"(\d{1,3})", raw)
    if not m:
        return 1
    days = int(m.group(1))
    return max(1, min(days, 30))


def _parse_autonomy_manual_schedule_times(text, now_dt=None, max_items=6):
    """v1.5.22：解析 `/小俠自主 指定排程 14:00, 16:20, 18:00`。"""
    now_dt = now_dt or datetime.now(TZ_TPE)
    raw = str(text or "").strip()
    raw = raw.replace("，", ",").replace("、", ",").replace("；", ",").replace(";", ",")
    pieces = [x.strip() for x in re.split(r"[,\s]+", raw) if x.strip()]
    times = []
    errors = []
    seen = set()

    for token in pieces:
        m = re.fullmatch(r"(?:今天)?(\d{1,2})[:：](\d{2})", token)
        if not m:
            errors.append(f"`{token}` 不是 HH:MM 格式")
            continue
        hh = int(m.group(1))
        mm = int(m.group(2))
        if not (0 <= hh <= 23 and 0 <= mm <= 59):
            errors.append(f"`{token}` 超出 00:00～23:59")
            continue
        t = f"{hh:02d}:{mm:02d}"
        if t not in seen:
            seen.add(t)
            times.append(t)

    times = sorted(times)
    if len(times) > max_items:
        errors.append(f"最多只能指定 {max_items} 個時段，已忽略第 {max_items + 1} 個以後。")
        times = times[:max_items]
    return times, errors


def _autonomy_manual_schedule_slots(times, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    rows = []
    for idx, t in enumerate(times or [], 1):
        try:
            hh, mm = [int(x) for x in str(t).split(":", 1)]
            slot_dt = now_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
        except Exception:
            continue
        status = "pending"
        note = ""
        # 手動指定只排今天。已經過去的時間不補發，避免一設定就連發舊時段。
        if slot_dt <= now_dt:
            status = "skipped_past_time"
            note = "指定時段已過，不補發。"
        rows.append({
            "id": f"MANUAL_SLOT_{now_dt.strftime('%Y%m%d')}_{idx:02d}",
            "time": f"{hh:02d}:{mm:02d}",
            "status": status,
            "manual": True,
            "note": note,
            "created_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        })
    return rows


def _mark_autonomy_scheduler_cancelled(state, reason="manual_pause_or_off"):
    if not isinstance(state, dict):
        return state
    scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
    if scheduler:
        for slot in scheduler.get("slots") or []:
            if isinstance(slot, dict) and slot.get("status") == "pending":
                slot["status"] = "cancelled"
                slot["cancelled_reason"] = reason
                slot["cancelled_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        scheduler["updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        state["auto_scheduler"] = scheduler
    return state


def _clear_autonomy_auto_schedule(state):
    if isinstance(state, dict):
        state["auto_scheduler"] = {}
    return state


def _get_xiaoxia_autonomy_channel_for_auto():
    channel = None
    if XIAOXIA_AUTONOMY_CHANNEL_ID:
        try:
            channel = girlfriend_bot.get_channel(int(XIAOXIA_AUTONOMY_CHANNEL_ID))
        except Exception:
            channel = None
    if channel is None:
        channel = discord.utils.get(girlfriend_bot.get_all_channels(), name=XIAOXIA_AUTONOMY_CHANNEL_NAME)
    return channel


def _autonomy_proxy_message_to_channel(message, target_channel):
    """v1.5.24：/小俠自主 可從任一女友小俠頻道輸入，但主要回應統一送到主生活頻道。"""
    proxy = type("AutonomyRoutedMessage", (), {})()
    for attr in ("author", "content", "attachments", "guild", "id", "created_at"):
        try:
            setattr(proxy, attr, getattr(message, attr))
        except Exception:
            pass
    proxy.channel = target_channel
    return proxy


def _autonomy_normalize_ad_hoc_title(title):
    title = _clean_text_compact(title or "")
    title = re.sub(r"^[「『\\\"']+|[」』\\\"']+$", "", title).strip()
    title = re.sub(r"\s+", " ", title).strip()
    return title


def _autonomy_ad_hoc_theme_key(title):
    """自由文字活動的主題線 key；同名或明顯同類活動下次可延續，不從空白開始。"""
    t = _autonomy_normalize_ad_hoc_title(title)
    hay = t.lower()
    if "大學" in t and "同學" in t and any(k in t for k in ("會", "聚", "吃飯", "見面")):
        return "adhoc_college_classmates"
    if any(k in t for k in ("書展", "書市", "書店活動")):
        return "adhoc_book_fair"
    if any(k in t for k in ("寵物展", "貓展", "狗展", "寵物市集")):
        return "adhoc_pet_expo"
    if any(k in t for k in ("潛水", "潜水", "diving", "浮潛", "水肺")):
        return "adhoc_diving"
    safe = re.sub(r"[^A-Za-z0-9_\u4e00-\u9fff]+", "_", t).strip("_")
    if len(safe) > 40:
        safe = safe[:40].strip("_")
    return "adhoc_" + (safe or "specified_activity")


def _autonomy_classify_ad_hoc_activity(title):
    t = _autonomy_normalize_ad_hoc_title(title)
    if any(k in t for k in ("潛水", "潜水", "浮潛", "水肺", "健身", "瑜珈", "瑜伽", "跑步", "網球", "羽球", "游泳")):
        return "運動健康", "public_sport"
    if any(k in t for k in ("書展", "畫展", "展覽", "美術館", "博物館", "音樂會", "演奏會", "劇場", "電影")):
        return "藝文活動", "public_culture"
    if any(k in t for k in ("同學", "朋友", "聚會", "同學會", "餐敘", "聚餐")):
        return "社交但安全", "public_social"
    if any(k in t for k in ("家", "居家", "房間", "臥室", "書房", "客廳", "料理", "烘焙")):
        return "居家生活", "home_private"
    if any(k in t for k in ("上課", "學習", "課程", "研習", "講座")):
        return "學習成長", "public_learning"
    return "大俠指定活動", "public"


def _autonomy_make_ad_hoc_activity(title, raw_query=""):
    title = _autonomy_normalize_ad_hoc_title(title)
    category, location_type = _autonomy_classify_ad_hoc_activity(title)
    theme_key = _autonomy_ad_hoc_theme_key(title)
    safe_id_tail = re.sub(r"[^A-Za-z0-9_\u4e00-\u9fff]+", "_", title).strip("_")[:24].strip("_") or "activity"
    now_dt = datetime.now(TZ_TPE)
    return {
        "id": f"ADHOC_{now_dt.strftime('%Y%m%d')}_{safe_id_tail}",
        "title": title,
        "category": category,
        "source": "daxia_specified_activity",
        "activity_mode": "ad_hoc",
        "location_type": location_type,
        "activity_tags": [title, "大俠指定活動", category],
        "theme_key": theme_key,
        "continuity_group": theme_key,
        "photo_prompt_seed": f"小俠今天去「{title}」，用成熟自然的生活感拍下一張能讓大俠理解現場氣氛的照片；畫面要清楚呈現活動環境、她正在做的事、當下心情與服裝選擇。",
        "event_upgrade_potential": f"大俠手動指定活動：{title}",
        "raw_query": raw_query,
    }


def _autonomy_resolve_or_create_activity(query, message=None, catalog=None):
    q = _autonomy_normalize_ad_hoc_title(query)
    if not q:
        return None, False
    activity = _autonomy_resolve_activity(q, message=message, catalog=catalog or load_xiaoxia_activity_catalog())
    if activity:
        item = dict(activity)
        item.setdefault("activity_mode", "catalog")
        return item, False
    return _autonomy_make_ad_hoc_activity(q, raw_query=query), True


def _parse_autonomy_specified_activity_request(query):
    """解析：指定活動 自由文字 [Wxxx] [now|現在|立即|馬上|HH:MM]。
    - Wxxx 可出現在任意位置，不必寫「指定衣櫃」。
    - HH:MM 與 Wxxx 的順序可對調。
    """
    raw = str(query or "").strip()
    if not raw:
        return {"activity_text": "", "timing_mode": "", "time": "", "wardrobe_id": "", "error": "missing_activity"}

    working = raw

    wardrobe_ids = _extract_wardrobe_ids_from_text(working)
    wardrobe_id = wardrobe_ids[0] if wardrobe_ids else ""
    if wardrobe_id:
        working = re.sub(r"\b" + re.escape(wardrobe_id) + r"\b", " ", working, count=1, flags=re.IGNORECASE)

    now_match = re.search(r"(?<!\S)(now|現在|立即|馬上)(?!\S)", working, flags=re.IGNORECASE)
    has_now = bool(now_match)
    if has_now:
        working = re.sub(r"(?<!\S)(now|現在|立即|馬上)(?!\S)", " ", working, count=1, flags=re.IGNORECASE)

    time_match = re.search(r"(?<!\S)([01]?\d|2[0-3]):([0-5]\d)(?!\S)", working)
    time_text = ""
    if time_match:
        hh = int(time_match.group(1))
        mm = int(time_match.group(2))
        time_text = f"{hh:02d}:{mm:02d}"
        working = re.sub(r"(?<!\S)([01]?\d|2[0-3]):([0-5]\d)(?!\S)", " ", working, count=1)

    activity_text = _autonomy_normalize_ad_hoc_title(working)
    if not activity_text:
        return {"activity_text": "", "timing_mode": "", "time": time_text, "wardrobe_id": wardrobe_id, "error": "missing_activity"}

    timing_mode = "auto"
    if has_now:
        timing_mode = "now"
    elif time_text:
        timing_mode = "time"

    return {
        "activity_text": activity_text,
        "timing_mode": timing_mode,
        "time": time_text,
        "wardrobe_id": wardrobe_id,
        "error": "",
    }


def _autonomy_slot_dt_today(time_text, now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    try:
        hh, mm = [int(x) for x in str(time_text or "").split(":", 1)]
        return now_dt.replace(hour=hh, minute=mm, second=0, microsecond=0)
    except Exception:
        return None


def _autonomy_sort_slots(slots):
    def key(item):
        dt = _autonomy_slot_dt_today((item or {}).get("time"))
        return dt or datetime.max.replace(tzinfo=TZ_TPE)
    return sorted([s for s in (slots or []) if isinstance(s, dict)], key=key)


def _autonomy_make_specified_activity_slot(activity, time_text, now_dt=None, scheduled_by="daxia", wardrobe_item=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    activity = _autonomy_enrich_activity(activity)
    mode = str(activity.get("activity_mode") or ("catalog" if not str(activity.get("id") or "").startswith("ADHOC_") else "ad_hoc"))
    wardrobe_id = ""
    wardrobe_name = ""
    if isinstance(wardrobe_item, dict):
        wardrobe_id = str(wardrobe_item.get("id") or "").strip().upper()
        wardrobe_name = str(wardrobe_item.get("name") or "").strip()
    return {
        "id": f"MANUAL_ACTIVITY_{now_dt.strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}",
        "time": str(time_text),
        "status": "pending",
        "manual": True,
        "manual_kind": "specified_activity",
        "activity_mode": mode,
        "activity_id": str(activity.get("id") or ""),
        "activity_title": str(activity.get("title") or ""),
        "activity_category": str(activity.get("category") or ""),
        "theme_key": _autonomy_theme_key_for_activity(activity),
        "source": "daxia_specified_activity",
        "scheduled_by": scheduled_by,
        "created_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        "specified_wardrobe_id": wardrobe_id,
        "specified_wardrobe_name": wardrobe_name,
    }


def _autonomy_find_auto_time_for_manual_activity(slots, now_dt=None, min_gap_minutes=60):
    """替未給時間的手動指定活動找今天剩餘可用時間；與 pending/running slot 至少間隔 1 小時。"""
    now_dt = now_dt or datetime.now(TZ_TPE)
    start_hour = int(XIAOXIA_AUTONOMY_ACTIVE_START_HOUR)
    end_hour = int(XIAOXIA_AUTONOMY_ACTIVE_END_HOUR)
    if end_hour <= start_hour:
        end_hour = min(23, start_hour + 1)
    start_dt = now_dt.replace(hour=start_hour, minute=0, second=0, microsecond=0)
    end_dt = now_dt.replace(hour=end_hour, minute=0, second=0, microsecond=0)
    earliest = max(start_dt, now_dt + timedelta(minutes=10))
    if earliest > end_dt:
        return None

    occupied = []
    for s in slots or []:
        if not isinstance(s, dict):
            continue
        if str(s.get("status") or "") not in {"pending", "running"}:
            continue
        dt = _autonomy_slot_dt_today(s.get("time"), now_dt=now_dt)
        if dt:
            occupied.append(dt)

    # 以 10 分鐘為單位，讓時間看起來比較自然；候選隨機，避免每天機械排整點。
    start_min = ((earliest.hour * 60 + earliest.minute + 9) // 10) * 10
    end_min = end_dt.hour * 60 + end_dt.minute
    candidates = []
    for minute in range(start_min, end_min + 1, 10):
        dt = now_dt.replace(hour=minute // 60, minute=minute % 60, second=0, microsecond=0)
        if all(abs((dt - used).total_seconds()) >= min_gap_minutes * 60 for used in occupied):
            candidates.append(dt)
    if not candidates:
        return None
    random.shuffle(candidates)
    chosen = sorted(candidates[:min(6, len(candidates))])[0] if len(candidates) > 1 else candidates[0]
    return chosen.strftime("%H:%M")


def _autonomy_add_specified_activity_slot(activity, time_text=None, now_dt=None, auto_pick=False, wardrobe_item=None):
    """新增一個大俠指定活動 slot；不覆蓋既有 auto slots，也不受 daily_limit 限制。"""
    now_dt = now_dt or datetime.now(TZ_TPE)
    state = load_xiaoxia_autonomy_state()
    scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
    if scheduler.get("date") != now_dt.strftime("%Y-%m-%d"):
        scheduler = _autonomy_ensure_auto_schedule(now_dt)
        state = load_xiaoxia_autonomy_state()
    slots = scheduler.get("slots") if isinstance(scheduler.get("slots"), list) else []

    if auto_pick:
        time_text = _autonomy_find_auto_time_for_manual_activity(slots, now_dt=now_dt, min_gap_minutes=60)
        if not time_text:
            return None, "today_time_not_enough"
    else:
        slot_dt = _autonomy_slot_dt_today(time_text, now_dt=now_dt)
        if not slot_dt:
            return None, "invalid_time"
        if slot_dt <= now_dt:
            return None, "time_passed"

    slot = _autonomy_make_specified_activity_slot(activity, time_text, now_dt=now_dt, wardrobe_item=wardrobe_item)
    slots.append(slot)
    scheduler["slots"] = _autonomy_sort_slots(slots)
    scheduler["date"] = now_dt.strftime("%Y-%m-%d")
    scheduler["manual_activity_slots"] = True
    scheduler["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
    # 不改變大俠原本的自動排程開/關狀態；即使自動排程關閉，手動指定活動 slot 仍會被排程任務處理。
    state["auto_scheduler"] = scheduler
    save_xiaoxia_autonomy_state(state)
    return slot, ""



def _autonomy_pending_manual_activity_slots(state=None, now_dt=None):
    """回傳今日仍可取消的手動指定活動 slots，依時間排序。"""
    now_dt = now_dt or datetime.now(TZ_TPE)
    if not isinstance(state, dict):
        state = load_xiaoxia_autonomy_state()
    scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
    if scheduler.get("date") != now_dt.strftime("%Y-%m-%d"):
        return []
    rows = []
    for slot in (scheduler.get("slots") or []):
        if not isinstance(slot, dict):
            continue
        if slot.get("manual_kind") != "specified_activity":
            continue
        if str(slot.get("status") or "") != "pending":
            continue
        rows.append(slot)
    return _autonomy_sort_slots(rows)


def _autonomy_cancel_manual_activity_slot(index, now_dt=None):
    """以今日 pending 手動指定活動的 1-based 編號取消單筆 slot；保留取消紀錄。"""
    now_dt = now_dt or datetime.now(TZ_TPE)
    state = load_xiaoxia_autonomy_state()
    scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
    if scheduler.get("date") != now_dt.strftime("%Y-%m-%d"):
        return None, "no_pending_manual_activity"

    pending = _autonomy_pending_manual_activity_slots(state=state, now_dt=now_dt)
    try:
        idx = int(index)
    except Exception:
        return None, "invalid_index"
    if idx < 1 or idx > len(pending):
        return None, "index_out_of_range"

    target = pending[idx - 1]
    target_id = str(target.get("id") or "")
    found = None
    for slot in (scheduler.get("slots") or []):
        if isinstance(slot, dict) and str(slot.get("id") or "") == target_id:
            slot["status"] = "cancelled_by_daxia"
            slot["cancelled_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            slot["cancelled_by"] = "daxia_command"
            found = slot
            break
    if not found:
        return None, "slot_not_found"

    scheduler["manual_activity_slots"] = any(
        isinstance(s, dict)
        and s.get("manual_kind") == "specified_activity"
        and str(s.get("status") or "") in {"pending", "running"}
        for s in (scheduler.get("slots") or [])
    )
    scheduler["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
    state["auto_scheduler"] = scheduler
    save_xiaoxia_autonomy_state(state)
    return found, ""


def _autonomy_generate_auto_slots(now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    count = int(XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT or 0)
    if count <= 0:
        return []
    start_hour = int(XIAOXIA_AUTONOMY_ACTIVE_START_HOUR)
    end_hour = int(XIAOXIA_AUTONOMY_ACTIVE_END_HOUR)
    if end_hour <= start_hour:
        end_hour = min(23, start_hour + 1)
    min_gap_minutes = max(60, int(XIAOXIA_AUTONOMY_MIN_INTERVAL_HOURS or 2) * 60)

    start_dt = now_dt.replace(hour=start_hour, minute=0, second=0, microsecond=0)
    end_dt = now_dt.replace(hour=end_hour, minute=0, second=0, microsecond=0)
    earliest = start_dt
    if now_dt.date() == start_dt.date():
        earliest = max(start_dt, now_dt + timedelta(minutes=10))
    if earliest > end_dt:
        return []

    available_minutes = int((end_dt - earliest).total_seconds() // 60)
    max_count_by_gap = max(1, available_minutes // min_gap_minutes + 1)
    count = max(0, min(count, max_count_by_gap, 6))
    if count <= 0:
        return []

    slots = []
    for _ in range(200):
        candidates = sorted(random.randint(0, max(0, available_minutes)) for __ in range(count))
        if all((candidates[i] - candidates[i-1]) >= min_gap_minutes for i in range(1, len(candidates))):
            slots = candidates
            break
    if not slots:
        slots = [min(available_minutes, i * min_gap_minutes) for i in range(count)]

    rows = []
    for idx, minute_offset in enumerate(slots, 1):
        t = earliest + timedelta(minutes=int(minute_offset))
        rows.append({
            "id": f"AUTO_SLOT_{now_dt.strftime('%Y%m%d')}_{idx:02d}",
            "time": t.strftime("%H:%M"),
            "status": "pending",
            "created_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
        })
    return rows


def _autonomy_schedule_config_snapshot():
    return {
        "daily_limit": int(XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT or 0),
        "min_interval_hours": int(XIAOXIA_AUTONOMY_MIN_INTERVAL_HOURS or 2),
        "active_start_hour": int(XIAOXIA_AUTONOMY_ACTIVE_START_HOUR),
        "active_end_hour": int(XIAOXIA_AUTONOMY_ACTIVE_END_HOUR),
        "channel_id": int(XIAOXIA_AUTONOMY_CHANNEL_ID or 0),
        "channel_name": XIAOXIA_AUTONOMY_CHANNEL_NAME,
        "timezone": "UTC+8/Taipei",
    }


def _autonomy_schedule_config_changed(scheduler, expected):
    if not isinstance(scheduler, dict):
        return True
    for key, value in expected.items():
        if scheduler.get(key) != value:
            return True
    return False


def _autonomy_slot_time_in_active_window(slot_time):
    try:
        hh, _mm = [int(x) for x in str(slot_time or "").split(":", 1)]
    except Exception:
        return False
    start_hour = int(XIAOXIA_AUTONOMY_ACTIVE_START_HOUR)
    end_hour = int(XIAOXIA_AUTONOMY_ACTIVE_END_HOUR)
    return start_hour <= hh <= end_hour


def _autonomy_ensure_auto_schedule(now_dt=None):
    now_dt = now_dt or datetime.now(TZ_TPE)
    date_key = now_dt.strftime("%Y-%m-%d")
    state = load_xiaoxia_autonomy_state()
    scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
    expected = _autonomy_schedule_config_snapshot()
    # v1.5.22：大俠手動指定整日排程時，當天不被亂數排程覆蓋。
    if scheduler.get("date") == date_key and scheduler.get("manual_schedule"):
        return scheduler

    should_rebuild = (
        scheduler.get("date") != date_key
        or _autonomy_schedule_config_changed(scheduler, expected)
    )
    if should_rebuild:
        old_slots = scheduler.get("slots") if isinstance(scheduler.get("slots"), list) else []
        # v1.5.24：env 改變或 daily_limit=0 重建時，保留今天尚未完成的大俠指定活動 slots。
        manual_activity_slots = []
        if scheduler.get("date") == date_key:
            for s in old_slots:
                if isinstance(s, dict) and s.get("manual_kind") == "specified_activity" and s.get("status") in {"pending", "running"}:
                    manual_activity_slots.append(s)
        auto_slots = _autonomy_generate_auto_slots(now_dt) if int(XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT or 0) > 0 else []
        scheduler = {
            "date": date_key,
            **expected,
            "slots": _autonomy_sort_slots(auto_slots + manual_activity_slots),
            "manual_activity_slots": bool(manual_activity_slots),
            "updated_at": now_dt.strftime("%Y-%m-%d %H:%M:%S"),
            "rebuilt_reason": "date_or_env_config_changed",
        }
        state["auto_scheduler"] = scheduler
        save_xiaoxia_autonomy_state(state)
        print(f"🌱 [AUTONOMY_AUTO_SCHEDULE_CREATED] date={date_key} config={expected} slots={scheduler.get('slots')}")
    return scheduler


@tasks.loop(minutes=10)
async def xiaoxia_autonomy_auto_task():
    now_dt = datetime.now(TZ_TPE)
    state = load_xiaoxia_autonomy_state()

    # v1.5.24：任務即使 daily_limit=0 也要運作，因為大俠可能安排手動指定活動 slot。
    if int(XIAOXIA_AUTONOMY_DAILY_ACTIVITY_LIMIT or 0) > 0:
        scheduler = _autonomy_ensure_auto_schedule(now_dt)
        state = load_xiaoxia_autonomy_state()
    else:
        scheduler = state.get("auto_scheduler") if isinstance(state.get("auto_scheduler"), dict) else {}
        if scheduler.get("date") != now_dt.strftime("%Y-%m-%d"):
            scheduler = _autonomy_ensure_auto_schedule(now_dt)
            state = load_xiaoxia_autonomy_state()

    slots = scheduler.get("slots") if isinstance(scheduler.get("slots"), list) else []
    control = _autonomy_auto_control_state(state, now_dt)
    due = []
    changed_slots = False
    for item in slots:
        if not isinstance(item, dict) or item.get("status") != "pending":
            continue
        is_manual_activity = item.get("manual_kind") == "specified_activity"
        # v1.5.20-R3：若舊排程殘留在目前環境變數的允許時段外，直接跳過，不補發。
        # v1.5.22：但大俠手動指定整日排程時，以大俠指定時間為準，不套用 env window。
        # v1.5.24：大俠指定活動 slot 也不套用 env window；大俠指定優先。
        if (not scheduler.get("manual_schedule")) and (not is_manual_activity) and not _autonomy_slot_time_in_active_window(item.get("time")):
            item["status"] = "skipped_outside_active_window"
            item["skipped_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
            item["active_window"] = f"{XIAOXIA_AUTONOMY_ACTIVE_START_HOUR:02d}:00-{XIAOXIA_AUTONOMY_ACTIVE_END_HOUR:02d}:00"
            changed_slots = True
            print(f"🌱 [AUTONOMY_SLOT_SKIPPED_OUTSIDE_WINDOW] slot={item.get('time')} window={item.get('active_window')}")
            continue
        slot_dt = _autonomy_slot_dt_today(item.get("time"), now_dt=now_dt)
        if not slot_dt:
            continue
        if now_dt >= slot_dt:
            if control.get("paused") and not is_manual_activity:
                continue
            due.append(item)
    if changed_slots:
        state = load_xiaoxia_autonomy_state()
        scheduler["updated_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
        state["auto_scheduler"] = scheduler
        save_xiaoxia_autonomy_state(state)

    if control.get("paused") and not due:
        print(f"🌱 [AUTONOMY_AUTO_PAUSED] reason={control.get('reason')} pause_until={control.get('pause_until')}")
        return
    if not due:
        return

    # v1.10.29：愛意是聊天中突然插入的私密事件。若愛意已排隊／正在拍，
    # 自主 slot 保持 pending，下一輪再執行，不把愛意 status/結果淹掉。
    if int(LOVE_GENERATION_ACTIVE_COUNT or 0) > 0 or _love_generation_task_running():
        print(
            f"💗 [AUTONOMY_DEFERRED_FOR_LOVE] due={len(due)} "
            f"love_active={LOVE_GENERATION_ACTIVE_COUNT} love_task={_love_generation_task_running()}"
        )
        return

    channel = _get_xiaoxia_autonomy_channel_for_auto()
    if not channel:
        print(f"⚠️ [AUTONOMY_AUTO_CHANNEL_MISSING] id={XIAOXIA_AUTONOMY_CHANNEL_ID} name={XIAOXIA_AUTONOMY_CHANNEL_NAME}")
        return

    item = due[0]
    item["status"] = "running"
    item["started_at"] = now_dt.strftime("%Y-%m-%d %H:%M:%S")
    state = load_xiaoxia_autonomy_state()
    state["auto_scheduler"] = scheduler
    save_xiaoxia_autonomy_state(state)

    try:
        is_manual_activity = item.get("manual_kind") == "specified_activity"
        if is_manual_activity:
            title = str(item.get("activity_title") or item.get("activity_id") or "大俠指定活動").strip()
            wid = str(item.get("specified_wardrobe_id") or "").strip().upper()
            wname = str(item.get("specified_wardrobe_name") or "").strip()
            wardrobe_note = f"｜指定衣服：{wid} {wname}" if wid else ""
            await channel.send(f"🌱 小俠到了大俠指定的生活時段（{item.get('time')}），準備去做：**{title}**{wardrobe_note}。")
            command_text = f"/小俠自主 指定活動 {title}"
            if wid:
                command_text += f" {wid}"
            command_text += " now"
        else:
            await channel.send(f"🌱 小俠到了今天自己安排的生活時段（{item.get('time')}），準備去做一件事、拍一張照給大俠。")
            command_text = "/小俠自主 重抽"

        fake_message = type("AutonomyAutoMessage", (), {})()
        fake_message.channel = channel
        fake_message.author = getattr(girlfriend_bot, "user", None)
        fake_message.content = command_text
        ok = await handle_xiaoxia_autonomy_command(fake_message, command_text)
        item["status"] = "sent" if ok else "failed"
        item["sent_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
    except Exception as exc:
        item["status"] = "failed"
        item["error"] = f"{type(exc).__name__}: {str(exc)[:300]}"
        print(f"⚠️ [AUTONOMY_AUTO_SEND_FAILED] {item['error']}")
    finally:
        state = load_xiaoxia_autonomy_state()
        scheduler["updated_at"] = datetime.now(TZ_TPE).strftime("%Y-%m-%d %H:%M:%S")
        state["auto_scheduler"] = scheduler
        save_xiaoxia_autonomy_state(state)


