def _clean_xia_reply(reply: str) -> str:
    reply = _sanitize_visible_reply_text(reply)
    if len(reply) > 1900:
        reply = reply[:1850] + "\n\n(內容過長，已截斷；請指定需要檢視的區段。)"
    return reply

@architect_bot.event
async def on_message(message):
    if message.author.bot:
        return

    # v52.1：在小夏工作室支援 /life_events，避免被一般聊天流程吃掉。
    if message.content.strip() == "/life_events":
        try:
            profile = load_profile()
            events, changed = refresh_life_events(profile=profile)
            if changed:
                save_profile(profile)
            context = format_life_event_context(events)
            await message.channel.send("🧭 **目前重大事件狀態機**\n```\n" + context[:1800] + "\n```")
        except Exception as exc:
            await message.channel.send(f"❌ 重大事件狀態機讀取失敗：{exc}")
        return

    # 故事頻道一律不由小夏介入。
    if is_story_channel_or_thread(message.channel):
        return

    # 🎴 小俠專屬命運牌路由：
    # 同一則訊息會同時送到兩個 Discord Bot。只要是命運牌指令，
    # 或這位使用者在此頻道尚有未結束的一局，小夏都必須完全靜默，
    # 讓小俠的 CoupleGameService 單獨處理開局與 A/B/C、1/2/3、0 等局內輸入。
    if is_couple_game_channel(message.channel):
        # 開局指令必須無條件讓給小俠；不可等 session 寫入後才判定，
        # 否則兩個 Bot 同時收到 !命運牌 時，小夏可能搶先送出頻道封鎖訊息。
        raw_game_text = str(message.content or "").strip()
        if raw_game_text.startswith("!命運牌") or raw_game_text.startswith("/命運牌"):
            return
        try:
            if couple_game_service.might_handle(message):
                return
        except Exception as exc:
            print(
                f"⚠️ [COUPLE_GAME_ARCHITECT_GUARD_ERROR] "
                f"{type(exc).__name__}: {exc}"
            )

    # 🧭 多輪服務路由仲裁：
    # Calendar 若正在等待 0/1/2、候選編號或修改內容，必須優先續接，
    # 避免純數字先被名片服務誤認為名片候選選號。
    calendar_pending = False
    try:
        calendar_pending = google_calendar_service.has_pending_for(message)
    except Exception as exc:
        print(
            f"⚠️ [GOOGLE_CALENDAR_PENDING_CHECK_ERROR] "
            f"{type(exc).__name__}: {exc}"
        )

    if calendar_pending:
        try:
            if await google_calendar_service.handle_message(message):
                return
        except Exception as exc:
            print(
                f"⚠️ [GOOGLE_CALENDAR_BRIDGE_ERROR] "
                f"{type(exc).__name__}: {exc}"
            )

    # 📇 無 Calendar 待辦時，名片服務維持優先。
    # 公開 #架構師專用與私人 #助手小夏工作室使用同一份 Google Sheets，
    # 但各自持有獨立多輪候選選號 session，避免數字跨頻道誤判。
    active_business_card_service = (
        private_business_card_service
        if is_private_assistant_workspace(message.channel)
        else business_card_service
    )
    try:
        if await active_business_card_service.handle_message(message):
            return
    except Exception as exc:
        print(
            f"⚠️ [BUSINESS_CARD_BRIDGE_ERROR] "
            f"{type(exc).__name__}: {exc}"
        )

    # 📅 沒有待確認狀態時，再判斷這一則是不是新的 Calendar 需求。
    if not calendar_pending:
        try:
            if await google_calendar_service.handle_message(message):
                return
        except Exception as exc:
            print(
                f"⚠️ [GOOGLE_CALENDAR_BRIDGE_ERROR] "
                f"{type(exc).__name__}: {exc}"
            )

    private_mode = is_private_assistant_workspace(message.channel)
    upload_room = is_private_upload_channel(message.channel)
    note_room = is_private_note_channel(message.channel)
    public_mode = is_public_service_channel(message.channel)

    # !update 後續完全使用自然語言對答；使用者只需記得 !update。
    pending_update = memory_update_sessions.get(message.author.id)
    if private_mode and pending_update and not message.content.startswith("!"):
        reply_text = message.content.strip()
        if reply_text in {"取消", "取消更新", "不用了"}:
            memory_update_sessions.pop(message.author.id, None)
            await message.channel.send("🗑️ 已取消本次記憶修訂，所有資料都沒有被修改。")
            return

        if reply_text in {"確認", "確認執行", "執行更新", "確定執行"}:
            await message.channel.send("💾 正式寫入前，小夏正在先備份所有原始記憶檔……")
            try:
                manifest = _apply_memory_update_case(pending_update)
                memory_update_sessions.pop(message.author.id, None)
                # 清除聊天 session，讓小俠下一次回覆重新載入最新規則。
                girlfriend_chat_sessions.clear()
                await message.channel.send(
                    "✅ **記憶修訂完成。**\n"
                    f"已套用 `{manifest.get('applied_action_count', 0)}` 筆草案修改，"
                    f"並強制清掃 `{manifest.get('temporal_cleanup_count', 0)}` 筆日期殘留；"
                    "已同步更新禁用詞／偏好表達／最新事實。\n"
                    f"備份位置：`{manifest.get('backup_dir')}`\n"
                    "若結果不如預期，可告訴小夏要復原，或使用 `!undo_update`。"
                )
            except Exception as exc:
                await message.channel.send(f"❌ 記憶修訂執行失敗，原始資料未被覆蓋：{exc}")
            return

        # 其他自然語言一律視為對草案的補充，小夏重新分析。
        await message.channel.send("✏️ 收到補充，小夏正在重新整理修改草案……")
        try:
            revised = await _build_memory_update_case(
                pending_update["request"],
                feedback=(pending_update.get("feedback", "") + "\n" + reply_text).strip(),
            )
            memory_update_sessions[message.author.id] = revised
            await message.channel.send(_format_update_preview(revised))
        except Exception as exc:
            await message.channel.send(f"❌ 草案調整失敗：{exc}")
        return

    # 指令分流：先判斷精準允許的私人共享指令，再處理一般對話。
    if message.content.startswith('!'):
        command_name = message.content[1:].strip().split()[0].lower() if message.content[1:].strip() else ""

        # 私人工具一律可加本人鎖；避免未來私人 Server 增加成員後被誤觸。
        if (private_mode or upload_room or note_room) and not is_owner_or_unlocked(message.author.id):
            await message.channel.send("⛔ 此私人工具僅限管理者使用。")
            return

        # #助手小夏工作室：完整私人工具控制台
        if private_mode:
            await architect_bot.process_commands(message)
            return

        # #唐分糕 / #給你全世界：僅允許把照片收入日記或企劃，
        # 原始上傳訊息仍留在此頻道，供小俠看到並自然接話。
        if upload_room:
            if command_name in {"upload_diary", "upload_project"}:
                await architect_bot.process_commands(message)
            else:
                await message.channel.send("🔒 此頻道只開放 `!upload_diary` 與 `!upload_project`；其他工具請到 `#助手小夏工作室`。")
            return

        # #小俠書房：僅允許就地整理書房知識。
        if note_room:
            if command_name == "筆記":
                await architect_bot.process_commands(message)
            else:
                await message.channel.send("🔒 此頻道只開放 `!筆記`；其他工具請到 `#助手小夏工作室`。")
            return

        # 公開服務區維持只開放 ping。
        if public_mode:
            if command_name == "ping":
                await architect_bot.process_commands(message)
            else:
                await message.channel.send("🔒 此功能僅在私人服務空間提供。")
            return

        return

    # 非指令的一般聊天：小夏仍只在助手工作室或公開指定服務頻道出聲；
    # 不會在小俠的照片／書房對話頻道插話搶戲。
    if not private_mode and not public_mode:
        return

    # 公開晨報與 FOMO 是播報頻道：除非標記小夏，否則不插話。
    if public_mode and message.channel.id in {MORNING_CHANNEL_ID, FOMO_CHANNEL_ID}:
        if not (architect_bot.user.mentioned_in(message) or "@小夏" in message.content):
            return

    mode_key = "private" if private_mode else "public"
    user_id = message.author.id
    session_key = f"{mode_key}:{user_id}"
    user_input = message.content.replace(f'<@{architect_bot.user.id}>', '').replace('@小夏', '').strip()
    if not user_input:
        return

    system_prompt = PRIVATE_XIA_SYSTEM_PROMPT if private_mode else PUBLIC_XIA_SYSTEM_PROMPT
    fallback_reply = (
        "大俠學長，小夏剛剛沒有聽清楚，可以再說一次嗎？"
        if private_mode
        else "抱歉，目前未能辨識需求。請提供錯誤訊息、預期行為或相關檔案。"
    )

    async with message.channel.typing():
        try:
            if session_key not in architect_chat_sessions:
                architect_chat_sessions[session_key] = gemini_client.aio.chats.create(
                    model="gemini-2.5-flash",
                    config=types.GenerateContentConfig(
                        system_instruction=system_prompt,
                        safety_settings=[
                            types.SafetySetting(category="HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold="BLOCK_NONE"),
                            types.SafetySetting(category="HARM_CATEGORY_HATE_SPEECH", threshold="BLOCK_NONE"),
                            types.SafetySetting(category="HARM_CATEGORY_HARASSMENT", threshold="BLOCK_NONE"),
                            types.SafetySetting(category="HARM_CATEGORY_DANGEROUS_CONTENT", threshold="BLOCK_NONE")
                        ]
                    )
                )

            response = await architect_chat_sessions[session_key].send_message(user_input)
            reply = _clean_xia_reply(response.text if response and response.text else fallback_reply)
            await message.reply(reply or fallback_reply)

        except Exception as exc:
            if private_mode:
                await message.channel.send(f"💦 大俠學長，小夏暫時無法處理這個需求：{exc}")
            else:
                await message.channel.send(f"⚠️ 架構師模組暫時無法處理此需求。錯誤：{exc}")



# ==========================================
# 👥 v1.5.26：統一人物場景政策
# ==========================================
# 核心原則：
# 1. 小俠永遠是畫面主角。
# 2. 社交／公共／活動情境可有其他人物。
# 3. 女性可與小俠自然互動。
# 4. 公共場合可有男性背景人物，但男性不得與小俠互動。
# 5. 私密場合只有小俠一人。
#
# 本區刻意放在啟動器之前，以覆寫舊版散落於各生圖路徑的 strict-solo 規則。

XIAOXIA_UNIFIED_PEOPLE_POLICY = """
UNIFIED PEOPLE AND INTERACTION POLICY — highest priority:
- Xiaoxia must always be the unmistakable main character, primary subject, and visual focus.
- Xiaoxia may appear in social, public, travel, work, study, volunteer, sport, class, event, and activity scenes.
- Female friends, sisters, classmates, colleagues, staff, students, or other female characters may appear and naturally interact with Xiaoxia when the requested scene calls for it. They must remain secondary to Xiaoxia and must not obscure or replace her identity.
- Xiaoxia is the only identity-locked subject. Figures/Images 1-9 and all Xiaoxia appearance anchors apply exclusively to Xiaoxia, never to supporting women.
- Supporting women must be clearly different individuals, not Xiaoxia clones, twins, duplicates, or alternate versions. Give them visibly different face shapes, facial features, hairstyles or hair lengths, clothing colors/silhouettes, and natural body builds.
- Supporting women must use ordinary natural styling and lower visual emphasis. They must not receive Xiaoxia's signature face, long brown hairstyle, body proportions, bust emphasis, hourglass styling, glamour treatment, strongest lighting, sharpest detail, or central composition.
- Every other person exists only to support Xiaoxia's story. Xiaoxia must remain the unmistakable heroine and the first person the viewer notices.
- Xiaoxia must remain the most recognizable, visually prominent, attractive, sharply rendered, and compositionally dominant woman. Supporting women may be appealing, but must not have more emphasized curves, bust prominence, glamour styling, lighting priority, fashion emphasis, or visual weight than Xiaoxia.
- When a female companion interacts with Xiaoxia, frame her as a supporting friend rather than a second heroine; composition, lighting, focus, styling, and body emphasis must lead attention back to Xiaoxia.
- Nearby women must never appear more voluptuous or more bust-emphasized than Xiaoxia.
- In public places, male people may appear only as incidental environmental background figures needed for realism.
- No male person may interact with Xiaoxia in any way: no conversation, eye contact, shared table, walking together, standing or sitting as her companion, posing together, handing objects, helping, coaching, touching, embracing, or relationship/date/partner composition.
- A male background figure must remain clearly secondary, separated from Xiaoxia, non-interacting, non-companion-like, and never become a foreground or co-primary subject.
- In private scenes, Xiaoxia must be the only human figure. No other woman, man, child, external hand, viewer body part, reflection, silhouette, shadow, or partial person may appear.
- Daxia/the boyfriend is always an invisible camera viewpoint only and must never be visually depicted or substituted by any head, hand, arm, shoulder, back, reflection, shadow, or cropped body part.
- Xiaoxia's own anatomy, hands, fingers, limbs, posture, and movement must remain natural and physically plausible.
"""

SOLO_XIAOXIA_VISUAL_RULES = XIAOXIA_UNIFIED_PEOPLE_POLICY
STRICT_SOLO_AND_ANATOMY_PROMPT = XIAOXIA_UNIFIED_PEOPLE_POLICY
SOLO_SCENE_REWRITE_GUARD = XIAOXIA_UNIFIED_PEOPLE_POLICY
SOLO_NEGATIVE_MINIMAL = (
    "Xiaoxia is always the primary subject. Female characters may interact naturally when the requested social/activity scene requires it. "
    "Supporting women must be clearly different individuals and must never inherit Xiaoxia's identity, face, hairstyle, body anchors, glamour styling, or visual priority. "
    "Men may exist only as non-interacting incidental public background figures. No male interaction, companion/date framing, viewer body parts, or Daxia depiction. "
    "Private scenes contain Xiaoxia alone."
)

XIAOXIA_SUPPORTING_WOMEN_IDENTITY_ISOLATION = """
SUPPORTING WOMEN IDENTITY ISOLATION — mandatory whenever another woman appears:
- Xiaoxia is the only identity-locked person. Apply Figures/Images 1-9, Xiaoxia's face identity, long brown hair identity, fair luminous skin anchor, tall-slim-curvy body anchor, bust/waist emphasis, and Xiaoxia Aesthetic exclusively to Xiaoxia.
- Never transfer, blend, clone, average, or repeat Xiaoxia's identity or body design onto a supporting woman. Supporting women are separate people, not twins, duplicates, lookalikes, reflections, or alternate Xiaoxias.
- Make each supporting woman visibly distinct through a different face shape, eyes/nose/mouth arrangement, hairstyle or hair length, hair texture, clothing color and silhouette, and a natural individual body build.
- Prefer obvious differentiation such as one shoulder-length or tied hairstyle and one shorter/straighter hairstyle; avoid giving every woman the same long wavy brown hair.
- Supporting women should have ordinary, natural, scene-appropriate proportions and styling. Do not emphasize their bust, curves, cleavage, glamour, or fashion more strongly than Xiaoxia.
- Xiaoxia must occupy the strongest focal position through central or compositionally dominant placement, clearest face visibility, sharpest detail, best lighting, strongest eye guidance, and the most refined styling.
- Supporting women remain secondary in framing, lighting, detail, pose prominence, and visual weight, while still looking like natural friends who genuinely interact with Xiaoxia.
"""

_V1526_FEMALE_SOCIAL_WORDS = (
    "姊妹淘", "姐妹淘", "閨蜜", "闺蜜", "女性朋友", "女朋友們", "女同學", "女同学", "女同事",
    "姊妹", "姐妹", "女生們", "女生们", "女性學生", "女性学生", "女學生", "女学生", "女性同伴",
    "female friend", "female friends", "women friends", "sisters", "female classmates", "female colleagues",
    "female students", "women-only", "girls' night", "girls night"
)
_V1526_MALE_INTERACTION_WORDS = (
    "和男性", "跟男性", "和男生", "跟男生", "和男人", "跟男人", "男朋友", "男友", "男性朋友",
    "男同學", "男同学", "男同事", "男教練", "男教练", "男性教練", "男性教练", "男伴", "男性同伴",
    "with a man", "with a male", "male friend", "boyfriend", "male colleague", "male classmate", "male coach"
)

def _v1526_contains(text, words):
    low = str(text or "").lower()
    return any(str(w).lower() in low for w in words)

# 保留舊函式作為基礎，再集中修正人物政策。
_v1525_build_visual_checklist = _build_visual_checklist

def _build_visual_checklist(mode="photo", user_text="", visual_dict=None, current_outfit=None, trace_context=None):
    checklist = _v1525_build_visual_checklist(mode, user_text, visual_dict, current_outfit, trace_context)
    checklist = dict(checklist or {})
    source = _visual_policy_source_text(mode, user_text, visual_dict, current_outfit, trace_context)
    mode_norm = str(mode or "").strip().lower()
    tc = trace_context if isinstance(trace_context, dict) else {}

    # v1.8.16: Cosplay generation contract is intentionally strict-solo.
    # Keep QA/checklist metadata aligned with the actual Seedream cosplay prompt.
    if mode_norm == "cosplay":
        checklist.update({
            "private_scene": False,
            "strict_solo_required": True,
            "allow_background_bystanders": False,
            "specified_character_interaction": False,
            "people_policy": "cosplay_strict_solo",
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": False,
            "female_interaction_ok": False,
        })
        checklist["must_not_have"] = _dedupe_keep_order((checklist.get("must_not_have") or []) + [
            "any additional human figure, companion, bystander, external hand, reflection, silhouette, or visible viewer body part",
            "any male person anywhere in the cosplay frame",
            "Daxia/viewer visually depicted as a person or body part",
        ])
        return checklist

    private = bool(_is_private_scene_text(source))
    explicit_solo = bool(_explicit_solo_or_empty_scene_requested(source))
    female_social = (not private) and _v1526_contains(source, _V1526_FEMALE_SOCIAL_WORDS)
    male_interaction_requested = (not private) and _v1526_contains(source, _V1526_MALE_INTERACTION_WORDS)
    public_scene = (not private) and bool(_allow_background_bystanders_from_text(source, mode=mode))

    # v1.8.19：Diary 的 people policy 必須與 Hybrid / Pure / More / 骰子一致。
    # 若上游 Photo Selector / Scene builder 已明示這是公共場景可有背景路人，
    # checklist 需忠實承接，避免下游 prompt builder 又被寫死成 strict-solo。
    if mode_norm == "diary":
        diary_bystander_hint = bool(
            tc.get("diary_allow_background_bystanders")
            or tc.get("allow_background_bystanders")
            or checklist.get("allow_background_bystanders")
            or (isinstance(visual_dict, dict) and visual_dict.get("__allow_background_bystanders"))
        )
        if diary_bystander_hint and not private and not explicit_solo:
            public_scene = True

    if private or explicit_solo:
        checklist.update({
            "private_scene": True,
            "strict_solo_required": True,
            "allow_background_bystanders": False,
            "specified_character_interaction": False,
            "people_policy": "private_strict_solo",
            "no_male_people": True,
            "male_background_ok": False,
            "female_background_ok": False,
            "female_interaction_ok": False,
        })
    elif female_social:
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "allow_background_bystanders": True,
            "specified_character_interaction": False,
            "people_policy": "autonomy_female_interaction_ok",
            "no_male_people": False,
            "male_background_ok": True,
            "female_background_ok": True,
            "female_interaction_ok": True,
        })
    elif male_interaction_requested:
        # 使用者文字即使提到男性互動，也不得把它變成畫面互動；男性只能降為公共背景。
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "allow_background_bystanders": True,
            "specified_character_interaction": False,
            "people_policy": "autonomy_public_background_ok",
            "no_male_people": False,
            "male_background_ok": True,
            "female_background_ok": True,
            "female_interaction_ok": False,
            "male_interaction_forbidden": True,
        })
    elif public_scene or checklist.get("allow_background_bystanders"):
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "allow_background_bystanders": True,
            "specified_character_interaction": False,
            "people_policy": "autonomy_public_background_ok",
            "no_male_people": False,
            "male_background_ok": True,
            "female_background_ok": True,
            "female_interaction_ok": False,
        })
    else:
        checklist.update({
            "private_scene": False,
            "strict_solo_required": False,
            "specified_character_interaction": False,
            "people_policy": "solo_primary_subject",
            "no_male_people": False,
            "male_background_ok": False,
            "female_background_ok": False,
            "female_interaction_ok": False,
        })

    must_not = list(checklist.get("must_not_have") or [])
    # v1.8.13: background bystanders and forbidden companions are different things.
    # If the Scene/public policy allows background people, remove the legacy blanket ban that
    # would make QA reject every bystander even though allow_background_bystanders=True.
    if checklist.get("allow_background_bystanders") and not checklist.get("strict_solo_required"):
        must_not = [
            x for x in must_not
            if "any additional human figure, companion, bystander" not in str(x).lower()
        ]
    # Female interaction explicitly called for by Scene must not be killed by generic companion bans.
    if checklist.get("female_interaction_ok"):
        must_not = [x for x in must_not if "interacting companion" not in str(x).lower() and "second person" not in str(x).lower()]
    must_not += [
        "any male person interacting with Xiaoxia by talking, eye contact, shared table, walking together, posing together, passing objects, helping, coaching, touching, or companion/date framing",
        "Daxia/viewer visually depicted as a head, hand, arm, shoulder, back, reflection, shadow, silhouette, or cropped body part",
        "any other person becoming co-primary or more visually prominent than Xiaoxia",
    ]
    if checklist.get("strict_solo_required"):
        must_not.append("any additional human figure in the private or explicitly solo scene")
    checklist["must_not_have"] = _dedupe_keep_order(must_not)
    return checklist


def _seedream_people_policy_line(checklist=None):
    c = checklist if isinstance(checklist, dict) else {}
    policy = str(c.get("people_policy") or "")
    if policy == "cosplay_strict_solo":
        return "People rule: COSPLAY STRICT SOLO. Xiaoxia is the only visible human figure. No other woman, man, child, companion, bystander, external hand, viewer body part, reflection, shadow, silhouette, or partial person. Daxia remains an invisible camera viewpoint only."
    if c.get("strict_solo_required") or policy == "private_strict_solo":
        return "People rule: PRIVATE OR EXPLICIT SOLO SCENE. Xiaoxia is the only human figure. No other woman, man, child, external hand, viewer body part, reflection, shadow, silhouette, or partial person. Daxia remains an invisible camera viewpoint only."
    if policy == "autonomy_female_interaction_ok" or c.get("female_interaction_ok"):
        return "People rule: Xiaoxia is the unmistakable main character and visual focus. Female friends/sisters/classmates/colleagues may naturally interact with her as required by the scene, while remaining secondary and visibly distinct. Xiaoxia alone may inherit Figures/Images 1-9 and all Xiaoxia face, hair, body, bust/waist, and aesthetic anchors. Supporting women must have different faces, hairstyles/hair lengths, outfits, and natural body builds; they must not be Xiaoxia clones and must not receive stronger curves, bust emphasis, glamour, lighting, detail, or compositional weight than Xiaoxia. Men may appear only as distant incidental public background and may not talk to, look at, sit with, walk with, pose with, help, touch, or otherwise interact with Xiaoxia. No male companion/date framing. Never visualize Daxia/viewer."
    if policy == "autonomy_sport_no_male":
        return "People rule: Xiaoxia is the unmistakable main character. Female-only secondary people may appear when the activity needs them. No male person anywhere, no external hands, and never visualize Daxia/viewer."
    if policy in {"autonomy_public_background_ok", "public_background_bystanders_allowed"} or c.get("allow_background_bystanders"):
        return "People rule: Xiaoxia is the unmistakable main character and only primary subject. Public background people may appear for realism, including men. Any man must remain incidental, distant/secondary, and completely non-interacting with Xiaoxia: no conversation, eye contact, shared table, walking together, posing, passing objects, helping, coaching, touching, or companion/date composition. Female background people may be present but do not interact unless the scene explicitly calls for female social interaction. Never visualize Daxia/viewer."
    return "People rule: Xiaoxia is the unmistakable main character and only primary subject. Do not add a companion. No male may interact with Xiaoxia. Never visualize Daxia/viewer or external body parts."


def _v1526_relax_old_solo_text(prompt, checklist=None):
    """移除舊版殘留的『所有情境只能一人』語句，再注入單一政策。"""
    text = str(prompt or "")
    replacements = {
        "Create a new solo photorealistic lifestyle image of Xiaoxia.": "Create a new photorealistic lifestyle image centered unmistakably on Xiaoxia.",
        "- Natural anatomy, single person only, candid lifestyle photo.": "- Natural anatomy and candid lifestyle photography. Apply the people rule above exactly.",
        "- Character visibility rule: strictly only Xiaoxia appears in the image; Xiaoxia is the only human figure.": "- Character priority rule: Xiaoxia must remain the unmistakable main character and only primary subject; apply the scene-specific people policy.",
        "- Forbidden visual intrusions: no external hands, people, external feet, or any visible body part of the viewer.": "- Forbidden visual intrusions: no external hands/feet or visible body part of the viewer; other people are governed only by the scene-specific people policy.",
        "- Strictly solo Xiaoxia only; no man, no other people, no visible viewer body parts, no foreground hands/arms/shoulders, no male silhouette or reflection.": "- Xiaoxia must be the unmistakable main character. Never show viewer body parts or a male interacting/companion figure; apply the scene-specific people policy.",
        "No other people of any gender.": "No unrequested co-primary subject.",
        "Strictly solo focus on Xiaoxia.": "Keep unmistakable primary focus on Xiaoxia.",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    # 清除最常造成女性角色被整批消除的固定長句。
    text = text.replace("NO external hands, people, external feet, men, male heads, male faces, male hair, male shoulders, male backs, male body parts, visible viewer body parts, foreground hands/arms/shoulders, blurred foreground male figures, silhouettes, cropped people, or reflections.",
                        "No external viewer body parts or Daxia depiction. Men may appear only as non-interacting incidental public background when allowed by the people policy; no male interaction or companion framing.")
    policy_line = _seedream_people_policy_line(checklist)
    c = checklist if isinstance(checklist, dict) else {}
    supporting_block = ""
    if c.get("female_interaction_ok") or str(c.get("people_policy") or "") == "autonomy_female_interaction_ok":
        supporting_block = XIAOXIA_SUPPORTING_WOMEN_IDENTITY_ISOLATION.strip() + "\n"
    return f"{XIAOXIA_UNIFIED_PEOPLE_POLICY.strip()}\n{supporting_block}{policy_line}\n\n{text}".strip()

_v1525_build_hard_anchor_block = _build_hard_anchor_block

def _build_hard_anchor_block(mode, visual_dict, initial_prompt=""):
    base = _v1525_build_hard_anchor_block(mode, visual_dict, initial_prompt)
    checklist = None
    if isinstance(visual_dict, dict):
        checklist = visual_dict.get("__visual_checklist")
        if not isinstance(checklist, dict):
            tc = visual_dict.get("__trace_context")
            if isinstance(tc, dict):
                checklist = tc.get("visual_checklist")
    return _v1526_relax_old_solo_text(base, checklist)

_v1525_build_pose_critical_seedream_prompt = _build_pose_critical_seedream_prompt

def _build_pose_critical_seedream_prompt(user_request, has_reference=False, current_outfit=None, retry_reason="", visual_checklist=None):
    base = _v1525_build_pose_critical_seedream_prompt(user_request, has_reference, current_outfit, retry_reason, visual_checklist)
    return _v1526_relax_old_solo_text(base, visual_checklist)


# ==========================================
# 🪶 v1.5.40_R1 — Seedream compact prompt layer
# Goal: preserve only non-negotiable boundaries; leave pose, expression, and visual staging to Seedream.
# Covers first generation, 修正這張 / 再修一次, More, 骰子取代, and reroll paths.
# ==========================================

def _v1540_people_rule(checklist=None):
    """v1.8.13: compact people rule follows the Scene-derived checklist instead of forcing solo."""
    c = checklist if isinstance(checklist, dict) else {}
    policy = str(c.get("people_policy") or "")

    if c.get("strict_solo_required") or policy == "private_strict_solo":
        return (
            "People: private/explicit-solo scene; Xiaoxia is the only visible human figure. "
            "Do not add another person, external hands, reflections, shadows, or visible viewer body parts; Daxia stays invisible."
        )

    if c.get("female_interaction_ok") or policy == "autonomy_female_interaction_ok":
        return (
            "People: follow the Scene exactly. Scene-specified women may naturally interact with Xiaoxia but remain clearly secondary and visually distinct. "
            "Men may appear only as incidental public background and must never interact with Xiaoxia. Do not add unstated companions; Daxia stays invisible."
        )

    if c.get("allow_background_bystanders") or policy in {"autonomy_public_background_ok", "public_background_bystanders_allowed"}:
        return (
            "People: follow the Scene exactly. Public/background people explicitly stated or naturally allowed by the Scene may remain secondary. "
            "Men may appear only as incidental background and must never interact with Xiaoxia. Do not add an unstated foreground companion; Xiaoxia stays primary and Daxia stays invisible."
        )

    if c.get("specified_character_interaction"):
        return (
            "People: include only the additional character or characters explicitly required by the Scene, keep them secondary, "
            "never allow male interaction with Xiaoxia, and never visualize Daxia/viewer."
        )

    return (
        "People: Xiaoxia is the only primary subject. Do not add an unstated companion. "
        "No male may interact with Xiaoxia; never visualize Daxia/viewer or external viewer body parts."
    )


def _v1540_compact_identity_line():
    return (
        "Identity: preserve Xiaoxia's recognizable adult East Asian face, fair luminous skin, long brown hair, "
        "tall slim figure, distinctly narrow waist, naturally very full and visibly prominent elegant bust, "
        "strong bust-to-waist contrast, refined hourglass silhouette, and long graceful legs. "
        "Her fuller upper-body silhouette and narrow waist must remain clearly readable through the clothing "
        "in seated, standing, full-body, side-facing, and multi-person compositions, while anatomy stays natural."
    )


def _v1540_extract_request(text):
    text = str(text or "").strip()
    markers = [
        "TEXT REQUEST — this controls the final scene, pose, action, and composition:",
        "TEXT REQUEST:",
        "CURRENT DAXIA REPAIR REQUEST (AESTHETICALLY INTERPRETED):",
    ]
    for marker in markers:
        if marker in text:
            text = text.split(marker, 1)[1].strip()
            break
    # Remove old fixed-tail sections if they were already embedded by a previous continuation.
    for marker in ["Mandatory obedience rules:", "PREVIOUS OUTPUT WAS REJECTED:"]:
        if marker in text:
            text = text.split(marker, 1)[0].strip()
    return re.sub(r"\n{3,}", "\n\n", text).strip()


def _build_pose_critical_seedream_prompt(user_request, has_reference=False, current_outfit=None, retry_reason="", visual_checklist=None):
    request = _v1540_extract_request(user_request)
    lines = [
        "FIGURE ROLES: Figures 1-9 identify Xiaoxia only; never copy their pose, room, background, or composition.",
        _v1540_compact_identity_line(),
        _v1540_people_rule(visual_checklist),
    ]
    if has_reference:
        lines.append("Outfit: Figure 10 is the clothing reference. Preserve its distinctive design; text controls scene, action, pose, and camera.")
    elif current_outfit:
        lines.append(f"Outfit continuity: {str(current_outfit).strip()}")
    lines += [
        f"Request: {request}",
        "Priority: make the requested pose/action unmistakable; keep anatomy natural and do not substitute a generic fashion pose or another location.",
    ]
    if retry_reason:
        lines.append(f"Retry correction: {str(retry_reason).strip()}")
    return "\n".join(x for x in lines if x).strip()


def _build_photo_reference_minimal_seedream_prompt(user_request, current_outfit=None, retry_reason="", has_figure10=True, visual_checklist=None):
    request = _v1540_extract_request(user_request)
    lines = [
        "FIGURE ROLES: Figures 1-9 identify Xiaoxia only; never copy their pose, setting, outfit, or composition.",
        _v1540_compact_identity_line(),
        _v1540_people_rule(visual_checklist),
    ]
    if has_figure10:
        lines.append("Outfit: use Figure 10 faithfully for the garment and distinctive visible accessories; do not let it override the requested scene or action.")
    elif current_outfit:
        lines.append(f"Outfit continuity: {str(current_outfit).strip()}")
    lines += [
        f"Request: {request}",
        "Priority: show the requested scene and main action clearly. Keep the image natural; do not replace it with a generic portrait or invent another location.",
    ]
    if retry_reason:
        lines.append(f"Retry correction: {str(retry_reason).strip()}")
    return "\n".join(x for x in lines if x).strip()


def _build_hard_anchor_block(mode, visual_dict, initial_prompt=""):
    visual_dict = visual_dict if isinstance(visual_dict, dict) else {}
    checklist = visual_dict.get("__visual_checklist")
    if not isinstance(checklist, dict):
        tc = visual_dict.get("__trace_context")
        checklist = tc.get("visual_checklist") if isinstance(tc, dict) else {}
    request = _v1540_extract_request(initial_prompt)
    anchors = []
    for key, label in [
        ("scene_summary", "Scene"), ("setting_anchor", "Scene"), ("time_anchor", "Time"),
        ("activity", "Activity"), ("primary_action", "Action"), ("outfit_intent", "Outfit"),
    ]:
        value = _clean_text_compact(visual_dict.get(key))
        if value and all(value.lower() not in x.lower() for x in anchors):
            anchors.append(f"{label}: {value}")
    lines = [
        _v1540_compact_identity_line(),
        _v1540_people_rule(checklist),
    ]
    lines.extend(anchors[:5])
    if request:
        lines.append(f"Request: {request}")
    lines.append("Priority: preserve the requested story and activity; Xiaoxia remains the clear protagonist. Leave natural pose, expression, lighting nuance, and composition to Seedream unless explicitly specified.")
    return "\n".join(lines).strip()


def _repair_semantic_contract(context):
    """v1.8.13: Repair uses the same Title + Scene contract; Image 10 is the current visual state only."""
    context = context if isinstance(context, dict) else {}
    mode = _repair_context_mode(context)
    scene = _clean_text_compact(
        context.get("authoritative_scene")
        or (_compose_photobook_scene(context.get("photobook_content_scene"), context.get("photobook_camera_scene")) if mode == "photobook" else "")
        or context.get("composition")
        or context.get("scene_summary")
        or context.get("scene_text")
        or ""
    )
    if mode == "diary":
        return scene
    if mode == "cosplay":
        state = context.get("cosplay_state") if isinstance(context.get("cosplay_state"), dict) else {}
        title = context.get("cosplay_title_hint") or context.get("cosplay_character_name") or state.get("character_name") or context.get("topic") or ""
        return _compose_title_scene_render_prompt("cosplay", title, scene)
    if _is_autonomy_context(context):
        title = context.get("activity_title") or context.get("title") or "小俠自主活動"
        return _compose_title_scene_render_prompt("autonomy", title, scene)
    if mode == "photobook" or str(context.get("album_type") or "").lower() == "photobook":
        title = context.get("shot_title") or context.get("title") or context.get("album_title") or ""
        return _compose_title_scene_render_prompt("photobook", title, scene)
    title = context.get("title") or context.get("scene_summary") or "這一刻"
    return _compose_title_scene_render_prompt("photo", title, scene)


def _seedream_repair_mode_block(context):
    return _repair_semantic_contract(context)


def _seedream_repair_prompt(custom_prompt, context=None, interpreted_request=None):
    context = context if isinstance(context, dict) else {}
    interpreted = interpreted_request or _rewrite_repair_request_for_aesthetics(custom_prompt)
    request = str(interpreted.get("rewritten") or custom_prompt or "").strip()
    semantic_contract = _repair_semantic_contract(context)
    checklist = context.get("visual_checklist") if isinstance(context.get("visual_checklist"), dict) else {}
    return "\n\n".join(x for x in [
        "FIGURE ROLES: Figures 1-9 identify Xiaoxia only. Image 10 is the current completed photo to repair; it is not a new story source.",
        _v1540_compact_identity_line(),
        _v1540_people_rule(checklist),
        "TITLE + SCENE CONTRACT: use this to preserve the intended story. Scene facts remain mandatory; Title is semantic help only.",
        semantic_contract,
        "CURRENT IMAGE RULE: preserve Image 10's already-correct visual details unless they conflict with Scene or Daxia's repair request.",
        f"CHANGE ONLY: {request}",
        "Make the smallest clearly visible correction. Do not redesign scene, outfit, activity, time, or composition unless Daxia explicitly requests that exact change. Keep anatomy natural.",
    ] if str(x).strip()).strip()


# ==========================================
# 🚀 終極啟動器
# ==========================================
async def main():
    print(f"🚀 [LOBSTER_MAIN_ENTER] version={LOBSTER_VERSION}")
    auto_heal_environment()

    if not GIRLFRIEND_TOKEN or not ARCHITECT_TOKEN:
        print("❌ 錯誤：缺少環境變數，請確認 GIRLFRIEND_TOKEN 與 ARCHITECT_TOKEN 皆已設定！")
        return

    print(
        "🚀 [LOBSTER_MAIN_TOKENS] "
        f"girlfriend={'OK' if GIRLFRIEND_TOKEN else 'MISSING'} "
        f"architect={'OK' if ARCHITECT_TOKEN else 'MISSING'}"
    )

    config = uvicorn.Config(api_app, host="0.0.0.0", port=8080, log_level="warning")
    server = uvicorn.Server(config)

    calendar_scheduler_task = asyncio.create_task(
        _xiaoxia_calendar_daily_refresh_scheduler(),
        name="xiaoxia_calendar_daily_refresh_scheduler",
    )
    print("📅 [LOBSTER_MAIN] Calendar scheduler task created independently")

    calendar_weekly_planner_task = asyncio.create_task(
        _xiaoxia_calendar_weekly_planner_scheduler(),
        name="xiaoxia_calendar_weekly_planner_scheduler",
    )
    print("📅 [LOBSTER_MAIN] Weekly Calendar Planner scheduler task created independently")

    try:
        await asyncio.gather(
            server.serve(),
            girlfriend_bot.start(GIRLFRIEND_TOKEN),
            architect_bot.start(ARCHITECT_TOKEN)
        )
    finally:
        if not calendar_scheduler_task.done():
            calendar_scheduler_task.cancel()
        if not calendar_weekly_planner_task.done():
            calendar_weekly_planner_task.cancel()
        try:
            await calendar_scheduler_task
        except asyncio.CancelledError:
            pass
        try:
            await calendar_weekly_planner_task
        except asyncio.CancelledError:
            pass
        print("🛑 [LOBSTER_MAIN_EXIT]")

if __name__ == "__main__":
    print(f"🚀 [LOBSTER_ENTRYPOINT] version={LOBSTER_VERSION}")
    try:
        asyncio.run(main())
    except Exception as exc:
        print(f"❌ [LOBSTER_FATAL] {type(exc).__name__}: {exc}")
        traceback.print_exc()
        raise

